INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nibzard/looper/release-runbook', 'community', 'nibzard', 'looper', 'nibzard/looper', 'release-runbook', 0, 0, 36, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:29.799Z', 'f6f54d14e8c5c2d477de2d31a52251759379c087437e95fc7078351823f8ea0d', '{"id":"nibzard/looper/release-runbook","name":"release-runbook","description":{"en":"The release-runbook skill automates the release workflow for developers, ensuring a clean and efficient process. It verifies repository state, runs tests, and publishes GitHub releases.","zh":"Release Runbook是一种自动化GitHub发布工作流的工具，确保代码库的状态、运行测试、版本升级和发布","ja":"Release RunbookはGitHubリリースの自動化を実現するツールで、コードリポジトリの状態を確認し、テストを実行し、バージョンを昇格し、リリースを行う","ko":"Release Runbook은 깃허브 자동 릴리즈 워크플ロー 툴로, 코드 저장소 상태 확인, 테스트 실행, 버전 업그레이드 및 릴리즈를 수행한다","es":"Release Runbook es una herramienta que automatiza el flujo de trabajo de Git, verificando el estado del repositorio y publicando versiones.","fr":"Release Runbook est un outil qui automatise le workflow Git, en vérifiant l''état du référentiel et en publiant des versions.","de":"Release Runbook ist ein Tool, das den Git-Workflow automatisiert, indem es den Repository-Zustand überprüft und Versionen veröffentlicht.","pt":"O release-runbook é uma ferramenta que automatiza o fluxo de trabalho de lançamento, verificando o estado do repositório e publicando releases no GitHub.","ru":"Release-runbook - это инструмент, автоматизирующий релизный workflow, проверяющий состояние репозитория и публикующий релизы на GitHub с помощью ИИ Агентов.","ar":"release-runbook هو أداة تؤتمة تدفق العمل لإصدار البرامج، حيث يتحقق من حالة المستودع وينشر الإصدارات على GitHub"},"seo":{"title":{"en":"release-runbook: Automated Release Workflow Setup Guide |...","zh":"Release Runbook_SETUP GUIDE: GitHub自动化发布工作流","ja":"Release Runbookベストプラクティス: GitHubリリース自動化","ko":"Release Runbook 구축 가이드: 깃허브 자동 릴리즈 워크플ロー","es":"Guía de configuración de Release Runbook para flujos de t...","fr":"Guide de mise en place de Release Runbook pour les workfl...","de":"Release Runbook Einrichtungsleitfaden für Git-Workflows","pt":"Release Runbook: Guia de Configuração para Fluxo de Traba...","ru":"Release Runbook: ИИ Агенты для Автоматизации Релизов","ar":"release-runbook: دليل إعداد Fluxo de Trabalho للطرح"},"description":{"en":"Streamline your release process with release-runbook. Learn how to automate verification, testing, and deployment. Get started now!","zh":"了解Release Runbook的技术细节，自动化GitHub发布工作流，提高开发效率","ja":"Release Runbookの詳細を学び、GitHubリリースの自動化を実現する","ko":"Release Runbook의 기능과 기술을 익히고 깃허브 자동 릴리즈를 구현하세요","es":"Automatice sus flujos de trabajo de Git con Release Runbook. Verifique el estado del repositorio, ejecute pruebas y publique versiones con esta herramienta d...","fr":"Automatisez vos workflows Git avec Release Runbook. Vérifiez l''état du référentiel, exécutez des tests et publiez des versions avec cet outil d''AI Agent","de":"Automatisieren Sie Ihre Git-Workflows mit Release Runbook. Überprüfen Sie den Repository-Zustand, führen Sie Tests aus und veröffentlichen Sie Versionen mit ...","pt":"Aprenda a configurar o release-runbook para automatizar o fluxo de trabalho de lançamento, incluindo verificação de estado do repositório e publicação de rel...","ru":"Узнайте, как настроить release-runbook для автоматизации релизов, включая проверку состояния репозитория и публикацию релизов на GitHub с помощью ИИ Агентов","ar":"تعلم كيفية إعداد release-runbook للتشغيل الآلي لتدفق العمل لإصدار البرامج، بما في ذلك التحقق من حالة المستودع ونشر الإصدارات على GitHub"},"definition":{"en":"release-runbook is a skill that automates the release workflow, executing tasks such as verifying repository state, running tests, and publishing GitHub releases.","zh":"Release Runbook是一种自动化工具，用于执行GitHub发布工作流","ja":"Release RunbookはGitHubリリースの自動化を実現するツール","ko":"Release Runbook은 깃허브 자동 릴리즈 워크플ロー 툴","es":"Release Runbook es una herramienta de AI Agent que automatiza el flujo de trabajo de Git","fr":"Release Runbook est un outil d''AI Agent qui automatise le workflow Git","de":"Release Runbook ist ein AI-Tool, das den Git-Workflow automatisiert","pt":"O que é release-runbook? É uma ferramenta que executa um fluxo de trabalho de lançamento automatizado.","ru":"Что такое release-runbook? Это инструмент, выполняющий автоматизированный релизный workflow.","ar":"ما هو release-runbook؟ هو أداة تنفذ تدفق العمل لإصدار البرامج آليًا"},"features":{"en":["Verifies repository state using `git status -s` and `git diff`","Runs tests and bumps versions using language runtimes","Publishes GitHub releases and updates downstream artifacts","Checks remote repository using `git remote -v`","Confirms GitHub authentication using `gh auth status`"],"zh":["自动检查代码库状态","运行测试和版本升级","自动发布GitHub Release","更新下游构件","支持git、gh、jq和语言运行时","确认远程仓库和当前分支"],"ja":["コードリポジトリの状態を自動的に確認","テストとバージョンを昇格","GitHubリリースの自動化","下流コンポーネントの更新","git、gh、jq、言語ランタイムのサポート","リモートリポジトリと現在のブランチの確認"],"ko":["자동으로 코드 저장소 상태 확인","테스트 실행 및 버전 업그레이드","깃허브 릴리즈 자동화","하위 구성 요소 업데이트","git, gh, jq 및 언어 런타임 지원","원격 저장소 및 현재 분기 확인"],"es":["Verificación del estado del repositorio con `git status -s` y `git diff`","Ejecución de pruebas y bump de versiones","Publicación de versiones en GitHub","Actualización de artefactos descendentes después de la creación de la etiqueta","Verificación de la autenticación de GitHub con `gh auth status`","Uso de herramientas como `git`, `gh` y `jq`"],"fr":["Vérification de l''état du référentiel avec `git status -s` et `git diff`","Exécution de tests et bump de versions","Publication de versions sur GitHub","Mise à jour des artefacts descendants après la création de l''étiquette","Vérification de l''authentification GitHub avec `gh auth status`","Utilisation d''outils tels que `git`, `gh` et `jq`"],"de":["Überprüfung des Repository-Zustands mit `git status -s` und `git diff`","Ausführung von Tests und Versionsbump","Veröffentlichung von Versionen auf GitHub","Aktualisierung von Downstream-Artefakten nach der Erstellung des Tags","Überprüfung der GitHub-Authentifizierung mit `gh auth status`","Verwendung von Tools wie `git`, `gh` und `jq`"],"pt":["Verificação de estado do repositório com `git status -s` e `git diff`","Confirmação de remote e branch atual com `git remote -v`","Verificação de autenticação do GitHub com `gh auth status`","Uso de ferramentas como `git`, `gh`, `jq` e linguagens de programação","Publicação de releases no GitHub"],"ru":["Проверка состояния репозитория с помощью `git status -s` и `git diff`","Подтверждение удаленного репозитория и текущей ветки с помощью `git remote -v`","Проверка аутентификации GitHub с помощью `gh auth status`","Использование инструментов seperti `git`, `gh`, `jq` и языков программирования","Публикация релизов на GitHub с помощью ИИ Агентов"],"ar":["التحقق من حالة المستودع باستخدام `git status -s` و `git diff`","التأكد من Remote والفرع الحالي باستخدام `git remote -v`","التحقق من مصادقة GitHub باستخدام `gh auth status`","استخدام أدوات مثل `git` و `gh` و `jq` ولغات البرمجة","نشر الإصدارات على GitHub"]},"keywords":{"en":["how to use release-runbook","release-runbook setup guide","automated release workflow","github release automation","release-runbook vs manual deployment","release-runbook install","what is release-runbook","release-runbook tutorial","release-runbook best practices"],"zh":["Release Runbook","GitHub自动化","代码库状态检查","自动化测试","版本升级","GitHub Release","AIエージェント","自动化发布工作流"],"ja":["Release Runbook","GitHub自動化","コードリポジトリの状態確認","自動テスト","バージョン昇格","GitHubリリース","AIエージェント","自動化されたリリースワークフロー"],"ko":["Release Runbook","깃허브 자동화","코드 저장소 상태 확인","자동 테스트","버전 업그레이드","깃허브 릴리즈","AI 에이전트","자동 릴리즈 워크플ロー"],"es":["Release Runbook","AI Agent","flujo de trabajo de Git","automatización de Git","herramientas de desarrollo","GitHub","Git","pruebas automatizadas","versiones de software"],"fr":["Release Runbook","AI Agent","workflow Git","automatisation Git","outils de développement","GitHub","Git","tests automatisés","versions de logiciel"],"de":["Release Runbook","AI-Tool","Git-Workflow","Git-Automatisierung","Entwicklungstools","GitHub","Git","automatisierte Tests","Software-Versionen"],"pt":["release-runbook","fluxo de trabalho de lançamento","automatização de lançamento","github","git","gh","jq","linguagens de programação","ferramentas de desenvolvimento"],"ru":["release-runbook","релизный workflow","автоматизация релизов","github","git","gh","jq","языки программирования","инструменты разработки","ИИ Агенты"],"ar":["release-runbook","تدفق العمل لإصدار البرامج","التشغيل الآلي لإصدار البرامج","github","git","gh","jq","لغات البرمجة","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"nibzard","repo":"looper","repoPath":"nibzard/looper","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"release-runbook","description":"Release preparation and publish workflow: run tests, bump version, tag, push, and create a GitHub release (and update Homebrew formula if present). Use when asked to cut a release, bump version, create tags, or publish a release.","bodyPreview":"# Release Runbook\n\n## Overview\nExecute a clean release workflow: verify repo state, run tests, bump versions, tag, push, publish a GitHub release, and update downstream artifacts after the tag exists.\n\n## Workflow\n\n### 1) Preflight\n- Check repo state: `git status -s` and `git diff` should be clean.\n- Confirm remote: `git remote -v` and current branch.\n- Verify GitHub auth: `gh auth status`.\n- Ensure required tools are available (`git`, `gh`, `jq`, language runtimes).\n\n### 2) Decide the version b","body":"# Release Runbook\n\n## Overview\nExecute a clean release workflow: verify repo state, run tests, bump versions, tag, push, publish a GitHub release, and update downstream artifacts after the tag exists.\n\n## Workflow\n\n### 1) Preflight\n- Check repo state: `git status -s` and `git diff` should be clean.\n- Confirm remote: `git remote -v` and current branch.\n- Verify GitHub auth: `gh auth status`.\n- Ensure required tools are available (`git`, `gh`, `jq`, language runtimes).\n\n### 2) Decide the version bump\n- Choose SemVer bump (major/minor/patch) based on changes.\n- Locate version references and update them before tagging:\n  - Common files: `VERSION`, `package.json`, `pyproject.toml`, `Cargo.toml`, `go.mod`, `setup.cfg`, `setup.py`, `Formula/*.rb` (url only), `README.md` badges.\n  - Use `rg -n \"version|VERSION|__version__\"` to find references.\n\n### 3) Run tests (or a documented smoke test)\n- Prefer project-defined tests (README/Makefile/CI):\n  - `make test`, `npm test`, `pytest`, `go test ./...`, etc.\n- If no tests exist, run a minimal smoke check and record it in the release notes.\n- Looper-specific smoke check (if repo contains `bin/looper.sh`):\n  - Create a temp project, set `MAX_ITERATIONS` low, run the loop, and verify it exits cleanly.\n\n### 4) Commit release changes\n- Stage and commit all changes required for the release.\n- Keep commit messages Conventional Commits unless the repo specifies otherwise.\n\n### 5) Tag and push\n- Create an annotated tag on the release commit:\n  - `git tag -a vX.Y.Z -m \"vX.Y.Z\"`\n- Push code and tag:\n  - `git push origin <branch>`\n  - `git push origin vX.Y.Z`\n\n### 6) Publish GitHub release\n- Create a release from the tag:\n  - `gh release create vX.Y.Z --title \"vX.Y.Z\" --notes \"<summary>\"`\n\n### 7) Update Homebrew formula (if present)\n- Only after the release tag exists (tarball is published).\n- Compute the new sha:\n  - `curl -L -s https://github.com/<org>/<repo>/archive/refs/tags/vX.Y.Z.tar.gz | sha256sum | awk ''{print $1}''`\n- Update `Formula/*.rb` with the new `url` and `sha256`.\n- Commit and push the formula update.\n\n## Notes\n- Tag should point to the release commit; formula updates are separate and can land after the tag.\n- If tests fail, stop and fix before tagging.\n- Keep release notes short and factual (highlights + testing performed).\n\n## Helper Script\nUse `scripts/release.sh` to automate the end-to-end release flow.\n\nExamples:\n```bash\n# Tag, push, release, and update Formula/*.rb\nscripts/release.sh --version 0.2.0 --test-cmd \"make test\"\n\n# Use a custom bump command and a VERSION file\nscripts/release.sh --version 1.4.0 --bump-cmd \"npm version minor --no-git-tag-version\" --version-file VERSION\n```\n\nNotes:\n- `--version-file` overwrites files with the raw version string (no leading `v`).\n- Formula updates are performed after the tag exists; set `--skip-formula` to skip.\n- Use `--dry-run` to preview commands without executing.\n"},"lastSynced":"2026-03-08T02:04:29.799Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined GitHub release automation and version management.","zh":"适用于需要简化 GitHub 发布自动化和版本管理的 DevOps 代理。","ja":"GitHub リリースの自動化とバージョン管理をストリームライン化する必要がある DevOps エージェントに適しています。","ko":"GitHub 출시 자동화 및 버전 관리를 간소화해야 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren una automatización de lanzamiento de GitHub y una gestión de versiones optimizadas.","fr":"Idéal pour les agents DevOps nécessitant une automatisation de publication GitHub et une gestion de version simplifiée.","de":"Ideal für DevOps-Agents, die eine optimierte GitHub-Release-Automatisierung und Versionsverwaltung benötigen.","pt":"Ideal para Agentes DevOps que exigem automação de lançamento do GitHub e gerenciamento de versão simplificados.","ru":"Идеально подходит для агентов DevOps, требующих упрощенной автоматизации выпуска GitHub и управления версиями.","ar":"مثالي للوكلاء DevOps الذين يطلبون تسهيل آلي لإصدار GitHub وإدارة الإصدار."},"recommendation":{"en":"Empowers agents to automate the release workflow by verifying repository states, running tests, bumping versions, and publishing GitHub releases using tools like `git`, `gh`, and `jq`.","zh":"赋予代理自动执行发布工作流的能力，通过验证仓库状态、运行测试、增加版本并使用 `git`、`gh`、`jq` 等工具发布 GitHub 发布。","ja":"エージェントが `git`、`gh`、`jq` などのツールを使用して、リポジトリ状態の検証、テストの実行、バージョンの増分、GitHub リリースの公開など、リリースワークフローを自動化する機能を提供します。","ko":"에이전트가 `git`, `gh`, `jq`などの 도구를 사용하여 리포지토리 상태의検증, 테스트의 실행, 버전의 증분, GitHub 출시의 게시 등 릴리스 워크플로를 자동화할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a automatizar el flujo de trabajo de lanzamiento verificando estados de repositorio, ejecutando pruebas, aumentando versiones y publicando lanzamientos de GitHub utilizando herramientas como `git`, `gh` y `jq`.","fr":"Permet aux agents d''automatiser le flux de travail de publication en vérifiant les états de référentiel, en exécutant des tests, en incrémentant les versions et en publiant des versions GitHub à l''aide d''outils tels que `git`, `gh` et `jq`.","de":"Ermächtigt die Agenten, den Release-Workflow zu automatisieren, indem sie Repository-Zustände überprüfen, Tests ausführen, Versionen erhöhen und GitHub-Veröffentlichungen mit Tools wie `git`, `gh` und `jq` veröffentlichen.","pt":"Habilita os agentes a automatizar o fluxo de trabalho de lançamento, verificando estados de repositório, executando testes, aumentando versões e publicando lançamentos do GitHub usando ferramentas como `git`, `gh` e `jq`.","ru":"Наделяет агентов возможностью автоматизировать рабочий процесс выпуска, проверяя состояние репозитория, выполняя тесты, увеличивая версии и публикуя выпуски GitHub с помощью инструментов seperti `git`, `gh` и `jq`.","ar":"يمكن الوكلاء من ت 자동 hóa تدفق عمل الإصدار من خلال التحقق من حالة المستودع وتشغيل الاختبارات وزيادة الإصدارات ونشر إصدارات GitHub باستخدام أدوات مثل `git` و `gh` و `jq`."},"useCases":{"en":["Automating the verification of repository states before release","Streamlining the testing and version bumping process for GitHub releases","Publishing GitHub releases and updating downstream artifacts efficiently"],"zh":["自动执行发布前仓库状态的验证","简化 GitHub 发布的测试和版本增加过程","高效地发布 GitHub 发布并更新下游工件"],"ja":["リリース前にリポジトリ状態の検証を自動化する","GitHub リリースのテストとバージョンの増分プロセスをストリームライン化する","GitHub リリースを効率的に公開し、ダウンストリームのアーティファクトを更新する"],"ko":["릴리스 전에 리포지토리 상태의 검증을 자동화합니다","GitHub 릴리스의 테스트와 버전 증분 프로세스를 간소화합니다","GitHub 릴리스를 효율적으로 게시하고 하류 아티팩트를 업데이트합니다"],"es":["Automatizar la verificación de estados de repositorio antes del lanzamiento","Optimizar el proceso de pruebas y aumento de versiones para lanzamientos de GitHub","Publicar lanzamientos de GitHub y actualizar artefactos posteriores de manera eficiente"],"fr":["Automatiser la vérification des états de référentiel avant la publication","Optimiser le processus de tests et d''incrémentation de version pour les publications GitHub","Publier des versions GitHub et mettre à jour des artefacts en aval de manière efficace"],"de":["Automatisieren der Überprüfung von Repository-Zuständen vor dem Release","Optimieren des Test- und Versions-Inkrementierungsprozesses für GitHub-Veröffentlichungen","Veröffentlichen von GitHub-Veröffentlichungen und effizientes Aktualisieren von Downstream-Artefakten"],"pt":["Automatizar a verificação de estados de repositório antes do lançamento","Simplificar o processo de teste e aumento de versão para lançamentos do GitHub","Publicar lançamentos do GitHub e atualizar artefatos downstream de forma eficiente"],"ru":["Автоматизировать проверку состояния репозитория перед выпуском","Упростить процесс тестирования и увеличения версии для выпусков GitHub","Публиковать выпуски GitHub и обновлять артефакты downstream эффективно"],"ar":["تأتمتة التحقق من حالة المستودع قبل الإصدار","تبسيط عملية الاختبار وزيادة الإصدار لإصدارات GitHub","نشر إصدارات GitHub وتحديث المكونات الأساسية بفعالية"]},"limitations":{"en":["Requires GitHub authentication","Needs `git`, `gh`, `jq`, and language runtimes to be available","Limited to GitHub releases"],"zh":["需要 GitHub 身份验证","需要 `git`、`gh`、`jq` 和语言运行时可用","仅限 GitHub 发布"],"ja":["GitHub 認証が必要","`git`、`gh`、`jq`、および言語ランタイムが利用可能である必要がある","GitHub リリースのみに限定される"],"ko":["GitHub 인증이 필요합니다","`git`, `gh`, `jq` 및 언어 런타임이 사용 가능해야 합니다","GitHub 릴리스에만 제한됩니다"],"es":["Requiere autenticación de GitHub","Necesita que `git`, `gh`, `jq` y los entornos de ejecución de lenguaje estén disponibles","Limitado a lanzamientos de GitHub"],"fr":["Nécessite une authentification GitHub","Nécessite que `git`, `gh`, `jq` et les runtime de langage soient disponibles","Limité aux publications GitHub"],"de":["Benötigt GitHub-Authentifizierung","Benötigt, dass `git`, `gh`, `jq` und Sprachlauffzeiten verfügbar sind","Begrenzt auf GitHub-Veröffentlichungen"],"pt":["Exige autenticação do GitHub","Precisa que `git`, `gh`, `jq` e ambientes de execução de linguagem estejam disponíveis","Limitado a lançamentos do GitHub"],"ru":["Требует аутентификации GitHub","Требует наличия `git`, `gh`, `jq` и сред выполнения языка","Ограничен выпусками GitHub"],"ar":["يتطلب مصادقة GitHub","يحتاج إلى توفر `git` و `gh` و `jq` وبيئات تشغيل اللغة","محدود بالإصدارات GitHub"]},"version":4},"contentHash":"f6f54d14e8c5c2d477de2d31a52251759379c087437e95fc7078351823f8ea0d","qualityScore":36}');
