INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nehemiaharchives/lucene-kmp/port', 'port', 'nehemiaharchives', 'lucene-kmp', 'community', 'port nehemiaharchives lucene-kmp community The Port skill enables the integration of Apache Lucene with Kotlin Multiplatform, supporting Kotlin/Android, Kotlin/Native, and Kotlin/JVM. It benefits developers seeking a multiplatform library. Apache Lucene 的 Kotlin Multiplatform 端口开发，实现跨平台支持 Apache Lucene の Kotlin Multiplatform ポート開発は、Android、Native、JVM のサポートを実現します Apache Lucene의 Kotlin Multiplatform 포트 개발은 Android, Native, JVM을 지원하는 크로스 플랫폼 솔루션을 제공합니다 Apache Lucene Port es una biblioteca multiplataforma para Kotlin que admite Kotlin/Android, Kotlin/Native y Kotlin/JVM Apache Lucene Port est une bibliothèque multiplateforme pour Kotlin qui prend en charge Kotlin/Android, Kotlin/Native et Kotlin/JVM Apache Lucene Port ist eine Multiplattform-Bibliothek für Kotlin, die Kotlin/Android, Kotlin/Native und Kotlin/JVM unterstützt O port Apache Lucene para Kotlin Multiplatform permite o desenvolvimento de bibliotecas multiplataforma Порт Apache Lucene для Kotlin Multiplatform позволяет разрабатывать многоплатформенные библиотеки منفذ Apache Lucene لمنصة Kotlin المتعددة يسمح بتطوير مكتبات متعددة المنصات how to use port with Kotlin Multiplatform what is port in Apache Lucene port alternative for Java port vs Elasticsearch port install guide for Kotlin/Android port setup for Kotlin/Native Apache Lucene Kotlin Multiplatform 跨平台开发 Android 开发 Native 开发 JVM 开发 Lucene-KMP Kotlin 开发 Ports Apache Lucene from Java to Kotlin common for multiplatform support Supports Kotlin/Android, Kotlin/Native(iOS, macOS, Linux), and Kotlin/JVM(desktop and server) Utilizes the `lucene/lucene/core/src/java/org/apache/lucene/` package structure Includes unit tests in the `lucene/lucene/core/src/test/org/apache/lucene/` package Enables the creation of a multiplatform library `lucene-kmp` Port is a Kotlin Multiplatform library that ports Apache Lucene from Java to platform-agnostic Kotlin common');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cjprybol/Mycelia/julia-style', 'community', 'cjprybol', 'Mycelia', 'cjprybol/Mycelia', 'julia-style', 0, 0, 36, '2026-03-08T01:57:15.371Z', '2026-03-08T02:05:38.381Z', '770ba80670fa4e052c42a5480a09c41937c5fc75aa8d6f26565300fb8568a7b4', '{"id":"cjprybol/Mycelia/julia-style","name":"julia-style","description":{"en":"julia-style is a strict coding standard for multiomic analysis and data integration, designed for Linux-based HPC and cloud systems, benefiting developers and researchers in biological characterization, prediction, and design.","zh":"Julia 风格编码是一种严格的编码标准，用于生物学数据分析和多组学研究，旨在提高代码质量和可读性","ja":"Julia スタイルコーディングは、生物学データ分析と多オミクス研究のために、厳格なコーディング規則を提供することで、コードの品質と可読性を向上させることを目的としています","ko":"Julia 스타일 코딩은 생물학 데이터 분석과 멀티오믹스 연구를 위한 엄격한 코딩 규칙을 제공하여 코드의 품질과 가독성을 향상시키는 것을 목적으로 합니다","es":"julia-style es un estilo de codificación para análisis multiómico y integración de datos en sistemas Linux","fr":"julia-style est un style de codage pour l''analyse multiomique et l''intégration de données sur les systèmes Linux","de":"julia-style ist ein Codierstil für die Multiomikanalyse und Datenintegration in Linux-Systemen","pt":"O estilo Julia é uma abordagem para análise multiômica e integração de dados em sistemas Linux-based HPC e cloud","ru":"Стиль Julia - это подход для многоомной аналитики и интеграции данных в системах HPC и облаке на основе Linux","ar":"أسلوب جوليا هو نهج لتحليل البيانات البيولوجية المتعددة وتكامل البيانات في أنظمة الحوسبة عالية الأداء وسحب البيانات التي تعمل بنظام لينكس"},"seo":{"title":{"en":"julia-style: Coding Style Guide for AI Agents | AI Agent ...","zh":"Julia 风格编码指南：生物学数据分析最佳实践","ja":"Julia スタイルガイド：生物学データ分析のためのベストプラクティス","ko":"Julia 스타일 코딩 가이드: 생물학 데이터 분석을 위한最佳实践","es":"Guía de configuración de julia-style para análisis multió...","fr":"Guide de mise en place de julia-style pour l''analyse mult...","de":"Einrichtungsleitfaden für julia-style zur Multiomikanalyse","pt":"Guia de Configuração do Estilo Julia para Análise Multiômica","ru":"Настройка стиля Julia для многоомной аналитики и ИИ Агентов","ar":"دليل تنصيب أسلوب جوليا لتحليل البيانات البيولوجية المتعددة"},"description":{"en":"Unlock efficient multiomic analysis with julia-style. Discover how to integrate data for biological characterization, prediction, and design on Linux-based H...","zh":"了解 Julia 风格编码的重要性和应用，特别是在生物学数据分析和多组学研究领域","ja":"Julia スタイルコーディングの重要性と生物学データ分析、多オミクス研究におけるその応用について学びましょう","ko":"Julia 스타일 코딩의 중요성과 생물학 데이터 분석, 멀티오믹스 연구 분야에서의 적용에 대해 알아보세요","es":"Aprenda a configurar julia-style para análisis biológicos avanzados en sistemas HPC y cloud","fr":"Découvrez comment configurer julia-style pour l''analyse biologique avancée sur les systèmes HPC et cloud","de":"Erfahren Sie, wie Sie julia-style für fortschrittliche biologische Analysen in HPC- und Cloud-Systemen einrichten","pt":"Aprenda a configurar o estilo Julia para análise multiômica e integração de dados em sistemas HPC e cloud","ru":"Узнайте, как настроить стиль Julia для многоомной аналитики и интеграции данных в системах HPC и облаке с помощью ИИ Агентов","ar":"تعلم كيفية تنصيب أسلوب جوليا لتحليل البيانات البيولوجية المتعددة وتكامل البيانات في أنظمة الحوسبة عالية الأداء وسحب البيانات"},"definition":{"en":"julia-style is a set of coding rules for the Mycelia repository, enforcing strict import rules, fully qualified names, and no shorthand aliases for efficient coding.","zh":"Julia 风格编码是一种编码标准，用于生物学数据分析和多组学研究，强调严格的编码规则和命名约定","ja":"Julia スタイルコーディングは、生物学データ分析と多オミクス研究のためのコーディング規則であり、厳格なコーディング規則と命名規約を重視しています","ko":"Julia 스타일 코딩은 생물학 데이터 분석과 멀티오믹스 연구를 위한 코딩 규칙으로, 엄격한 코딩 규칙과 명명 규약을 강조합니다","es":"julia-style es un conjunto de reglas de codificación para análisis biológicos en Julia","fr":"julia-style est un ensemble de règles de codage pour l''analyse biologique en Julia","de":"julia-style ist eine Sammlung von Codierregeln für biologische Analysen in Julia","pt":"O estilo Julia é um conjunto de regras de codificação para análise multiômica e integração de dados","ru":"Стиль Julia - это набор правил кодирования для многоомной аналитики и интеграции данных","ar":"أسلوب جوليا هو مجموعة من قواعد البرمجة لتحليل البيانات البيولوجية المتعددة وتكامل البيانات"},"features":{"en":["Enforces strict import rules using `import` instead of `using`","Requires fully qualified names, such as `Mycelia.Rhizomorph`","Prohibits shorthand aliases, ensuring clarity and readability","Supports dependencies imported at top-level in `src/Mycelia.jl`","Ensures consistency across all source files"],"zh":["严格的导入规则，禁止使用 `using`","完全限定命名，避免缩写别名","依赖项导入在顶级文件 `src/Mycelia.jl` 中","支持 Linux 基础的 HPC 和云系统","用于生物学数据分析和多组学研究"],"ja":["厳格なインポート規則、`using` の使用禁止","完全修飾された命名、省略形の別名を避ける","依存関係のインポートはトップレベルのファイル `src/Mycelia.jl` における","LinuxベースのHPCとクラウドシステムをサポート","生物学データ分析と多オミクス研究のために使用"],"ko":["엄격한 임포트 규칙, `using` 사용 금지","완전 한정된 명명, 축약형 별名 피하기","의존성 임포트는 최상위 파일 `src/Mycelia.jl` 에서","Linux 기반의 HPC와 클라우드 시스템 지원","생물학 데이터 분석과 멀티오믹스 연구를 위한"],"es":["Importación estricta de dependencias","Uso de nombres completamente calificados","Evitación de alias abreviados","Compatibilidad con sistemas HPC y cloud","Análisis multiómico avanzado"],"fr":["Importation stricte des dépendances","Utilisation de noms entièrement qualifiés","Évitement des alias abrégés","Compatibilité avec les systèmes HPC et cloud","Analyse multiomique avancée"],"de":["Strenge Importierung von Abhängigkeiten","Verwendung von vollständig qualifizierten Namen","Vermeidung von Abkürzungs-Aliasen","Kompatibilität mit HPC- und Cloud-Systemen","Fortschrittliche Multiomikanalyse"],"pt":["Importação de dependências no nível superior em src/Mycelia.jl","Uso de nomes totalmente qualificados, como Mycelia.Rhizomorph","Proibição do uso de aliases abreviados, como R = Mycelia.Rhizomorph","Uso de import em vez de using","Análise multiômica e integração de dados em sistemas HPC e cloud"],"ru":["Импорт зависимостей на верхнем уровне в src/Mycelia.jl","Использование полностью квалифицированных имен, таких как Mycelia.Rhizomorph","Запрет на использование сокращенных псевдонимов, таких как R = Mycelia.Rhizomorph","Использование import вместо using","Многоомная аналитика и интеграция данных в системах HPC и облаке с помощью ИИ Агентов"],"ar":["استيراد التبعيات في المستوى الأعلى في src/Mycelia.jl","استخدام الأسماء المؤهلة بالكامل، مثل Mycelia.Rhizomorph","منع استخدام الأسماء المستعارة المختصرة، مثل R = Mycelia.Rhizomorph","استخدام import بدلاً من using","تحليل البيانات البيولوجية المتعددة وتكامل البيانات في أنظمة الحوسبة عالية الأداء وسحب البيانات"]},"keywords":{"en":["how to use julia-style","julia-style coding rules","julia-style vs other coding styles","julia-style install guide","julia-style setup for Linux-based HPC","multiomic analysis with julia-style","julia-style for biological characterization","julia-style alternative for cloud systems"],"zh":["Julia 编码风格","生物学数据分析","多组学研究","Linux HPC","云系统","依赖项管理","命名约定","AI 工具","AI エージェント"],"ja":["Julia スタイルコーディング","生物学データ分析","多オミクス研究","Linux HPC","クラウドシステム","依存関係管理","命名規約","AI エージェント","AI ツール"],"ko":["Julia 스타일 코딩","생물학 데이터 분석","멀티오믹스 연구","Linux HPC","클라우드 시스템","의존성 관리","명명 규약","AI 에이전트","AI 툴"],"es":["julia-style","análisis multiómico","integración de datos","sistemas HPC","cloud computing","codificación en Julia","reglas de codificación","análisis biológico","herramientas de AI","agentes de IA"],"fr":["julia-style","analyse multiomique","intégration de données","systèmes HPC","informatique cloud","codage en Julia","règles de codage","analyse biologique","outils d''IA","agents d''IA"],"de":["julia-style","Multiomikanalyse","Datenintegration","HPC-Systeme","Cloud-Computing","Codierung in Julia","Codierregeln","biologische Analyse","AI-Tools","KI-Agents"],"pt":["estilo julia","análise multiômica","integração de dados","sistemas HPC","sistemas cloud","linguagem julia","codificação julia","regras de codificação julia"],"ru":["стиль julia","многоомная аналитика","интеграция данных","системы HPC","системы облаке","язык julia","кодирование julia","правила кодирования julia","ИИ Агенты"],"ar":["أسلوب جوليا","تحليل البيانات البيولوجية المتعددة","تكامل البيانات","أنظمة الحوسبة عالية الأداء","أنظمة سحب البيانات","لغة جوليا","برمجة جوليا","قواعد البرمجة جوليا"]}},"owner":"cjprybol","repo":"Mycelia","repoPath":"cjprybol/Mycelia","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"julia-style","description":"Julia coding style and import rules for Mycelia package","bodyPreview":"# Mycelia Julia Coding Style\n\nWhen working in the Mycelia repository, follow these strict coding rules.\n\n## Import Rules (STRICT)\n\n- **NEVER use `using`** - always use `import`\n- **Fully qualify all names** - use `Mycelia.Rhizomorph`, `DataFrames.DataFrame()`, etc.\n- **No shorthand aliases** - avoid `R = Mycelia.Rhizomorph`; use full qualified names\n- Dependencies are imported at top-level in `src/Mycelia.jl` and available in all source files\n\nExample:\n```julia\n# WRONG\nusing DataFrames\ndf = Data","body":"# Mycelia Julia Coding Style\n\nWhen working in the Mycelia repository, follow these strict coding rules.\n\n## Import Rules (STRICT)\n\n- **NEVER use `using`** - always use `import`\n- **Fully qualify all names** - use `Mycelia.Rhizomorph`, `DataFrames.DataFrame()`, etc.\n- **No shorthand aliases** - avoid `R = Mycelia.Rhizomorph`; use full qualified names\n- Dependencies are imported at top-level in `src/Mycelia.jl` and available in all source files\n\nExample:\n```julia\n# WRONG\nusing DataFrames\ndf = DataFrame()\n\n# WRONG\nimport DataFrames: DataFrame\ndf = DataFrame()\n\n# CORRECT\nimport DataFrames\ndf = DataFrames.DataFrame()\n```\n\n## Naming Conventions\n\n- **Modules**: CamelCase (e.g., `Rhizomorph`, `KmerAnalysis`)\n- **Functions/Variables**: snake_case (e.g., `process_sequences`, `kmer_count`)\n- **Constants**: SCREAMING_SNAKE_CASE (e.g., `MAX_KMER_SIZE`)\n- **No emojis** in code or comments\n\n## Sequence Types (BioSequences)\n\nAlways use proper BioSequences types:\n- `BioSequences.LongDNA{4}` for DNA\n- `BioSequences.LongRNA{4}` for RNA\n- `BioSequences.LongAA` for amino acids\n\nExtract from FASTQ:\n```julia\nFASTX.sequence(BioSequences.LongDNA{4}, record)\n```\n\nAvoid string conversions in k-mer graphs, qualmer graphs, and assembly algorithms. Use `string()` only for external tool interfaces or final output.\n\n## Formatting\n\n- 4-space indentation\n- Clear docstrings: `\"\"\"signature...\"\"\"`\n- Prefer pure functions and explicit keyword arguments\n- Use `joinpath` for file paths (portability)\n- Avoid type piracy\n\nDefault formatter: JuliaFormatter.jl with SciMLStyle or BlueStyle, unless repo indicates Runic.jl.\n\n## Architecture Notes\n\n- Main module uses dynamic file inclusion\n- All `.jl` files in `src/` are auto-included via `Mycelia.jl`\n- Rhizomorph and Mycelia do NOT export symbols by design\n- Tests and callers MUST use fully qualified names\n"},"lastSynced":"2026-03-08T02:05:38.381Z","agentAnalysis":{"suitability":{"en":"Perfect for Multiomic Analysis Agents needing strict coding standards for Linux-based HPC and cloud systems.","zh":"非常适合需要严格编码标准的Linux 기반 HPC 和云系统的多组学分析代理。","ja":"マルチオミクス分析エージェントがLinuxベースのHPCおよびクラウドシステムに厳格なコーディング標準を必要とする場合に最適です。","ko":"Linux 기반 HPC 및 클라우드 시스템에 엄격한 코딩 표준이 필요한 멀티 오믹스 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis Multiómico que necesitan estrictas normas de codificación para sistemas HPC y cloud basados en Linux.","fr":"Parfait pour les Agents d''Analyse Multiomique nécessitant des normes de codage strictes pour les systèmes HPC et cloud basés sur Linux.","de":"Perfekt für Multiomik-Analyse-Agents, die strenge Codierungsstandards für Linux-basierte HPC- und Cloud-Systeme benötigen.","pt":"Perfeito para Agentes de Análise Multiômica que necessitam de padrões de codificação estritos para sistemas HPC e cloud baseados em Linux.","ru":"Идеально подходит для агентов анализа мультиомики, требующих строгих стандартов кодирования для систем HPC и облачных систем на основе Linux.","ar":"مثالي للوكلاء تحليل متعدد الأوميكس الذين يحتاجون إلى معايير ترميز صارمة لأنظمة HPC والسحابة المستندة إلى لينكس."},"recommendation":{"en":"Empowers agents to enforce a strict Julia coding standard, utilizing fully qualified names and avoiding shorthand aliases, ensuring seamless integration with DataFrames and Mycelia repositories over import protocols.","zh":"赋予代理执行严格的Julia编码标准，利用完全限定名称，避免简写别名，确保与DataFrames和Mycelia存储库之间的无缝集成，通过导入协议实现。","ja":"エージェントに厳格なJuliaコーディング標準を実施する権限を与え、完全修飾名を使用し、ショートハンドエイリアスを避け、インポートプロトコルを介してDataFramesおよびMyceliaリポジトリとの統合をスムーズに行うことができます。","ko":"에이전트가 엄격한 Julia 코딩 표준을 강제할 수 있도록 하며, 완전히限定된 이름을 사용하고 축약형 별칭을 피하여, DataFrames 및 Mycelia 저장소와의 통합을 import 프로토콜을 통해 원활하게 수행할 수 있습니다.","es":"Habilita a los agentes para hacer cumplir un estricto estándar de codificación de Julia, utilizando nombres completamente calificados y evitando alias abreviados, garantizando una integración sin problemas con los repositorios de DataFrames y Mycelia a través de protocolos de importación.","fr":"Permet aux agents d''appliquer une norme de codage Julia stricte, en utilisant des noms entièrement qualifiés et en évitant les alias abrégés, assurant une intégration sans problème avec les référentiels de DataFrames et Mycelia via des protocoles d''importation.","de":"Ermächtigt die Agents, einen strengen Julia-Codierungsstandard durchzusetzen, indem sie voll qualifizierte Namen verwenden und Abkürzungs-Aliase vermeiden, um eine nahtlose Integration mit DataFrames- und Mycelia-Repositorys über Importprotokolle sicherzustellen.","pt":"Habilita os agentes a impor um padrão de codificação Julia estrito, utilizando nomes totalmente qualificados e evitando aliases abreviados, garantindo integração perfeita com repositórios DataFrames e Mycelia sobre protocolos de importação.","ru":"Наделяет агентов возможностью реализовать строгий стандарт кодирования Julia, используя полностью квалифицированные имена и избегая сокращенных псевдонимов, обеспечивая бесшовную интеграцию с репозиториями DataFrames и Mycelia по протоколам импорта.","ar":"تمكن الوكلاء من فرض معيار ترميز Julia صارم ، باستخدام أسماء مؤهلة بالكامل وتجنب الأسماء المستعارة المختصرة ، مما يضمن تكاملًا مثاليًا مع مستودعات DataFrames و Mycelia عبر بروتوكولات الاستيراد."},"useCases":{"en":["Enforcing strict coding standards for multiomic data analysis","Importing dependencies at top-level for unified access","Avoiding shorthand aliases for improved code readability"],"zh":["执行多组学数据分析的严格编码标准","在顶级导入依赖项以实现统一访问","避免简写别名以提高代码可读性"],"ja":["マルチオミクスデータ分析の厳格なコーディング標準の適用","統一されたアクセスを実現するためにトップレベルで依存関係をインポートする","コードの可読性を向上させるためにショートハンドエイリアスを避ける"],"ko":["멀티 오믹스 데이터 분석을 위한 엄격한 코딩 표준 적용","통합된 접근을 위해 최상위 수준에서 의존성을 import하는 것","코드의 가독성을 개선하기 위해 축약형 별칭을 피하는 것"],"es":["Hacer cumplir estrictas normas de codificación para el análisis de datos multiómicos","Importar dependencias a nivel superior para acceso unificado","Evitar alias abreviados para mejorar la legibilidad del código"],"fr":["Faire respecter des normes de codage strictes pour l''analyse de données multiomiques","Importer des dépendances au niveau supérieur pour un accès unifié","Éviter les alias abrégés pour améliorer la lisibilité du code"],"de":["Durchsetzen strenger Codierungsstandards für die Multiomik-Datenanalyse","Importieren von Abhängigkeiten auf oberster Ebene für einheitlichen Zugriff","Vermeiden von Abkürzungs-Aliassen für verbesserte Code-Lesbarkeit"],"pt":["Impor padrões de codificação estritos para análise de dados multiômica","Importar dependências no nível superior para acesso unificado","Evitar aliases abreviados para melhorar a legibilidade do código"],"ru":["Внедрение строгих стандартов кодирования для анализа мультиомических данных","Импорт зависимостей на верхнем уровне для унифицированного доступа","Избежание сокращенных псевдонимов для улучшения читаемости кода"],"ar":["تطبيق معايير ترميز صارمة لتحليل البيانات متعددة الأوميكس","استيراد التبعيات على المستوى العلوي للوصول الموحد","تجنب الأسماء المستعارة المختصرة لتحسين قراءة الكود"]},"limitations":{"en":["Requires adherence to strict import rules","Linux-based HPC and cloud systems only","Julia programming language only"],"zh":["需要遵守严格的导入规则","仅限Linux 기반 HPC 和云系统","仅限Julia编程语言"],"ja":["厳格なインポート規則の遵守が必要","LinuxベースのHPCおよびクラウドシステムのみ","Juliaプログラミング言語のみ"],"ko":["엄격한 import 규칙을 준수해야 함","Linux 기반 HPC 및 클라우드 시스템만","Julia 프로그래밍 언어만"],"es":["Requiere adherirse a reglas de importación estrictas","Sistemas HPC y cloud basados en Linux solo","Lenguaje de programación Julia solo"],"fr":["Nécessite de respecter des règles d''importation strictes","Systèmes HPC et cloud basés sur Linux uniquement","Langage de programmation Julia uniquement"],"de":["Erfordert die Einhaltung strenger Importregeln","Nur Linux-basierte HPC- und Cloud-Systeme","Nur Julia-Programmiersprache"],"pt":["Exige adesão a regras de importação estritas","Apenas sistemas HPC e cloud baseados em Linux","Apenas linguagem de programação Julia"],"ru":["Требует соблюдения строгих правил импорта","Только системы HPC и облачные системы на основе Linux","Только язык программирования Julia"],"ar":["يتطلب الامتثال للقواعد الصارمة للاستيراد","نظم HPC والسحابة المستندة إلى لينكس فقط","لغة برمجة Julia فقط"]},"version":4},"contentHash":"770ba80670fa4e052c42a5480a09c41937c5fc75aa8d6f26565300fb8568a7b4","qualityScore":36}');
