INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cjprybol/Mycelia/julia-style', 'julia-style', 'cjprybol', 'Mycelia', 'community', 'julia-style cjprybol Mycelia community julia-style is a strict coding standard for multiomic analysis and data integration, designed for Linux-based HPC and cloud systems, benefiting developers and researchers in biological characterization, prediction, and design. Julia 风格编码是一种严格的编码标准，用于生物学数据分析和多组学研究，旨在提高代码质量和可读性 Julia スタイルコーディングは、生物学データ分析と多オミクス研究のために、厳格なコーディング規則を提供することで、コードの品質と可読性を向上させることを目的としています Julia 스타일 코딩은 생물학 데이터 분석과 멀티오믹스 연구를 위한 엄격한 코딩 규칙을 제공하여 코드의 품질과 가독성을 향상시키는 것을 목적으로 합니다 julia-style es un estilo de codificación para análisis multiómico y integración de datos en sistemas Linux julia-style est un style de codage pour l''analyse multiomique et l''intégration de données sur les systèmes Linux julia-style ist ein Codierstil für die Multiomikanalyse und Datenintegration in Linux-Systemen O estilo Julia é uma abordagem para análise multiômica e integração de dados em sistemas Linux-based HPC e cloud Стиль Julia - это подход для многоомной аналитики и интеграции данных в системах HPC и облаке на основе Linux أسلوب جوليا هو نهج لتحليل البيانات البيولوجية المتعددة وتكامل البيانات في أنظمة الحوسبة عالية الأداء وسحب البيانات التي تعمل بنظام لينكس how to use julia-style julia-style coding rules julia-style vs other coding styles julia-style install guide julia-style setup for Linux-based HPC multiomic analysis with julia-style julia-style for biological characterization julia-style alternative for cloud systems Julia 编码风格 生物学数据分析 多组学研究 Linux HPC 云系统 依赖项管理 命名约定 AI 工具 AI エージェント Enforces strict import rules using `import` instead of `using` Requires fully qualified names, such as `Mycelia.Rhizomorph` Prohibits shorthand aliases, ensuring clarity and readability Supports dependencies imported at top-level in `src/Mycelia.jl` Ensures consistency across all source files julia-style is a set of coding rules for the Mycelia repository, enforcing strict import rules, fully qualified names, and no shorthand aliases for efficient coding.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AlabamaMike/copilot-agents/defense-in-depth', 'community', 'AlabamaMike', 'copilot-agents', 'AlabamaMike/copilot-agents', 'defense-in-depth', 0, 0, 36, '2026-03-08T01:57:15.382Z', '2026-03-08T02:05:41.425Z', '7f4f533e6c372aa678bc6c778dad2dd99e61514cb048cfeeab760d65d911a803', '{"id":"AlabamaMike/copilot-agents/defense-in-depth","name":"defense-in-depth","description":{"en":"The defense-in-depth skill provides custom agents for GH copilot, enabling developers to validate data at every layer, making bugs structurally impossible. This benefits developers working with complex data validation.","zh":"深度防御是一种安全策略，通过在每个层级验证数据来防止bug和安全漏洞","ja":"ディフェンス・イン・デプスは、毎層でデータを検証してバグやセキュリティ漏洞を防ぐセキュリティ戦略です","ko":"심층 방어는 모든 계층에서 데이터를 검증하여 버그와 보안 취약점을 방지하는 보안 전략입니다","es":"La defensa en profundidad es una estrategia de seguridad que valida los datos en cada capa para evitar vulnerabilidades. Aprende a implementarla en tus proyectos de desarrollo","fr":"La défense en profondeur est une stratégie de sécurité qui valide les données à chaque couche pour éviter les vulnérabilités. Découvrez comment l''implémenter dans vos projets de développement","de":"Die Verteidigung in der Tiefe ist eine Sicherheitsstrategie, die Daten in jeder Ebene validiert, um Schwachstellen zu vermeiden. Erfahren Sie, wie Sie sie in Ihren Entwicklungsprojekten implementieren","pt":"A defesa em profundidade é uma técnica de validação de dados que garante a segurança e a integridade dos dados em múltiplas camadas","ru":"Защита в глубину - это метод проверки данных, обеспечивающий безопасность и целостность данных на нескольких уровнях","ar":"الدفاع بالعمق هو تقنية للتحقق من البيانات تضمن أمان البيانات وسلامتها على مستويات متعددة"},"seo":{"title":{"en":"Defense-in-Depth: Validation Setup Guide | AI Agent Skill","zh":"深度防御设置指南 -Defense-in-Depth","ja":"ディフェンス・イン・デプス設定ガイド - AIエージェント","ko":"심층 방어 설정 가이드 - Defense-in-Depth","es":"Guía de implementación de defensa en profundidad para age...","fr":"Guide de configuration de la défense en profondeur pour l...","de":"Einrichtungsleitfaden für Verteidigung in der Tiefe für K...","pt":"Guia de Configuração de Defesa em Profundidade para Agent...","ru":"Руководство по настройке защиты в глубину для ИИ Агентов","ar":"دليل إعداد الدفاع بالعمق لعمليات الوكلاء الذكية"},"description":{"en":"Discover how to structurally prevent bugs with multiple validation layers. Learn defense-in-depth best practices for AI agents and GH copilot now!","zh":"了解深度防御的核心原则：在每个层级验证数据，防止bug和安全漏洞","ja":"ディフェンス・イン・デプスの核心原則：データを毎層で検証してバグやセキュリティ漏洞を防ぐ","ko":"심층 방어의 핵심 원칙: 모든 계층에서 데이터를 검증하여 버그와 보안 취약점을 방지","es":"Aprende a proteger tus aplicaciones con la estrategia de defensa en profundidad, validando datos en cada capa para evitar vulnerabilidades","fr":"Découvrez comment protéger vos applications avec la stratégie de défense en profondeur, en validant les données à chaque couche pour éviter les vulnérabilités","de":"Erfahren Sie, wie Sie Ihre Anwendungen mit der Strategie der Verteidigung in der Tiefe schützen, indem Sie Daten in jeder Ebene validieren, um Schwachstellen...","pt":"Aprenda a implementar a defesa em profundidade em seus agentes de IA para evitar bugs e garantir a segurança dos dados","ru":"Узнайте, как реализовать защиту в глубину в ваших ИИ Агентах, чтобы предотвратить ошибки и обеспечить безопасность данных","ar":"تعرف على كيفية تنفيذ الدفاع بالعمق في وكلائك الذكية لتجنب الأعطال وضمان أمان البيانات"},"definition":{"en":"Defense-in-depth is a validation principle that ensures data integrity by checking it at every layer, preventing bugs and errors from occurring.","zh":"深度防御是一种通过多层验证来防止bug和安全漏洞的安全策略","ja":"ディフェンス・イン・デプスは、バグやセキュリティ漏洞を防ぐために多層で検証するセキュリティ戦略です","ko":"심층 방어는 버그와 보안 취약점을 방지하기 위해 여러 계층에서 검증하는 보안 전략입니다","es":"Defensa en profundidad es una estrategia de seguridad que implica la validación de datos en cada capa para prevenir vulnerabilidades","fr":"La défense en profondeur est une stratégie de sécurité qui consiste à valider les données à chaque couche pour prévenir les vulnérabilités","de":"Verteidigung in der Tiefe ist eine Sicherheitsstrategie, die die Validierung von Daten in jeder Ebene zur Vermeidung von Schwachstellen beinhaltet","pt":"Defesa em profundidade é uma abordagem de segurança que valida dados em cada camada para prevenir bugs e erros","ru":"Защита в глубину - это подход к безопасности, который проверяет данные на каждом уровне для предотвращения ошибок и багов","ar":"الدفاع بالعمق هو نهج أمان يتحقق من البيانات في كل مستوى لمنع الأعطال والخطأ"},"features":{"en":["Validates data at every layer to prevent bugs","Catches different cases through multiple validation layers","Entry validation catches invalid data at the point of entry","Supports custom agents for GH copilot","Enforces structurally impossible bug prevention"],"zh":["核心原则：在每个层级验证数据","多层验证：防止bug和安全漏洞","Entry validation：捕获无效数据","不同层级捕获不同案例"],"ja":["核心原則：毎層でデータを検証","多層検証：バグやセキュリティ漏洞を防ぐ","Entry validation：無効データを捕获","不同層で不同のケースを捕获"],"ko":["핵심 원칙: 모든 계층에서 데이터를 검증","다중 계층 검증: 버그와 보안 취약점을 방지","Entry validation: 無效 데이터를 捕获","다른 계층에서 다른 경우를 捕获"],"es":["Validación de datos en cada capa","Implementación de múltiples capas de seguridad","Detección de vulnerabilidades en tiempo de ejecución","Integración con herramientas de desarrollo como GH Copilot","Soporte para la validación de entrada y salida de datos"],"fr":["Validation des données à chaque couche","Mise en œuvre de plusieurs couches de sécurité","Détection des vulnérabilités en temps d''exécution","Intégration avec des outils de développement tels que GH Copilot","Prise en charge de la validation des entrées et des sorties de données"],"de":["Validierung von Daten in jeder Ebene","Implementierung von mehreren Sicherheitsebenen","Erkennung von Schwachstellen während der Ausführung","Integration mit Entwicklungstools wie GH Copilot","Unterstützung für die Validierung von Eingabe- und Ausgabedaten"],"pt":["Validação de dados em múltiplas camadas","Prevenção de bugs e erros","Garantia de segurança e integridade dos dados","Implementação em agentes de IA","Integração com GH Copilot"],"ru":["Проверка данных на нескольких уровнях","Предотвращение ошибок и багов","Обеспечение безопасности и целостности данных","Реализация в ИИ Агентах","Интеграция с GH Copilot"],"ar":["التحقق من البيانات على مستويات متعددة","منع الأعطال والخطأ","ضمان أمان البيانات وسلامتها","تنفيذ في عمليات الوكلاء الذكية","التكامل مع GH Copilot"]},"keywords":{"en":["how to use defense-in-depth","defense-in-depth validation","GH copilot custom agents","data validation best practices","defense-in-depth setup guide","defense-in-depth vs single validation"],"zh":["深度防御","安全策略","多层验证","bug防止","安全漏洞防止","AIエージェント","数据验证"],"ja":["ディフェンス・イン・デプス","セキュリティ戦略","多層検証","バグ防止","セキュリティ漏洞防止","AIエージェント","データ検証"],"ko":["심층 방어","보안 전략","다중 계층 검증","버그 방지","보안 취약점 방지","AI 에이전트","데이터 검증"],"es":["defensa en profundidad","seguridad de aplicaciones","validación de datos","desarrollo de software","herramientas de desarrollo","GH Copilot","seguridad en capas","protección de vulnerabilidades"],"fr":["défense en profondeur","sécurité des applications","validation des données","développement de logiciels","outils de développement","GH Copilot","sécurité en couches","protection des vulnérabilités"],"de":["Verteidigung in der Tiefe","Sicherheit von Anwendungen","Validierung von Daten","Software-Entwicklung","Entwicklungstools","GH Copilot","Sicherheit in Ebenen","Schwachstellen-Schutz"],"pt":["defesa em profundidade","segurança de dados","validação de dados","agentes de IA","GH Copilot","desenvolvimento de software","segurança cibernética"],"ru":["защита в глубину","безопасность данных","проверка данных","ИИ Агенты","GH Copilot","разработка программного обеспечения","кибербезопасность"],"ar":["الدفاع بالعمق","أمان البيانات","التحقق من البيانات","عمليات الوكلاء الذكية","GH Copilot","تطوير البرمجيات","الأمان السيبراني"]}},"owner":"AlabamaMike","repo":"copilot-agents","repoPath":"AlabamaMike/copilot-agents","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.382Z","topics":[],"category":"community","skillMd":{"name":"defense-in-depth","description":"Use when invalid data causes failures deep in execution, requiring validation at multiple system layers - validates at every layer data passes through to make bugs structurally impossible","bodyPreview":"# Defense-in-Depth Validation\n\n## Overview\n\nWhen you fix a bug caused by invalid data, adding validation at one place feels sufficient. But that single check can be bypassed by different code paths, refactoring, or mocks.\n\n**Core principle:** Validate at EVERY layer data passes through. Make the bug structurally impossible.\n\n## Why Multiple Layers\n\nSingle validation: \"We fixed the bug\"\nMultiple layers: \"We made the bug impossible\"\n\nDifferent layers catch different cases:\n- Entry validation catch","body":"# Defense-in-Depth Validation\n\n## Overview\n\nWhen you fix a bug caused by invalid data, adding validation at one place feels sufficient. But that single check can be bypassed by different code paths, refactoring, or mocks.\n\n**Core principle:** Validate at EVERY layer data passes through. Make the bug structurally impossible.\n\n## Why Multiple Layers\n\nSingle validation: \"We fixed the bug\"\nMultiple layers: \"We made the bug impossible\"\n\nDifferent layers catch different cases:\n- Entry validation catches most bugs\n- Business logic catches edge cases\n- Environment guards prevent context-specific dangers\n- Debug logging helps when other layers fail\n\n## The Four Layers\n\n### Layer 1: Entry Point Validation\n**Purpose:** Reject obviously invalid input at API boundary\n\n```typescript\nfunction createProject(name: string, workingDirectory: string) {\n  if (!workingDirectory || workingDirectory.trim() === '''') {\n    throw new Error(''workingDirectory cannot be empty'');\n  }\n  if (!existsSync(workingDirectory)) {\n    throw new Error(`workingDirectory does not exist: ${workingDirectory}`);\n  }\n  if (!statSync(workingDirectory).isDirectory()) {\n    throw new Error(`workingDirectory is not a directory: ${workingDirectory}`);\n  }\n  // ... proceed\n}\n```\n\n### Layer 2: Business Logic Validation\n**Purpose:** Ensure data makes sense for this operation\n\n```typescript\nfunction initializeWorkspace(projectDir: string, sessionId: string) {\n  if (!projectDir) {\n    throw new Error(''projectDir required for workspace initialization'');\n  }\n  // ... proceed\n}\n```\n\n### Layer 3: Environment Guards\n**Purpose:** Prevent dangerous operations in specific contexts\n\n```typescript\nasync function gitInit(directory: string) {\n  // In tests, refuse git init outside temp directories\n  if (process.env.NODE_ENV === ''test'') {\n    const normalized = normalize(resolve(directory));\n    const tmpDir = normalize(resolve(tmpdir()));\n\n    if (!normalized.startsWith(tmpDir)) {\n      throw new Error(\n        `Refusing git init outside temp dir during tests: ${directory}`\n      );\n    }\n  }\n  // ... proceed\n}\n```\n\n### Layer 4: Debug Instrumentation\n**Purpose:** Capture context for forensics\n\n```typescript\nasync function gitInit(directory: string) {\n  const stack = new Error().stack;\n  logger.debug(''About to git init'', {\n    directory,\n    cwd: process.cwd(),\n    stack,\n  });\n  // ... proceed\n}\n```\n\n## Applying the Pattern\n\nWhen you find a bug:\n\n1. **Trace the data flow** - Where does bad value originate? Where used?\n2. **Map all checkpoints** - List every point data passes through\n3. **Add validation at each layer** - Entry, business, environment, debug\n4. **Test each layer** - Try to bypass layer 1, verify layer 2 catches it\n\n## Example from Session\n\nBug: Empty `projectDir` caused `git init` in source code\n\n**Data flow:**\n1. Test setup → empty string\n2. `Project.create(name, '''')`\n3. `WorkspaceManager.createWorkspace('''')`\n4. `git init` runs in `process.cwd()`\n\n**Four layers added:**\n- Layer 1: `Project.create()` validates not empty/exists/writable\n- Layer 2: `WorkspaceManager` validates projectDir not empty\n- Layer 3: `WorktreeManager` refuses git init outside tmpdir in tests\n- Layer 4: Stack trace logging before git init\n\n**Result:** All 1847 tests passed, bug impossible to reproduce\n\n## Key Insight\n\nAll four layers were necessary. During testing, each layer caught bugs the others missed:\n- Different code paths bypassed entry validation\n- Mocks bypassed business logic checks\n- Edge cases on different platforms needed environment guards\n- Debug logging identified structural misuse\n\n**Don''t stop at one validation point.** Add checks at every layer.\n"},"lastSynced":"2026-03-08T02:05:41.425Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing robust data validation and bug prevention capabilities.","zh":"非常适合需要强大的数据验证和错误预防能力的代码审查代理。","ja":"コードレビューエージェントが堅牢なデータ検証およびバグ防止機能を必要とする場合に最適です。","ko":"코드 검토 에이전트가 강력한 데이터 검증 및 버그 방지 기능을 필요로 할 때 가장 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades de validación de datos robustas y de prevención de errores.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de validation de données robustes et de prévention de bogues.","de":"Perfekt für Code-Review-Agents, die robuste Datenvalidierungs- und Fehlerpräventionsfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de validação de dados robusta e capacidades de prevenção de bugs.","ru":"Идеально подходит для агентов проверки кода, которым требуются надежная проверка данных и возможности предотвращения ошибок.","ar":"مثالي للوكلاء مراجعة الكود الذين يحتاجون إلى التحقق من البيانات المتين وقدرات منع العيوب."},"recommendation":{"en":"Empowers agents to enforce defense-in-depth validation, making bugs structurally impossible by validating data at every layer, utilizing multiple layers of validation including entry validation, and ensuring data integrity through comprehensive checks.","zh":"赋予代理人执行多层次验证的能力，从而通过在每个层次验证数据并利用多个层次的验证（包括输入验证）来使错误结构上不可能发生，确保数据完整性通过全面检查。","ja":"エージェントに、デファンス・イン・デプス検証を実施する能力を付与し、すべてのレイヤーでデータを検証し、複数の検証レイヤー（エントリ検証を含む）を利用してバグを構造的に不可能にし、包括的なチェックを通じてデータの完全性を確保する。","ko":"에이전트가 수준별로 데이터를 검증하고, 여러 계층의 검증을 이용하여 버그를 구조적으로 불가능하게 만들고, 포괄적인 확인을 통해 데이터 무결성을 보장하는 방어 심층 검증을 강화하는 기능을 제공합니다.","es":"Habilita a los agentes a aplicar una validación de defensa en profundidad, lo que hace que los errores sean estructuralmente imposibles validando los datos en cada capa, utilizando múltiples capas de validación, incluida la validación de entrada, y garantizando la integridad de los datos a través de controles exhaustivos.","fr":"Permet aux agents d''appliquer une validation de défense en profondeur, ce qui rend les bogues structurellement impossibles en validant les données à chaque couche, en utilisant plusieurs couches de validation, y compris la validation d''entrée, et en garantissant l''intégrité des données grâce à des vérifications exhaustives.","de":"Ermächtigt Agenten, eine verteidigungsorientierte Validierung durchzusetzen, die Bugs strukturell unmöglich macht, indem Daten in jeder Schicht validiert werden, mehrere Validierungsschichten verwendet werden, einschließlich Einvalidierung, und die Datenintegrität durch umfassende Prüfungen gewährleistet wird.","pt":"Habilita os agentes a impor uma validação de defesa em profundidade, tornando os bugs estruturalmente impossíveis, validando os dados em cada camada, utilizando várias camadas de validação, incluindo validação de entrada e garantindo a integridade dos dados por meio de verificações abrangentes.","ru":"Позволяет агентам обеспечить проверку в глубину, что делает ошибки структуонально невозможными, проверяя данные на каждом уровне, используя несколько слоев проверки, включая проверку ввода, и гарантируя целостность данных посредством комплексных проверок.","ar":"يمنح الوكلاء القدرة على فرض التحقق من الدفاع في العمق، مما يجعل الأخطاء مستحيلة هيكليًا من خلال التحقق من البيانات في كل طبقة، واستخدام طبقات متعددة من التحقق، بما في ذلك التحقق من المدخلات، وضمان سلامة البيانات من خلال فحوصات شاملة."},"useCases":{"en":["Validating complex data at multiple layers","Preventing bugs through structural impossibility","Ensuring data integrity in GH copilot environments"],"zh":["在多个层面验证复杂数据","通过结构上不可能预防错误","在GH Copilot环境中确保数据完整性"],"ja":["複数のレイヤーで複雑なデータを検証する","構造的に不可能にすることでバグを防ぐ","GH Copilot環境でデータの完全性を確保する"],"ko":["여러 계층에서 복잡한 데이터를 검증하는 것","구조적으로 불가능하게 만들어 버그를 방지하는 것","GH Copilot 환경에서 데이터 무결성을 보장하는 것"],"es":["Validar datos complejos en múltiples capas","Prevenir errores a través de imposibilidad estructural","Garantizar la integridad de los datos en entornos de GH copilot"],"fr":["Valider des données complexes à plusieurs couches","Prévenir les bogues par impossibilité structurelle","Assurer l''intégrité des données dans les environnements GH copilot"],"de":["Komplexe Daten in mehreren Schichten validieren","Fehler durch strukturelle Unmöglichkeit verhindern","Datenintegrität in GH-Copilot-Umgebungen gewährleisten"],"pt":["Validar dados complexos em várias camadas","Prevenir bugs por impossibilidade estrutural","Garantir a integridade dos dados em ambientes GH copilot"],"ru":["Проверка сложных данных на нескольких уровнях","Предотвращение ошибок за счет структуальной невозможности","Обеспечение целостности данных в средах GH copilot"],"ar":["التحقق من البيانات المعقدة على عدة طبقات","منع الأخطاء بسبب الاستحالة الهيكلية","ضمان سلامة البيانات في بيئات GH copilot"]},"limitations":{"en":["Requires custom agent implementation for GH copilot","May increase development complexity due to multiple validation layers"],"zh":["需要为GH Copilot自定义代理实现","可能由于多个验证层而增加开发复杂性"],"ja":["GH Copilot用のカスタムエージェント実装が必要","複数の検証レイヤーにより開発の複雑性が増加する可能性"],"ko":["GH Copilot를 위한 사용자 정의 에이전트 구현이 필요","여러 계층의 검증으로 인해 개발 복잡성이 증가할 수 있음"],"es":["Requiere implementación de agente personalizada para GH copilot","Puede aumentar la complejidad de desarrollo debido a múltiples capas de validación"],"fr":["Nécessite une implémentation d''agent personnalisée pour GH copilot","Peut augmenter la complexité de développement en raison de plusieurs couches de validation"],"de":["Benötigt eine benutzerdefinierte Agentenimplementierung für GH-Copilot","Kann die Entwicklungskomplexität aufgrund mehrerer Validierungsschichten erhöhen"],"pt":["Requer implementação personalizada de agente para GH copilot","Pode aumentar a complexidade do desenvolvimento devido a várias camadas de validação"],"ru":["Требует индивидуальной реализации агента для GH copilot","Может увеличить сложность разработки из-за нескольких слоев проверки"],"ar":["يتطلب تنفيذًا مخصصًا للوكيل من أجل GH copilot","قد يزيد من تعقيد التطوير بسبب طبقات متعددة من التحقق"]},"version":4},"contentHash":"7f4f533e6c372aa678bc6c778dad2dd99e61514cb048cfeeab760d65d911a803","qualityScore":36}');
