INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gscalzo/gscalzo.github.io/writing-linkedin-posts', 'writing-linkedin-posts', 'gscalzo', 'gscalzo.github.io', 'community', 'writing-linkedin-posts gscalzo gscalzo.github.io community The writing-linkedin-posts skill generates engaging LinkedIn posts that prioritize authenticity over performance, benefiting developers and marketers seeking to establish thought leadership 创建真实和有用的LinkedIn帖子，通过分享真实的经历和工作中的见解，建立思想领导力 真実で有益なLinkedIn投稿を作成し、真実の経験と仕事の中での洞察を共有して、思想のリーダーシップを確立 진짜이고 유익한 LinkedIn 게시물 작성, 실제 경험과 일에서 얻은 통찰력을 공유하여 생각 지도력을 확립 Escribir publicaciones de LinkedIn efectivas con agentes de IA implica crear contenido auténtico y útil. Nuestro enfoque se centra en la autenticidad y la experiencia real Créer des publications LinkedIn efficaces avec des outils d''IA nécessite de créer du contenu authentique et utile. Notre approche se concentre sur l''authenticité et l''expérience réelle Das Erstellen effektiver LinkedIn-Beiträge mit KI-Tools erfordert die Erstellung von authentischem und nützlichem Inhalt. Unser Ansatz konzentriert sich auf Echtheit und reale Erfahrung Desenvolva posts no LinkedIn que promovam o engajamento significativo e estabeleçam liderança de pensamento com ferramentas de IA. Разрабатывайте посты в LinkedIn, которые способствуют значимому взаимодействию и устанавливают лидерство в мышлении с помощью ИИ Агентов. قم بتطوير منشورات LinkedIn التي تعزز التفاعل المهم وتؤسس قيادة في التفكير باستخدام أدوات الذكاء الاصطناعي how to write authentic linkedin posts writing-linkedin-posts alternative linkedin post writer setup guide what is writing-linkedin-posts writing-linkedin-posts vs other ai tools install writing-linkedin-posts for ai agents AI智能工具 LinkedIn帖子写作 思想领导力 真实性优于表现力 分享真实的经历 创建有用的内容 提高参与度 Generates posts prioritizing authenticity over performance Creates content based on real experiences with honest reflection Includes specific insights from actual work Admits vulnerabilities and lessons learned Produces human-centered posts that resonate with readers writing-linkedin-posts is a skill that creates authentic, engaging LinkedIn posts focusing on real experiences, honest reflection, and specific work insights');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CofficLab/Cisum/i18n-translate', 'community', 'CofficLab', 'Cisum', 'CofficLab/Cisum', 'i18n-translate', 0, 0, 36, '2026-03-08T01:57:15.407Z', '2026-03-08T02:06:56.564Z', '435cfc71862d989a0d52bf28a637e0b7ba0bb4c04c53c54800dab2db450e6cbc', '{"id":"CofficLab/Cisum/i18n-translate","name":"i18n-translate","description":{"en":"The i18n-translate skill helps developers manage iOS and macOS localization by automating tasks such as cleaning stale entries and checking missing translations in .xcstrings files.","zh":"i18n-translate 是一个管理 iOS/macOS 项目中所有 *.xcstrings 文件的中文翻译的工具","ja":"i18n-translate は iOS/macOS プロジェクトの *.xcstrings ファイルの中国語訳を管理するツールです","ko":"i18n-translate는 iOS/macOS 프로젝트의 *.xcstrings 파일의 중국어 번역을 관리하는 도구입니다","es":"i18n-translate es una herramienta para administrar traducciones chinas en proyectos iOS/macOS, soportando zh-Hans y zh-HK. Maneja archivos .xcstrings y ejecuta scripts de Python para limpiar y verificar traducciones","fr":"i18n-translate est un outil pour gérer les traductions chinoises dans les projets iOS/macOS, prenant en charge zh-Hans et zh-HK. Il gère les fichiers .xcstrings et exécute des scripts Python pour nettoyer et vérifier les traductions","de":"i18n-translate ist ein Tool zur Verwaltung chinesischer Übersetzungen in iOS/macOS-Projekten, das zh-Hans und zh-HK unterstützt. Es verwaltet Dateien .xcstrings und führt Python-Skripte aus, um Übersetzungen zu bereinigen und zu überprüfen","pt":"O i18n-translate é uma ferramenta para gerenciar traduções em projetos iOS/macOS, suportando chinês simplificado e tradicional","ru":"i18n-translate - это инструмент для управления переводами в проектах iOS/macOS, поддерживающий упрощенный и традиционный китайский","ar":"i18n-translate هو أداة لإدارة الترجمات في مشاريع iOS/macOS، يدعم الصيني المبسّط والتقليد"},"seo":{"title":{"en":"i18n-translate: Simplify iOS/macOS Localization | AI Agen...","zh":"i18n-translate 本地化翻译管理 Setup Guide","ja":"i18n-translate AIエージェントのローカライズ翻訳管理ベストプラクティス","ko":"i18n-translate 로컬라이제이션 翻译 관리 가이드","es":"Guía de configuración de i18n-translate para iOS/macOS","fr":"Guide de mise en place de i18n-translate pour les platefo...","de":"Einrichtungsleitfaden für i18n-translate auf iOS/macOS-Pl...","pt":"i18n-translate: Guia de Configuração para Tradução de Pro...","ru":"i18n-translate: Руководство по настройке перевода проекто...","ar":"i18n-translate: دليل الإعداد لترجمة مشاريع iOS/macOS باست..."},"description":{"en":"Streamline your iOS and macOS localization process with i18n-translate. Learn how to manage .xcstrings files and automate translation tasks","zh":"管理 iOS/macOS 项目中所有 *.xcstrings 文件的中文翻译，支持简体中文和繁体中文","ja":"iOS/macOS プロジェクトの *.xcstrings ファイルの中国語訳を管理する AIエージェント","ko":"iOS/macOS 프로젝트의 *.xcstrings 파일의 중국어 번역을 관리하는 i18n-translate","es":"Aprenda a administrar archivos .xcstrings para traducciones chinas en proyectos iOS/macOS con i18n-translate, la herramienta de AI para desarrolladores","fr":"Découvrez comment gérer les fichiers .xcstrings pour les traductions chinoises dans les projets iOS/macOS avec i18n-translate, l''outil d''AI pour les développ...","de":"Erfahren Sie, wie Sie Dateien .xcstrings für chinesische Übersetzungen in iOS/macOS-Projekten mit i18n-translate, dem AI-Tool für Entwickler, verwalten","pt":"Aprenda a configurar o i18n-translate para gerenciar traduções em projetos iOS/macOS, incluindo suporte a chinês simplificado e tradicional","ru":"Узнайте, как настроить i18n-translate для управления переводами в проектах iOS/macOS, включая поддержку упрощенного и традиционного китайского","ar":"تعرف على كيفية設定 i18n-translate لإدارة الترجمات في مشاريع iOS/macOS، بما في ذلك الدعم للصيني المبسّط والتقليد"},"definition":{"en":"i18n-translate is a localization management tool for iOS and macOS projects, handling .xcstrings files for simplified translation workflows","zh":"i18n-translate 是一个本地化翻译管理工具，用于管理 *.xcstrings 文件","ja":"i18n-translate はローカライズ翻訳管理ツールであり、*.xcstrings ファイルを管理する","ko":"i18n-translate는 로컬라이제이션 翻译 관리 도구로 *.xcstrings 파일을 관리합니다","es":"i18n-translate es una herramienta de AI para administrar traducciones chinas en proyectos iOS/macOS","fr":"i18n-translate est un outil d''AI pour gérer les traductions chinoises dans les projets iOS/macOS","de":"i18n-translate ist ein AI-Tool zur Verwaltung chinesischer Übersetzungen in iOS/macOS-Projekten","pt":"O i18n-translate é uma ferramenta de tradução para projetos iOS/macOS que gerencia arquivos .xcstrings","ru":"i18n-translate - это инструмент перевода для проектов iOS/macOS, который управляет файлами .xcstrings","ar":"i18n-translate هو أداة ترجمة لمشاريع iOS/macOS التي تدير ملفات .xcstrings"},"features":{"en":["Manages .xcstrings files for iOS and macOS projects","Supports Simplified Chinese (zh-Hans) and Traditional Chinese (zh-HK) translations","Automates cleaning of stale entries using python3 scripts/clean_stale.py","Checks for missing translations with python3 scripts/check_missing.py","Executes tasks using bash commands for efficient workflow"],"zh":["支持简体中文 (zh-Hans) 和繁体中文 (zh-HK)","查找所有 .xcstrings 文件","清理过期条目","检查缺失翻译","批量处理所有文件"],"ja":["簡体中国語 (zh-Hans) と繁体中国語 (zh-HK) をサポート",".xcstrings ファイルの検索","期限切れのエントリのクリーンアップ","翻訳不足のチェック","バッチ処理"],"ko":["簡體中文 (zh-Hans)과 繁體中文 (zh-HK) 지원",".xcstrings 파일 검색","기한 만료 항목 삭제","번역 누락 확인","일괄 처리"],"es":["Administración de archivos .xcstrings para traducciones chinas","Soporte para zh-Hans y zh-HK","Ejecución de scripts de Python para limpiar y verificar traducciones","Búsqueda y eliminación de entradas obsoletas","Verificación de traducciones faltantes"],"fr":["Gestion des fichiers .xcstrings pour les traductions chinoises","Prise en charge de zh-Hans et zh-HK","Exécution de scripts Python pour nettoyer et vérifier les traductions","Recherche et suppression des entrées obsolètes","Vérification des traductions manquantes"],"de":["Verwaltung von Dateien .xcstrings für chinesische Übersetzungen","Unterstützung für zh-Hans und zh-HK","Ausführung von Python-Skripten zur Bereinigung und Überprüfung von Übersetzungen","Suche und Entfernung von veralteten Einträgen","Überprüfung fehlender Übersetzungen"],"pt":["Suporte a chinês simplificado e tradicional","Gestão de arquivos .xcstrings","Limpeza de entradas obsoletas com script Python","Verificação de traduções ausentes com script Python"],"ru":["Поддержка упрощенного и традиционного китайского","Управление файлами .xcstrings","Очистка устаревших записей с помощью скрипта Python","Проверка отсутствующих переводов с помощью скрипта Python"],"ar":["دعم الصيني المبسّط والتقليد","إدارة ملفات .xcstrings","تنظيف الإدخالات المنتهية الصلاحية باستخدام سكريبت بايثون","فحص الترجمات الناقصة باستخدام سكريبت بايثون"]},"keywords":{"en":["how to use i18n-translate","i18n-translate setup guide","i18n-translate alternative","ios localization management","macos translation automation","xcstrings file management","i18n-translate install","i18n-translate vs localization tools"],"zh":["i18n-translate","本地化翻译管理","iOS 本地化","macOS 本地化","中国語訳","简体中文","繁体中文"],"ja":["i18n-translate","ローカライズ翻訳管理","iOS ローカライズ","macOS ローカライズ","中国語訳","AIエージェント","ローカライズツール"],"ko":["i18n-translate","로컬라이제이션 翻译 관리","iOS 로컬라이제이션","macOS 로컬라이제이션","중국어 번역","로컬라이제이션 도구","AI 에이전트"],"es":["i18n-translate","traducciones chinas","iOS/macOS","archivos .xcstrings","herramientas de AI para desarrolladores","administración de traducciones","zh-Hans","zh-HK","scripts de Python"],"fr":["i18n-translate","traductions chinoises","iOS/macOS","fichiers .xcstrings","outils d''AI pour les développeurs","gestion des traductions","zh-Hans","zh-HK","scripts Python"],"de":["i18n-translate","chinesische Übersetzungen","iOS/macOS","Dateien .xcstrings","AI-Tools für Entwickler","Verwaltung von Übersetzungen","zh-Hans","zh-HK","Python-Skripte"],"pt":["i18n-translate","tradução de projetos iOS","gestão de traduções","arquivos .xcstrings","script Python para tradução","ferramentas de tradução para iOS","desenvolvimento de aplicativos iOS","tradução de aplicativos móveis"],"ru":["i18n-translate","перевод проектов iOS","управление переводами","файлы .xcstrings","скрипт Python для перевода","инструменты перевода для iOS","разработка приложений iOS","перевод мобильных приложений"],"ar":["i18n-translate","ترجمة مشاريع iOS","إدارة الترجمات","ملفات .xcstrings","سكريبت بايثون للترجمة","أدوات الترجمة لiOS","تطوير تطبيقات iOS","ترجمة تطبيقات المحمول"]}},"owner":"CofficLab","repo":"Cisum","repoPath":"CofficLab/Cisum","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.407Z","topics":[],"category":"community","skillMd":{"name":"i18n-translate","description":"管理 iOS/macOS 应用的 *.xcstrings 本地化翻译文件。自动清理过期条目、检测缺失翻译、添加简繁体中文翻译。当用户需要处理翻译、补充缺失的 zh-Hans/zh-HK 翻译、或清理 *.xcstrings 文件时使用此 skill。","bodyPreview":"# iOS/macOS 本地化翻译管理\n\n管理项目中所有 `*.xcstrings` 文件的中文翻译，支持简体中文 (zh-Hans) 和繁体中文 (zh-HK)。\n\n## 工作流程\n\n处理翻译请求时，首先查找所有 .xcstrings 文件，然后按以下顺序执行：\n\n### 0. 查找所有 .xcstrings 文件\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" | head -20\n```\n\n### 1. 清理过期条目\n\n```bash\npython3 scripts/clean_stale.py <文件路径>.xcstrings\n```\n\n删除所有 `extractionState` 为 `stale` 的条目。可批量处理所有文件：\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" -exec python3 scripts/clean_stale.py {} \\;\n```\n\n### 2. 检查缺失翻译\n\n```bash\npython3 scripts/check_mis","body":"# iOS/macOS 本地化翻译管理\n\n管理项目中所有 `*.xcstrings` 文件的中文翻译，支持简体中文 (zh-Hans) 和繁体中文 (zh-HK)。\n\n## 工作流程\n\n处理翻译请求时，首先查找所有 .xcstrings 文件，然后按以下顺序执行：\n\n### 0. 查找所有 .xcstrings 文件\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" | head -20\n```\n\n### 1. 清理过期条目\n\n```bash\npython3 scripts/clean_stale.py <文件路径>.xcstrings\n```\n\n删除所有 `extractionState` 为 `stale` 的条目。可批量处理所有文件：\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" -exec python3 scripts/clean_stale.py {} \\;\n```\n\n### 2. 检查缺失翻译\n\n```bash\npython3 scripts/check_missing.py <文件路径>.xcstrings\n```\n\n输出缺失的 zh-Hans 和 zh-HK 翻译统计。可批量检查：\n\n```bash\nfor f in $(find . -name \"*.xcstrings\" -not -path \".*\"); do\n    echo \"=== $f ===\"\n    python3 scripts/check_missing.py \"$f\"\ndone\n```\n\n### 3. 添加翻译\n\n```bash\npython3 scripts/add_translation.py <文件路径>.xcstrings \"Key\" \"简体中文翻译\" \"繁體中文翻譯\"\n```\n\n- `<文件路径>.xcstrings`: 目标文件路径（必需）\n- `Key`: 条目的 key（必需）\n- `zh-Hans`: 简体中文翻译（必需）\n- `zh-HK`: 繁体中文翻译（可选，未提供时自动转换）\n\n### 4. 验证文件\n\n```bash\npython3 scripts/validate.py <文件路径>.xcstrings\n```\n\n验证 JSON 格式正确性并统计翻译完成度。可批量验证：\n\n```bash\nfor f in $(find . -name \"*.xcstrings\" -not -path \".*\"); do\n    echo \"=== $f ===\"\n    python3 scripts/validate.py \"$f\"\ndone\n```\n\n### 批量处理所有文件\n\n使用 `batch_process.py` 脚本一次性处理所有 .xcstrings 文件：\n\n```bash\n# 列出所有 .xcstrings 文件\npython3 scripts/batch_process.py list\n\n# 批量清理所有文件的过期条目\npython3 scripts/batch_process.py clean\n\n# 批量检查所有文件的缺失翻译\npython3 scripts/batch_process.py check\n\n# 批量验证所有文件的格式\npython3 scripts/batch_process.py validate\n\n# 指定项目目录\npython3 scripts/batch_process.py validate --dir /path/to/project\n```\n\n## 翻译原则\n\n- **占位符保持不变**: `%@`, `%lld`, `%1$@`, `%d` 等格式化占位符必须原样保留\n- **技术术语**: API, SQLite, Host 等专有名词可保持英文\n- **UI 文本**: 简洁明了，符合 macOS/iOS 应用习惯\n- **简繁转换**: `add_translation.py` 包含常见词汇的简繁转换映射\n\n## 使用示例\n\n```\n用户: 检查项目所有 xcstrings 文件缺少的翻译\n→ 运行 batch_process.py list 查看所有文件\n→ 运行 batch_process.py check 检查所有文件\n\n用户: 为 Core.xcstrings 中的 \"Copy\" 添加翻译\n→ 运行 add_translation.py Core/Core.xcstrings \"Copy\" \"拷贝\" \"拷貝\"\n\n用户: 清理所有 xcstrings 文件中过期的翻译条目\n→ 运行 batch_process.py clean\n\n用户: 验证所有翻译文件的格式和完成度\n→ 运行 batch_process.py validate\n\n用户: 处理特定目录下的翻译文件\n→ 运行 batch_process.py check --dir ./Modules\n```\n\n## 注意事项\n\n- 所有操作会直接修改指定的 `.xcstrings` 文件\n- 修改前建议先备份文件\n- JSON 缩进使用 2 个空格\n- 编码必须是 UTF-8\n- 批量处理时使用 `find` 命令过滤掉隐藏文件（`.*/.*`）\n"},"lastSynced":"2026-03-08T02:06:56.564Z","agentAnalysis":{"suitability":{"en":"Ideal for iOS and macOS Development Agents requiring automated localization management and translation checks in .xcstrings files.","zh":"适用于需要自动化本地化管理和翻译检查的 iOS 和 macOS 开发代理，特别是在 .xcstrings 文件中。","ja":"iOS と macOS 開発エージェントが自動化されたローカライズ管理と翻訳チェックを必要とする場合に適しています。特に .xcstrings ファイル内で。","ko":"자동화된 로컬라이제이션 관리 및 번역 검사를 필요로 하는 iOS 및 macOS 개발 에이전트에 적합합니다. 특히 .xcstrings 파일 내에서","es":"Ideal para Agentes de Desarrollo de iOS y macOS que requieren una gestión de localización automatizada y comprobaciones de traducción en archivos .xcstrings.","fr":"Idéal pour les agents de développement iOS et macOS nécessitant une gestion de localisation automatisée et des vérifications de traduction dans les fichiers .xcstrings.","de":"Ideal für iOS- und macOS-Entwicklungsagenten, die eine automatisierte Lokalisierungsverwaltung und Übersetzungsprüfungen in .xcstrings-Dateien benötigen.","pt":"Ideal para Agentes de Desenvolvimento do iOS e macOS que exigem gerenciamento de localização automatizado e verificações de tradução em arquivos .xcstrings.","ru":"Идеально для агентов разработки iOS и macOS, требующих автоматизированного управления локализацией и проверки переводов в файлах .xcstrings.","ar":"مثالي للوكلاء النموزجية لتنمية iOS و macOS الذين يتطلبون إدارة التهجين التلقائي والتحقق من الترجمة في الملفات .xcstrings."},"recommendation":{"en":"Empowers agents to manage iOS and macOS localization by automating tasks such as cleaning stale entries and checking missing translations in .xcstrings files using Python scripts, supporting both Simplified Chinese (zh-Hans) and Traditional Chinese (zh-HK).","zh":"赋予代理管理 iOS 和 macOS 本地化的能力，通过使用 Python 脚本自动执行任务，例如从 .xcstrings 文件中清除过期条目，并检查缺失的翻译，支持简体中文（zh-Hans）和繁体中文（zh-HK）。","ja":"エージェントが iOS と macOS のローカライズを管理できるようにし、Python スクリプトを使用してタスクを自動化します。例えば、.xcstrings ファイルから古いエントリを削除したり、簡体中文（zh-Hans）と繁体中文（zh-HK）翻訳の不足をチェックします。","ko":"에이전트가 iOS 및 macOS 로컬라이제이션을 관리할 수 있도록 하고 Python 스크립트를 사용하여 작업을 자동화합니다. 예를 들어, .xcstrings 파일에서 오래된 항목을 제거하거나, 번역되지 않은 항목을 확인하며, 간체中文(zh-Hans)과 번체中文(zh-HK)을 지원합니다.","es":"Habilita a los agentes a gestionar la localización de iOS y macOS automatizando tareas como la limpieza de entradas obsoletas y la comprobación de traducciones que faltan en archivos .xcstrings utilizando scripts de Python, y admite tanto el chino simplificado (zh-Hans) como el chino tradicional (zh-HK).","fr":"Permet aux agents de gérer la localisation d''iOS et de macOS en automatisant des tâches telles que le nettoyage des entrées obsolètes et la vérification des traductions manquantes dans les fichiers .xcstrings à l''aide de scripts Python, et prend en charge à la fois le chinois simplifié (zh-Hans) et le chinois traditionnel (zh-HK).","de":"Ermächtigt die Agenten, die Lokalisierung von iOS und macOS zu verwalten, indem sie Aufgaben wie das Bereinigen veralteter Einträge und das Überprüfen fehlender Übersetzungen in .xcstrings-Dateien mithilfe von Python-Skripten automatisieren, und unterstützt sowohl Vereinfachtes Chinesisch (zh-Hans) als auch Traditionelles Chinesisch (zh-HK).","pt":"Habilita os agentes a gerenciar a localização do iOS e macOS, automatizando tarefas como limpar entradas obsoletas e verificar traduções ausentes em arquivos .xcstrings, usando scripts Python, suportando tanto Chinês Simplificado (zh-Hans) quanto Chinês Tradição (zh-HK).","ru":"Наделяет агентов возможностью управлять локализацией iOS и macOS, автоматизируя задачи, такие как очистка устаревших записей и проверка отсутствующих переводов в файлах .xcstrings, используя скрипты Python, поддерживая как упрощенный китайский (zh-Hans), так и традиционный китайский (zh-HK).","ar":"يمنح الوكلاء khảية إدارة التهجين لمنصة iOS وmacOS، عن طريق توفير المهام مثل تنظيف المدخلات القديمة والتحقق من الترجمات الناقصة في الملفات .xcstrings، باستخدام سكريبتات Python، ودعمًا للصيني المبسّط (zh-Hans) والصيني التقليد (zh-HK)."},"useCases":{"en":["Automating stale entry removal from .xcstrings files","Checking for missing translations in iOS and macOS projects","Batch processing of .xcstrings files for localization management"],"zh":["从 .xcstrings 文件中自动删除过期条目","在 iOS 和 macOS 项目中检查缺失的翻译","批量处理 .xcstrings 文件以进行本地化管理"],"ja":["自動的に .xcstrings ファイルから古いエントリを削除する","iOS と macOS プロジェクトで不足している翻訳をチェックする",".xcstrings ファイルのローカライズ管理のためのバッチ処理"],"ko":["自動으로 .xcstrings 파일에서 오래된 항목을 제거하는 것","iOS 및 macOS 프로젝트에서 번역되지 않은 항목을 확인하는 것",".xcstrings 파일의 로컬라이제이션 관리를 위한 일괄 처리"],"es":["Automatización de la eliminación de entradas obsoletas de archivos .xcstrings","Comprobación de traducciones que faltan en proyectos de iOS y macOS","Procesamiento por lotes de archivos .xcstrings para la gestión de la localización"],"fr":["Automatisation de la suppression des entrées obsolètes des fichiers .xcstrings","Vérification des traductions manquantes dans les projets iOS et macOS","Traitement par lots de fichiers .xcstrings pour la gestion de la localisation"],"de":["Automatisierung der Entfernung veralteter Einträge aus .xcstrings-Dateien","Überprüfung fehlender Übersetzungen in iOS- und macOS-Projekten","Stückverarbeitung von .xcstrings-Dateien für die Lokalisierungsverwaltung"],"pt":["Remoção automatizada de entradas obsoletas de arquivos .xcstrings","Verificação de traduções ausentes em projetos do iOS e macOS","Processamento em lote de arquivos .xcstrings para gerenciamento de localização"],"ru":["Автоматическое удаление устаревших записей из файлов .xcstrings","Проверка отсутствующих переводов в проектах iOS и macOS","Пакетная обработка файлов .xcstrings для управления локализацией"],"ar":["إزالة تلقائية للمدخلات القديمة من الملفات .xcstrings","التحقق من الترجمات الناقصة في مشاريع منصة iOS وmacOS","المعالجة بالجملة لملفات .xcstrings لإدارة التهجين"]},"limitations":{"en":["Requires Python 3.x","Limited to .xcstrings file format","Supports only Simplified Chinese (zh-Hans) and Traditional Chinese (zh-HK) translations"],"zh":["需要 Python 3.x","仅限 .xcstrings 文件格式","仅支持简体中文（zh-Hans）和繁体中文（zh-HK）翻译"],"ja":["Python 3.x が必要",".xcstrings ファイル形式のみに対応","簡体中文（zh-Hans）と繁体中文（zh-HK）翻訳のみをサポート"],"ko":["Python 3.x가 필요함",".xcstrings 파일 형식만 지원함","간체中文(zh-Hans)과 번체中文(zh-HK) 번역만을 지원함"],"es":["Requiere Python 3.x","Limitado al formato de archivo .xcstrings","Solo admite traducciones al chino simplificado (zh-Hans) y al chino tradicional (zh-HK)"],"fr":["Nécessite Python 3.x","Limité au format de fichier .xcstrings","Ne prend en charge que les traductions en chinois simplifié (zh-Hans) et en chinois traditionnel (zh-HK)"],"de":["Benötigt Python 3.x","Begrenzt auf das .xcstrings-Dateiformat","Unterstützt nur Übersetzungen ins Vereinfachte Chinesisch (zh-Hans) und Traditionelle Chinesisch (zh-HK)"],"pt":["Exige Python 3.x","Limitado ao formato de arquivo .xcstrings","Suporta apenas traduções para Chinês Simplificado (zh-Hans) e Chinês Tradição (zh-HK)"],"ru":["Требует Python 3.x","Ограничен форматом файла .xcstrings","Поддерживает только переводы на упрощенный китайский (zh-Hans) и традиционный китайский (zh-HK)"],"ar":["يتطلب Python 3.x","محدود بформات الملف .xcstrings","يدعم الترجمات فقط للصيني المبسّط (zh-Hans) والصيني التقليد (zh-HK)"]},"version":4},"contentHash":"435cfc71862d989a0d52bf28a637e0b7ba0bb4c04c53c54800dab2db450e6cbc","qualityScore":36}');
