INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CofficLab/Cisum/i18n-translate', 'i18n-translate', 'CofficLab', 'Cisum', 'community', 'i18n-translate CofficLab Cisum community The i18n-translate skill helps developers manage iOS and macOS localization by automating tasks such as cleaning stale entries and checking missing translations in .xcstrings files. i18n-translate 是一个管理 iOS/macOS 项目中所有 *.xcstrings 文件的中文翻译的工具 i18n-translate は iOS/macOS プロジェクトの *.xcstrings ファイルの中国語訳を管理するツールです i18n-translate는 iOS/macOS 프로젝트의 *.xcstrings 파일의 중국어 번역을 관리하는 도구입니다 i18n-translate es una herramienta para administrar traducciones chinas en proyectos iOS/macOS, soportando zh-Hans y zh-HK. Maneja archivos .xcstrings y ejecuta scripts de Python para limpiar y verificar traducciones i18n-translate est un outil pour gérer les traductions chinoises dans les projets iOS/macOS, prenant en charge zh-Hans et zh-HK. Il gère les fichiers .xcstrings et exécute des scripts Python pour nettoyer et vérifier les traductions i18n-translate ist ein Tool zur Verwaltung chinesischer Übersetzungen in iOS/macOS-Projekten, das zh-Hans und zh-HK unterstützt. Es verwaltet Dateien .xcstrings und führt Python-Skripte aus, um Übersetzungen zu bereinigen und zu überprüfen O i18n-translate é uma ferramenta para gerenciar traduções em projetos iOS/macOS, suportando chinês simplificado e tradicional i18n-translate - это инструмент для управления переводами в проектах iOS/macOS, поддерживающий упрощенный и традиционный китайский i18n-translate هو أداة لإدارة الترجمات في مشاريع iOS/macOS، يدعم الصيني المبسّط والتقليد how to use i18n-translate i18n-translate setup guide i18n-translate alternative ios localization management macos translation automation xcstrings file management i18n-translate install i18n-translate vs localization tools i18n-translate 本地化翻译管理 iOS 本地化 macOS 本地化 中国語訳 简体中文 繁体中文 Manages .xcstrings files for iOS and macOS projects Supports Simplified Chinese (zh-Hans) and Traditional Chinese (zh-HK) translations Automates cleaning of stale entries using python3 scripts/clean_stale.py Checks for missing translations with python3 scripts/check_missing.py Executes tasks using bash commands for efficient workflow i18n-translate is a localization management tool for iOS and macOS projects, handling .xcstrings files for simplified translation workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yon/agentic-dev-os/fix-bug', 'community', 'yon', 'agentic-dev-os', 'yon/agentic-dev-os', 'fix-bug', 0, 0, 36, '2026-03-08T01:57:15.407Z', '2026-03-08T02:06:57.027Z', '10eacbee6ffec1f3e8e2fa52d879ce1e368aa3113a5a9d785acb9e77e56e2abe', '{"id":"yon/agentic-dev-os/fix-bug","name":"fix-bug","description":{"en":"The fix-bug skill helps developers fix root causes of bugs, not just symptoms, by writing regression tests before fixing. This ensures bugs never return and improves code quality.","zh":"fix-bug是一种根因分析和修复技术，通过回归测试确保bug不再出现","ja":"fix-bugは根本原因を解決するバグ修正技術で、回帰テストを使用してバグを再現しないことを保証","ko":"fix-bug는 근본원인 분석과 수정기술로 회귀 테스트를 통해 버그가 다시 발생하지 않도록 합니다","es":"Fix-bug es una habilidad de AI Agent que ayuda a los desarrolladores a identificar y corregir errores de manera efectiva, enfocándose en la causa raíz del problema","fr":"Fix-bug est une compétence de l''outil IA qui aide les développeurs à identifier et à corriger les bogues de manière efficace, en se concentrant sur la cause profonde du problème","de":"Fix-bug ist eine Fähigkeit des KI-Tools, die Entwicklern hilft, Fehler effektiv zu identifizieren und zu beheben, indem sie sich auf die Ursache des Problems konzentriert","pt":"O Fix-Bug é uma habilidade que ajuda a corrigir bugs identificando a causa raiz e escrevendo testes de regressão","ru":"Fix-Bug - это навык, который помогает исправлять ошибки, определяя коренную причину и записывая тесты регрессии ИИ Агентов","ar":"Fix-Bug هو مهارة تساعد على إصلاح الأعطال بالتعرف على السبب الجذري وكتابة اختبارات الانحدار للعوامل الذكية"},"seo":{"title":{"en":"fix-bug: Root Cause Bug Fixing Setup Guide | AI Agent Skill","zh":"fix-bug 故障修复最佳实践","ja":"fix-bug AIエージェントの根本原因解決","ko":"fix-bug 버그 수정 가이드","es":"Guía de Configuración para fix-bug: Corrección de Errores...","fr":"Guide de Configuration pour fix-bug: Correction de 