INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yon/agentic-dev-os/fix-bug', 'fix-bug', 'yon', 'agentic-dev-os', 'community', 'fix-bug yon agentic-dev-os community The fix-bug skill helps developers fix root causes of bugs, not just symptoms, by writing regression tests before fixing. This ensures bugs never return and improves code quality. fix-bug是一种根因分析和修复技术，通过回归测试确保bug不再出现 fix-bugは根本原因を解決するバグ修正技術で、回帰テストを使用してバグを再現しないことを保証 fix-bug는 근본원인 분석과 수정기술로 회귀 테스트를 통해 버그가 다시 발생하지 않도록 합니다 Fix-bug es una habilidad de AI Agent que ayuda a los desarrolladores a identificar y corregir errores de manera efectiva, enfocándose en la causa raíz del problema Fix-bug est une compétence de l''outil IA qui aide les développeurs à identifier et à corriger les bogues de manière efficace, en se concentrant sur la cause profonde du problème Fix-bug ist eine Fähigkeit des KI-Tools, die Entwicklern hilft, Fehler effektiv zu identifizieren und zu beheben, indem sie sich auf die Ursache des Problems konzentriert O Fix-Bug é uma habilidade que ajuda a corrigir bugs identificando a causa raiz e escrevendo testes de regressão Fix-Bug - это навык, который помогает исправлять ошибки, определяя коренную причину и записывая тесты регрессии ИИ Агентов Fix-Bug هو مهارة تساعد على إصلاح الأعطال بالتعرف على السبب الجذري وكتابة اختبارات الانحدار للعوامل الذكية how to use fix-bug what is fix-bug fix-bug alternative fix-bug vs debug-tool fix-bug install fix-bug setup guide root cause bug fixing regression testing best practices symptom-chasing prevention fix-bug 根本原因分析 回归测试 软件bug修复 AI工具 代码优化 边界数据检查 Null Pointer Exception Identifies root causes of bugs, not just symptoms Writes regression tests before fixing bugs Ensures bugs never return by fixing the root cause Follows a philosophy of fixing the root cause, not the symptom Prevents symptom-chasing by focusing on root cause analysis Supports deterministic bug fixing using regression tests fix-bug is a skill that enables developers to identify and fix the root causes of bugs, rather than just treating the symptoms, using techniques like regression testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Sunwood-AI-OSS-Hub/zero-cc/repo-create', 'community', 'Sunwood-AI-OSS-Hub', 'zero-cc', 'Sunwood-AI-OSS-Hub/zero-cc', 'repo-create', 0, 0, 36, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:07.224Z', '51842d02c728326072e5e9a26f3813f79777761fa411c27f6b9cb788aeacdd7c', '{"id":"Sunwood-AI-OSS-Hub/zero-cc/repo-create","name":"repo-create","description":{"en":"The repo-create skill automates GitHub repository creation and initialization for developers, using the GitHub CLI and fal.ai API key.","zh":"repo-create是一个GitHub仓库创建工具，支持CLI和API密钥认证","ja":"repo-createはGitHubリポジトリを新規作成・初期化するAIエージェントです","ko":"repo-create는 GitHub 리포지토리를 생성하고 초기화하는 도구입니다","es":"repo-create es una herramienta para crear y configurar repositorios de GitHub. Utiliza GitHub CLI y autenticación para un proceso sencillo","fr":"repo-create est un outil pour créer et configurer des référentiels GitHub. Il utilise GitHub CLI et l''authentification pour un processus simple","de":"repo-create ist ein Tool zum Erstellen und Konfigurieren von GitHub-Repositorys. Es verwendet GitHub CLI und Authentifizierung für einen einfachen Prozess","pt":"O repo-create é uma ferramenta de linha de comando que cria e inicializa repositórios GitHub. Ele suporta opções como visibilidade pública ou privada e descrição do repositório.","ru":"Repo-create - это инструмент командной строки, который создает и инициализирует репозитории GitHub. Он поддерживает опции, такие как публичная или приватная видимость и описание репозитория с помощью ИИ Агентов","ar":"repo-create هو أداة سطر الأوامر التي تنشئ ومبادرة مستودعات جيت هاب. يدعم خيارات مثل الرؤية العامة أو الخاصة ووصف المستودع باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"repo-create: GitHub Repository Setup Guide | AI Agent Skill","zh":"repo-create_SETUP_GITHUB仓库创建工具","ja":"GitHubリポジトリ作成ツール repo-create Setup Guide","ko":"repo-create_GitHub_리포지토리_생성_도구","es":"Guía de configuración de repo-create para GitHub","fr":"Guide de mise en place de repo-create pour GitHub","de":"Einrichtungsanleitung für repo-create in GitHub","pt":"Guia de Configuração do repo-create: Crie Repositórios Gi...","ru":"Настройка repo-create: Создание репозиториев GitHub с пом...","ar":"دليل إعداد repo-create: إنشاء مستودعات جيت هاب باستخدام أ..."},"description":{"en":"Streamline your GitHub workflow with repo-create. Learn how to automate repository creation and initialization with this AI agent skill.","zh":"使用repo-create AIエージェント创建和初始化GitHub仓库，支持CLI和API密钥认证","ja":"GitHubリポジトリを新規作成・初期化するrepo-create AIエージェントの機能と設定方法","ko":"repo-create를 사용하여 GitHub 리포지토리를 생성하고 초기화하는 방법 및 기능","es":"Crea y configura repositorios de GitHub con repo-create. Aprende a utilizar GitHub CLI y autenticación","fr":"Créez et configurez des référentiels GitHub avec repo-create. Découvrez comment utiliser GitHub CLI et l''authentification","de":"Erstellen und konfigurieren Sie GitHub-Repositorys mit repo-create. Erfahren Sie, wie Sie GitHub CLI und Authentifizierung verwenden","pt":"Aprenda a criar repositórios GitHub com o repo-create, uma ferramenta de linha de comando que simplifica o processo de inicialização de projetos","ru":"Узнайте, как создать репозиторий GitHub с помощью repo-create, инструмента командной строки, который упрощает процесс инициализации проектов с помощью ИИ Аге...","ar":"تعرف على كيفية إنشاء مستودعات جيت هاب باستخدام repo-create، أداة سطر الأوامر التي تبسط عملية بدء المشاريع باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"repo-create is a GitHub repository creator skill that automates the process of creating and initializing new repositories using the GitHub CLI.","zh":"repo-create是用于创建和初始化GitHub仓库的AI工具","ja":"repo-createはGitHubリポジトリを新規作成・初期化するために使用されるAIエージェントです","ko":"repo-create는 GitHub 리포지토리를 생성하고 초기화하는 AI 도구입니다","es":"repo-create es una herramienta de línea de comandos para crear y configurar repositorios de GitHub","fr":"repo-create est un outil en ligne de commande pour créer et configurer des référentiels GitHub","de":"repo-create ist ein Kommandozeilen-Tool zum Erstellen und Konfigurieren von GitHub-Repositorys","pt":"O repo-create é uma ferramenta que cria e configura repositórios GitHub de forma automática","ru":"Repo-create - это инструмент, который создает и настраивает репозитории GitHub автоматически с помощью ИИ Агентов","ar":"repo-create هو أداة تنشئ وت$config مستودعات جيت هاب تلقائيًا باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Creates new GitHub repositories using the `gh repo create` command","Supports public and private repository visibility options via `--public` and `--private` flags","Allows for custom repository descriptions using the `--description` or `-d` option","Automates cloning of created repositories to the current directory with the `--clone` option","Utilizes the fal.ai API key for header image generation","Requires authentication via `gh auth login` for GitHub CLI"],"zh":["支持GitHub CLI（gh）","支持API密钥认证（FAL_KEY）","可指定仓库名和可视性","支持仓库描述和clone功能","使用命令行参数解析"],"ja":["GitHub CLI（gh）をサポート","APIキー認証（FAL_KEY）をサポート","リポジトリ名と可視性を指定可能","リポジトリ説明とclone機能をサポート","コマンドライン引数解析を使用"],"ko":["GitHub CLI（gh） 지원","API 키 인증（FAL_KEY） 지원","리포지토리 이름과 가시성을 지정할 수 있음","리포지토리 설명과 클론 기능 지원","명령행 인수 해석 사용"],"es":["Crea repositorios de GitHub con GitHub CLI","Autenticación con gh auth login","Configuración de visibilidad pública o privada","Opción para clonar el repositorio en el directorio actual","Soporte para descripciones de repositorio","Utiliza fal.ai API para la generación de imágenes de cabecera"],"fr":["Crée des référentiels GitHub avec GitHub CLI","Authentification avec gh auth login","Configuration de la visibilité publique ou privée","Option pour cloner le référentiel dans le répertoire actuel","Prise en charge des descriptions de référentiel","Utilise l''API fal.ai pour la génération d''images d''en-tête"],"de":["Erstellt GitHub-Repositorys mit GitHub CLI","Authentifizierung mit gh auth login","Konfiguration der Sichtbarkeit als öffentlich oder privat","Option zum Klonen des Repositorys im aktuellen Verzeichnis","Unterstützung für Repository-Beschreibungen","Verwendet die fal.ai-API für die Generierung von Header-Bildern"],"pt":["Criação de repositórios GitHub com linha de comando","Suporte a visibilidade pública ou privada","Opção para adicionar descrição do repositório","Possibilidade de clonar o repositório para o diretório atual","Integração com GitHub CLI (gh)","Suporte a autenticação com gh auth login"],"ru":["Создание репозиториев GitHub с помощью командной строки","Поддержка публичной или приватной видимости","Опция для добавления описания репозитория","Возможность клонировать репозиторий в текущий каталог","Интеграция с GitHub CLI (gh)","Поддержка аутентификации с gh auth login и ИИ Агентов"],"ar":["إنشاء مستودعات جيت هاب باستخدام سطر الأوامر","دعم الرؤية العامة أو الخاصة","خيار لإضافة وصف للمستودع","إمكانية نسخ المستودع إلى الدليل الحالي","التكامل مع جيت هاب CLI (gh)","دعم المصادقة مع gh auth login وأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use repo-create","repo-create setup guide","GitHub repository creation automation","repo-create vs GitHub CLI","repo-create install","what is repo-create","repo-create alternative","automating GitHub workflows","GitHub repository initialization"],"zh":["repo-create","GitHub仓库创建","AIエージェント","CLI工具","API密钥认证","仓库管理"],"ja":["repo-create","GitHubリポジトリ作成","AIエージェント","CLIツール","APIキー認証","リポジトリ管理"],"ko":["repo-create","GitHub 리포지토리 생성","AI 도구","CLI 툴","API 키 인증","리포지토리 관리"],"es":["repo-create","GitHub CLI","autenticación GitHub","crear repositorio GitHub","configurar visibilidad GitHub","clonar repositorio GitHub","herramientas de línea de comandos para GitHub","fal.ai API"],"fr":["repo-create","GitHub CLI","authentification GitHub","créer un référentiel GitHub","configurer la visibilité GitHub","cloner un référentiel GitHub","outils en ligne de commande pour GitHub","API fal.ai"],"de":["repo-create","GitHub CLI","GitHub-Authentifizierung","Erstellen von GitHub-Repositorys","Konfigurieren der Sichtbarkeit in GitHub","Klonen von GitHub-Repositorys","Kommandozeilentools für GitHub","fal.ai-API"],"pt":["repo-create","criar repositório github","github cli","gh auth login","repositório público","repositório privado","descrição do repositório","clonar repositório","linha de comando","ferramenta de desenvolvimento"],"ru":["repo-create","создать репозиторий github","github cli","gh auth login","публичный репозиторий","приватный репозиторий","описание репозитория","клонировать репозиторий","командная строка","инструмент разработки","ИИ Агенты"],"ar":["repo-create","إنشاء مستودع جيت هاب","جيت هاب CLI","gh auth login","مستودع عام","مستودع خاص","وصف المستودع","نسخ المستودع","سطر الأوامر","أداة تطوير","أدوات الذكاء الاصطناعي"]}},"owner":"Sunwood-AI-OSS-Hub","repo":"zero-cc","repoPath":"Sunwood-AI-OSS-Hub/zero-cc","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"repo-create","description":"|","bodyPreview":"# GitHub Repository Creator\n\nGitHubリポジトリを新規作成・初期化します。\n\n## 前提条件\n\n- GitHub CLI (`gh`) がインストール済み\n- `gh auth login` で認証済み\n- fal.ai APIキー (`FAL_KEY`) が `.env` に設定済み（ヘッダー画像生成用）\n\n## ワークフロー\n\n### 1. 引数解析\n`$ARGUMENTS` からリポジトリ名とオプションを特定:\n\n- `repo-create [name]` → リポジトリ名\n- `--public` / `--private` → 可視性（デフォルト: public）\n- `--description` / `-d` → 説明\n- `--clone` → カレントディレクトリにclone\n\n### 2. 作成手順\n\n1. **リポジトリ名の決定**\n   - 引数指定 → 使用\n   - 未指定 → カレントディレクトリ名を使用\n\n2. **GitHubリポジトリ作成**\n   ```bash\n   gh repo create [name] -","body":"# GitHub Repository Creator\n\nGitHubリポジトリを新規作成・初期化します。\n\n## 前提条件\n\n- GitHub CLI (`gh`) がインストール済み\n- `gh auth login` で認証済み\n- fal.ai APIキー (`FAL_KEY`) が `.env` に設定済み（ヘッダー画像生成用）\n\n## ワークフロー\n\n### 1. 引数解析\n`$ARGUMENTS` からリポジトリ名とオプションを特定:\n\n- `repo-create [name]` → リポジトリ名\n- `--public` / `--private` → 可視性（デフォルト: public）\n- `--description` / `-d` → 説明\n- `--clone` → カレントディレクトリにclone\n\n### 2. 作成手順\n\n1. **リポジトリ名の決定**\n   - 引数指定 → 使用\n   - 未指定 → カレントディレクトリ名を使用\n\n2. **GitHubリポジトリ作成**\n   ```bash\n   gh repo create [name] --[public|private] --description \"[description]\"\n   ```\n\n3. **初期ファイル生成**（--clone 指定時）\n\n   詳細は [references/](references/) を参照:\n   - `README-template.md` - README.md テンプレート\n   - `LICENSE-options.md` - ライセンス選択ガイド\n   - `badges.md` - バッジ一覧\n   - `EXAMPLES.md` - 使用例\n\n   **生成するファイル:**\n   - `README.md` - テンプレートをベースに作成\n   - `.gitignore` - 言語自動検出（`gh repo create` のデフォルト）\n   - `LICENSE` - 選択プロンプト（MIT/Apache-2.0/GPL-3.0等）→ See [LICENSE-options.md](references/LICENSE-options.md)\n   - `assets/` - 画像用ディレクトリ作成\n\n4. **ヘッダー画像生成**（fal.ai Nano Banana Pro）\n\n   詳細は [references/header-image-generation.md](references/header-image-generation.md) を参照。\n\n   **手順:**\n   1. リポジトリの内容を分析して適切なスタイルとカラーマップを選択\n   2. エレガントなフォントを使用したヘッダー画像のプロンプトを構築\n   3. Nano Banana Pro で画像生成\n   4. 生成された画像を `assets/header.png` にリネームして保存\n\n   **実行コマンド:**\n   ```bash\n   npx tsx .claude/skills/fal-ai/scripts/t2i-nano-banana-pro.ts \"<prompt>\" --size 16:9 --resolution 2k --format png --output ./assets\n   ```\n\n5. **Initial Commit**\n   ```bash\n   git init\n   git branch -M main\n   git add .\n   git commit -m \"Initial commit\"\n   git push -u origin main\n   ```\n\n6. **完了メッセージ**\n   - リポジトリURL\n   - 次のステップ\n\n## 使用例\n\n詳細な使用例は [references/EXAMPLES.md](references/EXAMPLES.md) を参照。\n\n```bash\n/repo-create my-awesome-project\n/repo-create my-app --private --description \"My awesome app\"\n/repo-create my-lib --clone\n```\n"},"lastSynced":"2026-03-08T02:07:07.224Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Productivity Agents automating GitHub repository setup and initialization workflows.","zh":"适用于开发者生产力代理自动执行 GitHub 仓库设置和初始化工作流的理想场景。","ja":"GitHub リポジトリの設定と初期化ワークフローを自動化する Developer Productivity エージェントに最適です。","ko":"GitHub 리포지토리 설정 및 초기화 워크플ロー 자동화를 위한 개발자 생산성 에이전트에 적합합니다.","es":"Ideal para Agentes de Productividad de Desarrolladores que automatizan la configuración y la inicialización de flujos de trabajo del repositorio de GitHub.","fr":"Idéal pour les Agents de productivité des développeurs automatisant la configuration et l''initialisation des flux de travail du référentiel GitHub.","de":"Ideal für Developer-Produktivitätsagenten, die die Einrichtung und Initialisierung von GitHub-Repository-Workflows automatisieren.","pt":"Ideal para Agentes de Produtividade de Desenvolvedor que automatizam a configuração e os fluxos de trabalho de inicialização de repositórios GitHub.","ru":"Идеально подходит для Агентов Повышения Производительности Разработчиков, автоматизирующих настройку репозитория GitHub и рабочие процессы инициализации.","ar":"مثالي لوكلاء إنتاجية المطورين الذين يقومون بأتمتة إعداد مستودعات GitHub وسير عمل التهيئة."},"recommendation":{"en":"Enables automated GitHub repository creation using GitHub CLI (gh) with configurable visibility (public/private), description, and cloning options. Integrates fal.ai API for header image generation through environment variables.","zh":"通过 GitHub CLI（gh）启用自动化的 GitHub 仓库创建，具有可配置的可见性（公有/私有）、描述和克隆选项。通过环境变量集成了 fal.ai API，用于生成头图像。","ja":"GitHub CLI（gh）を使用した自動化されたGitHubリポジトリの作成を可能にし、可視性（パブリック/プライベート）、説明、クローンのオプションを設定できます。環境変数を通じて fal.ai API を統合し、ヘッダー画像の生成を可能にします。","ko":"GitHub CLI(gh)를 사용하여 자동화된 GitHub 리포지토리 생성을 가능하게 하며, 공개/비공개와 같은 가시성, 설명 및 클론 옵션을 구성할 수 있습니다. 또한 환경 변수를 통해 fal.ai API를 통합하여 헤더 이미지를 생성합니다.","es":"Permite la creación automática de repositorios de GitHub utilizando GitHub CLI (gh) con visibilidad configurable (pública/privada), descripción y opciones de clonación. Integra la API de fal.ai para la generación de imágenes de encabezado a través de variables de entorno.","fr":"Permet la création automatisée de référentiels GitHub en utilisant GitHub CLI (gh) avec une visibilité configurable (publique/privée), une description et des options de clonage. Intègre l''API fal.ai pour la génération d''images d''en-tête via des variables d''environnement.","de":"Ermöglicht die automatisierte Erstellung von GitHub-Repositorys unter Verwendung von GitHub CLI (gh) mit konfigurierbarer Sichtbarkeit (öffentlich/privat), Beschreibung und Klonoptionen. Integriert die fal.ai-API für die Generierung von Header-Bildern über Umgebungsvariablen.","pt":"Permite a criação automatizada de repositórios GitHub usando a GitHub CLI (gh) com visibilidade configurável (pública/privada), descrição e opções de clonagem. Integra a API do fal.ai para geração de imagem de cabeçalho por meio de variáveis de ambiente.","ru":"Обеспечивает автоматизированное создание репозиториев GitHub с использованием GitHub CLI (gh) с настраиваемой видимостью (публичная/частная), описанием и опциями клонирования. Интегрирует API fal.ai для создания изображений заголовков через переменные окружения.","ar":"يتيح إنشاء مستودعات GitHub تلقائيًا باستخدام GitHub CLI (gh) مع إمكانية تكامل الرؤية (عام/خاص)، والوصف، وخيارات الاستنساخ. يُدمج مع واجهة برمجة تطبيقات fal.ai لتوليد صور الرأس من خلال متغيرات البيئة."},"useCases":{"en":["Automating project bootstrap workflows","Initializing repositories with standardized configurations","Generating header images via fal.ai integration","Cloning repositories directly to working directories"],"zh":["自动化项目启动工作流程","使用标准化配置初始化仓库","通过 fal.ai 集成生成头图像","直接克隆仓库到工作目录"],"ja":["プロジェクトのブートストラップ ワークフローを自動化する","標準化された構成でリポジトリを初期化する","fal.ai 統合を介してヘッダー画像を生成する","リポジトリを直接作業ディレクトリにクローンする"],"ko":["프로젝트 부트스트랩 워크플로 자동화","표준 구성으로 리포지토리 초기화","fal.ai 통합을 통해 헤더 이미지 생성","리포지토리를 직접 작업 디렉토리에 클론"],"es":["Automatizar flujos de trabajo de inicialización de proyectos","Inicializar repositorios con configuraciones estandarizadas","Generar imágenes de encabezado a través de la integración con fal.ai","Clonar repositorios directamente en directorios de trabajo"],"fr":["Automatiser les flux de travail de démarrage de projet","Initialiser les référentiels avec des configurations standardisées","Générer des images d''en-tête via l''intégration avec fal.ai","Cloner les référentiels directement dans les répertoires de travail"],"de":["Automatisieren von Projekt-Bootstrap-Workflows","Initialisieren von Repositorys mit standardisierten Konfigurationen","Generieren von Header-Bildern über die Integration mit fal.ai","Klonen von Repositorys direkt in Arbeitsverzeichnisse"],"pt":["Automatizando fluxos de trabalho de inicialização de projetos","Inicializando repositórios com configurações padronizadas","Gerando imagens de cabeçalho via integração com fal.ai","Clonando repositórios diretamente para diretórios de trabalho"],"ru":["Автоматизация рабочих процессов начальной загрузки проекта","Инициализация репозиториев со стандартизированными конфигурациями","Генерация изображений заголовков через интеграцию с fal.ai","Клонирование репозиториев непосредственно в рабочие директории"],"ar":["أتمتة سير عمل تهيئة المشروع","تهيئة المستودعات بإعدادات قياسية","توليد صور الرأس عبر التكامل مع fal.ai","استنساخ المستودعات مباشرة إلى أدلة العمل"]},"limitations":{"en":["Requires GitHub CLI installation and authentication","Needs fal.ai API key in .env file","Dependent on gh command-line tool functionality"],"zh":["需要安装和认证 GitHub CLI","需要在 .env 文件中包含 fal.ai API 密钥","依赖于 gh 命令行工具的功能"],"ja":["GitHub CLIのインストールと認証が必要",".envファイルにfal.ai APIキーを含める必要がある","ghコマンドラインツールの機能に依存する"],"ko":["GitHub CLI 설치 및 인증이 필요합니다",".env 파일에 fal.ai API 키를 포함해야 합니다","gh 명령줄 도구의 기능에 의존합니다"],"es":["Requiere la instalación y autenticación de GitHub CLI","Necesita la clave de API de fal.ai en el archivo .env","Depende de la funcionalidad de la herramienta de línea de comandos gh"],"fr":["Nécessite l''installation et l''authentification de GitHub CLI","A besoin de la clé d''API fal.ai dans le fichier .env","Dépend de la fonctionnalité de l''outil de ligne de commande gh"],"de":["Benötigt die Installation und Authentifizierung von GitHub CLI","Benötigt den fal.ai-API-Schlüssel in der Datei .env","Hängt von der Funktionalität des gh-Befehlszeilentools ab"],"pt":["Requer a instalação e autenticação da GitHub CLI","Necessita de uma chave de API do fal.ai no arquivo .env","Dependente da funcionalidade da ferramenta de linha de comando gh"],"ru":["Требует установки и аутентификации GitHub CLI","Требуется ключ API fal.ai в файле .env","Зависит от функциональности командной строки gh"],"ar":["يتطلب تثبيت GitHub CLI والمصادقة","يحتاج إلى مفتاح واجهة برمجة تطبيقات fal.ai في ملف .env","يعتمد على وظيفة أداة سطر الأوامر gh"]},"version":4},"contentHash":"51842d02c728326072e5e9a26f3813f79777761fa411c27f6b9cb788aeacdd7c","qualityScore":36}');
