INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Sunwood-AI-OSS-Hub/zero-cc/repo-create', 'repo-create', 'Sunwood-AI-OSS-Hub', 'zero-cc', 'community', 'repo-create Sunwood-AI-OSS-Hub zero-cc community The repo-create skill automates GitHub repository creation and initialization for developers, using the GitHub CLI and fal.ai API key. repo-create是一个GitHub仓库创建工具，支持CLI和API密钥认证 repo-createはGitHubリポジトリを新規作成・初期化するAIエージェントです repo-create는 GitHub 리포지토리를 생성하고 초기화하는 도구입니다 repo-create es una herramienta para crear y configurar repositorios de GitHub. Utiliza GitHub CLI y autenticación para un proceso sencillo repo-create est un outil pour créer et configurer des référentiels GitHub. Il utilise GitHub CLI et l''authentification pour un processus simple repo-create ist ein Tool zum Erstellen und Konfigurieren von GitHub-Repositorys. Es verwendet GitHub CLI und Authentifizierung für einen einfachen Prozess O repo-create é uma ferramenta de linha de comando que cria e inicializa repositórios GitHub. Ele suporta opções como visibilidade pública ou privada e descrição do repositório. Repo-create - это инструмент командной строки, который создает и инициализирует репозитории GitHub. Он поддерживает опции, такие как публичная или приватная видимость и описание репозитория с помощью ИИ Агентов repo-create هو أداة سطر الأوامر التي تنشئ ومبادرة مستودعات جيت هاب. يدعم خيارات مثل الرؤية العامة أو الخاصة ووصف المستودع باستخدام أدوات الذكاء الاصطناعي how to use repo-create repo-create setup guide GitHub repository creation automation repo-create vs GitHub CLI repo-create install what is repo-create repo-create alternative automating GitHub workflows GitHub repository initialization repo-create GitHub仓库创建 AIエージェント CLI工具 API密钥认证 仓库管理 Creates new GitHub repositories using the `gh repo create` command Supports public and private repository visibility options via `--public` and `--private` flags Allows for custom repository descriptions using the `--description` or `-d` option Automates cloning of created repositories to the current directory with the `--clone` option Utilizes the fal.ai API key for header image generation Requires authentication via `gh auth login` for GitHub CLI repo-create is a GitHub repository creator skill that automates the process of creating and initializing new repositories using the GitHub CLI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cdeistopened/skill-stack/voice-matching-wizard', 'community', 'cdeistopened', 'skill-stack', 'cdeistopened/skill-stack', 'voice-matching-wizard', 0, 0, 36, '2026-03-08T01:57:15.415Z', '2026-03-08T02:07:12.363Z', '9366dbdf33613f2fbcc5d258022edba0b5bcbe10f26a8cdb461a8d53f946e2a1', '{"id":"cdeistopened/skill-stack/voice-matching-wizard","name":"voice-matching-wizard","description":{"en":"The voice-matching-wizard skill creates a voice skill that captures the patterns, rhythms, and sensibilities of any writing style, benefiting developers and writers alike.","zh":"声频匹配向导是一个创建语音技能的工具，能够捕捉任何写作风格的模式、节奏和细微差别","ja":"ボイスマッチングウィザードは、書き込みスタイルを認識するためのパターン、リズム、ニュアンスを抽出するAIツールです","ko":"보이스 매칭 마법사는 任意의 글쓰기 스타일을模倣하는 음성 스킬을 생성할 수 있는 도구입니다","es":"El asistente de coincidencia de voz es una herramienta que identifica patrones y ritmos en la escritura, permitiendo la creación de un asistente de voz personalizado","fr":"L''assistant de correspondance vocale est un outil qui identifie les modèles et les rythmes dans l''écriture, permettant la création d''un assistant vocal personnalisé","de":"Der Voice-Matching-Wizard ist ein Tool, das Muster und Rhythmen in der Schrift erkennt und die Erstellung eines benutzerdefinierten Voice-Assistenten ermöglicht","pt":"O Voice Matching Wizard é uma ferramenta de inteligência criativa que ajuda a identificar padrões e ritmos de estilos de escrita.","ru":"ИИ Агент Voice Matching Wizard — инструмент для распознавания шаблонов и стилей письма.","ar":"ساحر مطابقة الصوت هو أداة ذكاء إبداعي تساعد على تحديد الأنماط والإيقاعات لأي نمط كتابة."},"seo":{"title":{"en":"voice-matching-wizard: Voice Pattern Analysis Setup Guide...","zh":"声频匹配向导设置指南 - Voice Matching Wizard","ja":"ボイスマッチングウィザードのベストプラクティス - AIエージェント","ko":"보이스 매칭 마법사 설정 가이드 - AI Tools","es":"Guía de configuración del asistente de coincidencia de voz","fr":"Guide d''installation du wizard de correspondance vocale","de":"Einrichtungsleitfaden für den Voice-Matching-Wizard","pt":"Guia de Configuração do Voice Matching Wizard para Inteli...","ru":"Настройка ИИ Агента Voice Matching Wizard для Распознаван...","ar":"دليل إعداد ساحر مطابقة الصوت للذكاء الإبداعي"},"description":{"en":"Unlock the secrets of recognizable writing with voice-matching-wizard. Discover how to capture patterns, rhythms, and sensibilities. Get started now!","zh":"了解声频匹配向导的技术细节，创建一个捕捉任何写作风格的模式、节奏和细微差别的语音技能","ja":"ボイスマッチングウィザードの機能を紹介します。AIエージェントを使用して、認識可能な書き込みスタイルを作成する方法を学びます","ko":"보이스 매칭 마법사의 기술 상세를 살펴보고, 任意의 글쓰기 스타일을模倣하는 음성 스킬을 생성하는 방법을 알아보세요","es":"Aprende a crear un asistente de voz que capture patrones y ritmos de cualquier estilo de escritura con nuestra guía de coincidencia de voz","fr":"Découvrez comment créer un assistant vocal qui capture les modèles et les rythmes de n''importe quel style d''écriture avec notre guide de correspondance vocale","de":"Erfahren Sie, wie Sie einen Voice-Assistenten erstellen, der Muster und Rhythmen jedes Schreibstils erfasst, mit unserem Leitfaden für Voice-Matching","pt":"Aprenda a criar habilidades de voz que capturam padrões e ritmos de estilos de escrita com o Voice Matching Wizard","ru":"Откройте возможности ИИ Агента Voice Matching Wizard для распознавания шаблонов и стилей письма","ar":"اكتشف كيفية إنشاء مهارات صوتية تقلد الأنماط والإيقاعات لأي نمط كتابة باستخدام ساحر مطابقة الصوت"},"definition":{"en":"voice-matching-wizard is a skill that identifies what makes writing recognizable, including vocabulary, sentence length, and deeper patterns like idea unfolding and pauses.","zh":"声频匹配向导是一种AI工具，用于创建语音技能以识别写作风格的模式和节奏","ja":"ボイスマッチングウィザードは、書き込みスタイルを認識するためのAIエージェントの一種です","ko":"보이스 매칭 마법사는 글쓰기 스타일을识别하는 음성 스킬을 생성하는 AI Tools입니다","es":"El asistente de coincidencia de voz es una herramienta de inteligencia artificial que analiza patrones de escritura","fr":"L''assistant de correspondance vocale est un outil d''intelligence artificielle qui analyse les modèles d''écriture","de":"Der Voice-Matching-Wizard ist ein KI-Tool, das Schreibmuster analysiert","pt":"O Voice Matching Wizard é uma técnica de inteligência artificial que identifica padrões de escrita.","ru":"ИИ Агент Voice Matching Wizard — это техника искусственного интеллекта для распознавания шаблонов письма.","ar":"ساحر مطابقة الصوت هو تقنية ذكاء اصطناعي لتحديد أنماط الكتابة."},"features":{"en":["Gathers representative writing samples for pattern analysis","Extracts patterns across multiple dimensions, including vocabulary and sentence length","Identifies deeper patterns like idea unfolding and writer pauses","Walks users through a step-by-step process for voice matching","Captures the sensibilities and rhythms of any writing style"],"zh":["支持多维度的模式抽取","能够识别写作风格的模式、节奏和细微差别","提供语音技能创建的向导式流程","支持代表性样本的收集和分析","能够提取写作风格的深层模式"],"ja":["多次元のパターン抽出をサポート","書き込みスタイルのパターン、リズム、ニュアンスを識別","ボイススキルの作成をガイドするワークフローを提供","代表的なサンプルの収集と分析をサポート","書き込みスタイルの深層パターンを抽出"],"ko":["다중 차원의 패턴 추출을 지원","글쓰기 스타일의 패턴, 리듬, 뉴앙스를 식별","음성 스킬 생성을 위한 가이드式 프로세스를 제공","대표적인 샘플의 수집과 분석을 지원","글쓰기 스타일의 깊은 패턴을 추출"],"es":["Análisis de patrones de escritura en múltiples dimensiones","Extracción de patrones y ritmos de la escritura","Creación de un asistente de voz personalizado","Identificación de marcadores y patrones de escritura","Análisis de la estructura y el ritmo de la escritura"],"fr":["Analyse de modèles d''écriture en plusieurs dimensions","Extraction de modèles et de rythmes d''écriture","Création d''un assistant vocal personnalisé","Identification de marqueurs et de modèles d''écriture","Analyse de la structure et du rythme de l''écriture"],"de":["Analyse von Schreibmustern in mehreren Dimensionen","Extraktion von Mustern und Rhythmen der Schrift","Erstellung eines benutzerdefinierten Voice-Assistenten","Identifizierung von Markern und Schreibmustern","Analyse der Struktur und des Rhythmus der Schrift"],"pt":["Criação de habilidades de voz personalizadas","Análise de padrões de escrita em múltiplas dimensões","Extração de padrões de texto","Reconhecimento de estilos de escrita","Desenvolvimento de inteligência criativa"],"ru":["Создание индивидуальных голосовых навыков","Анализ шаблонов письма в нескольких измерениях","Извлечение шаблонов текста","Распознавание стилей письма","Разработка творческого интеллекта"],"ar":["إنشاء مهارات صوتية مخصصة","تحليل الأنماط الكتابية في أبعاد متعددة","استخراج أنماط النص","تحديد أنماط الكتابة","تنمية الذكاء الإبداعي"]},"keywords":{"en":["how to use voice-matching-wizard","what is voice-matching-wizard","voice-matching-wizard alternative","voice-matching-wizard setup guide","voice-matching-wizard install","voice pattern analysis tools","writing style recognition software","voice-matching-wizard vs writing analysis tools"],"zh":["声频匹配向导","AI工具","语音技能","写作风格识别","模式抽取","多维度分析","代表性样本收集","深层模式提取"],"ja":["ボイスマッチングウィザード","AIエージェント","ボイススキル","書き込みスタイル識別","パターン抽出","多次元分析","代表的なサンプルの収集","深層パターン抽出"],"ko":["보이스 매칭 마법사","AI Tools","음성 스킬","글쓰기 스타일 식별","패턴 추출","다중 차원 분석","대표적인 샘플 수집","깊은 패턴 추출"],"es":["asistente de voz","coincidencia de voz","inteligencia artificial","análisis de patrones","escritura personalizada","herramientas de voz","desarrollo de asistentes de voz","tecnologías de voz","IA para escritura"],"fr":["assistant vocal","correspondance vocale","intelligence artificielle","analyse de modèles","écriture personnalisée","outils de voix","développement d''assistants vocaux","technologies de voix","IA pour l''écriture"],"de":["Voice-Assistent","Voice-Matching","Künstliche Intelligenz","Musteranalyse","personalisierte Schrift","Voice-Tools","Entwicklung von Voice-Assistenten","Sprachtechnologien","KI für Schrift"],"pt":["inteligência criativa","reconhecimento de voz","análise de padrões","desenvolvimento de habilidades de voz","ferramentas de IA","IA para escrita","reconhecimento de estilos de escrita"],"ru":["ИИ Агенты","распознавание голоса","анализ шаблонов","разработка голосовых навыков","инструменты ИИ","ИИ для письма","распознавание стилей письма"],"ar":["أدوات الذكاء الاصطناعي","تحليل الصوت","تحليل الأنماط","تطوير المهارات الصوتية","أدوات ال IA","الذكاء الاصطناعي للكتابة","تحديد أنماط الكتابة"]}},"owner":"cdeistopened","repo":"skill-stack","repoPath":"cdeistopened/skill-stack","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.415Z","topics":[],"category":"community","skillMd":{"name":"voice-matching-wizard","description":"Transform writing samples into a codified voice style that can be replicated consistently. This wizard guides you through analyzing samples, extracting patterns, and generating a custom voice skill.","bodyPreview":"# Voice Matching Wizard\n\nCreate a voice skill that captures the patterns, rhythms, and sensibilities of any writing style.\n\n## What This Does\n\nVoice matching is the art of identifying what makes writing *recognizable*. Not just the obvious markers—vocabulary, sentence length—but the deeper patterns: how ideas unfold, where the writer pauses, what they leave unsaid.\n\nThis wizard walks you through the process of:\n1. Gathering representative samples\n2. Extracting patterns across multiple dimensions","body":"# Voice Matching Wizard\n\nCreate a voice skill that captures the patterns, rhythms, and sensibilities of any writing style.\n\n## What This Does\n\nVoice matching is the art of identifying what makes writing *recognizable*. Not just the obvious markers—vocabulary, sentence length—but the deeper patterns: how ideas unfold, where the writer pauses, what they leave unsaid.\n\nThis wizard walks you through the process of:\n1. Gathering representative samples\n2. Extracting patterns across multiple dimensions\n3. Synthesizing a usable voice profile\n4. Generating a working skill file\n\nThe output is a `voice-[name].skill.md` you can use alongside other skills (like `anti-ai-writing`) for consistent, authentic content.\n\n---\n\n## Before You Begin\n\n**What makes a good sample:**\n- At least 500 words\n- Writing you''re proud of (or writing you want to emulate)\n- Representative of the voice you want to capture\n- From the same medium (all newsletters, all blog posts, etc.)\n\n**What to avoid:**\n- Heavily edited committee writing\n- Content written under constraints\n- Mixed formats (tweets + longform together)\n- Very old work that doesn''t reflect current voice\n\n**How many samples:**\n- 2-3 samples: Basic patterns\n- 4-5 samples: Good coverage\n- 10+: Comprehensive capture\n\n---\n\n## Three Paths Through This Wizard\n\n### Path A: \"I have samples of my own writing\"\nYou want to codify your existing voice so AI can match it consistently.\n→ Skip to **Phase 1: Gather Your Samples**\n\n### Path B: \"I want to write like [someone I admire]\"\nYou want to emulate an author, publication, or brand voice.\n→ If the writer is well-known (major author, publication), you may be able to use their name directly in prompts. For custom or lesser-known voices, you''ll still need samples.\n→ Proceed to **Phase 1: Gather Your Samples**\n\n### Path C: \"I''m not sure what my voice is yet\"\nYou want to discover and develop your voice through this process.\n→ Start with **Phase 0: Voice Discovery** (below)\n\n---\n\n## Phase 0: Voice Discovery (Optional)\n\n*Skip this if you already have samples or know what voice you want.*\n\nTo discover your voice, we need to understand how you naturally communicate when you''re not performing.\n\n**Answer these questions:**\n\n1. **How do you explain things to friends?**\n   - Do you use stories and examples?\n   - Do you build logical arguments?\n   - Do you make jokes?\n   - Do you ask questions to draw them in?\n\n2. **What writers or publications do you gravitate toward?**\n   - Not who you think you *should* read—who do you actually read?\n   - What about their style appeals to you?\n\n3. **What''s your natural sentence length?**\n   - Short and punchy?\n   - Long and flowing?\n   - Variable depending on the point?\n\n4. **How do you feel about jargon?**\n   - Love it (signals expertise)?\n   - Hate it (pretentious)?\n   - Use it sparingly when precise?\n\n5. **What''s your relationship with your reader?**\n   - Peer/friend?\n   - Mentor/teacher?\n   - Curious explorer?\n\nBased on your answers, find 2-3 pieces you''ve written that feel authentic. Use those for Phase 1.\n\n---\n\n## Phase 1: Gather Samples\n\nCollect 2-5 writing samples. Paste each one into a separate document, or note where they can be found.\n\n**For each sample, note:**\n- Source/context (blog post, newsletter, etc.)\n- When it was written\n- Why you chose it\n\n---\n\n## Phase 2: Extract Patterns\n\nAnalyze each sample across these dimensions:\n\n### 2.1 Sentence Architecture\n\n| Element | What to Look For |\n|---------|------------------|\n| **Length** | Average sentence length (short/medium/long) |\n| **Variation** | Does length vary deliberately for rhythm? |\n| **Complexity** | Simple declarative? Compound? Complex? |\n| **Punctuation** | Em dashes? Semicolons? Minimal? |\n| **Fragments** | Used for emphasis? Never? |\n\n**Signature structures to identify:**\n- Opening patterns (\"Here''s the thing:\")\n- Rhythm breaks (\"But.\")\n- List patterns (\"First... Second... Third...\")\n- Closing moves (questions, callbacks, calls to action)\n\n### 2.2 Word Choice\n\n| Element | What to Look For |\n|---------|------------------|\n| **Vocabulary level** | Simple/moderate/sophisticated |\n| **Formality** | 1-5 scale (casual to formal) |\n| **Contractions** | Always/sometimes/never |\n| **Jargon** | Industry terms? Avoided? |\n| **Strong language** | Profanity level/style if any |\n\n**Identify:**\n- Favorite words (appears 3+ times across samples)\n- Avoided words (never appears despite opportunity)\n- Signature phrases\n\n### 2.3 Tone & Attitude\n\n| Element | What to Look For |\n|---------|------------------|\n| **Emotional register** | Warm? Cool? Intense? Measured? |\n| **Reader relationship** | Peer? Mentor? Friend? Expert? |\n| **Humor style** | Sarcasm? Wordplay? Self-deprecation? None? |\n| **Certainty level** | Definitive or exploratory? |\n| **Attitude toward subject** | Passionate? Skeptical? Curious? |\n\n### 2.4 Structural Moves\n\n| Element | What to Look For |\n|---------|------------------|\n| **Openings** | Story? Question? Bold claim? Scene-setting? |\n| **Transitions** | Seamless? Signposted? Abrupt? |\n| **Closings** | Call to action? Question? Summary? Callback? |\n| **Paragraph length** | Short punchy? Long flowing? Mixed? |\n\n### 2.5 Distinctive Techniques\n\nWhat makes this voice *recognizable*?\n\n- Rhetorical devices (questions, analogies, callbacks)\n- Signature moves unique to this writer\n- How evidence is presented (data? anecdotes? logic?)\n- Pattern interrupts (how does the writer surprise?)\n\n### 2.6 What They DON''T Do\n\nJust as important:\n- Phrases never used\n- Structures avoided\n- Topics skipped\n- Formality levels never hit\n\n---\n\n## Phase 3: Synthesize\n\n### The Voice in One Paragraph\n\nWrite a single paragraph capturing the essence:\n\n> \"[Name]''s voice is [primary characteristics]. They write like [relationship to reader], using [key techniques]. Their tone is [tone], with [humor style if applicable]. Sentences tend to be [structure]. They favor [word choice] and avoid [avoidances]. The overall effect is [feeling/impact].\"\n\n### Voice Spectrum\n\nRate the voice on these scales (1-5):\n\n```\nFormal ←――――――――――→ Casual         [ ]\nExpert ←――――――――――→ Peer           [ ]\nSerious ←―――――――――→ Playful        [ ]\nReserved ←――――――――→ Opinionated    [ ]\nAbstract ←――――――――→ Concrete       [ ]\n```\n\n---\n\n## Phase 4: Generate the Voice Skill\n\nUsing your analysis, create `voice-[name].skill.md` with this structure:\n\n```markdown\n---\nname: voice-[name]\ndescription: Write in [Name]''s distinctive voice. [One sentence characterization]. Use with anti-ai-writing for authentic content.\n---\n\n# Voice: [Name]\n\n[Your one-paragraph voice description from Phase 3]\n\n## Voice Spectrum\n\n- Formal/Casual: [1-5]\n- Expert/Peer: [1-5]\n- Serious/Playful: [1-5]\n- Reserved/Opinionated: [1-5]\n- Abstract/Concrete: [1-5]\n\n## Core Characteristics\n\n### Sentence Architecture\n[Your findings from 2.1]\n\n### Word Choice\n[Your findings from 2.2]\n\n### Tone & Attitude\n[Your findings from 2.3]\n\n### Structural Moves\n[Your findings from 2.4]\n\n### Distinctive Techniques\n[Your findings from 2.5]\n\n### Avoidances\n[Your findings from 2.6]\n\n## Example Patterns\n\n### Signature Openings\n[3-5 examples from samples with pattern explanation]\n\n### Signature Transitions\n[3-5 examples]\n\n### Signature Closings\n[3-5 examples]\n\n### Signature Sentences\n[5-10 exemplary sentences that capture the voice]\n\n## The [Name] Test\n\nBefore publishing, ask:\n- [ ] Would [Name] actually write this sentence?\n- [ ] Does it match the voice spectrum above?\n- [ ] Are signature patterns present?\n- [ ] Are avoidances absent?\n- [ ] Does it *feel* right?\n\n## Anti-Patterns\n\nIf you see these, you''ve drifted from the voice:\n- [List 5-10 patterns that would violate this voice]\n```\n\n---\n\n## Phase 5: Validate\n\nTest your voice skill:\n\n1. Write a short piece using only the voice skill\n2. Compare to original samples\n3. Identify gaps or mischaracterizations\n4. Refine based on testing\n\n**Validation checklist:**\n- [ ] Voice description captures the essence\n- [ ] Spectrum ratings feel accurate\n- [ ] Example patterns are genuinely representative\n- [ ] Test output sounds like the samples\n- [ ] Nothing important was missed\n\n---\n\n## Human Writing Fundamentals\n\n*Every voice skill should build on these principles from `anti-ai-writing`.*\n\n### The Energy Transfer Principle\n\nThe best writing is a transfer of energy from writer to reader. When analyzing samples, notice how the writer transfers energy:\n- Do they write conversations or speeches?\n- Do they speak WITH their audience or AT them?\n- Where do they use specific, concrete language vs. abstract ideas?\n\n### The SUCKS Framework\n\nApply this when generating voice output:\n\n**S - Specific**: Who is the ONE reader?\n**U - Unique & Useful**: Does it change how they think, feel, or act?\n**C - Clear, Curious, Conversational**: Does it read like talking to a friend?\n**K - Kept Simple & Structured**: Simple ideas, clear structure?\n**S - Sticky**: Are there memorable phrases they''ll repeat?\n\n### Sticky Sentence Techniques\n\nWhen identifying signature sentences in Phase 2, look for these techniques:\n\n**Alliteration** — Same starting sounds\n- \"Specificity is the secret\"\n- \"The best jobs are neither decreed nor degreed\"\n\n**Symmetry** — Parallel structure\n- \"Read for awareness. Write for understanding.\"\n- \"It''s not 10,000 hours. It''s 10,000 iterations.\"\n\n**Contrast** — Opposing ideas\n- \"To be everywhere is to be nowhere.\"\n- \"Be clear, not clever. Concise, not complex.\"\n\n**Rhythm** — Pleasing cadence\n- Sentence length variation for effect\n- Short sentences for emphasis\n- Longer sentences for flow\n\nInclude the writer''s use of these techniques in your voice skill.\n\n### AI Tells to Eliminate\n\nWhen using your voice skill, watch for these patterns that signal AI involvement:\n\n**The Correlative Construction** (most common):\n- ❌ \"X aren''t just Y - they''re Z\"\n- ❌ \"It''s not about X, it''s about Y\"\n\n**Forbidden Openers**:\n- ❌ \"In the ever-evolving world of...\"\n- ❌ \"Gone are the days when...\"\n- ❌ \"Let that sink in\"\n\n**Hedging Language**:\n- ❌ \"This might help you\" → \"This will help you\"\n- ❌ \"It could be argued...\" → state it directly\n\n**Overused Softeners**:\n- Too much \"just\" and \"actually\"\n- Passive voice (\"was determined\")\n- Corporate jargon\n\n**Test:** For each sentence, ask: Would this appear in ChatGPT output? If yes, rewrite it.\n\n---\n\n## Using Your Voice Skill\n\nSave to: `.claude/skills/voice-[name]/SKILL.md`\n\n**Invoke alongside other skills:**\n- `voice-[name]` + `anti-ai-writing` = Authentic, humanized content\n- `voice-[name]` + `ghostwriter` = Long-form pieces in voice\n- `voice-[name]` + `social-content-creation` = Platform-specific posts\n\n**Update as needed:**\nYour voice evolves. Revisit the skill quarterly or when something feels off.\n\n---\n\n## Related Skills\n\n- **anti-ai-writing** — Core humanization engine (use with all voice work)\n- **ghostwriter** — For long-form content in someone else''s voice\n- **transcript-polisher** — For interview-based content\n\n---\n\n*One well-crafted voice skill compounds across everything you create.*\n"},"lastSynced":"2026-03-08T02:07:12.363Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing advanced writing style analysis and voice matching capabilities.","zh":"适合需要高级写作风格分析和语音匹配能力的语言代理。","ja":"高度な文章スタイル分析とボイスマッチング機能を必要とする言語エージェントに適しています。","ko":"선진적인 글쓰기 스타일 분석 및 음성 일치 기능이 필요한 언어 에이전트에 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan un análisis avanzado de estilo de escritura y capacidades de coincidencia de voz.","fr":"Parfait pour les Agents de Langage ayant besoin d''une analyse avancée de style d''écriture et de capacités de correspondance de voix.","de":"Perfekt für Sprachagenten, die eine erweiterte Schreibstilanalyse und Stimmenabgleichsfunktionen benötigen.","pt":"Perfeito para Agentes de Linguagem que necessitam de análise avançada de estilo de escrita e capacidades de correspondência de voz.","ru":"Идеально для языковых агентов, требующих продвинутого анализа стиля письма и возможностей голосового соответствия.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى تحليل متقدم للأسلوب الكتابي وقدرات مطابقة الصوت."},"recommendation":{"en":"Empowers agents to capture patterns, rhythms, and sensibilities of any writing style, utilizing techniques such as gathering representative samples and extracting patterns across multiple dimensions, including vocabulary, sentence length, and idea unfolding.","zh":"赋予代理能力捕捉任何写作风格的模式、节奏和情感，利用诸如收集代表性样本和在多个维度（包括词汇、句子长度和想法展开）中提取模式的技术。","ja":"エージェントに、代表的なサンプルを収集したり、語彙、文の長さ、アイデアの展開など、多次元でパターンを抽出したりする技術を使用して、どのような文章スタイルでもパターン、リズム、感性を捉える能力を付与します。","ko":"어떤 글쓰기 스타일이라도 패턴, 리듬, 감성 등을 捕捉할 수 있는 능력을 에이전트에게 부여하며, 대표적인 샘플을 수집하거나 어휘, 문장 길이, 아이디어 전개 등 여러 차원에서 패턴을 추출하는 기술 등을 활용합니다.","es":"Permite a los agentes capturar patrones, ritmos y sensibilidades de cualquier estilo de escritura, utilizando técnicas como la recopilación de muestras representativas y la extracción de patrones en múltiples dimensiones, incluyendo vocabulario, longitud de oración e ideas desplegadas.","fr":"Permet aux agents de capturer des modèles, des rythmes et des sensibilités de n''importe quel style d''écriture, en utilisant des techniques telles que la collecte d''échantillons représentatifs et l''extraction de modèles sur plusieurs dimensions, notamment le vocabulaire, la longueur de phrase et le déroulement des idées.","de":"Ermöglich es den Agenten, Muster, Rhythmen und Sensibilitäten jedes Schreibstils zu erfassen, indem Techniken wie das Sammeln repräsentativer Stichproben und das Extrahieren von Mustern über mehrere Dimensionen hinweg verwendet werden, einschließlich Vokabular, Satzlänge und Ideenentfaltung.","pt":"Permite que os agentes capturem padrões, ritmos e sensibilidades de qualquer estilo de escrita, utilizando técnicas como coleta de amostras representativas e extração de padrões em várias dimensões, incluindo vocabulário, comprimento de frase e desenvolvimento de ideias.","ru":"Позволяет агентам захватить закономерности, ритмы и чувствительность любого стиля письма, используя такие методы, как сбор репрезентативных образцов и извлечение закономерностей в нескольких измерениях, включая словарный запас, длину предложения и развертывание идей.","ar":"يسمح للوكلاء بالتقاط الأنماط والأوزان والحساسية لأي أسلوب كتابي، باستخدام تقنيات مثل جمع عينات ممثلة واستخراج الأنماط عبر أبعاد متعددة، بما في ذلك المفردات وطول الجملة وتنمية الأفكار."},"useCases":{"en":["Analyzing authorial voice in literary texts","Generating content with a specific writing style","Identifying patterns in user-generated content"],"zh":["文学文本中的作者声音分析","以特定写作风格生成内容","用户生成内容中的模式识别"],"ja":["文学テキストにおける著者ボイスの分析","特定の文章スタイルでコンテンツを生成すること","ユーザー生成コンテンツにおけるパターンの識別"],"ko":["문학 텍스트에서의 저자 음성 분석","특정 글쓰기 스타일로 콘텐츠 생성","사용자 생성 콘텐츠에서의 패턴 식별"],"es":["Análisis de la voz autorial en textos literarios","Generación de contenido con un estilo de escritura específico","Identificación de patrones en contenido generado por el usuario"],"fr":["Analyse de la voix auteur dans les textes littéraires","Génération de contenu avec un style d''écriture spécifique","Identification de modèles dans le contenu généré par l''utilisateur"],"de":["Analyse der Autorenstimme in literarischen Texten","Erzeugung von Inhalten mit einem bestimmten Schreibstil","Identifizierung von Mustern in benutzergeneriertem Inhalt"],"pt":["Analisar a voz autoral em textos literários","Gerar conteúdo com um estilo de escrita específico","Identificar padrões em conteúdo gerado pelo usuário"],"ru":["Анализ авторского голоса в литературных текстах","Генерация контента с определенным стилем письма","Определение закономерностей в контенте, созданном пользователями"],"ar":["تحليل الصوت المؤلف في النصوص الأدبية","генерация المحتوى بأسلوب كتابي محدد","تحديد الأنماط في المحتوى الذي أنشأه المستخدم"]},"limitations":{"en":["Requires large representative samples of writing styles","May not work well with very short texts or texts with multiple authors"],"zh":["需要大量代表性的写作风格样本","可能不适用于非常短的文本或多个作者的文本"],"ja":["大量の代表的な文章スタイルのサンプルが必要","非常に短いテキストや複数の著者によるテキストではうまく機能しない可能性がある"],"ko":["대량의 대표적인 글쓰기 스타일 샘플이 필요","非常히 짧은 텍스트 또는 여러 저자의 텍스트에서는 잘 작동하지 않을 수 있음"],"es":["Requiere grandes muestras representativas de estilos de escritura","Puede no funcionar bien con textos muy cortos o textos con múltiples autores"],"fr":["Nécessite de grandes échantillons représentatifs de styles d''écriture","Peut ne pas fonctionner bien avec des textes très courts ou des textes avec plusieurs auteurs"],"de":["Benötigt große repräsentative Stichproben von Schreibstilen","Kann möglicherweise nicht gut mit sehr kurzen Texten oder Texten mit mehreren Autoren funktionieren"],"pt":["Requer amostras representativas grandes de estilos de escrita","Pode não funcionar bem com textos muito curtos ou textos com vários autores"],"ru":["Требует больших репрезентативных образцов стилей письма","Может не работать хорошо с очень короткими текстами или текстами с несколькими авторами"],"ar":["يتطلب عينات كبيرة وممثلة لأسلوب الكتابة","يمكن أن لا يعمل جيدًا مع نصوص قصيرة جدًا أو نصوص ذات مؤلفين متعددين"]},"version":4},"contentHash":"9366dbdf33613f2fbcc5d258022edba0b5bcbe10f26a8cdb461a8d53f946e2a1","qualityScore":36}');
