INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cdeistopened/skill-stack/voice-matching-wizard', 'voice-matching-wizard', 'cdeistopened', 'skill-stack', 'community', 'voice-matching-wizard cdeistopened skill-stack community The voice-matching-wizard skill creates a voice skill that captures the patterns, rhythms, and sensibilities of any writing style, benefiting developers and writers alike. 声频匹配向导是一个创建语音技能的工具，能够捕捉任何写作风格的模式、节奏和细微差别 ボイスマッチングウィザードは、書き込みスタイルを認識するためのパターン、リズム、ニュアンスを抽出するAIツールです 보이스 매칭 마법사는 任意의 글쓰기 스타일을模倣하는 음성 스킬을 생성할 수 있는 도구입니다 El asistente de coincidencia de voz es una herramienta que identifica patrones y ritmos en la escritura, permitiendo la creación de un asistente de voz personalizado L''assistant de correspondance vocale est un outil qui identifie les modèles et les rythmes dans l''écriture, permettant la création d''un assistant vocal personnalisé Der Voice-Matching-Wizard ist ein Tool, das Muster und Rhythmen in der Schrift erkennt und die Erstellung eines benutzerdefinierten Voice-Assistenten ermöglicht O Voice Matching Wizard é uma ferramenta de inteligência criativa que ajuda a identificar padrões e ritmos de estilos de escrita. ИИ Агент Voice Matching Wizard — инструмент для распознавания шаблонов и стилей письма. ساحر مطابقة الصوت هو أداة ذكاء إبداعي تساعد على تحديد الأنماط والإيقاعات لأي نمط كتابة. how to use voice-matching-wizard what is voice-matching-wizard voice-matching-wizard alternative voice-matching-wizard setup guide voice-matching-wizard install voice pattern analysis tools writing style recognition software voice-matching-wizard vs writing analysis tools 声频匹配向导 AI工具 语音技能 写作风格识别 模式抽取 多维度分析 代表性样本收集 深层模式提取 Gathers representative writing samples for pattern analysis Extracts patterns across multiple dimensions, including vocabulary and sentence length Identifies deeper patterns like idea unfolding and writer pauses Walks users through a step-by-step process for voice matching Captures the sensibilities and rhythms of any writing style voice-matching-wizard is a skill that identifies what makes writing recognizable, including vocabulary, sentence length, and deeper patterns like idea unfolding and pauses.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hinsley/DiffSymAgent/reduce-relie-basics', 'community', 'hinsley', 'DiffSymAgent', 'hinsley/DiffSymAgent', 'reduce-relie-basics', 0, 0, 36, '2026-03-08T01:57:15.425Z', '2026-03-08T02:07:28.117Z', 'cb4f6751ae17202b7c15ef1434fc73c2005d568f8de97290bc8b3da1c0f4118d', '{"id":"hinsley/DiffSymAgent/reduce-relie-basics","name":"reduce-relie-basics","description":{"en":"The reduce-relie-basics skill provides an AI agent workflow for Lie group methods in differential equations using REDUCE CAS and ReLie, benefiting developers working with differential equations and Lie group theory.","zh":"REDUCE 和 ReLie 基础环境设置指南，包括 Docker 和 CLI 的配置","ja":"REDUCE + ReLie の設定方法を学ぶ - Docker と CLI のベストプラクティス","ko":"REDUCE 및 ReLie 기본 설정을 위한 가이드 - Docker 및 CLI 설정","es":"reduce-relie-basics es un flujo de trabajo de agente de IA para métodos de grupo de Lie en ecuaciones diferenciales que utiliza REDUCE CAS y ReLie","fr":"reduce-relie-basics est un flux de travail d''agent d''IA pour les méthodes de groupe de Lie dans les équations différentielles qui utilise REDUCE CAS et ReLie","de":"reduce-relie-basics ist ein AI-Workflown für Lie-Gruppenmethoden in Differentialgleichungen, der REDUCE CAS und ReLie verwendet","pt":"O reduce-relie-basics é uma ferramenta de workflow do agente AI para métodos de grupo de Lie em equações diferenciais, utilizando REDUCE CAS e ReLie.","ru":"Reduce-relie-basics - это рабочий процесс агента ИИ для методов Ли в дифференциальных уравнениях, использующий REDUCE CAS и ReLie.","ar":"reduce-relie-basics هو أداة تدفق عمل للوكلاء الذكية لأدوات مجموعة لي في المعادلات التفاضلية، باستخدام REDUCE CAS و ReLie."},"seo":{"title":{"en":"reduce-relie-basics: Docker Setup Guide for AI Agents","zh":"REDUCE 和 ReLie 基础设置指南","ja":"REDUCE + ReLie のベストプラクティス - AIエージェントの設定","ko":"REDUCE 및 ReLie 기본 설정 가이드 - AI 도구","es":"Guía de configuración para reduce-relie-basics: Agentes d...","fr":"Guide de configuration pour reduce-relie-basics : Outils ...","de":"Konfigurationsleitfaden für reduce-relie-basics: KI-Tools...","pt":"Guia de Configuração do reduce-relie-basics para Lie Group","ru":"Руководство по настройке reduce-relie-basics для методов Ли","ar":"دليل إعداد reduce-relie-basics لأدوات مجموعة لي"},"description":{"en":"Get started with reduce-relie-basics AI agent workflow by setting up Docker and exploring Lie group methods in differential equations - learn how to ensure a...","zh":"了解如何设置 REDUCE 和 ReLie 基础环境，包括 Docker 和 CLI 的配置","ja":"AIエージェントの REDUCE + ReLie を設定するためのベストプラクティスを学ぶ","ko":"REDUCE 및 ReLie 기본 설정을 위한 Docker 및 CLI 설정 가이드","es":"Aprende a configurar reduce-relie-basics para trabajar con métodos de grupo de Lie en ecuaciones diferenciales con REDUCE CAS y ReLie","fr":"Découvrez comment configurer reduce-relie-basics pour travailler avec des méthodes de groupe de Lie dans les équations différentielles avec REDUCE CAS et ReLie","de":"Erfahren Sie, wie Sie reduce-relie-basics für die Arbeit mit Lie-Gruppenmethoden in Differentialgleichungen mit REDUCE CAS und ReLie konfigurieren","pt":"Aprenda a configurar o reduce-relie-basics com Docker e CLI para resolver equações diferenciais com métodos de grupo de Lie","ru":"Узнайте, как настроить reduce-relie-basics с помощью Docker и CLI для решения дифференциальных уравнений с помощью методов Ли","ar":"تعرف على كيفية إعداد reduce-relie-basics مع Docker و CLI لحل المعادلات التفاضلية بأدوات مجموعة لي"},"definition":{"en":"reduce-relie-basics is a technical skill for setting up and working with REDUCE CAS and ReLie in a Docker environment for Lie group methods in differential equations","zh":"REDUCE 和 ReLie 是一种用于微分方程的 Lie 群方法的 AI 工作流","ja":"REDUCE + ReLie は、微分方程式に対する Lie 群法の AI ワークフローです","ko":"REDUCE 및 ReLie 는 미분 방정식에 대한 Lie 群법의 AI 워크플로우입니다","es":"reduce-relie-basics es un agente de IA que aplica métodos de grupo de Lie en ecuaciones diferenciales","fr":"reduce-relie-basics est un agent d''IA qui applique des méthodes de groupe de Lie dans les équations différentielles","de":"reduce-relie-basics ist ein KI-Tool, das Lie-Gruppenmethoden auf Differentialgleichungen anwendet","pt":"O que é reduce-relie-basics? É uma ferramenta de workflow do agente AI para métodos de grupo de Lie.","ru":"Что такое reduce-relie-basics? Это рабочий процесс агента ИИ для методов Ли.","ar":"ما هو reduce-relie-basics? هو أداة تدفق عمل للوكلاء الذكية لأدوات مجموعة لي."},"features":{"en":["Ensures Docker daemon is reachable via `docker info` command","Checks Docker CLI availability with `docker --version`","Starts Docker Desktop on macOS with `open -a Docker`","Supports Colima startup with `colima start` command","Includes example wait loop for Docker daemon availability"],"zh":["使用 Docker 设置 REDUCE 和 ReLie 基础环境","配置 CLI 以确保 Docker 守护进程可达","使用 wait 循环等待 Docker 守护进程启动","支持 Colima 代替 Docker Desktop","提供 Docker 版本和信息检查","确保 Docker 守护进程可达并启动"],"ja":["Docker を使用して REDUCE + ReLie の基本環境を設定","CLI を設定して Docker デーモンに到達できるようにする","待機ループを使用して Docker デーモンの起動を待つ","Colima を Docker Desktop の代わりに使用する","Docker バージョンと情報の確認","Docker デーモンに到達して起動する"],"ko":["Docker 를 사용하여 REDUCE 및 ReLie 기본 환경을 설정","CLI 를 설정하여 Docker 데몬에 도달할 수 있도록 함","대기 루프를 사용하여 Docker 데몬의 시작을 기다림","Colima 를 Docker Desktop 의 대안으로 사용","Docker 버전 및 정보 확인","Docker 데몬에 도달하여 시작"],"es":["Utiliza REDUCE CAS para resolver ecuaciones diferenciales","Incorpora ReLie para métodos de grupo de Lie","Requiere Docker para su ejecución","Verifica la disponibilidad del daemon de Docker","Ofrece un bucle de espera para garantizar la disponibilidad de Docker","Utiliza CLI para interactuar con Docker"],"fr":["Utilise REDUCE CAS pour résoudre les équations différentielles","Intègre ReLie pour les méthodes de groupe de Lie","Nécessite Docker pour son exécution","Vérifie la disponibilité du démon de Docker","Offre une boucle d''attente pour garantir la disponibilité de Docker","Utilise CLI pour interagir avec Docker"],"de":["Verwendet REDUCE CAS zur Lösung von Differentialgleichungen","Integriert ReLie für Lie-Gruppenmethoden","Benötigt Docker für die Ausführung","Überprüft die Verfügbarkeit des Docker-Daemons","Bietet eine Warteschleife, um die Verfügbarkeit von Docker zu gewährleisten","Verwendet CLI zur Interaktion mit Docker"],"pt":["Utiliza Docker para garantir a disponibilidade do daemon","Verifica a versão do CLI do Docker","Utiliza o comando `docker info` para verificar a disponibilidade do daemon","Fornece um exemplo de loop de espera para garantir a disponibilidade do daemon","Suporta Colima como alternativa ao Docker Desktop"],"ru":["Использует Docker для обеспечения доступности демона","Проверяет версию CLI Docker","Использует команду `docker info` для проверки доступности демона","Предоставляет пример цикла ожидания для обеспечения доступности демона","Поддерживает Colima как альтернативу Docker Desktop"],"ar":["يستخدم Docker لضمان توافر الدايمون","يتحقق من إصدار واجهة سطر الأوامر في Docker","يستخدم الأمر `docker info` للتحقق من توافر الدايمون","يوفر مثالًا على حلقة الانتظار لضمان توافر الدايمون","يدعم Colima كبديل لبرنامج Docker Desktop"]},"keywords":{"en":["how to use reduce-relie-basics","reduce-relie-basics setup guide","reduce-relie-basics vs REDUCE CAS","reduce-relie-basics install","what is reduce-relie-basics","reduce-relie-basics alternative","Lie group methods in differential equations","REDUCE CAS tutorial","ReLie documentation"],"zh":["REDUCE 和 ReLie","Lie 群方法","微分方程","Docker","CLI","AI 工作流","设置指南","最佳实践"],"ja":["REDUCE + ReLie","Lie 群法","微分方程式","Docker","CLI","AI ワークフロー","設定方法","ベストプラクティス","AIエージェント"],"ko":["REDUCE 및 ReLie","Lie 群법","미분 방정식","Docker","CLI","AI 워크플로우","설정 가이드","최적의 관행","AI 도구"],"es":["agentes de IA para ecuaciones diferenciales","métodos de grupo de Lie","REDUCE CAS","ReLie","Docker","CLI","ecuaciones diferenciales","configuración de reduce-relie-basics","guía de configuración"],"fr":["outils d''IA pour équations différentielles","méthodes de groupe de Lie","REDUCE CAS","ReLie","Docker","CLI","équations différentielles","configuration de reduce-relie-basics","guide de configuration"],"de":["KI-Tools für Differentialgleichungen","Lie-Gruppenmethoden","REDUCE CAS","ReLie","Docker","CLI","Differentialgleichungen","Konfiguration von reduce-relie-basics","Konfigurationsleitfaden"],"pt":["reduce-relie-basics","métodos de grupo de Lie","equações diferenciais","Docker","CLI","REDUCE CAS","ReLie","agente AI","workflow","Colima"],"ru":["reduce-relie-basics","методы Ли","дифференциальные уравнения","Docker","CLI","REDUCE CAS","ReLie","агент ИИ","рабочий процесс","Colima"],"ar":["reduce-relie-basics","أدوات مجموعة لي","المعادلات التفاضلية","Docker","واجهة سطر الأوامر","REDUCE CAS","ReLie","الوكلاء الذكية","تدفق العمل","Colima"]}},"owner":"hinsley","repo":"DiffSymAgent","repoPath":"hinsley/DiffSymAgent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.425Z","topics":[],"category":"community","skillMd":{"name":"reduce-relie-basics","description":"Run REDUCE in Docker for this repo (using lunacamp/reduce-algebra), load the vendored ReLie file from resources/relie-src/relie.red, and perform a tiny smoke test. Use when you need the canonical docker run command or a minimal ReLie bootstrap.","bodyPreview":"# REDUCE + ReLie basics\n\n## Ensure Docker is running\n\n- Check the CLI is available: `docker --version`.\n- Check the daemon is reachable: `docker info`.\n- If the daemon is not available, start Docker Desktop (macOS: `open -a Docker`) and wait until `docker info` succeeds.\n  - Example wait loop:\n    ```bash\n    for i in {1..60}; do docker info >/dev/null 2>&1 && break; sleep 1; done\n    ```\n- If you use Colima instead of Docker Desktop, start it with `colima start` and then re-check `docker info`.","body":"# REDUCE + ReLie basics\n\n## Ensure Docker is running\n\n- Check the CLI is available: `docker --version`.\n- Check the daemon is reachable: `docker info`.\n- If the daemon is not available, start Docker Desktop (macOS: `open -a Docker`) and wait until `docker info` succeeds.\n  - Example wait loop:\n    ```bash\n    for i in {1..60}; do docker info >/dev/null 2>&1 && break; sleep 1; done\n    ```\n- If you use Colima instead of Docker Desktop, start it with `colima start` and then re-check `docker info`.\n- If you see `permission denied while trying to connect to the docker API at unix:///.../docker.sock`, rerun the command with elevated permissions or fix your socket access.\n  - In Codex CLI with sandboxing, rerun the docker command with escalated permissions so it can reach the socket.\n\n## Use local ReLie source\n\nUse the vendored ReLie file in this repo:\n\n`resources/relie-src/relie.red`\n\n## Run REDUCE in Docker (repo mounted)\n\nUse this canonical command from the repo root:\n\n```bash\ndocker run --rm -it --platform linux/amd64 \\\n  -v \"$PWD\":/workspace -w /workspace \\\n  --entrypoint /usr/lib/reduce/cslbuild/csl/reduce \\\n  lunacamp/reduce-algebra\n```\n\nNotes:\n- On Apple Silicon, keep `--platform linux/amd64`.\n- If `docker` is not in PATH, use its full path.\n\n## Load ReLie and run a tiny smoke test\n\nIn the REDUCE prompt:\n\n```reduce\nin \"resources/relie-src/relie.red\"$\n\n% Tiny smoke test: confirm the REPL responds after load.\n1+1;\n```\n\nExit with `bye;` when done.\n\n## Optional: run a tiny ReLie pipeline test (heat equation)\n\nThis mirrors a full run without interactive typing:\n\n```bash\ndocker run --rm -i --platform linux/amd64 \\\n  -v \"$PWD\":/workspace -w /workspace \\\n  --entrypoint /usr/lib/reduce/cslbuild/csl/reduce \\\n  lunacamp/reduce-algebra <<''EOF''\n\nin \"resources/relie-src/relie.red\"$\n\njetorder := 2$\nxvar := {t,x}$\nuvar := {u}$\ndiffeqs := {u_t - u_xx}$\nleadders := {u_xx}$\n\nrelie(4)$\nreliegen(1,{})$\n\nsymmetries;\ngenerators;\nbye;\nEOF\n```\n\nIf you present results to a user, summarize them in natural language (see `reduce-relie-lie-symmetries`).\n"},"lastSynced":"2026-03-08T02:07:28.117Z","agentAnalysis":{"suitability":{"en":"Ideal for Mathematical Computing Agents automating symbolic Lie group analysis of differential equations.","zh":"适用于数学计算代理自动进行符号李群分析的微分方程。","ja":"数学計算エージェントが微分方程式のリーグループ解析を自動化するために最適です。","ko":"수학 계산 에이전트가 미분 방정식의 기호 리 군 분석을 자동화하는 데 적합합니다.","es":"Ideal para agentes de computación matemática que automatizan el análisis de grupos de Lie simbólicos de ecuaciones diferenciales.","fr":"Idéal pour les agents de calcul mathématique automatisant l''analyse de groupes de Lie symboliques d''équations différentielles.","de":"Ideal für mathematische Rechenagenten, die die symbolische Lie-Gruppenanalyse von Differentialgleichungen automatisieren.","pt":"Ideal para Agentes de Computação Matemática que automatizam a análise simbólica de grupos de Lie de equações diferenciais.","ru":"Идеально подходит для агентов математических вычислений, автоматизирующих символический анализ групп Ли дифференциальных уравнений.","ar":"مثالي لوكلاء الحوسبة الرياضية الذين يقومون بأتمتة التحليل الرمزي لمجموعة ليه للمعادلات التفاضلية."},"recommendation":{"en":"Enables agents to execute REDUCE CAS workflows with ReLie for automated symmetry detection and reduction of differential equations through Lie group methods. Provides containerized execution environment via Docker for consistent computational algebra operations.","zh":"使代理能够通过ReLie执行REDUCE CAS工作流以自动检测和降低微分方程的对称性，并通过Docker提供容器化执行环境以进行一致的计算代数操作。","ja":"エージェントがReLieを使用してREDUCE CASワークフローを実行し、リーグループ法を使用して微分方程式の対称性を自動的に検出して削減することを可能にします。また、Dockerを介して一貫した計算代数操作のためにコンテナ化された実行環境を提供します。","ko":"에이전트가 ReLie를 사용하여 REDUCE CAS 워크플로를 실행하여 리 군 방법을 사용하여 미분 방정식의 대칭성을 자동으로 감지하고 감소 시키는 것을 가능하게 합니다. 또한 계산 대수 연산을 일관되게 수행하는 데 필요한 컨테이너화된 실행 환경을 Docker를 통해 제공합니다.","es":"Permite a los agentes ejecutar flujos de trabajo de REDUCE CAS con ReLie para la detección automática de simetría y reducción de ecuaciones diferenciales mediante métodos de grupo de Lie. Proporciona un entorno de ejecución containerizado a través de Docker para operaciones de álgebra computacional consistentes.","fr":"Permet aux agents d''exécuter des flux de travail REDUCE CAS avec ReLie pour la détection automatique de symétrie et la réduction d''équations différentielles par des méthodes de groupe de Lie. Fournit un environnement d''exécution containerisé via Docker pour des opérations d''algèbre computationnelle cohérentes.","de":"Ermöglicht es Agenten, REDUCE-CAS-Workflows mit ReLie für automatische Symmetrierkennung und Reduktion von Differentialgleichungen mit Lie-Gruppenmethoden auszuführen. Bietet eine containerisierte Ausführungsumgebung über Docker für konsistente computeralgebraische Operationen.","pt":"Permite que os agentes executem fluxos de trabalho REDUCE CAS com ReLie para detecção automática de simetria e redução de equações diferenciais por meio de métodos de grupo de Lie. Fornece um ambiente de execução conteinerizado via Docker para operações consistentes de álgebra computacional.","ru":"Позволяет агентам выполнять рабочие процессы REDUCE CAS с ReLie для автоматического обнаружения симметрии и редукции дифференциальных уравнений с помощью методов групп Ли. Обеспечивает контейнеризованную среду выполнения через Docker для согласованных операций вычислительной алгебры.","ar":"يمكن الوكلاء من تنفيذ سير عمل REDUCE CAS مع ReLie للكشف التلقائي عن التناظر واختزال المعادلات التفاضلية من خلال طرق مجموعة ليه. يوفر بيئة تنفيذ معزولة عبر Docker لعمليات الجبر الحسابي المتسقة."},"useCases":{"en":["Automating symmetry detection for ordinary differential equations","Generating Lie group transformations for PDE reduction","Executing containerized REDUCE CAS computations","Validating mathematical solutions through symbolic computation"],"zh":["自动检测普通微分方程的对称性","为PDE减少生成李群变换","执行容器化的REDUCE CAS计算","通过符号计算验证数学解"],"ja":["普通微分方程式の対称性を自動的に検出する","PDEの削減のためのリーグループ変換を生成する","コンテナ化されたREDUCE CAS計算を実行する","数学的な解を符号計算を通じて検証する"],"ko":["일반 미분 방정식의 대칭성을 자동으로 감지하는 것","PDE 감소를 위한 리 군 변환을 생성하는 것","컨테이너화된 REDUCE CAS 계산을 실행하는 것","수학적 해를 기호 계산을 통해 검증하는 것"],"es":["Automatizar la detección de simetría para ecuaciones diferenciales ordinarias","Generar transformaciones de grupo de Lie para la reducción de EDP","Ejecutar cálculos containerizados de REDUCE CAS","Validar soluciones matemáticas a través de cálculo simbólico"],"fr":["Automatiser la détection de symétrie pour les équations différentielles ordinaires","Générer des transformations de groupe de Lie pour la réduction des EDP","Exécuter des calculs containerisés REDUCE CAS","Valider les solutions mathématiques via le calcul symbolique"],"de":["Automatisieren der Symmetrierkennung für gewöhnliche Differentialgleichungen","Generieren von Lie-Gruppentransformationen für die Reduktion von PDE","Ausführen containerisierter REDUCE-CAS-Berechnungen","Validieren mathematischer Lösungen durch symbolische Berechnung"],"pt":["Automatização da detecção de simetria para equações diferenciais ordinárias","Geração de transformações de grupo de Lie para redução de EDPs","Execução de computações REDUCE CAS conteinerizadas","Validação de soluções matemáticas por meio de computação simbólica"],"ru":["Автоматическое обнаружение симметрии для обыкновенных дифференциальных уравнений","Генерация преобразований групп Ли для редукции уравнений в частных производных","Выполнение контейнеризованных вычислений REDUCE CAS","Проверка математических решений с помощью символьных вычислений"],"ar":["أتمتة الكشف عن التناظر للمعادلات التفاضلية العادية","توليد تحولات مجموعة ليه لاختزال المعادلات التفاضلية الجزئية","تنفيذ حسابات REDUCE CAS المعزولة","التحقق من صحة الحلول الرياضية من خلال الحوسبة الرمزية"]},"limitations":{"en":["Requires Docker runtime and active daemon","Dependent on REDUCE CAS and ReLie specific syntax","Needs manual Docker initialization if not running"],"zh":["需要Docker运行时和活动守护进程","依赖于REDUCE CAS和ReLie特定的语法","如果未运行则需要手动初始化Docker"],"ja":["Dockerランタイムとアクティブなデーモンが必要","REDUCE CASとReLieの特定の構文に依存している","実行されていない場合はDockerの手動初期化が必要"],"ko":["Docker 런타임과 활성 데몬이 필요합니다","REDUCE CAS 및 ReLie의 특정 구문에 의존합니다","실행되지 않은 경우 Docker의 수동 초기화를 필요로 합니다"],"es":["Requiere tiempo de ejecución de Docker y daemon activo","Depende de la sintaxis específica de REDUCE CAS y ReLie","Necesita inicialización manual de Docker si no se está ejecutando"],"fr":["Nécessite un temps d''exécution Docker et un daemon actif","Dépend de la syntaxe spécifique de REDUCE CAS et ReLie","Nécessite une initialisation manuelle de Docker si ce n''est pas le cas"],"de":["Benötigt Docker-Laufzeit und aktiven Daemon","Hängt von der spezifischen Syntax von REDUCE CAS und ReLie ab","Benötigt manuelle Docker-Initialisierung, wenn nicht gestartet"],"pt":["Requer o runtime do Docker e um daemon ativo","Dependente da sintaxe específica do REDUCE CAS e ReLie","Requer inicialização manual do Docker se não estiver em execução"],"ru":["Требуется среда выполнения Docker и активный демон","Зависит от конкретного синтаксиса REDUCE CAS и ReLie","Требует ручной инициализации Docker, если он не запущен"],"ar":["يتطلب وقت تشغيل Docker وبرنامج خفي نشط","يعتمد على بناء جملة محدد لـ REDUCE CAS و ReLie","يتطلب تهيئة Docker يدويًا إذا لم يكن قيد التشغيل"]},"version":4},"contentHash":"cb4f6751ae17202b7c15ef1434fc73c2005d568f8de97290bc8b3da1c0f4118d","qualityScore":36}');
