INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hinsley/DiffSymAgent/reduce-relie-basics', 'reduce-relie-basics', 'hinsley', 'DiffSymAgent', 'community', 'reduce-relie-basics hinsley DiffSymAgent community The reduce-relie-basics skill provides an AI agent workflow for Lie group methods in differential equations using REDUCE CAS and ReLie, benefiting developers working with differential equations and Lie group theory. REDUCE 和 ReLie 基础环境设置指南，包括 Docker 和 CLI 的配置 REDUCE + ReLie の設定方法を学ぶ - Docker と CLI のベストプラクティス REDUCE 및 ReLie 기본 설정을 위한 가이드 - Docker 및 CLI 설정 reduce-relie-basics es un flujo de trabajo de agente de IA para métodos de grupo de Lie en ecuaciones diferenciales que utiliza REDUCE CAS y ReLie reduce-relie-basics est un flux de travail d''agent d''IA pour les méthodes de groupe de Lie dans les équations différentielles qui utilise REDUCE CAS et ReLie reduce-relie-basics ist ein AI-Workflown für Lie-Gruppenmethoden in Differentialgleichungen, der REDUCE CAS und ReLie verwendet O reduce-relie-basics é uma ferramenta de workflow do agente AI para métodos de grupo de Lie em equações diferenciais, utilizando REDUCE CAS e ReLie. Reduce-relie-basics - это рабочий процесс агента ИИ для методов Ли в дифференциальных уравнениях, использующий REDUCE CAS и ReLie. reduce-relie-basics هو أداة تدفق عمل للوكلاء الذكية لأدوات مجموعة لي في المعادلات التفاضلية، باستخدام REDUCE CAS و ReLie. how to use reduce-relie-basics reduce-relie-basics setup guide reduce-relie-basics vs REDUCE CAS reduce-relie-basics install what is reduce-relie-basics reduce-relie-basics alternative Lie group methods in differential equations REDUCE CAS tutorial ReLie documentation REDUCE 和 ReLie Lie 群方法 微分方程 Docker CLI AI 工作流 设置指南 最佳实践 Ensures Docker daemon is reachable via `docker info` command Checks Docker CLI availability with `docker --version` Starts Docker Desktop on macOS with `open -a Docker` Supports Colima startup with `colima start` command Includes example wait loop for Docker daemon availability reduce-relie-basics is a technical skill for setting up and working with REDUCE CAS and ReLie in a Docker environment for Lie group methods in differential equations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tony/sdl3-playproject/plan-update', 'community', 'tony', 'sdl3-playproject', 'tony/sdl3-playproject', 'plan-update', 0, 0, 36, '2026-03-08T01:57:15.432Z', '2026-03-08T02:07:35.174Z', '00ecc57056c1abfab58a1aacc3c793251595d353b685b50e311e9ec8ac917287', '{"id":"tony/sdl3-playproject/plan-update","name":"plan-update","description":{"en":"The plan-update skill updates planning notes and commits documentation changes using Git commands, benefiting developers working on SDL3 play projects.","zh":"计划更新涉及更新计划笔记和提交文档更改，使用Git命令和SDL3","ja":"プラン更新は、GitコマンドとSDL3を使用して計画ノートとドキュメントを更新する","ko":"계획 업데이트는 Git 명령어와 SDL3를 사용하여 계획 노트와 문서를 업데이트하는 것을 포함","es":"plan-update es una habilidad que actualiza notas de planificación y documentos. Utiliza comandos Git como git branch y git log para recopilar información.","fr":"plan-update est une compétence qui met à jour les notes de planification et les documents. Elle utilise des commandes Git comme git branch et git log pour collecter des informations.","de":"plan-update ist eine Fähigkeit, die Planungsnotizen und Dokumente aktualisiert. Sie verwendet Git-Befehle wie git branch und git log, um Informationen zu sammeln.","pt":"O Plan-Update é uma ferramenta que atualiza notas de planejamento e committa alterações de documentação, utilizando comandos Git e SDL3.","ru":"Plan-Update - это инструмент, который обновляет заметки планирования и фиксирует изменения документации, используя команды Git и SDL3, а также ИИ Агенты.","ar":"التحديث الخطة هو أداة تحديث ملاحظات التخطيط وتعديلات الوثائق باستخدام أوامر Git و SDL3 وأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"plan-update: Git-Based Project Planning Setup Guide | AI ...","zh":"计划更新设置指南 - 使用SDL3和Vibe Coding","ja":"プラン更新のベストプラクティス - AIエージェントとCLIの活用","ko":"계획 업데이트 가이드 - SDL3 및 Vibe Coding을 사용하여","es":"Guía de Configuración de plan-update para Actualizaciones...","fr":"Guide de Configuration de plan-update pour Mises à Jour d...","de":"Konfigurationsleitfaden für plan-update zur Planaktualisi...","pt":"Guia de Configuração do Plan-Update: Atualize Seu Planeja...","ru":"Руководство по настройке Plan-Update: Обновите планирован...","ar":"دليل إعداد التحديث الخطة: قم بتحديث تخطيطك باستخدام SDL3 ..."},"description":{"en":"Discover how plan-update simplifies project planning with Git commands. Learn to update planning notes and commit documentation changes with ease.","zh":"了解计划更新的技术细节，包括Git命令和文档更新","ja":"プラン更新のための具体的な手順と技術要素を紹介","ko":"계획 업데이트에 대한 기술 정보 및 Git 명령어를 포함한 자세한 가이드","es":"Aprende a utilizar plan-update para actualizar notas de planificación y documentos. Descubre cómo ejecutar comandos Git y actualizar marcadores de estado.","fr":"Découvrez comment utiliser plan-update pour mettre à jour les notes de planification et les documents. Apprenez à exécuter des commandes Git et à mettre à jo...","de":"Erfahren Sie, wie Sie plan-update verwenden, um Planungsnotizen und Dokumente zu aktualisieren. Lernen Sie, Git-Befehle auszuführen und Statusmarken zu aktua...","pt":"Aprenda a atualizar seu planejamento com o Plan-Update, utilizando comandos Git e SDL3 para melhorar sua produtividade","ru":"Узнайте, как обновить планирование с помощью Plan-Update, используя команды Git и SDL3 для повышения производительности и ИИ Агентов","ar":"تعرف على كيفية تحديث تخطيطك باستخدام التحديث الخطة، باستخدام أوامر Git و SDL3 لتحسين إنتاجيتك وأدوات الذكاء الاصطناعي"},"definition":{"en":"plan-update is a skill that updates planning notes and commits documentation changes using Git commands like git branch and git status.","zh":"计划更新是指使用Git命令和SDL3更新计划笔记和提交文档更改的过程","ja":"プラン更新とは、GitコマンドとSDL3を使用して計画ノートとドキュメントを更新すること","ko":"계획 업데이트는 Git 명령어와 SDL3를 사용하여 계획 노트와 문서를 업데이트하는 것을 의미","es":"plan-update es una herramienta de inteligencia artificial que actualiza notas de planificación y documentos utilizando comandos Git.","fr":"plan-update est un outil d''intelligence artificielle qui met à jour les notes de planification et les documents en utilisant des commandes Git.","de":"plan-update ist ein KI-Tool, das Planungsnotizen und Dokumente mithilfe von Git-Befehlen aktualisiert.","pt":"O Plan-Update é uma ferramenta de atualização de planejamento que utiliza comandos Git e SDL3.","ru":"Plan-Update - это инструмент обновления планирования, который использует команды Git и SDL3, а также ИИ Агенты.","ar":"التحديث الخطة هو أداة تحديث التخطيط التي تستخدم أوامر Git و SDL3 وأدوات الذكاء الاصطناعي."},"features":{"en":["Runs Git commands to gather context, including `git branch --show-current` and `git status --short`","Updates status markers in `notes/plan.md` if it exists","Commits documentation changes to `UNREAL_CONVERSION_PLAN.md`","Executes `ls -la` commands to check for notes directory and plan files","Handles cases where `notes/plan.md` or `UNREAL_CONVERSION_PLAN.md` do not exist"],"zh":["使用Git命令更新计划笔记","提交文档更改","使用SDL3进行计划更新","运行`git branch --show-current`命令","运行`git status --short`命令","运行`git log -n 10 --oneline`命令"],"ja":["Gitコマンドを使用して計画ノートを更新","ドキュメントの変更をコミット","SDL3を使用してプラン更新","コマンド`git branch --show-current`を実行","コマンド`git status --short`を実行","コマンド`git log -n 10 --oneline`を実行"],"ko":["Git 명령어를 사용하여 계획 노트를 업데이트합니다","문서 변경을 커밋","SDL3를 사용하여 계획 업데이트를 수행","명령어 `git branch --show-current`를 실행","명령어 `git status --short`를 실행","명령어 `git log -n 10 --oneline`를 실행"],"es":["Actualiza notas de planificación utilizando comandos Git","Ejecuta comandos como git branch y git log para recopilar información","Actualiza marcadores de estado en notas de planificación","Utiliza comandos como ls -la para verificar la existencia de directorios y archivos","Compatible con documentos como UNREAL_CONVERSION_PLAN.md"],"fr":["Met à jour les notes de planification en utilisant des commandes Git","Exécute des commandes comme git branch et git log pour collecter des informations","Met à jour les marqueurs d''état dans les notes de planification","Utilise des commandes comme ls -la pour vérifier l''existence de répertoires et de fichiers","Compatible avec des documents tels que UNREAL_CONVERSION_PLAN.md"],"de":["Aktualisiert Planungsnotizen mithilfe von Git-Befehlen","Führt Befehle wie git branch und git log aus, um Informationen zu sammeln","Aktualisiert Statusmarken in Planungsnotizen","Verwendet Befehle wie ls -la, um die Existenz von Verzeichnissen und Dateien zu überprüfen","Kompatibel mit Dokumenten wie UNREAL_CONVERSION_PLAN.md"],"pt":["Atualiza notas de planejamento com comandos Git","Committa alterações de documentação com SDL3","Utiliza comandos como `git branch --show-current` e `git log -n 10 --oneline`","Verifica a existência de diretórios e arquivos como `notes/plan.md` e `UNREAL_CONVERSION_PLAN.md`","Executa comandos como `ls -la notes` e `ls -la UNREAL_CONVERSION_PLAN.md`"],"ru":["Обновляет заметки планирования с помощью команд Git","Фиксирует изменения документации с помощью SDL3 и ИИ Агентов","Использует команды как `git branch --show-current` и `git log -n 10 --oneline`","Проверяет существование директорий и файлов как `notes/plan.md` и `UNREAL_CONVERSION_PLAN.md`","Выполняет команды как `ls -la notes` и `ls -la UNREAL_CONVERSION_PLAN.md`"],"ar":["تحديث ملاحظات التخطيط باستخدام أوامر Git","تعديل وثائق باستخدام SDL3 وأدوات الذكاء الاصطناعي","استخدام أوامر مثل `git branch --show-current` و `git log -n 10 --oneline`","تحقق من وجود دلائل وأوراق مثل `notes/plan.md` و `UNREAL_CONVERSION_PLAN.md`","تنفيذ أوامر مثل `ls -la notes` و `ls -la UNREAL_CONVERSION_PLAN.md`"]},"keywords":{"en":["how to use plan-update","plan-update setup guide","git-based project planning","plan-update vs SDL3 play project","plan-update install","what is plan-update","plan-update alternative","git commands for project planning","plan-update documentation"],"zh":["计划更新","SDL3","Vibe Coding","Git命令","文档更新","计划笔记","AI工具","AIエージェント"],"ja":["プラン更新","SDL3","Vibe Coding","Gitコマンド","ドキュメント更新","計画ノート","AIエージェント","CLI"],"ko":["계획 업데이트","SDL3","Vibe Coding","Git 명령어","문서 업데이트","계획 노트","AI 툴","CLI"],"es":["plan-update","herramientas de inteligencia artificial","comandos Git","actualización de planificación","notas de planificación","documentos de planificación","git branch","git log","ls -la"],"fr":["plan-update","outils d''intelligence artificielle","commandes Git","mise à jour de planification","notes de planification","documents de planification","git branch","git log","ls -la"],"de":["plan-update","KI-Tools","Git-Befehle","Planaktualisierung","Planungsnotizen","Planungsdokumente","git branch","git log","ls -la"],"pt":["Plan-Update","SDL3","Git","planejamento","documentação","desenvolvimento de software","ferramentas de desenvolvimento","produtividade"],"ru":["Plan-Update","SDL3","Git","планирование","документация","разработка программного обеспечения","инструменты разработки","производительность","ИИ Агенты"],"ar":["التحديث الخطة","SDL3","Git","تخطيط","وثائق","تطوير البرمجيات","أدوات التطوير","إنتاجية","أدوات الذكاء الاصطناعي"]}},"owner":"tony","repo":"sdl3-playproject","repoPath":"tony/sdl3-playproject","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.432Z","topics":[],"category":"community","skillMd":{"name":"plan-update","description":"Update planning notes and commit the changes.","bodyPreview":"# Plan Update\n\nUpdate planning notes and commit documentation changes.\n\n## Context to gather\n\nRun these commands and include the output:\n\n- `git branch --show-current`\n- `git status --short`\n- `git log -n 10 --oneline`\n- `ls -la notes 2>/dev/null || echo \"No notes directory\"`\n- `ls -la UNREAL_CONVERSION_PLAN.md 2>/dev/null || echo \"No UNREAL_CONVERSION_PLAN.md\"`\n\n## Your task\n\n1. If `notes/plan.md` exists, read it fully and update status markers\n2. If there is no notes plan, update `UNREAL_CONVE","body":"# Plan Update\n\nUpdate planning notes and commit documentation changes.\n\n## Context to gather\n\nRun these commands and include the output:\n\n- `git branch --show-current`\n- `git status --short`\n- `git log -n 10 --oneline`\n- `ls -la notes 2>/dev/null || echo \"No notes directory\"`\n- `ls -la UNREAL_CONVERSION_PLAN.md 2>/dev/null || echo \"No UNREAL_CONVERSION_PLAN.md\"`\n\n## Your task\n\n1. If `notes/plan.md` exists, read it fully and update status markers\n2. If there is no notes plan, update `UNREAL_CONVERSION_PLAN.md` with current progress\n3. Cross-reference with recent commits to mark completed items\n4. Add new items discovered during recent work\n5. Commit independently:\n\n```\ndocs(notes) update plan status for <topic>\n\nwhy: Keep plan in sync with actual progress\nwhat:\n- Mark <items> as completed\n- Add <new items> discovered\n```\n\nImportant:\n- Do NOT start implementation\n- Only update notes/plan docs\n- Keep the commit focused on documentation changes only\n"},"lastSynced":"2026-03-08T02:07:35.174Z","agentAnalysis":{"suitability":{"en":"Essential for Development Workflow Agents managing project documentation and Git-based planning processes.","zh":"适用于管理项目文档和基于 Git 的规划过程的开发工作流代理。","ja":"プロジェクト文書と Git ベースの計画プロセスを管理する開発ワークフロー エージェントに不可欠です。","ko":"프로젝트 문서 및 Git 기반의 계획 프로세스를 관리하는 개발 워크플로우 에이전트에 필수적입니다.","es":"Esencial para los Agentes de flujo de trabajo de desarrollo que administran la documentación del proyecto y los procesos de planificación basados en Git.","fr":"Essentiel pour les agents de flux de travail de développement gérant la documentation de projet et les processus de planification basés sur Git.","de":"Wesentlich für Entwicklung-Workflow-Agents, die Projekt-Dokumentation und Git-basierte Planungsprozesse verwalten.","pt":"Essencial para Agents de Fluxo de Desenvolvimento que gerenciam documentação de projeto e processos de planejamento baseados em Git.","ru":"Необходимо для Development Workflow Agents, управляющих документацией проекта и процессами планирования на основе Git.","ar":"ضروري لعمليات وكيل تدفق التطوير الذين يديرون توثيق المشروع والعمليات التخطيطية القائمة على Git."},"recommendation":{"en":"Enables automated Git-based documentation maintenance by updating planning notes with status markers and committing changes through direct Git command execution. Provides project context awareness through branch status checking, file system inspection, and commit history analysis.","zh":"通过更新带有状态标记的规划注释并通过直接 Git 命令执行提交更改来实现自动化的 Git 基础文档维护。通过分支状态检查、文件系统检查和提交历史分析提供项目上下文感知。","ja":"ステータス マーカーを付けた計画ノートを更新し、直接の Git コマンド実行によって変更をコミットすることで、自動化された Git ベースのドキュメント メンテナンスを可能にします。ブランチの状態を確認したり、ファイル システムを調査したり、コミット履歴を分析したりすることで、プロジェクトのコンテキスト認識を提供します。","ko":"상태 표시기를 가진 계획 노트를 업데이트하고 직접 Git 명령 실행을 통해 변경을 커밋함으로써 자동화된 Git 기반 문서 유지관리가 가능합니다. 브랜치 상태 확인, 파일 시스템 조사, 커밋 기록 분석을 통해 프로젝트 컨텍스트 인식 제공합니다.","es":"Permite el mantenimiento automatizado de la documentación basada en Git al actualizar las notas de planificación con marcadores de estado y confirmar los cambios a través de la ejecución directa de comandos Git. Proporciona conciencia del contexto del proyecto a través de la comprobación del estado de la rama, la inspección del sistema de archivos y el análisis del historial de confirmación.","fr":"Permet la maintenance automatisée de la documentation basée sur Git en mettant à jour les notes de planification avec des marqueurs d''état et en confirmant les modifications via l''exécution directe de commandes Git. Fournit une prise de conscience du contexte du projet via la vérification de l''état de la branche, l''inspection du système de fichiers et l''analyse de l''historique de confirmation.","de":"Ermöglicht die automatisierte Wartung von Git-basierten Dokumentationen durch die Aktualisierung von Planungshinweisen mit Statusmarkern und die Bestätigung von Änderungen durch die direkte Ausführung von Git-Befehlen. Bietet Projekt-Kontextbewusstsein durch die Überprüfung des Branch-Status, die Inspektion des Dateisystems und die Analyse des Commit-Verlaufs.","pt":"Permite a manutenção automatizada de documentação baseada em Git, atualizando notas de planejamento com marcadores de status e commitando alterações por meio da execução direta de comandos Git. Fornece conscientização do contexto do projeto por meio da verificação do status da branch, inspeção do sistema de arquivos e análise do histórico de commits.","ru":"Позволяет автоматизировать обслуживание документации на основе Git, обновляя заметки о планировании метками статуса и фиксируя изменения путем прямого выполнения команд Git. Предоставляет осведомленность о контексте проекта путем проверки статуса ветки, инспекции файловой системы и анализа истории коммитов.","ar":"يمكّن من صيانة التوثيق الآلي القائم على Git من خلال تحديث ملاحظات التخطيط مع علامات الحالة وترشيح التغييرات من خلال تنفيذ أوامر Git المباشر. يوفر الوعي السياقي للمشروع من خلال التحقق من حالة الفرع والتحقق من نظام الملفات وتحليل سجل الإلتزامات."},"useCases":{"en":["Automating planning documentation updates with status markers","Committing project documentation changes via Git commands","Maintaining version control for SDL3 play project plans","Synchronizing notes/plan.md with current development progress"],"zh":["使用状态标记自动化规划文档更新","通过 Git 命令提交项目文档更改","维护 SDL3 游戏项目计划的版本控制","将 notes/plan.md 与当前开发进度同步"],"ja":["ステータス マーカーを使用して計画ドキュメントを自動更新する","Git コマンドを使用してプロジェクト ドキュメントの変更をコミットする","SDL3 プレイ プロジェクト プランのバージョン管理を維持する","notes/plan.md を現在の開発進度と同期する"],"ko":["상태 표시기를 사용하여 계획 문서를 자동 업데이트하는 것","Git 명령을 사용하여 프로젝트 문서의 변경을 커밋하는 것","SDL3 플레이 프로젝트 계획의 버전 관리를 유지하는 것","notes/plan.md 를 현재 개발 진행 상황과 동기화하는 것"],"es":["Automatizar las actualizaciones de la documentación de planificación con marcadores de estado","Confirmar los cambios de la documentación del proyecto a través de comandos Git","Mantener el control de versiones para los planes de proyectos de SDL3","Sincronizar notas/plan.md con el progreso de desarrollo actual"],"fr":["Automatiser les mises à jour de la documentation de planification avec des marqueurs d''état","Confirmer les modifications de la documentation de projet via des commandes Git","Maintenir le contrôle de version pour les plans de projets SDL3","Synchroniser notes/plan.md avec le progrès de développement actuel"],"de":["Automatisieren von Planungsdokumentations-Updates mit Statusmarkern","Bestätigen von Projektdokumentations-Änderungen über Git-Befehle","Wartung der Versionskontrolle für SDL3-Projekt-Pläne","Synchronisieren von notes/plan.md mit dem aktuellen Entwicklungsfortschritt"],"pt":["Automatizar atualizações de documentação de planejamento com marcadores de status","Commitar alterações de documentação de projeto via comandos Git","Manter controle de versão para planos de projeto SDL3","Sincronizar notas/plan.md com o progresso atual do desenvolvimento"],"ru":["Автоматизировать обновления документации планирования с метками статуса","Фиксировать изменения документации проекта через команды Git","Поддерживать контроль версий для планов проекта SDL3","Синхронизировать заметки/plan.md с текущим прогрессом разработки"],"ar":["تأتمتة تحديثات توثيق التخطيط مع علامات الحالة","إلتزام التغييرات في توثيق المشروع عبر أوامر Git","الحفاظ على سيطرة الإصدار لأنظمة تخطيط المشروع SDL3","مزامنة الملاحظات/plan.md مع التقدم الحالي في التطوير"]},"limitations":{"en":["Requires Git repository access and command execution permissions","Dependent on notes/plan.md or UNREAL_CONVERSION_PLAN.md file existence","Needs filesystem access for directory and file inspection"],"zh":["需要 Git 仓库访问和命令执行权限","依赖于 notes/plan.md 或 UNREAL_CONVERSION_PLAN.md 文件的存在","需要文件系统访问权限以进行目录和文件检查"],"ja":["Git リポジトリへのアクセスとコマンド実行の権限が必要","notes/plan.md または UNREAL_CONVERSION_PLAN.md ファイルの存在に依存する","ディレクトリとファイルのインスペクションを行うためにファイル システムへのアクセスが必要"],"ko":["Git 저장소 액세스 및 명령 실행 권한이 필요합니다.","notes/plan.md 또는 UNREAL_CONVERSION_PLAN.md 파일 존재에 종속됩니다.","디렉토리 및 파일 검사를 수행하기 위해 파일 시스템 액세스가 필요합니다."],"es":["Requiere acceso al repositorio Git y permisos de ejecución de comandos","Dependiente de la existencia del archivo notes/plan.md o UNREAL_CONVERSION_PLAN.md","Necesita acceso al sistema de archivos para la inspección de directorios y archivos"],"fr":["Nécessite un accès au référentiel Git et des autorisations d''exécution de commandes","Dépend de l''existence du fichier notes/plan.md ou UNREAL_CONVERSION_PLAN.md","Nécessite un accès au système de fichiers pour l''inspection des répertoires et des fichiers"],"de":["Erfordert Zugriff auf das Git-Repository und Befehlsausführungsberechtigungen","Abhängig von der Existenz der Datei notes/plan.md oder UNREAL_CONVERSION_PLAN.md","Benötigt Dateisystemzugriff für die Inspektion von Verzeichnissen und Dateien"],"pt":["Requer acesso ao repositório Git e permissões de execução de comandos","Dependente da existência do arquivo notes/plan.md ou UNREAL_CONVERSION_PLAN.md","Necessita acesso ao sistema de arquivos para inspeção de diretórios e arquivos"],"ru":["Требует доступа к репозиторию Git и разрешений на выполнение команд","Зависит от существования файла notes/plan.md или UNREAL_CONVERSION_PLAN.md","Требует доступа к файловой системе для инспекции директорий и файлов"],"ar":["يتطلب الوصول إلى مستودع Git والسماح بتنفيذ الأوامر","يعتمد على وجود ملف notes/plan.md أو UNREAL_CONVERSION_PLAN.md","يحتاج إلى الوصول إلى نظام الملفات للتحقق من الدلائل والملفات"]},"version":4},"contentHash":"00ecc57056c1abfab58a1aacc3c793251595d353b685b50e311e9ec8ac917287","qualityScore":36}');
