INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tony/sdl3-playproject/plan-update', 'plan-update', 'tony', 'sdl3-playproject', 'community', 'plan-update tony sdl3-playproject community The plan-update skill updates planning notes and commits documentation changes using Git commands, benefiting developers working on SDL3 play projects. 计划更新涉及更新计划笔记和提交文档更改，使用Git命令和SDL3 プラン更新は、GitコマンドとSDL3を使用して計画ノートとドキュメントを更新する 계획 업데이트는 Git 명령어와 SDL3를 사용하여 계획 노트와 문서를 업데이트하는 것을 포함 plan-update es una habilidad que actualiza notas de planificación y documentos. Utiliza comandos Git como git branch y git log para recopilar información. plan-update est une compétence qui met à jour les notes de planification et les documents. Elle utilise des commandes Git comme git branch et git log pour collecter des informations. plan-update ist eine Fähigkeit, die Planungsnotizen und Dokumente aktualisiert. Sie verwendet Git-Befehle wie git branch und git log, um Informationen zu sammeln. O Plan-Update é uma ferramenta que atualiza notas de planejamento e committa alterações de documentação, utilizando comandos Git e SDL3. Plan-Update - это инструмент, который обновляет заметки планирования и фиксирует изменения документации, используя команды Git и SDL3, а также ИИ Агенты. التحديث الخطة هو أداة تحديث ملاحظات التخطيط وتعديلات الوثائق باستخدام أوامر Git و SDL3 وأدوات الذكاء الاصطناعي. how to use plan-update plan-update setup guide git-based project planning plan-update vs SDL3 play project plan-update install what is plan-update plan-update alternative git commands for project planning plan-update documentation 计划更新 SDL3 Vibe Coding Git命令 文档更新 计划笔记 AI工具 AIエージェント Runs Git commands to gather context, including `git branch --show-current` and `git status --short` Updates status markers in `notes/plan.md` if it exists Commits documentation changes to `UNREAL_CONVERSION_PLAN.md` Executes `ls -la` commands to check for notes directory and plan files Handles cases where `notes/plan.md` or `UNREAL_CONVERSION_PLAN.md` do not exist plan-update is a skill that updates planning notes and commits documentation changes using Git commands like git branch and git status.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('oNya685/SysYTest/create-sysy-testcase', 'community', 'oNya685', 'SysYTest', 'oNya685/SysYTest', 'create-sysy-testcase', 0, 0, 36, '2026-03-08T01:57:15.437Z', '2026-03-08T02:07:39.502Z', '772a728653f78b74c2da2c8a22d336d5b1a5d835df43feb79592897432a565da', '{"id":"oNya685/SysYTest/create-sysy-testcase","name":"create-sysy-testcase","description":{"en":"The create-sysy-testcase skill converts standard C/C++ competitive programming code into Strict SysY and generates valid test data for compiler engineers. It adheres to specific grammar rules for accurate conversion.","zh":"create-sysy-testcase AI工具帮助您将C/C++代码转换为Strict SysY，生成有效的测试数据","ja":"SysYテストケースを作成するためのAIエージェントは、C/C++コードをStrict SysYに変換し、有効なテストデータを生成する","ko":"create-sysy-testcase AI 에이전트는 C/C++ 코드를 Strict SysY로 변환하고 유효한 테스트 데이터를 생성하여 테스트를 효율적으로进行합니다","es":"Convierte código C/C++ en Strict SysY y genera datos de prueba válidos con create-sysy-testcase. Una herramienta para ingenieros de compiladores.","fr":"Convertissez du code C/C++ en Strict SysY et générez des données de test valides avec create-sysy-testcase. Un outil pour les ingénieurs de compilateurs.","de":"Wandeln Sie C/C++-Code in Strict SysY um und generieren Sie gültige Testdaten mit create-sysy-testcase. Ein Tool für Compiler-Entwickler.","pt":"O create-sysy-testcase é uma ferramenta para testar compiladores SysY para MIPS, permitindo que você crie testes e compartilhe casos de teste","ru":"Create-sysy-testcase - это инструмент для тестирования компиляторов SysY в MIPS, позволяющий создавать тест-кейсы и делиться ими в ИИ Агенты","ar":"create-sysy-testcase هو أداة لاختبار مجمّعات SysY إلى MIPS، مما يسمح لك بإنشاء الاختبارات ومشاركة حالات الاختبار في أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"create-sysy-testcase: Strict SysY Testcase Conversion Set...","zh":"创建SysY测试用例：AI工具最佳实践","ja":"SysYテストケース作成：AIエージェントのセットアップガイド","ko":"SysY 테스트케이스 생성: AI 에이전트를 위한 최고의 테스트 방법","es":"Guía de configuración de create-sysy-testcase para ingeni...","fr":"Configurer create-sysy-testcase : Le guide des meilleures...","de":"Einrichten von create-sysy-testcase: Eine Anleitung für C...","pt":"Guia de Configuração do create-sysy-testcase: Melhores Pr...","ru":"Настройка create-sysy-testcase: Руководство по созданию т...","ar":"دليل إعداد create-sysy-testcase: أفضل الممارسات لاختبار م..."},"description":{"en":"Discover how to convert C/C++ code to Strict SysY and generate test data with create-sysy-testcase. Learn more and get started today!","zh":"使用create-sysy-testcase AI工具，轻松将C/C++代码转换为Strict SysY，生成有效的测试数据","ja":"SysYテストケースを作成するためのAIエージェントを使用して、C/C++コードをStrict SysYに変換し、有効なテストデータを生成する","ko":"create-sysy-testcase AI 에이전트를 사용하여 C/C++ 코드를 Strict SysY로 변환하고 유효한 테스트 데이터를 생성하는 방법","es":"Aprende a convertir código C/C++ en Strict SysY y genera datos de prueba válidos con create-sysy-testcase, una herramienta de AI Agent","fr":"Découvrez comment convertir du code C/C++ en Strict SysY et générer des données de test valides avec create-sysy-testcase, un outil d''Agent IA","de":"Erfahren Sie, wie Sie C/C++-Code in Strict SysY umwandeln und gültige Testdaten mit create-sysy-testcase, einem Tool von KI-Agents, generieren","pt":"Aprenda a criar testes para o compilador SysY para MIPS com o create-sysy-testcase e melhore a eficiência do seu workflow de desenvolvimento","ru":"Откройте для себя, как создавать тест-кейсы для компилятора SysY в MIPS с помощью create-sysy-testcase и улучшите эффективность вашего процесса разработки в ...","ar":"تعرف على كيفية إنشاء الاختبارات لمجمّع SysY إلى MIPS باستخدام create-sysy-testcase و تحسين كفاءة سير عمل التطوير الخاص بك في أدوات الذكاء الاصطناعي"},"definition":{"en":"create-sysy-testcase is a skill that converts C/C++ code to Strict SysY, a simplified C subset, and generates test data for compiler testing and validation.","zh":"create-sysy-testcase是用于将C/C++代码转换为Strict SysY的AI工具","ja":"SysYテストケース作成は、C/C++コードをStrict SysYに変換するAIエージェントの機能","ko":"create-sysy-testcase는 C/C++ 코드를 Strict SysY로 변환하는 AI 에이전트입니다","es":"create-sysy-testcase es una herramienta de AI Agent que convierte código C/C++ en Strict SysY y genera datos de prueba válidos","fr":"create-sysy-testcase est un outil d''Agent IA qui convertit du code C/C++ en Strict SysY et génère des données de test valides","de":"create-sysy-testcase ist ein Tool von KI-Agents, das C/C++-Code in Strict SysY umwandelt und gültige Testdaten generiert","pt":"O create-sysy-testcase é uma ferramenta de teste para compiladores SysY para MIPS que permite a criação e compartilhamento de testes","ru":"Create-sysy-testcase - это инструмент для тестирования компиляторов SysY в MIPS, предназначенный для создания и обмена тест-кейсами в ИИ Агенты","ar":"create-sysy-testcase هو أداة اختبار لمجمّعات SysY إلى MIPS التي تسمح بإنشاء ومشاركة الاختبارات في أدوات الذكاء الاصطناعي"},"features":{"en":["Converts C/C++ code to Strict SysY using implicit prototypes","Generates valid test data for compiler testing and validation","Adheres to non-negotiable grammar rules for accurate conversion","Supports reading of references/sysy_lang_grammar.md for syntax edge cases","Enforces strict grammar rules for deterministic testcase conversion"],"zh":["支持C/C++代码转换为Strict SysY","生成有效的测试数据","遵循严格的语法规则","支持Implicit Prototypes","支持CLI命令行接口"],"ja":["C/C++コードをStrict SysYに変換する","有効なテストデータを生成する","厳密な文法規則に従う","Implicit Prototypesをサポートする","CLIコマンドラインインターフェースをサポートする"],"ko":["C/C++ 코드를 Strict SysY로 변환하는 기능","유효한 테스트 데이터를 생성하는 기능","엄격한 문법 규칙을 따르는 기능","Implicit Prototypes를 지원하는 기능","CLI 명령줄 인터페이스를 지원하는 기능"],"es":["Conversión de código C/C++ en Strict SysY","Generación de datos de prueba válidos","Cumplimiento estricto de las reglas de gramática de SysY","Compatibilidad con la herramienta de AI Agent","Soporte para ingenieros de compiladores"],"fr":["Conversion de code C/C++ en Strict SysY","Génération de données de test valides","Respect strict des règles de grammaire de SysY","Compatibilité avec l''outil d''Agent IA","Support pour les ingénieurs de compilateurs"],"de":["Umwandlung von C/C++-Code in Strict SysY","Generierung gültiger Testdaten","Strenger Einhaltung der SysY-Grammatikregeln","Kompatibilität mit dem Tool von KI-Agents","Unterstützung für Compiler-Entwickler"],"pt":["Criação de testes para compiladores SysY para MIPS","Compartilhamento de casos de teste","Suporte a gramática Strict SysY","Conversão de código C/C++ para SysY","Geração de dados de teste válidos"],"ru":["Создание тест-кейсов для компиляторов SysY в MIPS","Обмен тест-кейсами","Поддержка грамматики Strict SysY","Преобразование кода C/C++ в SysY","Генерация валидных тестовых данных в ИИ Агенты"],"ar":["إنشاء الاختبارات لمجمّعات SysY إلى MIPS","مشاركة حالات الاختبار","دعم قواعد Strict SysY","تحويل 코드 C/C++ إلى SysY","توليد بيانات اختبار صالحة في أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use create-sysy-testcase","create-sysy-testcase setup guide","what is create-sysy-testcase","create-sysy-testcase alternative","create-sysy-testcase vs compiler test tools","strict sysy testcase conversion"],"zh":["SysY测试用例","C/C++代码转换","Strict SysY","AI工具","测试数据生成","语法规则","Implicit Prototypes","CLI命令行接口"],"ja":["SysYテストケース","C/C++コード変換","Strict SysY","AIエージェント","テストデータ生成","文法規則","Implicit Prototypes","CLIコマンドラインインターフェース"],"ko":["SysY 테스트케이스","C/C++ 코드 변환","Strict SysY","AI 에이전트","테스트 데이터 생성","문법 규칙","Implicit Prototypes","CLI 명령줄 인터페이스"],"es":["create-sysy-testcase","AI Agent","Strict SysY","C/C++","ingenieros de compiladores","herramientas de compilación","pruebas de software","desarrollo de software"],"fr":["create-sysy-testcase","Agent IA","Strict SysY","C/C++","ingénieurs de compilateurs","outils de compilation","tests de logiciel","développement de logiciel"],"de":["create-sysy-testcase","KI-Agents","Strict SysY","C/C++","Compiler-Entwickler","Compilierungstools","Software-Tests","Software-Entwicklung"],"pt":["create-sysy-testcase","compilador SysY para MIPS","teste de compilador","gramática Strict SysY","conversão de código C/C++","geração de dados de teste","desenvolvimento de software","ferramentas de teste"],"ru":["create-sysy-testcase","компилятор SysY в MIPS","тестирование компилятора","грамматика Strict SysY","преобразование кода C/C++","генерация тестовых данных","разработка программного обеспечения","инструменты тестирования в ИИ Агенты"],"ar":["create-sysy-testcase","مجمّع SysY إلى MIPS","اختبار المجمّع","قواعد Strict SysY","تحويل 코드 C/C++","توليد بيانات اختبار","تطوير البرمجيات","أدوات الاختبار في أدوات الذكاء الاصطناعي"]}},"owner":"oNya685","repo":"SysYTest","repoPath":"oNya685/SysYTest","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.437Z","topics":[],"category":"community","skillMd":{"name":"create-sysy-testcase","description":"Convert C/C++ code into Strict SysY testcases using Python automation scripts.","bodyPreview":"# SysY Testcase Conversion Workflow\n\nYou are an expert compiler engineer. Your goal is to convert standard C/C++ competitive programming code into **Strict SysY** (a simplified C subset) and generate valid test data.\n\n## Non-Negotiable Grammar Rules\n**Adhere to these rules strictly.** Read `references/sysy_lang_grammar.md` **only** if you encounter an obscure syntax edge case not covered here.\n\n| Feature | Constraint | Fix / Refactor |\n| :--- | :--- | :--- |\n| **Prototypes** | **Implicit** | **D","body":"# SysY Testcase Conversion Workflow\n\nYou are an expert compiler engineer. Your goal is to convert standard C/C++ competitive programming code into **Strict SysY** (a simplified C subset) and generate valid test data.\n\n## Non-Negotiable Grammar Rules\n**Adhere to these rules strictly.** Read `references/sysy_lang_grammar.md` **only** if you encounter an obscure syntax edge case not covered here.\n\n| Feature | Constraint | Fix / Refactor |\n| :--- | :--- | :--- |\n| **Prototypes** | **Implicit** | **Do NOT** write `int getint();` or `int printf(...);`. |\n| **Memory / Size** | **Max 4MB Total** (MARS Limit) | **Scale Down Constants**. `1e6` $\\to$ `1e4`. Total `int` elements < 500,000. |\n| **Preprocessor** | **BANNED** (`#include`, `#define`, `#ifdef`) | Use `const int` for constants. Delete imports. |\n| **Types** | `int`, `void` **ONLY** | No `long long`, `float`, `double`, `char`, `bool`. |\n| **Pointers** | **BANNED** (`int *p`, `&x`, `*ptr`) | Pass arrays as `int a[]`. Use **return values** for scalar outputs (no `void f(int *res)`). |\n| **Arrays** | **1D Arrays ONLY** | Flatten `int a[N][M]` $\\to$ `int a[N*M]`. **No VLAs**. |\n| **Loops** | **`for` loops ONLY**. **No declarations inside `()`** | Move vars out: `int i; for(i=0;...)`. No `do-while`. No `while`. turn `while(1)` into `for(;;)`. |\n| **Returns** | **Non-void funcs MUST return** | Add dummy `return 0;` at end of function, **even after infinite loops**. |\n| **Conditions As Values** | `Exp → AddExp` (arithmetic only) | Do **NOT** use relational / logical expressions as values, e.g. `return a < b;` or `x = (a < b);`. Rewrite: `if (a < b) return 1; return 0;` or `x = 0; if (a < b) x = 1;`. |\n| **Input** | `int getint()` **ONLY** | No `scanf`, `cin`, `getchar`. |\n| **Output** | `printf` **ONLY** | Format string is a **SysY `StringConst`**: **only** `%d` is allowed as a format placeholder, and the **only** escape sequence is `\\n` (backslash may appear **only** in `\\n`). **No** other format specifiers/modifiers (e.g. `%c`, `%s`, `%%`, `%05d`) and **no** other escapes (e.g. `\\\\`, `\\\"`, `\\t`, `\\r`, `\\0`). Ensure the number of `, Exp` arguments equals the number of `%d`. |\n| **Parentheses** | `PrimaryExp → ''('' Exp '')''` and `Exp → AddExp` | `(...)` as an expression can wrap **arithmetic only**. Besides mandatory syntax like `if (Cond)` / `for (...; Cond; ...)`, do **NOT** add extra parentheses around conditions (any `== != < > <= >= && || !`). Rewrite via precedence/distribution, e.g. `if (t2 > 0 && (a == 42 || a == 47))` $\\to$ `if (t2 > 0 && a == 42 || t2 > 0 && a == 47)`. |\n| **Operators** | No Bitwise (`<<`, `>>`, `&`, `|`, `^`) | Use arithmetic: `*2`, `/2`, `%2`. Use lookup tables. |\n| **Structs** | **BANNED** | Split into parallel arrays (e.g., `x[N]`, `y[N]`). |\n| **Globals** | Encouraged for large arrays | Prevent stack overflow in SysY runtime, keep totol size < 4MB. |\n| **Input Data** | **Strictly 1 Integer Per Line** (`in.txt`) | No spaces (`1 2`). Must be `1\\n2`. Matches MIPS syscall. If `testfile.txt` uses a **sentinel** to stop reading (e.g., `if (ch == 0) break;`, `while (x != 0)`, `while (1) { x=getint(); if (x==0) break; }`), then `in.txt` must **explicitly include that sentinel value as the last integer**. **Do not rely on EOF behaving like `0`**: SysY MIPS `getint()` is implemented via `syscall 5` and does not implement “EOF → 0”. |\n\n## Execution Protocol\n\nFollow these steps sequentially.\n\n### Step 1: Initialize\n\nUse the helper script to create the directory and placeholder files.\n\n```bash\npython3 .codex/skills/create-sysy-testcase/scripts/init_case.py <TARGET_DIR>\n```\n\n### Step 2: Write Logic (The Intelligence Part)\n\nTranslate the source logic into Strict SysY. Focus your \"thinking\" here.\n\n- **Scale Down**: If original code has `MAXN = 100000`, change it smaller to fix up to MARS''s address space limit(about 4MB). Ensure logic consistency.\n- **Refactor** logic to fit the constraints above (e.g., flatten 2D arrays).\n- **Write** the code to `testfile.txt`.\n- **Write** input data to `in.txt` (newline-separated integers only) matching your scaled-down size. If the program reads until a sentinel (e.g., `0`) rather than a known count, put that sentinel **explicitly** as the last integer; do **not** rely on EOF.\n\n```bash\ncat <<''EOF'' > <TARGET_DIR>/testfile.txt\n// ... your converted SysY code ...\nEOF\n\ncat <<''EOF'' > <TARGET_DIR>/in.txt\n// ... your input numbers ...\nEOF\n```\n\n### Step 3: Compile, Run & Verify\n\nUse the runner script. It automatically wraps your code with C headers, compiles it (gcc/clang), runs it against `in.txt`, and generates `ans.txt`.\n\n```bash\npython3 .codex/skills/create-sysy-testcase/scripts/run_case.py <TARGET_DIR>\n```\n\n### Step 4: Fix & Retry\n\nIf Step 3 reports a **COMPILE ERROR** or **RUNTIME ERROR**:\n\n1. Read the error output.\n2. Fix the logic in `testfile.txt`.\n3. Rerun Step 3.\n\n## Translation Strategy Tips\n- SysY input (`in.txt`) must be **newline-separated integers**.\n- If the original problem uses strings (e.g., \"PUSH\", \"POP\"), map them to integers (e.g., 1, 2) in your translation logic.\n- **MIPS Compatibility Check**: `in.txt` **must not** contain spaces between numbers.\n- **Never use EOF as a terminator**: if the program’s input loop expects a terminator value (commonly `0`, sometimes `-1`/`-999`), put that value **explicitly** at the end of `in.txt` (and keep it on its own line).\n- **Strengthen `in.txt` slightly**: prefer including a mix of small/edge values (e.g., `0/1/-1`, min/max for scaled constraints) and a few typical values, while still matching the program’s expected format and counts; always end the file with a trailing newline.\n"},"lastSynced":"2026-03-08T02:07:39.502Z","agentAnalysis":{"suitability":{"en":"Ideal for Compiler Agents requiring precise C/C++ to Strict SysY conversion and test data generation capabilities.","zh":"适合需要将C/C++代码精确转换为Strict SysY并生成测试数据的编译器代理。","ja":"C/C++をStrict SysYに正確に変換し、テストデータを生成する機能を必要とするコンパイラエージェントに最適。","ko":"C/C++를 Strict SysY로 정밀하게 변환하고 테스트 데이터를 생성하는 기능이 필요한 컴파일러 에이전트에 적합합니다.","es":"Ideal para agentes del compilador que requieren una conversión precisa de C/C++ a Strict SysY y capacidades de generación de datos de prueba.","fr":"Idéal pour les agents de compilateur nécessitant une conversion précise de C/C++ en Strict SysY et des capacités de génération de données de test.","de":"Ideal für Compiler-Agents, die eine präzise Umwandlung von C/C++ in Strict SysY und Testdaten-Generierungsfunktionen erfordern.","pt":"Ideal para Agentes Compiladores que exigem conversão precisa de C/C++ para Strict SysY e capacidades de geração de dados de teste.","ru":"Идеально подходит для агентов компиляторов, требующих точного преобразования C/C++ в Strict SysY и возможностей генерации тестовых данных.","ar":"مثالي لعمليات الوكيل المترجمة التي تتطلب تحويل دقيق من C/C++ إلى Strict SysY وقدرات توليد بيانات اختبار."},"recommendation":{"en":"Empowers agents to convert standard C/C++ competitive programming code into Strict SysY, adhering to specific grammar rules, and generate valid test data for compiler engineers using Strict SysY grammar rules and test data generation protocols.","zh":"赋予代理将标准C/C++竞赛编程代码转换为Strict SysY的能力，遵循特定的语法规则，并为使用Strict SysY语法规则和测试数据生成协议的编译器工程师生成有效的测试数据。","ja":"標準的なC/C++競技プログラミングコードをStrict SysYに変換する機能をエージェントに与え、特定の文法規則に従い、Strict SysYの文法規則とテストデータ生成プロトコルを使用するコンパイラエンジニアのために有効なテストデータを生成します。","ko":"에이전트가 표준 C/C++ 경쟁 프로그래밍 코드를 Strict SysY로 변환할 수 있는 기능을 부여하여 특정 문법 규칙을遵守하고 Strict SysY 문법 규칙 및 테스트 데이터 생성 프로토콜을 사용하는 컴파일러 엔지니어를 위해 유효한 테스트 데이터를 생성합니다.","es":"Habilita a los agentes a convertir código de programación competitiva estándar C/C++ en Strict SysY, siguiendo reglas gramaticales específicas, y genera datos de prueba válidos para ingenieros de compiladores utilizando reglas gramaticales y protocolos de generación de datos de prueba de Strict SysY.","fr":"Permet aux agents de convertir le code de programmation compétitive standard C/C++ en Strict SysY, en suivant des règles grammaticales spécifiques, et générer des données de test valides pour les ingénieurs de compilation utilisant les règles grammaticales et les protocoles de génération de données de test de Strict SysY.","de":"Ermächtigt Agents, standardmäßigen C/C++-Wettbewerbscode in Strict SysY umzuwandeln, indem bestimmte Grammatikregeln befolgt werden, und generiert gültige Testdaten für Compiler-Ingenieure unter Verwendung der Grammatikregeln und Testdaten-Generierungsprotokolle von Strict SysY.","pt":"Habilita os agentes a converterem código de programação competitiva padrão C/C++ em Strict SysY, seguindo regras gramaticais específicas, e gerar dados de teste válidos para engenheiros de compilador usando regras gramaticais Strict SysY e protocolos de geração de dados de teste.","ru":"Наделяет агентов возможностью преобразовывать стандартный конкурентный код программирования C/C++ в Strict SysY, соблюдая определенные грамматические правила, и генерировать действительные тестовые данные для инженеров-компиляторов, используя грамматические правила Strict SysY и протоколы генерации тестовых данных.","ar":"تمكين الوكيل من تحويل شفرة البرمجة التنافسية القياسية C/C++ إلى Strict SysY ، مع اتباع قواعد النحو المحددة ، وتوليد بيانات اختبار صالحة لمهندسي المترجمات باستخدام قواعد النحو Strict SysY وبروتوكولات توليد بيانات الاختبار."},"useCases":{"en":["Converting C/C++ code to Strict SysY for compiler testing","Generating valid test data for compiler engineers","Refactoring code to adhere to Strict SysY grammar rules"],"zh":["将C/C++代码转换为Strict SysY以进行编译器测试","为编译器工程师生成有效的测试数据","重构代码以遵守Strict SysY语法规则"],"ja":["コンパイラテストのためにC/C++コードをStrict SysYに変換する","コンパイラエンジニアのために有効なテストデータを生成する","Strict SysYの文法規則に従ってコードをリファクタリングする"],"ko":["컴파일러 테스트를 위해 C/C++ 코드를 Strict SysY로 변환하는 것","컴파일러 엔지니어를 위해 유효한 테스트 데이터를 생성하는 것","Strict SysY 문법 규칙을遵守하여 코드를 리팩토링하는 것"],"es":["Conversión de código C/C++ a Strict SysY para pruebas de compilador","Generación de datos de prueba válidos para ingenieros de compiladores","Reestructuración del código para que cumpla con las reglas gramaticales de Strict SysY"],"fr":["Conversion de code C/C++ en Strict SysY pour les tests de compilation","Génération de données de test valides pour les ingénieurs de compilation","Réorganisation du code pour se conformer aux règles grammaticales de Strict SysY"],"de":["Umwandlung von C/C++-Code in Strict SysY für Compilertests","Generierung gültiger Testdaten für Compiler-Ingenieure","Neustrukturierung des Codes, um den Grammatikregeln von Strict SysY zu entsprechen"],"pt":["Conversão de código C/C++ para Strict SysY para teste de compilador","Geração de dados de teste válidos para engenheiros de compilador","Reestruturação de código para atender às regras gramaticais Strict SysY"],"ru":["Преобразование кода C/C++ в Strict SysY для тестирования компилятора","Генерация действительных тестовых данных для инженеров-компиляторов","Переструктуризация кода для соответствия грамматическим правилам Strict SysY"],"ar":["تحويل شفرة C/C++ إلى Strict SysY لاختبار المترجمات","توليد بيانات اختبار صالحة لمهندسي المترجمات","إعادة هيكلة الشفرة لتلبية قواعد النحو Strict SysY"]},"limitations":{"en":["Requires adherence to specific Strict SysY grammar rules","Limited to C/C++ competitive programming code conversion"],"zh":["需要遵守特定的Strict SysY语法规则","仅限于C/C++竞赛编程代码的转换"],"ja":["特定のStrict SysYの文法規則に従う必要がある","C/C++競技プログラミングコードの変換のみに限定される"],"ko":["특정 Strict SysY 문법 규칙을 따라야 함","C/C++ 경쟁 프로그래밍 코드의 변환에만 제한됨"],"es":["Requiere la adhesión a reglas gramaticales específicas de Strict SysY","Limitado a la conversión de código de programación competitiva C/C++"],"fr":["Nécessite l''adhésion à des règles grammaticales spécifiques de Strict SysY","Limité à la conversion de code de programmation compétitive C/C++"],"de":["Erfordert die Einhaltung bestimmter Grammatikregeln von Strict SysY","Begrenzt auf die Umwandlung von C/C++-Wettbewerbscode"],"pt":["Exige aderência a regras gramaticais Strict SysY específicas","Limitado à conversão de código de programação competitiva C/C++"],"ru":["Требует соблюдения определенных грамматических правил Strict SysY","Ограничен преобразованием конкурентного кода программирования C/C++"],"ar":["يتطلب اتباع قواعد النحو المحددة Strict SysY","محدود بتحويل شفرة البرمجة التنافسية C/C++"]},"version":4},"contentHash":"772a728653f78b74c2da2c8a22d336d5b1a5d835df43feb79592897432a565da","qualityScore":36}');
