INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('oNya685/SysYTest/create-sysy-testcase', 'create-sysy-testcase', 'oNya685', 'SysYTest', 'community', 'create-sysy-testcase oNya685 SysYTest community The create-sysy-testcase skill converts standard C/C++ competitive programming code into Strict SysY and generates valid test data for compiler engineers. It adheres to specific grammar rules for accurate conversion. create-sysy-testcase AI工具帮助您将C/C++代码转换为Strict SysY，生成有效的测试数据 SysYテストケースを作成するためのAIエージェントは、C/C++コードをStrict SysYに変換し、有効なテストデータを生成する create-sysy-testcase AI 에이전트는 C/C++ 코드를 Strict SysY로 변환하고 유효한 테스트 데이터를 생성하여 테스트를 효율적으로进行합니다 Convierte código C/C++ en Strict SysY y genera datos de prueba válidos con create-sysy-testcase. Una herramienta para ingenieros de compiladores. Convertissez du code C/C++ en Strict SysY et générez des données de test valides avec create-sysy-testcase. Un outil pour les ingénieurs de compilateurs. Wandeln Sie C/C++-Code in Strict SysY um und generieren Sie gültige Testdaten mit create-sysy-testcase. Ein Tool für Compiler-Entwickler. O create-sysy-testcase é uma ferramenta para testar compiladores SysY para MIPS, permitindo que você crie testes e compartilhe casos de teste Create-sysy-testcase - это инструмент для тестирования компиляторов SysY в MIPS, позволяющий создавать тест-кейсы и делиться ими в ИИ Агенты create-sysy-testcase هو أداة لاختبار مجمّعات SysY إلى MIPS، مما يسمح لك بإنشاء الاختبارات ومشاركة حالات الاختبار في أدوات الذكاء الاصطناعي how to use create-sysy-testcase create-sysy-testcase setup guide what is create-sysy-testcase create-sysy-testcase alternative create-sysy-testcase vs compiler test tools strict sysy testcase conversion SysY测试用例 C/C++代码转换 Strict SysY AI工具 测试数据生成 语法规则 Implicit Prototypes CLI命令行接口 Converts C/C++ code to Strict SysY using implicit prototypes Generates valid test data for compiler testing and validation Adheres to non-negotiable grammar rules for accurate conversion Supports reading of references/sysy_lang_grammar.md for syntax edge cases Enforces strict grammar rules for deterministic testcase conversion create-sysy-testcase is a skill that converts C/C++ code to Strict SysY, a simplified C subset, and generates test data for compiler testing and validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryokun6/ryos/localize', 'community', 'ryokun6', 'ryos', 'ryokun6/ryos', 'localize', 0, 0, 36, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:42.656Z', '1348972c63bc800c05d22dbbe1e7720e9c9afa4865a0ef148b78fa7e97893ab0', '{"id":"ryokun6/ryos/localize","name":"localize","description":{"en":"The localize skill enables developers to extract hardcoded strings, replace them with t() calls, and manage translations across languages. It benefits developers working with internationalized applications.","zh":"本地化设置指南，帮助开发者使用ryOS和Cursor实现多语言支持","ja":"ローカライズ設定のベストプラクティス，ryOSとCursorを使用して多言語対応を実現","ko":"로컬라이제이션 설정 가이드，ryOS와 Cursor를 사용하여 多语言 지원을 구현합니다","es":"Localiza tus aplicaciones con ryOS y Cursor. Extrae cadenas codificadas y reemplázalas con llamadas a t().","fr":"Localisez vos applications avec ryOS et Cursor. Extraez les chaînes codées et remplacez-les par des appels à t().","de":"Lokalisieren Sie Ihre Anwendungen mit ryOS und Cursor. Extrahieren Sie codierte Zeichenfolgen und ersetzen Sie sie durch t()-Aufrufe.","pt":"Localize aplicativos com o ryOS, feito com Cursor, e siga o fluxo de trabalho de localização","ru":"Локализуйте приложения с помощью ryOS, сделанного с Cursor, и следуйте рабочему процессу локализации","ar":"تهيئة التطبيقات المحلية باستخدام ryOS، المصنوع مع Cursor، واتبع سير العمل الخاص بالتدويل"},"seo":{"title":{"en":"Localize: Setup Guide for AI Agents | AI Agent Skill","zh":"AIエージェント本地化设置指南","ja":"AIエージェントのローカライズベストプラクティス","ko":"AI 에이전트 로컬라이제이션 셋업 가이드","es":"Guía de configuración para localizar aplicaciones con ryOS","fr":"Guide d''installation pour localiser les applications avec...","de":"Einrichtungsanleitung für die Lokalisierung von Anwendung...","pt":"Guia de Configuração de Localização de Aplicativos","ru":"ИИ Агенты: Руководство по локализации приложений","ar":"إعداد تطبيقات محلية باستخدام 