INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryokun6/ryos/localize', 'localize', 'ryokun6', 'ryos', 'community', 'localize ryokun6 ryos community The localize skill enables developers to extract hardcoded strings, replace them with t() calls, and manage translations across languages. It benefits developers working with internationalized applications. 本地化设置指南，帮助开发者使用ryOS和Cursor实现多语言支持 ローカライズ設定のベストプラクティス，ryOSとCursorを使用して多言語対応を実現 로컬라이제이션 설정 가이드，ryOS와 Cursor를 사용하여 多语言 지원을 구현합니다 Localiza tus aplicaciones con ryOS y Cursor. Extrae cadenas codificadas y reemplázalas con llamadas a t(). Localisez vos applications avec ryOS et Cursor. Extraez les chaînes codées et remplacez-les par des appels à t(). Lokalisieren Sie Ihre Anwendungen mit ryOS und Cursor. Extrahieren Sie codierte Zeichenfolgen und ersetzen Sie sie durch t()-Aufrufe. Localize aplicativos com o ryOS, feito com Cursor, e siga o fluxo de trabalho de localização Локализуйте приложения с помощью ryOS, сделанного с Cursor, и следуйте рабочему процессу локализации تهيئة التطبيقات المحلية باستخدام ryOS، المصنوع مع Cursor، واتبع سير العمل الخاص بالتدويل how to use localize localize setup guide localize vs internationalization localize install what is localize localize alternative localization best practices translation.json format extract-strings.ts command AIエージェント本地化 ryOS本地化 Cursor本地化 多语言支持 翻译管理 本地化设置 ローカライズベストプラクティス 多语言开发 Extracts hardcoded strings using bun run scripts/extract-strings.ts Replaces strings with t() calls in source files Supports English translations via en/translation.json Syncs translations across languages Validates translation coverage Localize is a process of adapting software for different languages and regions, involving extraction, translation, and validation of content');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cipher982/longhouse/zerg-testing', 'community', 'cipher982', 'longhouse', 'cipher982/longhouse', 'zerg-testing', 0, 0, 36, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:43.923Z', '277531ec37d9247f4b8d06322360bf3848330cb06360ce697949b21c7040372c', '{"id":"cipher982/longhouse/zerg-testing","name":"zerg-testing","description":{"en":"zerg-testing is a centralized location for managing AI agents, providing a structured approach to testing with Make targets. It benefits developers by simplifying the testing process","zh":"Zerg Testing 是一个用于管理 AI 代理的集中式平台，提供多种测试命令和调试工具","ja":"Zerg Testing は AI エージェントを管理するための集中プラットフォームであり、多様なテストコマンドとデバッグツールを提供します","ko":"Zerg Testing은 AI 에이전트를 관리하는 집중화 된 플랫폼으로 다양한 테스트 명령어와 디버깅 도구를 제공합니다","es":"zerg-testing es una herramienta para gestionar agentes de IA de manera centralizada, utilizando comandos como make test y make test-e2e","fr":"zerg-testing est un outil pour gérer les agents IA de manière centralisée, en utilisant des commandes comme make test et make test-e2e","de":"zerg-testing ist ein Tool zur zentralen Verwaltung von AI-Agents, mit Befehlen wie make test und make test-e2e","pt":"O Zerg-Testing é uma solução para gerenciar ferramentas de IA de forma centralizada, utilizando comandos Make para testes unitários e de ponta a ponta","ru":"Zerg-Testing - это решение для централизованного управления ИИ Агентами, использующее команды Make для юнит-тестов и тестов от начала до конца","ar":"Zerg-Testing هو حل لإدارة أدوات الذكاء الاصطناعي بطريقة مركزية، باستخدام أوامر Make للاختبارات الوحدوية واختبارات النهاية إلى النهاية"},"seo":{"title":{"en":"zerg-testing: Centralized AI Agent Management Setup Guide...","zh":"Zerg Testing 设置指南：AI 代理管理","ja":"Zerg Testing セットアップガイド：AI エージェントの管理","ko":"Zerg Testing 설정 가이드: AI 에이전트 관리","es":"Guía de configuración de zerg-testing para agentes de IA","fr":"Guide de mise en place de zerg-testing pour les agents IA","de":"Einrichtungsleitfaden für zerg-testing in der AI-Agenten-...","pt":"Guia de Configuração do Zerg-Testing para Ferramentas de IA","ru":"Настройка Zerg-Testing для ИИ Агентов","ar":"دليل إعداد Zerg-Testing لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to streamline AI agent management with zerg-testing. Learn to run unit tests, core E2E, and full E2E tests with Make targets and improve your te...","zh":"了解 Zerg Testing 的核心命令和调试流程，实现高效的 AI 代理管理","ja":"Zerg Testing のコアコマンドとデバッグフローをマスターして、AI エージェントの管理を効率化しましょう","ko":"Zerg Testing의 코어 명령어와 디버깅 흐름을 익히고 효율적인 AI 에이전트 관리를 구현하세요","es":"Aprende a utilizar zerg-testing para gestionar agentes de IA de manera centralizada y eficiente","fr":"Découvrez comment utiliser zerg-testing pour gérer les agents IA de manière centralisée et efficace","de":"Erfahren Sie, wie Sie zerg-testing für die zentrale und effiziente Verwaltung von AI-Agents einsetzen","pt":"Aprenda a configurar o Zerg-Testing para gerenciar ferramentas de IA de forma centralizada e eficiente","ru":"Узнайте, как настроить Zerg-Testing для централизованного управления ИИ Агентами","ar":"تعرف على كيفية إعداد Zerg-Testing لإدارة أدوات الذكاء الاصطناعي بطريقة مركزية وفعالة"},"definition":{"en":"zerg-testing is a centralized testing framework that utilizes Make targets for managing AI agents, providing core commands for unit tests, E2E tests, and debugging","zh":"Zerg Testing 是一种用于管理 AI 代理的测试框架","ja":"Zerg Testing は AI エージェントを管理するためのテストフレームワークです","ko":"Zerg Testing은 AI 에이전트를 관리하기 위한 테스트 프레임워크입니다","es":"zerg-testing es una herramienta de gestión de agentes de IA que proporciona una ubicación centralizada para ejecutar pruebas unitarias y de extremo a extremo","fr":"zerg-testing est un outil de gestion d''agents IA qui offre un emplacement centralisé pour exécuter des tests unitaires et de bout en bout","de":"zerg-testing ist ein Tool zur Verwaltung von AI-Agents, das eine zentrale Stelle für die Ausführung von Einheitstests und End-to-End-Tests bietet","pt":"Zerg-Testing é uma ferramenta de gerenciamento de testes para IA","ru":"Zerg-Testing - это инструмент для управления тестами ИИ Агентов","ar":"Zerg-Testing هو أداة لإدارة الاختبارات لأدوات الذكاء الاصطناعي"},"features":{"en":["Runs unit tests using `make test` command","Executes core E2E tests with `make test-e2e-core` command","Supports full E2E testing with `make test-e2e` command","Allows for debugging with `make test-e2e-errors` and `make test-e2e-verbose` commands","Enables testing of specific test cases with `make test-e2e-single` command"],"zh":["支持 Make targets","提供 unit tests 和 E2E tests","支持测试重试","提供详细的测试输出","支持调试流程","提供测试错误信息"],"ja":["Make targets をサポート","ユニットテストと E2E テストを提供","テストのリトライをサポート","詳細なテスト出力を提供","デバッグフローをサポート","テストエラー情報を提供"],"ko":["Make targets 지원","유닛 테스트와 E2E 테스트 제공","테스트 재시도를 지원","詳細한 테스트 출력 제공","디버깅 흐름을 지원","테스트 오류 정보 제공"],"es":["Ejecución de pruebas unitarias con make test","Ejecución de pruebas de extremo a extremo con make test-e2e","Soporte para depuración con make test-e2e-errors y make test-e2e-verbose","Compatibilidad con comandos de Make para una ejecución flexible","Posibilidad de ejecutar pruebas individuales con make test-e2e-single","Informes de errores detallados para una depuración eficiente"],"fr":["Exécution de tests unitaires avec make test","Exécution de tests de bout en bout avec make test-e2e","Prise en charge de la débogage avec make test-e2e-errors et make test-e2e-verbose","Compatibilité avec les commandes Make pour une exécution flexible","Possibilité d''exécuter des tests individuels avec make test-e2e-single","Rapports d''erreurs détaillés pour une débogage efficace"],"de":["Ausführung von Einheitstests mit make test","Ausführung von End-to-End-Tests mit make test-e2e","Unterstützung für die Fehlersuche mit make test-e2e-errors und make test-e2e-verbose","Kompatibilität mit Make-Befehlen für eine flexible Ausführung","Möglichkeit, einzelne Tests mit make test-e2e-single auszuführen","Detaillierte Fehlerberichte für eine effiziente Fehlersuche"],"pt":["Utiliza comandos Make para testes unitários e de ponta a ponta","Suporte a testes de ponta a ponta com retry","Exibe erros de teste de ponta a ponta","Modo verbose para depuração","Testes unitários e de ponta a ponta em um único comando"],"ru":["Использует команды Make для юнит-тестов и тестов от начала до конца","Поддержка тестов от начала до конца с повторными попытками","Отображает ошибки тестов от начала до конца","Режим verbose для отладки","Юнит-тесты и тесты от начала до конца в одном команде"],"ar":["يستخدم أوامر Make للاختبارات الوحدوية واختبارات النهاية إلى النهاية","يدعم اختبارات النهاية إلى النهاية مع إعادة المحاولة","يعرض أخطاء اختبارات النهاية إلى النهاية","الوضع الصريح للتصحيح","اختبارات الوحدوية واختبارات النهاية إلى النهاية في أمر واحد"]},"keywords":{"en":["how to use zerg-testing","zerg-testing setup guide","zerg-testing alternative","zerg-testing vs pytest","what is zerg-testing","zerg-testing install","zerg-testing tutorial","zerg-testing best practices","zerg-testing for AI agents"],"zh":["Zerg Testing","AI 代理管理","Make targets","unit tests","E2E tests","测试框架","AI 工具","测试重试","调试流程"],"ja":["Zerg Testing","AI エージェントの管理","Make targets","ユニットテスト","E2E テスト","テストフレームワーク","AI エージェント","テストのリトライ","デバッグフロー"],"ko":["Zerg Testing","AI 에이전트 관리","Make targets","유닛 테스트","E2E 테스트","테스트 프레임워크","AI 도구","테스트 재시도","디버깅 흐름"],"es":["zerg-testing","agentes de IA","pruebas unitarias","pruebas de extremo a extremo","Make","depuración","gestión de agentes de IA","herramientas de desarrollo","desarrollo de software","pruebas automatizadas"],"fr":["zerg-testing","agents IA","tests unitaires","tests de bout en bout","Make","débogage","gestion d''agents IA","outils de développement","développement de logiciels","tests automatisés"],"de":["zerg-testing","AI-Agents","Einheitstests","End-to-End-Tests","Make","Fehlersuche","Verwaltung von AI-Agents","Entwicklungstools","Softwareentwicklung","automatisierte Tests"],"pt":["Zerg-Testing","ferramentas de IA","testes unitários","testes de ponta a ponta","comandos Make","gerenciamento de testes","desenvolvimento de software","automatização de testes"],"ru":["Zerg-Testing","ИИ Агенты","юнит-тесты","тесты от начала до конца","команды Make","управление тестами","разработка программного обеспечения","автоматизация тестов"],"ar":["Zerg-Testing","أدوات الذكاء الاصطناعي","اختبارات الوحدوية","اختبارات النهاية إلى النهاية","أوامر Make","إدارة الاختبارات","تطوير البرمجيات","آلية الاختبارات"]}},"owner":"cipher982","repo":"longhouse","repoPath":"cipher982/longhouse","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"zerg-testing","description":"Zerg testing workflow (unit + E2E). Use when running or debugging tests.","bodyPreview":"# Zerg Testing\n\n## Rules\n- Always use Make targets. Never run pytest/bun/playwright directly.\n\n## Core Commands\n```bash\nmake test                # unit tests\nmake test-e2e-core       # core E2E (must pass 100%)\nmake test-e2e            # full E2E (retries ok)\nmake test-full           # unit + full E2E + visual checks\nmake test-e2e-single TEST=tests/<spec>.ts\nmake test-e2e-errors     # show last E2E errors\nmake test-e2e-verbose    # full output for debugging\n```\n\n## Debugging Flow\n1) `make test-e","body":"# Zerg Testing\n\n## Rules\n- Always use Make targets. Never run pytest/bun/playwright directly.\n\n## Core Commands\n```bash\nmake test                # unit tests\nmake test-e2e-core       # core E2E (must pass 100%)\nmake test-e2e            # full E2E (retries ok)\nmake test-full           # unit + full E2E + visual checks\nmake test-e2e-single TEST=tests/<spec>.ts\nmake test-e2e-errors     # show last E2E errors\nmake test-e2e-verbose    # full output for debugging\n```\n\n## Debugging Flow\n1) `make test-e2e-errors`\n2) `make test-e2e-single TEST=tests/<spec>.ts`\n3) `make test-e2e-verbose`\n"},"lastSynced":"2026-03-08T02:07:43.923Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing structured testing with Make targets and pytest integration.","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要使用Make目标和pytest集成进行结构化测试。","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。これらはMakeターゲットとpytest統合を使用した構造化テストを必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합합니다. 구조화된 테스트를 위해 Make 대상과 pytest 통합이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan pruebas estructuradas con objetivos Make y integración de pytest.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant des tests structurés avec des cibles Make et une intégration de pytest.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die strukturierte Tests mit Make-Zielen und pytest-Integration benötigen.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de testes estruturados com alvos Make e integração com pytest.","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих структурированного тестирования с целями Make и интеграцией с pytest.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذي يحتاج إلى اختبارات منظمة مع أهداف Make ودمج pytest."},"recommendation":{"en":"Empowers agents to streamline testing workflows using Make targets, simplifying unit tests, end-to-end tests, and visual checks with tools like playwright, while ensuring consistency and reliability in test execution and debugging with specific commands like make test-e2e-core and make test-e2e-verbose.","zh":"赋予代理使用Make目标简化测试工作流的能力，使用工具如playwright简化单元测试、端到端测试和视觉检查，同时确保测试执行和调试的一致性和可靠性，使用特定命令如make test-e2e-core和make test-e2e-verbose。","ja":"Makeターゲットを使用してテストワークフローを簡素化するエージェントの能力を提供します。playwrightなどのツールを使用してユニットテスト、エンドツーエンドテスト、視覚的なチェックを簡素化します。また、make test-e2e-coreやmake test-e2e-verboseなどの特定のコマンドを使用してテストの実行とデバッグの一貫性と信頼性を確保します。","ko":"에이전트가 Make 대상 사용을 통해 테스트 워크플ロー简化를 가능하게 하며, playwright와 같은 툴을 사용하여 유닛 테스트, 종단 간 테스트, 시각적 확인을 간소화합니다. 또한 make test-e2e-core 및 make test-e2e-verbose와 같은 특정 명령을 사용하여 테스트 실행 및 디버깅의 일관성 및 신뢰성을 보장합니다.","es":"Habilita a los agentes a simplificar flujos de trabajo de prueba utilizando objetivos Make, simplificando pruebas unitarias, pruebas de extremo a extremo y comprobaciones visuales con herramientas como playwright, garantizando al mismo tiempo la consistencia y la confiabilidad en la ejecución y depuración de pruebas con comandos específicos como make test-e2e-core y make test-e2e-verbose.","fr":"Permet aux agents de rationaliser les flux de travail de test en utilisant des cibles Make, en simplifiant les tests unitaires, les tests de bout en bout et les vérifications visuelles avec des outils comme playwright, tout en assurant la cohérence et la fiabilité de l''exécution et du débogage des tests avec des commandes spécifiques comme make test-e2e-core et make test-e2e-verbose.","de":"Ermöglich es den Agents, Testworkflows mit Make-Zielen zu rationalisieren, Einheitstests, End-to-End-Tests und visuelle Prüfungen mit Tools wie playwright zu vereinfachen und gleichzeitig Konsistenz und Zuverlässigkeit bei der Testausführung und Fehlersuche mit spezifischen Befehlen wie make test-e2e-core und make test-e2e-verbose sicherzustellen.","pt":"Permite que os agentes simplifiquem os fluxos de trabalho de teste usando alvos Make, simplificando testes unitários, testes de ponta a ponta e verificações visuais com ferramentas como playwright, garantindo consistência e confiabilidade na execução e depuração de testes com comandos específicos como make test-e2e-core e make test-e2e-verbose.","ru":"Наделяет агентов возможностью оптимизировать рабочие процессы тестирования с помощью целей Make, упрощая модульные тесты, тесты от начала до конца и визуальные проверки с помощью инструментов như playwright, обеспечивая согласованность и надежность при выполнении и отладке тестов с помощью конкретных команд, таких как make test-e2e-core и make test-e2e-verbose.","ar":"يمكن العميل من تسهيل سير عمل الاختبار باستخدام أهداف Make، وبذلك يُبسط الاختبارات الوحدوية واختبارات من النهاية إلى النهاية والتحقق المرئي باستخدام أدوات مثل playwright، مع ضمان الاتساق والموثوقية في تشغيل الاختبارات وتصحيح الأخطاء بأوامر محددة مثل make test-e2e-core و make test-e2e-verbose."},"useCases":{"en":["Automating unit tests with make test","Debugging end-to-end tests using make test-e2e-verbose","Validating test coverage with make test-full"],"zh":["使用make test自动化单元测试","使用make test-e2e-verbose调试端到端测试","使用make test-full验证测试覆盖率"],"ja":["make testを使用してユニットテストを自動化する","make test-e2e-verboseを使用してエンドツーエンドテストをデバッグする","make test-fullを使用してテストカバレッジを検証する"],"ko":["make test를 사용하여 유닛 테스트 자동화","make test-e2e-verbose를 사용하여 종단 간 테스트 디버깅","make test-full를 사용하여 테스트 커버리지 확인"],"es":["Automatizar pruebas unitarias con make test","Depurar pruebas de extremo a extremo utilizando make test-e2e-verbose","Validar la cobertura de pruebas con make test-full"],"fr":["Automatiser les tests unitaires avec make test","Déboguer les tests de bout en bout en utilisant make test-e2e-verbose","Valider la couverture des tests avec make test-full"],"de":["Automatisieren von Einheitstests mit make test","Fehlersuche bei End-to-End-Tests mit make test-e2e-verbose","Überprüfen der Testabdeckung mit make test-full"],"pt":["Automatizar testes unitários com make test","Depurar testes de ponta a ponta usando make test-e2e-verbose","Validar cobertura de teste com make test-full"],"ru":["Автоматизировать модульные тесты с помощью make test","Отлаживать тесты от начала до конца с помощью make test-e2e-verbose","Проверять покрытие тестов с помощью make test-full"],"ar":["أتمتة الاختبارات الوحدوية مع make test","تصحيح الاختبارات من النهاية إلى النهاية باستخدام make test-e2e-verbose","التحقق من تغطية الاختبار مع make test-full"]},"limitations":{"en":["Requires Makefile configuration","Dependent on pytest, bun, and playwright for test execution"],"zh":["需要Makefile配置","依赖pytest、bun和playwright进行测试执行"],"ja":["Makefileの設定が必要","pytest、bun、playwrightに依存してテストを実行する"],"ko":["Makefile 설정이 필요","pytest, bun, playwright에 의존하여 테스트를 실행"],"es":["Requiere configuración de Makefile","Dependiente de pytest, bun y playwright para la ejecución de pruebas"],"fr":["Nécessite une configuration de Makefile","Dépend de pytest, bun et playwright pour l''exécution des tests"],"de":["Benötigt Makefile-Konfiguration","Abhängig von pytest, bun und playwright für die Testausführung"],"pt":["Requer configuração do Makefile","Dependente de pytest, bun e playwright para execução de testes"],"ru":["Требует конфигурации Makefile","Зависит от pytest, bun и playwright для выполнения тестов"],"ar":["يتطلب تكوين Makefile","يعتمد على pytest و bun و playwright لتشغيل الاختبارات"]},"version":4},"contentHash":"277531ec37d9247f4b8d06322360bf3848330cb06360ce697949b21c7040372c","qualityScore":36}');
