INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cipher982/longhouse/zerg-testing', 'zerg-testing', 'cipher982', 'longhouse', 'community', 'zerg-testing cipher982 longhouse community zerg-testing is a centralized location for managing AI agents, providing a structured approach to testing with Make targets. It benefits developers by simplifying the testing process Zerg Testing 是一个用于管理 AI 代理的集中式平台，提供多种测试命令和调试工具 Zerg Testing は AI エージェントを管理するための集中プラットフォームであり、多様なテストコマンドとデバッグツールを提供します Zerg Testing은 AI 에이전트를 관리하는 집중화 된 플랫폼으로 다양한 테스트 명령어와 디버깅 도구를 제공합니다 zerg-testing es una herramienta para gestionar agentes de IA de manera centralizada, utilizando comandos como make test y make test-e2e zerg-testing est un outil pour gérer les agents IA de manière centralisée, en utilisant des commandes comme make test et make test-e2e zerg-testing ist ein Tool zur zentralen Verwaltung von AI-Agents, mit Befehlen wie make test und make test-e2e O Zerg-Testing é uma solução para gerenciar ferramentas de IA de forma centralizada, utilizando comandos Make para testes unitários e de ponta a ponta Zerg-Testing - это решение для централизованного управления ИИ Агентами, использующее команды Make для юнит-тестов и тестов от начала до конца Zerg-Testing هو حل لإدارة أدوات الذكاء الاصطناعي بطريقة مركزية، باستخدام أوامر Make للاختبارات الوحدوية واختبارات النهاية إلى النهاية how to use zerg-testing zerg-testing setup guide zerg-testing alternative zerg-testing vs pytest what is zerg-testing zerg-testing install zerg-testing tutorial zerg-testing best practices zerg-testing for AI agents Zerg Testing AI 代理管理 Make targets unit tests E2E tests 测试框架 AI 工具 测试重试 调试流程 Runs unit tests using `make test` command Executes core E2E tests with `make test-e2e-core` command Supports full E2E testing with `make test-e2e` command Allows for debugging with `make test-e2e-errors` and `make test-e2e-verbose` commands Enables testing of specific test cases with `make test-e2e-single` command zerg-testing is a centralized testing framework that utilizes Make targets for managing AI agents, providing core commands for unit tests, E2E tests, and debugging');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blockmatic/basilic/ahooks', 'community', 'blockmatic', 'basilic', 'blockmatic/basilic', 'ahooks', 0, 0, 36, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:44.570Z', '3619a1d5c301136fecc3ca74d2cee8141e56e9ddf581957df92667bd894b257b', '{"id":"blockmatic/basilic/ahooks","name":"ahooks","description":{"en":"ahooks is a utility hook library for React state management, providing features like grouped state updates and localStorage persistence for client-side applications.","zh":"ahooks是一个React状态管理工具，提供组合状态更新和localStorage持久化功能","ja":"ahooksはReactの状態管理ツールで、状態の更新とlocalStorageの永続化機能を提供します","ko":"ahooks는 React 상태 관리 도구로 상태 업데이트와 localStorage 영속성 기능을 제공합니다","es":"ahooks es un utilitaire de gestión de estado para React que ofrece una forma sencilla de gestionar el estado de la aplicación","fr":"ahooks est un utilitaire de gestion d''état pour React qui offre une façon simple de gérer l''état de l''application","de":"ahooks ist ein Utility für die Zustandsverwaltung in React, das eine einfache Möglichkeit bietet, den Anwendungszustand zu verwalten","pt":"Ahooks é uma biblioteca para gerenciamento de estado em React, oferecendo hooks para atualizações de estado em grupo e persistência em localStorage.","ru":"ИИ Агент ahooks - это библиотека для управления состоянием в React, предоставляющая хуки для групповых обновлений состояния и сохранения в localStorage.","ar":"ahooks هو أداة لتنفيذ إدارة الحالة في تطبيقات الويب، تقدم hooks لتحديثات الحالة المجمعة وتخزينها في localStorage."},"seo":{"title":{"en":"ahooks: Setup Guide for React State Management | AI Agent...","zh":"ahooks_setup_guide","ja":"ahooks_Best_Practices","ko":"ahooks_React_State_Management","es":"Guía de configuración de ahooks para administración de es...","fr":"Guide de démarrage rapide pour ahooks, utilitaire de gest...","de":"Einrichtungsleitfaden für ahooks: React-Zustandsverwaltun...","pt":"Ahooks: Guia de Configuração para Gerenciamento de Estado...","ru":"ИИ Агент ahooks: Настройка для Управления Состоянием в React","ar":"إعداد ahooks لتنفيذ إدارة الحالة في تطبيقات الويب"},"description":{"en":"Unlock efficient React state management with ahooks v3+! Learn how to use utility hooks for grouped state updates and localStorage persistence.","zh":"使用ahooks进行React状态管理，实现组合状态更新和localStorage持久化","ja":"ahooksを使用してReactの状態管理を実現し、状態の更新とlocalStorageの永続化を行う","ko":"ahooks를 사용하여 React 상태 관리를 구현하고 상태 업데이트 및 localStorage 영속성을 제공합니다","es":"Aprende a utilizar ahooks para gestionar el estado de tu aplicación React con facilidad y eficiencia","fr":"Découvrez comment utiliser ahooks pour gérer l''état de votre application React de manière efficace","de":"Erfahren Sie, wie Sie ahooks verwenden, um den Zustand Ihrer React-Anwendung einfach und effizient zu verwalten","pt":"Aprenda a configurar ahooks para gerenciar estados em aplicações React com eficiência","ru":"Узнайте, как настроить ahooks для управления состоянием в приложениях React","ar":"اكتشف كيفية إعداد ahooks لتنفيذ إدارة الحالة في تطبيقات الويب بالاعتماد على React"},"definition":{"en":"ahooks is a React utility hook library for managing state, supporting features like useSetState for grouped state updates.","zh":"ahooks是一种React状态管理工具，用于管理应用程序的状态","ja":"ahooksはReactの状態管理ツールの一種で、アプリケーションの状態を管理します","ko":"ahooks는 React 상태 관리 도구의 일종으로 애플리케이션의 상태를 관리합니다","es":"ahooks es un conjunto de hooks de utilidad para la gestión de estado de React","fr":"ahooks est un ensemble de hooks utilitaires pour la gestion d''état de React","de":"ahooks ist eine Sammlung von Utility-Hooks für die Zustandsverwaltung in React","pt":"Ahooks é uma biblioteca de utilitários para React que fornece hooks para gerenciamento de estado","ru":"ИИ Агент ahooks - это библиотека утилит для React, предоставляющая хуки для управления состоянием","ar":"ahooks هي أداة لمكتبات الويب التي توفر hooks لإدارة الحالة في تطبيقات الويب"},"features":{"en":["Provides useSetState for grouped state updates","Supports localStorage persistence for client-side state management","Compatible with React 18+ and TypeScript v5+","Optimized for client-side only applications","Does not cover data fetching, URL state management, or complex state machines"],"zh":["支持React 18+和TypeScript v5+","提供组合状态更新功能","支持localStorage持久化","使用useSetState进行状态管理","适用于客户端应用程序"],"ja":["React 18+とTypeScript v5+をサポート","状態の更新機能を提供","localStorageの永続化をサポート","useSetStateを使用して状態管理","クライアントサイドアプリケーションに適しています"],"ko":["React 18+와 TypeScript v5+ 지원","상태 업데이트機能 제공","localStorage 영속성 지원","useSetState를 사용한 상태 관리","클라이언트 사이드 애플리케이션에 적합"],"es":["Utiliza useSetState para actualizaciones de estado agrupadas","Compatibilidad con React 18+ y soporte de hooks","Utiliza TypeScript v5+ para inferencia de tipos","Almacenamiento persistente en localStorage","Diseñado para aplicaciones client-side"],"fr":["Utilisez useSetState pour des mises à jour d''état regroupées","Compatibilité avec React 18+ et support des hooks","Utilisez TypeScript v5+ pour l''inférence de types","Stockage persistant dans localStorage","Conçu pour les applications client-side"],"de":["Verwenden Sie useSetState für gruppierte Zustandsaktualisierungen","Kompatibilität mit React 18+ und Hooks-Unterstützung","Verwenden Sie TypeScript v5+ für Typinferenz","Persistenter Speicher in localStorage","Entwickelt für Client-Seiten-Anwendungen"],"pt":["Suporte a atualizações de estado em grupo com useSetState","Persistência em localStorage para dados de estado","Compatibilidade com React 18+ e hooks","Suporte a TypeScript v5+ para inferência de tipo","Funciona apenas no lado do cliente, utilizando APIs do navegador"],"ru":["Поддержка групповых обновлений состояния с useSetState","Сохранение в localStorage для данных состояния","Совместимость с React 18+ и хуками","Поддержка TypeScript v5+ для вывода типа","Работает только на стороне клиента, используя браузерные API"],"ar":["دعم التحديثات المجمعة للحالة مع useSetState","التخزين في localStorage للبيانات الحالية","التوافق مع React 18+ و hooks","دعم TypeScript v5+ للاستدلال عن النوع","يعمل فقط على جانب العميل، مستخدمًا واجهات برمجة التطبيقات للمتصفح"]},"keywords":{"en":["how to use ahooks","ahooks setup guide","ahooks vs react-query","ahooks install","react state management with ahooks","ahooks alternative to redux"],"zh":["ahooks","React状态管理","组合状态更新","localStorage持久化","useSetState","React 18+","TypeScript v5+","AIエージェント工具"],"ja":["ahooks","React状態管理","状態更新","localStorage永続化","useSetState","React 18+","TypeScript v5+","AIエージェント"],"ko":["ahooks","React 상태 관리","상태 업데이트","localStorage 영속성","useSetState","React 18+","TypeScript v5+","AI 에이전트"],"es":["ahooks","gestión de estado de React","hooks de utilidad","useSetState","React 18+","TypeScript v5+","localStorage","Herramientas de desarrollo de React","Estado de la aplicación React"],"fr":["ahooks","gestion d''état de React","hooks utilitaires","useSetState","React 18+","TypeScript v5+","localStorage","Outils de développement React","État de l''application React"],"de":["ahooks","Zustandsverwaltung in React","Utility-Hooks","useSetState","React 18+","TypeScript v5+","localStorage","React-Entwicklungstools","Anwendungszustand in React"],"pt":["ahooks react","gerenciamento de estado react","hooks para react","react state management","utilitários para react","bibliotecas para react","desenvolvimento web com react"],"ru":["ИИ Агент ahooks","управление состоянием react","хуки для react","react состояние управления","утилиты для react","библиотеки для react","разработка веб-приложений с react"],"ar":["ahooks react","إدارة الحالة في react","hooks ل react","إدارة الحالة في تطبيقات الويب","أدوات لمكتبات الويب","مكتبات ل react","تطوير تطبيقات الويب باستخدام react"]}},"owner":"blockmatic","repo":"basilic","repoPath":"blockmatic/basilic","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"ahooks","description":"|","bodyPreview":"# Skill: ahooks\n\n## Scope\n\n- Applies to: ahooks v3+ utility hooks for React state management, grouped state updates, localStorage persistence\n- Does NOT cover: Data fetching (use TanStack Query), URL state management (use nuqs), complex state machines, async operations\n\n## Assumptions\n\n- ahooks v3+\n- React 18+ with hooks support\n- TypeScript v5+ (for type inference)\n- Client-side only (hooks require browser APIs for localStorage)\n\n## Principles\n\n- Use `useSetState` for grouped state that changes","body":"# Skill: ahooks\n\n## Scope\n\n- Applies to: ahooks v3+ utility hooks for React state management, grouped state updates, localStorage persistence\n- Does NOT cover: Data fetching (use TanStack Query), URL state management (use nuqs), complex state machines, async operations\n\n## Assumptions\n\n- ahooks v3+\n- React 18+ with hooks support\n- TypeScript v5+ (for type inference)\n- Client-side only (hooks require browser APIs for localStorage)\n\n## Principles\n\n- Use `useSetState` for grouped state that changes together (not URL-shareable)\n- Use `useLocalStorageState` for persistent state across browser sessions\n- Prefer nuqs for URL-shareable state over localStorage\n- Prefer TanStack Query for async operations and loading states\n- Use `useState` only for simple independent state (rare)\n\n## Constraints\n\n### MUST\n\n- Use `useSetState` for grouped state not in URL (form state, game engine state, ephemeral UI state)\n- Use `useLocalStorageState` for localStorage persistence\n\n### SHOULD\n\n- Prefer nuqs for URL-shareable state over localStorage\n- Prefer TanStack Query for async operations and loading states\n- Use TypeScript generics for type-safe state: `useLocalStorageState<boolean>(''key'', { defaultValue: false })`\n\n### AVOID\n\n- Using for URL state (use nuqs instead)\n- Using for loading/error states (use TanStack Query instead)\n- Using for complex async operations (use TanStack Query instead)\n- Mixing URL state with localStorage without explicit sync logic\n\n## Interactions\n\n- Complements nuqs for URL state management (can sync bidirectionally)\n- Complements TanStack Query for async operations (use TanStack Query for data fetching)\n- Part of state management decision tree (see React rules)\n- Works with React 18+ hooks architecture\n\n## Patterns\n\n### useSetState Pattern\n\nUse for grouped state that updates together:\n\n```typescript\nimport { useSetState } from ''ahooks''\n\nconst [state, setState] = useSetState({\n  name: '''',\n  email: '''',\n  age: 0,\n})\n\n// Partial updates (shallow merge)\nsetState({ name: ''John'' })\nsetState(prev => ({ ...prev, email: ''john@example.com'' }))\n```\n\n**When to use**: Form state, game engine state, UI state that changes together (if not URL-shareable)\n\n**When NOT to use**: URL-shareable state (use nuqs), loading states (use TanStack Query)\n\n### useLocalStorageState Pattern\n\nUse for state that persists across browser sessions:\n\n```typescript\nimport { useLocalStorageState } from ''ahooks''\n\nconst [value, setValue] = useLocalStorageState<boolean>(''key'', {\n  defaultValue: false,\n})\n\n// Type-safe with generics\nconst [settings, setSettings] = useLocalStorageState<Settings>(''settings'', {\n  defaultValue: { theme: ''light'', fontSize: 14 },\n})\n```\n\n**When to use**: User preferences, debug flags, settings that should persist across sessions\n\n**When NOT to use**: URL-shareable state (use nuqs), sensitive data (use secure storage)\n\n### Integration with nuqs\n\nBidirectional sync between URL and localStorage:\n\n```typescript\nimport { useLocalStorageState } from ''ahooks''\nimport { useQueryState } from ''nuqs''\nimport { useEffect, useRef } from ''react''\n\nconst [queryState, setQueryState] = useQueryState(''debug'')\nconst [storageState, setStorageState] = useLocalStorageState<boolean>(''debug'', {\n  defaultValue: false,\n})\nconst isFirstMount = useRef(true)\n\n// Sync on mount: localStorage → URL\nuseEffect(() => {\n  if (isFirstMount.current) {\n    isFirstMount.current = false\n    if (storageState && queryState !== ''true'') {\n      setQueryState(''true'')\n      return\n    }\n  }\n  // Sync changes: URL → localStorage\n  if (queryState === ''true'' && !storageState) {\n    setStorageState(true)\n  } else if (queryState === ''false'' && storageState) {\n    setStorageState(false)\n  }\n}, [queryState, storageState, setQueryState, setStorageState])\n```\n\n**Use case**: Debug flags, feature toggles that should be both URL-shareable and persistent\n\n### State Management Decision Tree\n\n1. **URL-shareable state** → Use `nuqs` (filters, search, tabs, pagination)\n2. **Grouped state not in URL** → Use `useSetState` (form state, game engine, ephemeral UI)\n3. **Async operations** → Use TanStack Query (data fetching, mutations, caching)\n4. **localStorage persistence** → Use `useLocalStorageState` (preferences, settings)\n5. **Simple independent state** → Use `useState` (rare, prefer other options)\n\n## References\n\n- [ahooks documentation](https://ahooks.js.org/) - Official documentation\n- React rules - State management decision tree and patterns\n- TanStack Query - Async operations and data fetching patterns\n"},"lastSynced":"2026-03-08T02:07:44.570Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring efficient React state management with features like grouped state updates and localStorage persistence.","zh":"适合需要高效React状态管理的前端代理，具有分组状态更新和localStorage持久性等功能。","ja":"効率的なReact状態管理が必要なフロントエンドエージェントに最適で、グループ化された状態の更新やlocalStorageの永続化などの機能を備えています。","ko":"효율적인 React 상태 관리가 필요한 프론트엔드 에이전트에 적합하며, 그룹화된 상태 업데이트와 localStorage 지속성 등의 기능을 제공합니다.","es":"Ideal para Agentes Frontend que requieren una gestión eficiente del estado de React con características como actualizaciones de estado agrupadas y persistencia de localStorage.","fr":"Idéal pour les agents Frontend nécessitant une gestion efficace de l''état React avec des fonctionnalités comme des mises à jour d''état regroupées et une persistence de localStorage.","de":"Ideal für Frontend-Agents, die eine effiziente React-Zustandsverwaltung mit Funktionen wie gruppierten Zustandsaktualisierungen und localStorage-Persistenz erfordern.","pt":"Ideal para Agentes Frontend que exigem gerenciamento de estado React eficiente com recursos como atualizações de estado agrupadas e persistência do localStorage.","ru":"Идеально для агентов фронтенда, требующих эффективного управления состоянием React с функциями, такими как групповые обновления состояния и сохранение в localStorage.","ar":"مثالي لعميل واجهة المستخدم الذي يتطلب إدارة فعالة لتحديثات حالة React مع ميزات مثل التحديثات المجمعة وتأثيرات التخزين المحلي."},"recommendation":{"en":"Empowers agents to manage complex client-side state using ahooks'' utility hooks, including useSetState for grouped state updates and localStorage persistence, all while leveraging React 18+ and TypeScript v5+ for robust type inference.","zh":"赋予代理管理复杂客户端状态的能力，使用ahooks的工具钩子，包括useSetState用于分组状态更新和localStorage持久化，同时利用React 18+和TypeScript v5+进行强大的类型推断。","ja":"ahooksのユーティリティフックを使用して、エージェントが複雑なクライアントサイド状態を管理できるようにします。useSetStateを使用したグループ化された状態の更新やlocalStorageの永続化などを提供し、React 18+とTypeScript v5+を利用して堅牢な型推論を実現します。","ko":"에이전트가 복잡한 클라이언트 측 상태를 관리할 수 있는 능력을 부여합니다. ahooks의 유틸리티 훅을 사용하여 useSetState를 통해 그룹화된 상태 업데이트와 localStorage 지속성을 제공하며, React 18+와 TypeScript v5+를 사용하여 강력한 타입 추론을 실현합니다.","es":"Habilita a los agentes a gestionar estados complejos del lado del cliente utilizando los hooks de utilidad de ahooks, incluyendo useSetState para actualizaciones de estado agrupadas y persistencia de localStorage, todo mientras aprovecha React 18+ y TypeScript v5+ para una inferencia de tipos robusta.","fr":"Permet aux agents de gérer des états complexes côté client en utilisant les hooks d''utilité d''ahooks, notamment useSetState pour des mises à jour d''état regroupées et une persistence de localStorage, le tout en exploitant React 18+ et TypeScript v5+ pour une inférence de type robuste.","de":"Ermächtigt Agenten, komplexe Client-Seitige Zustände mithilfe von ahooks'' Utility-Hooks zu verwalten, einschließlich useSetState für gruppierte Zustandsaktualisierungen und localStorage-Persistenz, alles unter Ausnutzung von React 18+ und TypeScript v5+ für eine robuste Typinferenz.","pt":"Habilita os agentes a gerenciar estados complexos do lado do cliente usando ganchos de utilidade do ahooks, incluindo useSetState para atualizações de estado agrupadas e persistência do localStorage, tudo isso aproveitando o React 18+ e o TypeScript v5+ para inferência de tipo robusta.","ru":"Наделяет агентов возможностью управлять сложными состояниями на стороне клиента с помощью утилитных хуков ahooks, включая useSetState для групповых обновлений состояния и сохранения в localStorage, все это при помощи React 18+ и TypeScript v5+ для надежной вывода типов.","ar":"تمكّن الوكيل من إدارة حالات العملاء المعقدة باستخدام Hooks من ahooks، بما في ذلك useSetState لتحديثات الحالة المجمعة وتأثيرات التخزين المحلي، مع الاستفادة من React 18+ وTypeScript v5+ للحصول على استدلال أنواع متين."},"useCases":{"en":["Implementing grouped state updates with useSetState","Persisting client-side state to localStorage for seamless user experiences","Optimizing React application performance with efficient state management"],"zh":["使用useSetState实现分组状态更新","将客户端状态持久化到localStorage以提供无缝的用户体验","使用高效的状态管理优化React应用程序性能"],"ja":["useSetStateを使用した状態の更新のグループ化","クライアントサイド状態をlocalStorageに永続化してシームレスなユーザーエクスペリエンスを提供","効率的な状態管理を使用してReactアプリケーションのパフォーマンスを最適化"],"ko":["useSetState를 사용하여 상태 업데이트를 그룹화","클라이언트 측 상태를 localStorage에 지속화하여 무결점의 사용자 경험을 제공","효율적인 상태 관리를 사용하여 React 애플리케이션의 성능을 최적화"],"es":["Implementar actualizaciones de estado agrupadas con useSetState","Permitir la persistencia del estado del lado del cliente en localStorage para experiencias de usuario sin interrupciones","Optimizar el rendimiento de la aplicación React con una gestión eficiente del estado"],"fr":["Mettre en œuvre des mises à jour d''état regroupées avec useSetState","Permettre la persistence de l''état côté client dans localStorage pour des expériences utilisateur sans interruption","Optimiser les performances de l''application React avec une gestion efficace de l''état"],"de":["Gruppierte Zustandsaktualisierungen mit useSetState implementieren","Persistenz des Client-Seitigen Zustands in localStorage für unterbrechungsfreie Benutzeroberflächen ermöglichen","React-Anwendungsleistung mit effizienter Zustandsverwaltung optimieren"],"pt":["Implementando atualizações de estado agrupadas com useSetState","Persistindo o estado do lado do cliente no localStorage para experiências de usuário sem interrupção","Otimizando o desempenho do aplicativo React com gerenciamento de estado eficiente"],"ru":["Реализация групповых обновлений состояния с помощью useSetState","Сохранение состояния на стороне клиента в localStorage для бесперебойного пользовательского опыта","Оптимизация производительности приложения React с эффективным управлением состоянием"],"ar":["تنفيذ تحديثات الحالة المجمعة باستخدام useSetState","الحفاظ على حالة العميل في التخزين المحلي لتجارب المستخدم بدون انقطاع","تحسين أداء تطبيقات React بإدارة الحالة الفعالة"]},"limitations":{"en":["Requires ahooks v3+ and React 18+ with hooks support","Limited to client-side applications due to reliance on browser APIs for localStorage","Does not cover data fetching, URL state management, or complex state machines"],"zh":["需要ahooks v3+和React 18+的钩子支持","由于依赖于浏览器API的localStorage，仅限于客户端应用","不涵盖数据获取、URL状态管理或复杂状态机"],"ja":["ahooks v3+とReact 18+のフックサポートが必要","ブラウザAPIのlocalStorageに依存しているため、クライアントサイドアプリケーションに限定","データ取得、URL状態管理、または複雑なステートマシンはカバーしていない"],"ko":["ahooks v3+와 React 18+의 훅 지원이 필요","브라우저 API의 localStorage에 의존하기 때문에 클라이언트 측 애플리케이션으로 제한","데이터 가져오기, URL 상태 관리 또는 복잡한 상태 머신을 다루지 않음"],"es":["Requiere ahooks v3+ y React 18+ con soporte para hooks","Limitado a aplicaciones del lado del cliente debido a la dependencia de las API del navegador para localStorage","No cubre la recuperación de datos, la gestión del estado de la URL o las máquinas de estado complejas"],"fr":["Nécessite ahooks v3+ et React 18+ avec prise en charge des hooks","Limité aux applications côté client en raison de la dépendance à l''égard des API du navigateur pour localStorage","Ne couvre pas la récupération de données, la gestion de l''état de l''URL ou les machines d''état complexes"],"de":["Benötigt ahooks v3+ und React 18+ mit Hooks-Unterstützung","Begrenzt auf Client-Seitige Anwendungen aufgrund der Abhängigkeit von Browser-APIs für localStorage","Deckt nicht die Datenabfrage, die URL-Zustandsverwaltung oder komplexe Zustandsmaschinen ab"],"pt":["Exige ahooks v3+ e React 18+ com suporte a ganchos","Limitado a aplicações de lado do cliente devido à dependência de APIs do navegador para localStorage","Não cobre busca de dados, gerenciamento de estado de URL ou máquinas de estado complexas"],"ru":["Требует ahooks v3+ и React 18+ с поддержкой хуков","Ограничен клиентскими приложениями из-за зависимости от браузерных API для localStorage","Не покрывает получение данных, управление состоянием URL или сложные машины состояний"],"ar":["يتطلب ahooks v3+ و React 18+ مع دعم Hooks","محدود للتطبيقات العميلية بسبب الاعتماد على واجهات برمجة التطبيقات للمتصفح من أجل التخزين المحلي","لا يغطي استرجاع البيانات أو إدارة حالة URL أو آلات الحالة المعقدة"]},"version":4},"contentHash":"3619a1d5c301136fecc3ca74d2cee8141e56e9ddf581957df92667bd894b257b","qualityScore":36}');
