INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blockmatic/basilic/ahooks', 'ahooks', 'blockmatic', 'basilic', 'community', 'ahooks blockmatic basilic community ahooks is a utility hook library for React state management, providing features like grouped state updates and localStorage persistence for client-side applications. ahooks是一个React状态管理工具，提供组合状态更新和localStorage持久化功能 ahooksはReactの状態管理ツールで、状態の更新とlocalStorageの永続化機能を提供します ahooks는 React 상태 관리 도구로 상태 업데이트와 localStorage 영속성 기능을 제공합니다 ahooks es un utilitaire de gestión de estado para React que ofrece una forma sencilla de gestionar el estado de la aplicación ahooks est un utilitaire de gestion d''état pour React qui offre une façon simple de gérer l''état de l''application ahooks ist ein Utility für die Zustandsverwaltung in React, das eine einfache Möglichkeit bietet, den Anwendungszustand zu verwalten Ahooks é uma biblioteca para gerenciamento de estado em React, oferecendo hooks para atualizações de estado em grupo e persistência em localStorage. ИИ Агент ahooks - это библиотека для управления состоянием в React, предоставляющая хуки для групповых обновлений состояния и сохранения в localStorage. ahooks هو أداة لتنفيذ إدارة الحالة في تطبيقات الويب، تقدم hooks لتحديثات الحالة المجمعة وتخزينها في localStorage. how to use ahooks ahooks setup guide ahooks vs react-query ahooks install react state management with ahooks ahooks alternative to redux ahooks React状态管理 组合状态更新 localStorage持久化 useSetState React 18+ TypeScript v5+ AIエージェント工具 Provides useSetState for grouped state updates Supports localStorage persistence for client-side state management Compatible with React 18+ and TypeScript v5+ Optimized for client-side only applications Does not cover data fetching, URL state management, or complex state machines ahooks is a React utility hook library for managing state, supporting features like useSetState for grouped state updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kweaver-ai/adp/bkn-modeling', 'community', 'kweaver-ai', 'adp', 'kweaver-ai/adp', 'bkn-modeling', 0, 0, 36, '2026-03-08T01:57:15.442Z', '2026-03-08T02:08:24.864Z', 'eb97fa02f01f4f9b28df205f9ef86556d34bb7f908cbd43e1f0907cd9e14f35e', '{"id":"kweaver-ai/adp/bkn-modeling","name":"bkn-modeling","description":{"en":"bkn-modeling bridges the gap between heterogeneous data sources and AI agents, providing unified data access and orchestrating data processing. It benefits developers working with AI agents and data platforms.","zh":"BKN建模是业务知识网络构建的关键步骤，涉及创建和定义实体类、关系和动作","ja":"BKNモデリングはビジネス知識ネットワーク構築の重要なステップであり、エンティティクラス、関係、動作の定義が含まれます","ko":"BKN 모델링은 비즈니스 지식 네트워크 구축의 핵심 단계로, 엔티티 클래스, 관계, 동작의 정의를 포함합니다","es":"bkn-modeling es una tecnología que permite crear redes de conocimiento empresarial para mejorar la integración de datos en proyectos de inteligencia artificial","fr":"bkn-modeling est une technologie qui permet de créer des réseaux de connaissance métier pour améliorer l''intégration des données dans les projets d''intelligence artificielle","de":"bkn-modeling ist eine Technologie, die die Erstellung von Geschäftswissensnetzwerken ermöglicht, um die Datenintegration in KI-Projekten zu verbessern","pt":"BKN Modeling é uma plataforma de dados inteligente que permite criar modelos de negócios com base em fontes heterogêneas de dados. Ela fornece uma estrutura para criar, configurar e orquestrar processos de dados.","ru":"BKN Modeling — это интеллектуальная платформа данных, которая позволяет создавать бизнес-модели на основе разнообразных источников данных. Она предоставляет структуру для создания, конфигурирования и оркестровки процессов данных.","ar":"بكن موديلينج هي منصة بيانات ذكية تمكن من إنشاء نماذج الأعمال باستخدام مصادر بيانات متعددة. توفر هيكلاً لإنشاء وتكوين وتنسيق عمليات البيانات"},"seo":{"title":{"en":"bkn-modeling: Setup Guide for AI Agents | AI Agent Skill","zh":"BKN建模入门指南 - 业务知识网络构建","ja":"BKNモデリングセットアップガイド - AIエージェントのためのビジネス知識ネットワーク","ko":"BKN 모델링 시작하기 - 비즈니스 지식 네트워크 구축 가이드","es":"Guía de configuración de bkn-modeling para agentes de int...","fr":"Guide de mise en place de bkn-modeling pour les agents d''...","de":"Einrichtungsleitfaden für bkn-modeling in künstlichen Int...","pt":"Guia de Configuração do BKN Modeling para Desenvolvedores","ru":"Настройка BKN Modeling: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد بكن موديلينج لمنصة آدب الذكية"},"description":{"en":"Unlock the power of bkn-modeling for AI agents. Learn how to create business knowledge networks with VEGA and DataFlow pipelines. Get started now!","zh":"了解BKN建模的基本概念和实践，包括创建业务知识网络、实体类和关系的定义","ja":"BKNモデリングの基本概念と実践を学び、ビジネス知識ネットワークの作成やエンティティクラスと関係の定義をマスターする","ko":"BKN 모델링의 기본 개념과 실습을 알아보며, 비즈니스 지식 네트워크 구축 및 엔티티 클래스와 관계 정의에 대해 배우세요","es":"Aprende a utilizar bkn-modeling para crear redes de conocimiento empresarial y mejorar la integración de datos en tus proyectos de inteligencia artificial","fr":"Découvrez comment utiliser bkn-modeling pour créer des réseaux de connaissance métier et améliorer l''intégration des données dans vos projets d''intelligence ...","de":"Erfahren Sie, wie Sie bkn-modeling verwenden können, um Geschäftswissensnetzwerke zu erstellen und die Datenintegration in Ihren KI-Projekten zu verbessern","pt":"Aprenda a criar e configurar modelos de negócios com BKN Modeling, uma plataforma de dados inteligente que integra fontes heterogêneas de dados e agentes de IA.","ru":"Изучите возможности BKN Modeling, платформы данных, которая объединяет разнообразные источники данных и ИИ Агенты для создания бизнес-моделей.","ar":"اكتشف كيفية إنشاء نماذج الأعمال باستخدام بكن موديلينج، منصة بيانات ذكية تدمج مصادر بيانات متعددة ووكلاء الذكاء الاصطناعي"},"definition":{"en":"bkn-modeling is a business knowledge network modeling skill that abstracts data complexity through ontology, enabling unified data access and data processing orchestration.","zh":"BKN建模是一种业务知识网络构建方法，用于定义实体类、关系和动作","ja":"BKNモデリングはビジネス知識ネットワーク構築方法の一種であり、エンティティクラス、関係、動作を定義する","ko":"BKN 모델링은 비즈니스 지식 네트워크 구축 방법 중 하나로, 엔티티 클래스, 관계, 동작을 정의하는 데 사용됩니다","es":"bkn-modeling es un modelo de red de conocimiento empresarial que utiliza ontologías para integrar datos heterogéneos","fr":"bkn-modeling est un modèle de réseau de connaissance métier qui utilise des ontologies pour intégrer des données hétérogènes","de":"bkn-modeling ist ein Modell für ein Geschäftswissensnetzwerk, das Ontologien zur Integration heterogener Daten verwendet","pt":"BKN Modeling é uma técnica de modelagem de negócios que utiliza conhecimento de negócios para criar modelos de dados.","ru":"BKN Modeling — это методология моделирования бизнеса, которая использует бизнес-знания для создания моделей данных.","ar":"بكن موديلينج هو أسلوب نمذجة الأعمال التي تستخدم المعرفة التجارية لإنشاء نماذج البيانات"},"features":{"en":["Creates business knowledge networks using templates and examples","Supports DataFlow pipelines for data processing orchestration","Provides unified data access through VEGA","Enables entity, relation, and action mapping in BKN files","Utilizes markdown file structure for network definition","References SPECIFICATION.md for BKN file syntax"],"zh":["创建业务知识网络","定义实体类和关系","使用VEGA实现统一数据访问","通过DataFlow管道编排数据处理"],"ja":["ビジネス知識ネットワークの作成","エンティティクラスと関係の定義","VEGAを使用した統一データアクセス","DataFlowパイプラインによるデータ処理のオーケストレーション"],"ko":["비즈니스 지식 네트워크 구축","엔티티 클래스와 관계 정의","VEGA를 사용한统一 데이터 액세스","DataFlow 파이프라인을 통한 데이터 처리 오케스트레이션"],"es":["Creación de redes de conocimiento empresarial utilizando ontologías","Integración de datos heterogéneos a través de VEGA","Orquestación de procesos de datos mediante DataFlow pipelines","Soporte para la creación de archivos BKN utilizando plantillas y ejemplos","Definición de entidades, relaciones y acciones en el modelo de red","Compatibilidad con la especificación BKN"],"fr":["Création de réseaux de connaissance métier utilisant des ontologies","Intégration de données hétérogènes via VEGA","Orchestration de processus de données via des pipelines DataFlow","Prise en charge de la création de fichiers BKN à l''aide de modèles et d''exemples","Définition d''entités, de relations et d''actions dans le modèle de réseau","Compatibilité avec la spécification BKN"],"de":["Erstellung von Geschäftswissensnetzwerken unter Verwendung von Ontologien","Integration heterogener Daten über VEGA","Orchestrierung von Datenprozessen mittels DataFlow-Pipelines","Unterstützung bei der Erstellung von BKN-Dateien mithilfe von Vorlagen und Beispielen","Definition von Entitäten, Beziehungen und Aktionen im Netzwerkmodell","Kompatibilität mit der BKN-Spezifikation"],"pt":["Criação de modelos de negócios com base em fontes heterogêneas de dados","Utilização de conhecimento de negócios para criar modelos de dados","Orquestração de processos de dados com DataFlow pipelines","Acesso unificado a dados com VEGA","Suporte a criação de modelos de negócios com templates e exemplos"],"ru":["Создание бизнес-моделей на основе разнообразных источников данных","Использование бизнес-знаний для создания моделей данных","Оркестровка процессов данных с помощью DataFlow pipelines","Единый доступ к данным с помощью VEGA","Поддержка создания бизнес-моделей с помощью шаблонов и примеров"],"ar":["إنشاء نماذج الأعمال باستخدام مصادر بيانات متعددة","استخدام المعرفة التجارية لإنشاء نماذج البيانات","تنسيق عمليات البيانات باستخدام DataFlow pipelines","دعم الوصول الموحد إلى البيانات مع VEGA","دعم إنشاء نماذج الأعمال باستخدام قوالب وأمثلة"]},"keywords":{"en":["how to use bkn-modeling","bkn-modeling setup guide","what is bkn-modeling","bkn-modeling vs ontology","bkn-modeling install","bkn-modeling for AI agents","VEGA data access","DataFlow pipeline orchestration","business knowledge network modeling"],"zh":["BKN建模","业务知识网络","实体类","关系","VEGA","DataFlow","AI工具","AIエージェント"],"ja":["BKNモデリング","ビジネス知識ネットワーク","エンティティクラス","関係","VEGA","DataFlow","AIエージェント","AIツール"],"ko":["BKN 모델링","비즈니스 지식 네트워크","엔티티 클래스","관계","VEGA","DataFlow","AI 에이전트","AI 툴"],"es":["bkn-modeling","agentes de inteligencia artificial","integración de datos","ontologías","VEGA","DataFlow pipelines","redes de conocimiento empresarial","creación de archivos BKN","especificación BKN"],"fr":["bkn-modeling","agents d''intelligence artificielle","intégration de données","ontologies","VEGA","pipelines DataFlow","réseaux de connaissance métier","création de fichiers BKN","spécification BKN"],"de":["bkn-modeling","künstliche Intelligenzagenten","Datenintegration","Ontologien","VEGA","DataFlow-Pipelines","Geschäftswissensnetzwerke","Erstellung von BKN-Dateien","BKN-Spezifikation"],"pt":["bkn modeling","modelagem de negócios","conhecimento de negócios","dados heterogêneos","DataFlow pipelines","VEGA","agentes de ia","desenvolvedores de ia","plataforma de dados inteligente"],"ru":["bkn modeling","моделирование бизнеса","бизнес-знания","разнообразные источники данных","DataFlow pipelines","VEGA","ИИ Агенты","разработчики ИИ","интеллектуальная платформа данных"],"ar":["بكن موديلينج","نمذجة الأعمال","المعرفة التجارية","مصادر بيانات متعددة","DataFlow pipelines","VEGA","وكلاء الذكاء الاصطناعي","مطورو الذكاء الاصطناعي","منصة بيانات ذكية"]}},"owner":"kweaver-ai","repo":"adp","repoPath":"kweaver-ai/adp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.442Z","topics":[],"category":"community","skillMd":{"name":"bkn-modeling","description":"编写和验证 BKN（业务知识网络）建模文件。用于创建实体类、关系类、行动类定义，或修改现有的 .bkn 文件。当用户提到业务知识网络、知识网络、BKN 文件时使用。","bodyPreview":"# BKN 业务知识网络建模\n\n辅助编写 BKN (Business Knowledge Network) 业务知识网络建模文件。\n\n## 快速开始\n\n### 创建新的知识网络\n\n1. 使用模板创建：`docs/ontology/bkn_docs/templates/network.bkn.template`\n2. 参考样例：`docs/ontology/bkn_docs/examples/k8s-topology.bkn`\n3. 查阅规范：`docs/ontology/bkn_docs/SPECIFICATION.md`\n\n### BKN 文件结构\n\n```markdown\n---\ntype: network\nid: my-network\nname: 我的网络\nversion: 1.0.0\n---\n\n# 网络标题\n\n## Entity: entity_id\n...\n\n## Relation: relation_id\n...\n\n## Action: action_id\n...\n```\n\n## 三种类型\n\n### 实体类 (Entity)\n\n描述业务对象，直接映射数据视图：\n\n```ma","body":"# BKN 业务知识网络建模\n\n辅助编写 BKN (Business Knowledge Network) 业务知识网络建模文件。\n\n## 快速开始\n\n### 创建新的知识网络\n\n1. 使用模板创建：`docs/ontology/bkn_docs/templates/network.bkn.template`\n2. 参考样例：`docs/ontology/bkn_docs/examples/k8s-topology.bkn`\n3. 查阅规范：`docs/ontology/bkn_docs/SPECIFICATION.md`\n\n### BKN 文件结构\n\n```markdown\n---\ntype: network\nid: my-network\nname: 我的网络\nversion: 1.0.0\n---\n\n# 网络标题\n\n## Entity: entity_id\n...\n\n## Relation: relation_id\n...\n\n## Action: action_id\n...\n```\n\n## 三种类型\n\n### 实体类 (Entity)\n\n描述业务对象，直接映射数据视图：\n\n```markdown\n## Entity: pod\n\n**Pod实例** - 描述\n\n### 数据来源\n\n| 类型 | ID |\n|------|-----|\n| data_view | view_id |\n\n> **主键**: `id` | **显示属性**: `pod_name`\n```\n\n**配置模式**:\n- **完全映射**: 只声明数据来源，自动继承所有字段\n- **属性覆盖**: 仅声明需要特殊配置的属性\n- **完整定义**: 完整声明所有属性（精细控制）\n\n### 关系类 (Relation)\n\n描述两个实体之间的关联：\n\n```markdown\n## Relation: pod_belongs_node\n\n**Pod属于节点**\n\n| 起点 | 终点 | 类型 |\n|------|------|------|\n| pod | node | direct |\n\n### 映射规则\n\n| 起点属性 | 终点属性 |\n|----------|----------|\n| pod_node_name | node_name |\n```\n\n### 行动类 (Action)\n\n描述可执行的操作：\n\n```markdown\n## Action: restart_pod\n\n**重启Pod**\n\n| 绑定实体 | 行动类型 |\n|----------|----------|\n| pod | modify |\n\n### 触发条件\n\n```yaml\nfield: pod_status\noperation: in\nvalue: [Unknown, Failed]\n`` `\n\n### 工具配置\n\n| 类型 | 工具ID |\n|------|--------|\n| tool | kubectl_delete_pod |\n\n### 参数绑定\n\n| 参数 | 来源 | 绑定 |\n|------|------|------|\n| pod | property | pod_name |\n```\n\n## 常用操作\n\n### 添加实体\n\n1. 在 `# 实体定义` section 下添加 `## Entity: {id}`\n2. 声明数据来源（必须）\n3. 声明主键和显示属性（必须）\n4. 可选：属性覆盖、逻辑属性\n\n### 添加关系\n\n1. 在 `# 关系定义` section 下添加 `## Relation: {id}`\n2. 声明起点、终点、类型（必须）\n3. 声明映射规则（必须）\n\n### 添加行动\n\n1. 在 `# 行动定义` section 下添加 `## Action: {id}`\n2. 声明绑定实体和行动类型（必须）\n3. 声明工具配置和参数绑定（必须）\n4. 可选：触发条件、调度配置\n\n## 增量导入\n\nBKN 支持动态增量导入，任何 `.bkn` 文件可直接导入到已有的知识网络。\n\n### 文件类型\n\n| type | 用途 |\n|------|------|\n| `entity` | 单个实体，独立文件 |\n| `relation` | 单个关系，独立文件 |\n| `action` | 单个行动，独立文件 |\n| `fragment` | 混合片段，包含多个定义 |\n| `delete` | 删除标记 |\n\n### 导入行为\n\n- **ID 不存在**: 新增定义\n- **ID 已存在**: 更新定义（覆盖）\n- **type: delete**: 删除指定定义\n\n### 稳定性要求（重要）\n\n- **幂等**：同一文件重复导入，结果必须一致\n- **确定性**：同一批输入文件（不依赖目录遍历顺序）导入结果必须一致\n- **冲突处理**：同一个 `(network, type, id)` 在同一批次重复定义时，默认应 fail-fast（推荐）\n\n### 行动治理（重要）\n\n行动连接执行面（tool/mcp），建议遵循：\n\n- 导入不等于启用；启用/执行需要独立权限与审计\n- Action 文档中明确：触发、影响范围、权限与前置条件、回滚/失败策略\n\n### 新增实体示例\n\n创建独立文件 `deployment.bkn`:\n\n```markdown\n---\ntype: entity\nid: deployment\nname: Deployment\nnetwork: k8s-network\n---\n\n# Deployment\n\n## 数据来源\n\n| 类型 | ID |\n|------|-----|\n| data_view | deployment_view |\n\n> **主键**: `id` | **显示属性**: `deployment_name`\n```\n\n导入后自动添加到 `k8s-network`。\n\n## 命名规范\n\n| 类型 | 格式 | 示例 |\n|------|------|------|\n| 网络 ID | snake_case | `k8s_topology` |\n| 实体 ID | snake_case | `pod`, `node` |\n| 关系 ID | snake_case | `pod_belongs_node` |\n| 行动 ID | snake_case | `restart_pod` |\n\n## 验证清单\n\n编写完成后检查：\n\n- [ ] Frontmatter 包含 type, id, name, version\n- [ ] 每个实体有数据来源、主键、显示属性\n- [ ] 每个关系有起点、终点、映射规则\n- [ ] 每个行动有绑定实体、工具配置、参数绑定\n- [ ] ID 使用 snake_case 格式\n- [ ] 表格格式正确\n\n## 参考文档\n\n- [架构设计](../../docs/ontology/bkn_docs/ARCHITECTURE.md)\n- [语言规范](../../docs/ontology/bkn_docs/SPECIFICATION.md)\n- 样例：\n  - [单文件模式](../../docs/ontology/bkn_docs/examples/k8s-topology.bkn)\n  - [按类型拆分](../../docs/ontology/bkn_docs/examples/k8s-network/)\n  - [每定义一文件](../../docs/ontology/bkn_docs/examples/k8s-modular/) - 推荐大规模场景\n- 模板文件：\n  - [网络模板](../../docs/ontology/bkn_docs/templates/network.bkn.template)\n  - [实体模板](../../docs/ontology/bkn_docs/templates/entity.bkn.template)\n  - [关系模板](../../docs/ontology/bkn_docs/templates/relation.bkn.template)\n  - [行动模板](../../docs/ontology/bkn_docs/templates/action.bkn.template)\n"},"lastSynced":"2026-03-08T02:08:24.864Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing unified data access and Business Knowledge Network modeling capabilities.","zh":"非常适合需要统一数据访问和Business Knowledge Network建模能力的AI代理。","ja":"統一されたデータアクセスとBusiness Knowledge Networkモデリングの機能が必要なAIエージェントに最適です。","ko":"통합 데이터 액세스 및 비즈니스 지식 네트워크 모델링 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan acceso unificado a datos y capacidades de modelado de Red de Conocimiento Empresarial.","fr":"Parfait pour les agents IA nécessitant un accès unifié aux données et des capacités de modélisation de Réseau de Connaissance d''Entreprise.","de":"Perfekt für KI-Agents, die einen einheitlichen Datenzugriff und Geschäfts-Wissens-Netzwerk-Modellierungs-Funktionen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de acesso unificado a dados e capacidades de modelagem de Rede de Conhecimento Empresarial.","ru":"Идеально для ИИ-агентов, которым необходим единный доступ к данным и возможности моделирования Сети деловых знаний.","ar":"مثالي للوكلاء الذكيين الذين يحتاجون إلى وصول موحد إلى البيانات وقدرات نمذجة شبكة المعرفة التجارية."},"recommendation":{"en":"Empowers agents to bridge heterogeneous data sources using BKN files, providing unified data access and orchestrating data processing with specifications outlined in SPECIFICATION.md, utilizing templates like network.bkn.template and examples such as k8s-topology.bkn.","zh":"通过BKN文件使代理能够连接异构数据源，提供统一的数据访问，并按照SPECIFICATION.md中概述的规格编排数据处理，使用诸如network.bkn.template的模板和k8s-topology.bkn等示例。","ja":"BKNファイルを使用して、エージェントが異種のデータソースをブリッジし、統一されたデータアクセスを提供し、SPECIFICATION.mdに概説されている仕様でデータ処理をオーケストレーションすることを可能にします。テンプレートとしてnetwork.bkn.templateやk8s-topology.bknなどの例を使用します。","ko":"BKN 파일을 사용하여 에이전트가 이기종 데이터 소스를 연결하고統一된 데이터 액세스를 제공하며 SPECIFICATION.md에概説されている 사양으로 데이터 처리를 오케스트레이션 할 수 있습니다. 템플릿으로 network.bkn.template이나 k8s-topology.bkn 등의 예를 사용합니다.","es":"Habilita a los agentes a conectar fuentes de datos heterogéneas utilizando archivos BKN, proporcionando acceso unificado a datos y orquestando el procesamiento de datos con especificaciones descritas en SPECIFICATION.md, utilizando plantillas como network.bkn.template y ejemplos como k8s-topology.bkn.","fr":"Permet aux agents de relier des sources de données hétérogènes en utilisant des fichiers BKN, fournissant un accès unifié aux données et orchestrant le traitement des données avec des spécifications décrites dans SPECIFICATION.md, en utilisant des modèles tels que network.bkn.template et des exemples tels que k8s-topology.bkn.","de":"Ermöglicht es Agents, heterogene Datenquellen mithilfe von BKN-Dateien zu verbinden, wodurch ein einheitlicher Datenzugriff bereitgestellt und die Datenverarbeitung mit Spezifikationen aus SPECIFICATION.md orchestriert wird, unter Verwendung von Vorlagen wie network.bkn.template und Beispielen wie k8s-topology.bkn.","pt":"Habilita os agentes a unificarem fontes de dados heterogêneas usando arquivos BKN, fornecendo acesso unificado a dados e orquestrando o processamento de dados com especificações delineadas em SPECIFICATION.md, utilizando modelos como network.bkn.template e exemplos como k8s-topology.bkn.","ru":"Наделяет агентов возможностью объединять разнообразные источники данных с помощью файлов BKN, обеспечивая единый доступ к данным и оркестрируя обработку данных в соответствии с спецификациями, изложенными в SPECIFICATION.md, используя шаблоны, такие как network.bkn.template, и примеры, такие как k8s-topology.bkn.","ar":"تمكّن الوكلاء من ربط مصادر البيانات المتنوعة باستخدام ملفات BKN، مما يوفر وصولاً موحداً إلى البيانات ويرتبط بمعالجة البيانات المتوفرة في SPECIFICATION.md، باستخدام قوالب مثل network.bkn.template وأمثلة مثل k8s-topology.bkn."},"useCases":{"en":["Creating new knowledge networks with entity, relation, and action definitions","Orchestrating data processing across disparate data sources","Generating BKN files for business knowledge network modeling"],"zh":["创建具有实体、关系和动作定义的新知识网络","编排跨异构数据源的数据处理","为业务知识网络建模生成BKN文件"],"ja":["エンティティ、関係、行動の定義を含む新しい知識ネットワークを作成する","異種のデータソースを跨いだデータ処理をオーケストレーションする","ビジネス知識ネットワークモデリングのためにBKNファイルを生成する"],"ko":["엔티티, 관계, 액션 정의를 포함하는 새로운 지식 네트워크를 생성","이기종 데이터 소스를跨いだ 데이터 처리를 오케스트레이션","비즈니스 지식 네트워크 모델링을 위한 BKN 파일 생성"],"es":["Crear nuevas redes de conocimiento con definiciones de entidad, relación y acción","Orquestar el procesamiento de datos a través de fuentes de datos dispares","Generar archivos BKN para el modelado de la red de conocimiento empresarial"],"fr":["Créer de nouveaux réseaux de connaissances avec des définitions d''entité, de relation et d''action","Orchestrer le traitement des données à travers des sources de données dispersées","Générer des fichiers BKN pour la modélisation du Réseau de Connaissance d''Entreprise"],"de":["Erstellen neuer Wissensnetze mit Entitäts-, Beziehungs- und Aktionsdefinitionen","Orchestrieren der Datenverarbeitung über disparate Datenquellen hinweg","Erzeugen von BKN-Dateien für die Modellierung des Geschäfts-Wissens-Netzwerks"],"pt":["Criação de novas redes de conhecimento com definições de entidade, relação e ação","Orquestração do processamento de dados em fontes de dados dispersas","Geração de arquivos BKN para modelagem de rede de conhecimento empresarial"],"ru":["Создание новых сетей знаний с определениями сущности, отношения и действия","Оркестрация обработки данных в различных источниках данных","Генерация файлов BKN для моделирования сети деловых знаний"],"ar":["إنشاء شبكات معرفة جديدة مع تعريفات الكيان والعلاقة والعمل","تنسيق معالجة البيانات عبر مصادر البيانات المنفصلة","توليد ملفات BKN لنمذجة شبكة المعرفة التجارية"]},"limitations":{"en":["Requires understanding of BKN file structure and syntax","Limited to Business Knowledge Network modeling use cases"],"zh":["需要了解BKN文件结构和语法","仅限业务知识网络建模的使用场景"],"ja":["BKNファイルの構造と構文を理解する必要がある","ビジネス知識ネットワークモデリングの使用ケースに限定される"],"ko":["BKN 파일 구조 및 구문을 이해해야 함","비즈니스 지식 네트워크 모델링의 사용 사례에 한정됨"],"es":["Requiere comprensión de la estructura y la sintaxis del archivo BKN","Limitado a casos de uso de modelado de Red de Conocimiento Empresarial"],"fr":["Nécessite une compréhension de la structure et de la syntaxe du fichier BKN","Limité aux cas d''utilisation de la modélisation du Réseau de Connaissance d''Entreprise"],"de":["Benötigt Verständnis für die Struktur und Syntax der BKN-Datei","Begrenzt auf Anwendungsfälle für die Modellierung des Geschäfts-Wissens-Netzwerks"],"pt":["Exige compreensão da estrutura e sintaxe do arquivo BKN","Limitado a casos de uso de modelagem de Rede de Conhecimento Empresarial"],"ru":["Требует понимания структуры и синтаксиса файла BKN","Ограничен случаями использования моделирования Сети деловых знаний"],"ar":["يتطلب فهم هيكل وتنسيق ملف BKN","محدود بحالات استخدام نمذجة شبكة المعرفة التجارية"]},"version":4},"contentHash":"eb97fa02f01f4f9b28df205f9ef86556d34bb7f908cbd43e1f0907cd9e14f35e","qualityScore":36}');
