INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kweaver-ai/adp/bkn-modeling', 'bkn-modeling', 'kweaver-ai', 'adp', 'community', 'bkn-modeling kweaver-ai adp community bkn-modeling bridges the gap between heterogeneous data sources and AI agents, providing unified data access and orchestrating data processing. It benefits developers working with AI agents and data platforms. BKN建模是业务知识网络构建的关键步骤，涉及创建和定义实体类、关系和动作 BKNモデリングはビジネス知識ネットワーク構築の重要なステップであり、エンティティクラス、関係、動作の定義が含まれます BKN 모델링은 비즈니스 지식 네트워크 구축의 핵심 단계로, 엔티티 클래스, 관계, 동작의 정의를 포함합니다 bkn-modeling es una tecnología que permite crear redes de conocimiento empresarial para mejorar la integración de datos en proyectos de inteligencia artificial bkn-modeling est une technologie qui permet de créer des réseaux de connaissance métier pour améliorer l''intégration des données dans les projets d''intelligence artificielle bkn-modeling ist eine Technologie, die die Erstellung von Geschäftswissensnetzwerken ermöglicht, um die Datenintegration in KI-Projekten zu verbessern BKN Modeling é uma plataforma de dados inteligente que permite criar modelos de negócios com base em fontes heterogêneas de dados. Ela fornece uma estrutura para criar, configurar e orquestrar processos de dados. BKN Modeling — это интеллектуальная платформа данных, которая позволяет создавать бизнес-модели на основе разнообразных источников данных. Она предоставляет структуру для создания, конфигурирования и оркестровки процессов данных. بكن موديلينج هي منصة بيانات ذكية تمكن من إنشاء نماذج الأعمال باستخدام مصادر بيانات متعددة. توفر هيكلاً لإنشاء وتكوين وتنسيق عمليات البيانات how to use bkn-modeling bkn-modeling setup guide what is bkn-modeling bkn-modeling vs ontology bkn-modeling install bkn-modeling for AI agents VEGA data access DataFlow pipeline orchestration business knowledge network modeling BKN建模 业务知识网络 实体类 关系 VEGA DataFlow AI工具 AIエージェント Creates business knowledge networks using templates and examples Supports DataFlow pipelines for data processing orchestration Provides unified data access through VEGA Enables entity, relation, and action mapping in BKN files Utilizes markdown file structure for network definition References SPECIFICATION.md for BKN file syntax bkn-modeling is a business knowledge network modeling skill that abstracts data complexity through ontology, enabling unified data access and data processing orchestration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wangqiqi/cursor-ai-rules/skill-dispatcher', 'community', 'wangqiqi', 'cursor-ai-rules', 'wangqiqi/cursor-ai-rules', 'skill-dispatcher', 0, 0, 36, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:43.854Z', '8e7d24baee842952a7545f47aa9ebd8a2ede5895ea85623a33fe5d5e93a15d40', '{"id":"wangqiqi/cursor-ai-rules/skill-dispatcher","name":"skill-dispatcher","description":{"en":"The skill-dispatcher skill provides an intelligent framework for discovering and matching skills in AI agents, supporting efficient human-machine collaboration. It benefits developers by automating skill discovery and loading.","zh":"Skill Dispatcher 是一个智能技能调度器，用于发现、匹配和调用技能，实现高效的 AI 协作体验","ja":"Skill Dispatcher は、スキルを自動で発見、匹配、呼び出し、AI エージェントとの協業を最適化する","ko":"Skill Dispatcher 는 인공지능 툴의 스마트한 협업 파트너로, 기술을 자동으로 발견, 일치 및 호출하여 효율적인 협업 경험을 제공합니다","es":"El skill-dispatcher es un sistema de colaboración de IA que permite la descubierta y llamada de habilidades en proyectos de desarrollo","fr":"Le skill-dispatcher est un système de collaboration d''IA qui permet la découverte et l''appel de compétences dans les projets de développement","de":"Der skill-dispatcher ist ein KI-Kollaborationssystem, das die Entdeckung und den Aufruf von Fähigkeiten in Entwicklungsprojekten ermöglicht","pt":"O Skill Dispatcher é uma ferramenta de inteligência artificial que automatiza a descoberta e o carregamento de habilidades no Cursor Editor","ru":"Skill Dispatcher - это инструмент ИИ, который автоматизирует обнаружение и загрузку навыков в редакторе Cursor","ar":"Skill Dispatcher هو أداة ذكاء اصطناعي التي تautomatiza اكتشاف وتحميل المهارات في محرر Cursor"},"seo":{"title":{"en":"skill-dispatcher: Intelligent Skill Dispatcher for AI Age...","zh":"Skill Dispatcher 设置指南 - 智能技能调度器","ja":"Skill Dispatcher のベストプラクティス - AIエージェントのためのスキルディスパッチャー","ko":"Skill Dispatcher 사용법 - 인공지능 툴의 스마트한 협업 파트너","es":"Guía de configuración de skill-dispatcher para Agentes de IA","fr":"Guide de mise en route de skill-dispatcher pour les Outil...","de":"Einrichtungsleitfaden für skill-dispatcher in KI-Agenten","pt":"Guia de Configuração do Skill Dispatcher - Ferramentas de...","ru":"Настройка Skill Dispatcher - ИИ Агенты для разработчиков","ar":"دليل إعداد Skill Dispatcher - أدوات ذكاء اصطناعي"},"description":{"en":"Discover how skill-dispatcher automates skill discovery and matching for AI agents. Learn how to setup and use this innovative tool to streamline your workflow.","zh":"了解 Skill Dispatcher 的核心功能和技术细节，实现高效的 AI 协作体验","ja":"Skill Dispatcher の機能とテクニカルな詳細を学び、AI エージェントとの協業を最適化する","ko":"Skill Dispatcher 의 핵심 기능과 기술적 세부 사항을 익히고 인공지능 툴과의 협업을 최적화 하세요","es":"Descubre cómo configurar skill-dispatcher para mejorar la colaboración entre humanos y Agentes de IA en proyectos de desarrollo","fr":"Découvrez comment configurer skill-dispatcher pour améliorer la collaboration entre les humains et les Outils d''IA dans les projets de développement","de":"Erfahren Sie, wie Sie skill-dispatcher konfigurieren, um die Zusammenarbeit zwischen Menschen und KI-Agenten in Entwicklungsprojekten zu verbessern","pt":"Aprenda a configurar o Skill Dispatcher, uma ferramenta de inteligência artificial para desenvolvedores, e melhore sua produtividade com recursos avançados d...","ru":"Узнайте, как настроить Skill Dispatcher, инструмент ИИ для разработчиков, и повысьте свою производительность с помощью продвинутых функций автоматизации","ar":"تعرف على كيفية إعداد Skill Dispatcher، أداة ذكاء اصطناعي للطورين، وتحسين إنتاجيتك باستخدام ميزات تلقائية متقدمة"},"definition":{"en":"skill-dispatcher is a smart skill dispatcher that discovers, matches, and calls skills in the .cursor/features/skills/ directory, enabling adaptive collaboration in AI agents.","zh":"Skill Dispatcher 是一个智能技能调度器，用于发现和调用技能","ja":"Skill Dispatcher は、スキルを発見、匹配、呼び出すための AI エージェント","ko":"Skill Dispatcher 는 기술을 발견하고 호출하는 인공지능 툴의 스마트한 협업 파트너","es":"El skill-dispatcher es un sistema que gestiona la colaboración entre humanos y Agentes de IA en proyectos de desarrollo","fr":"Le skill-dispatcher est un système qui gère la collaboration entre les humains et les Outils d''IA dans les projets de développement","de":"Der skill-dispatcher ist ein System, das die Zusammenarbeit zwischen Menschen und KI-Agenten in Entwicklungsprojekten verwaltet","pt":"O Skill Dispatcher é um mecanismo de inteligência artificial que gerencia a descoberta e o carregamento de habilidades no Cursor Editor","ru":"Skill Dispatcher - это механизм ИИ, который управляет обнаружением и загрузкой навыков в редакторе Cursor","ar":"Skill Dispatcher هو آلیة ذكاء اصطناعي التي تدير اكتشاف وتحميل المهارات في محرر Cursor"},"features":{"en":["Automates skill discovery and loading from .cursor/features/skills/ directory","Supports skill registration via registry.json and flat .md files","Parses skill metadata, including name, description, category, and dependencies","Enables one-click deployment and customizable configuration","Scans skills directory using .cursor/features/skills/*.md files"],"zh":["自动发现和加载项目中的所有可用技能","支持一键部署和个性化配置","实现高效、安全的人机协作体验","技能发现和匹配","调用 `.cursor/features/skills/` 目录中的技能"],"ja":["プロジェクト内のすべての利用可能なスキルを自動で発見、ロード","1 クリックデプロイとカスタマイズ可能な設定をサポート","効率的でセキュアなヒューマンと AI エージェントのコラボレーション体験を実現","スキルの発見とマッチング","`.cursor/features/skills/` ディレクトリ内のスキルを呼び出し"],"ko":["프로젝트 내의 모든 사용 가능한 기술을 자동으로 발견하고 로드","1 클릭 배포 및 사용자 지정 가능한 설정을 지원","효율적이고 안전한 인간과 인공지능 툴의 협업 경험을 제공","기술의 발견 및 일치","`.cursor/features/skills/` 디렉토리 내의 기술을 호출"],"es":["Descubierta automática de habilidades","Carga de habilidades desde el directorio .cursor/features/skills/","Soporte para formato de registro registry.json","Compatibilidad con archivos flat .md","Llamada de habilidades mediante comandos"],"fr":["Découverte automatique de compétences","Chargement de compétences depuis le répertoire .cursor/features/skills/","Prise en charge du format de registre registry.json","Compatibilité avec les fichiers flat .md","Appel de compétences via des commandes"],"de":["Automatische Entdeckung von Fähigkeiten","Laden von Fähigkeiten aus dem Verzeichnis .cursor/features/skills/","Unterstützung für das Registrierungsformat registry.json","Kompatibilität mit flat .md-Dateien","Aufruf von Fähigkeiten über Befehle"],"pt":["Descoberta automática de habilidades","Carregamento de habilidades personalizadas","Suporte a arquivos de registro e metadados","Integração com o Cursor Editor","Recursos de automação avançados"],"ru":["Автоматическое обнаружение навыков","Загрузка пользовательских навыков","Поддержка файлов регистрации и метаданных","Интеграция с редактором Cursor","Продвинутые функции автоматизации"],"ar":["اكتشاف تلقائي للمهارات","تحميل مهارات مخصصة","دعم ملفات التسجيل والبيانات الوصفية","التكامل مع محرر Cursor","ميزات تلقائية متقدمة"]},"keywords":{"en":["how to use skill-dispatcher","what is skill-dispatcher","skill-dispatcher alternative","skill-dispatcher vs cursor","skill-dispatcher install guide","skill-dispatcher setup tutorial","ai agent skill dispatcher","intelligent skill matching","automated skill discovery"],"zh":["Skill Dispatcher","AI 协作","智能技能调度器","自动发现","一键部署","个性化配置","人机协作","Cursor 编辑器"],"ja":["Skill Dispatcher","AI エージェント","スキルディスパッチャー","自動発見","1 クリックデプロイ","カスタマイズ可能な設定","ヒューマンと AI エージェントのコラボレーション","Cursor エディター"],"ko":["Skill Dispatcher","인공지능 툴","스마트한 협업 파트너","자동 발견","1 클릭 배포","사용자 지정 가능한 설정","인간과 인공지능 툴의 협업","Cursor 에디터"],"es":["Agentes de IA","Herramientas de IA","Desarrollo de software","Colaboración entre humanos y Agentes de IA","Skill-dispatcher","Configuración de skill-dispatcher","Guía de configuración de skill-dispatcher"],"fr":["Outils d''IA","Agents d''IA","Développement de logiciels","Collaboration entre les humains et les Outils d''IA","Skill-dispatcher","Configuration de skill-dispatcher","Guide de configuration de skill-dispatcher"],"de":["KI-Agenten","KI-Tools","Softwareentwicklung","Zusammenarbeit zwischen Menschen und KI-Agenten","Skill-dispatcher","Konfiguration von skill-dispatcher","Einrichtungsleitfaden für skill-dispatcher"],"pt":["Skill Dispatcher","Ferramentas de Inteligência Artificial","Desenvolvimento de Software","Automatização de Tarefas","Cursor Editor","Habilidades Personalizadas","Registros e Metadados"],"ru":["Skill Dispatcher","ИИ Агенты","Разработка Программного Обеспечения","Автоматизация Задач","Редактор Cursor","Пользовательские Навыки","Файлы Регистрации и Метаданных"],"ar":["Skill Dispatcher","أدوات ذكاء اصطناعي","طورين البرمجيات","تلقائية المهام","محرر Cursor","المهارات المخصصة","ملفات التسجيل والبيانات الوصفية"]}},"owner":"wangqiqi","repo":"cursor-ai-rules","repoPath":"wangqiqi/cursor-ai-rules","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"skill-dispatcher","description":"Discover, match, and invoke skills from .cursor/features/skills/ directory. Use when user mentions skills, needs to find appropriate skill for a task, or when skill invocation or delegation is required. Automatically reads registry.json for skill metadata and intelligent matching.","bodyPreview":"# Skill Dispatcher\n\n智能技能调度器，用于发现、匹配和调用 `.cursor/features/skills/` 目录中的技能。\n\n> **目录关系**: 本技能位于 `.cursor/skills/`（项目技能，符合 Cursor 标准）；调度的技能库在 `.cursor/features/skills/`（自定义格式：registry.json + flat .md 文件）。\n\n## 核心功能\n\n### 1. 技能发现 (Skill Discovery)\n\n自动发现和加载项目中的所有可用技能。\n\n#### 发现流程\n\n```bash\n# 1. 读取技能注册表\n.cursor/features/skills/registry.json\n\n# 2. 扫描技能目录\n.cursor/features/skills/*.md\n\n# 3. 解析技能元数据\n- name: 技能名称\n- description: 技能描述\n- category: 技能分类\n- dependencies: 依赖关系\n- auto_install: 自动安装标志\n```\n\n#### 发现命令\n\n使用","body":"# Skill Dispatcher\n\n智能技能调度器，用于发现、匹配和调用 `.cursor/features/skills/` 目录中的技能。\n\n> **目录关系**: 本技能位于 `.cursor/skills/`（项目技能，符合 Cursor 标准）；调度的技能库在 `.cursor/features/skills/`（自定义格式：registry.json + flat .md 文件）。\n\n## 核心功能\n\n### 1. 技能发现 (Skill Discovery)\n\n自动发现和加载项目中的所有可用技能。\n\n#### 发现流程\n\n```bash\n# 1. 读取技能注册表\n.cursor/features/skills/registry.json\n\n# 2. 扫描技能目录\n.cursor/features/skills/*.md\n\n# 3. 解析技能元数据\n- name: 技能名称\n- description: 技能描述\n- category: 技能分类\n- dependencies: 依赖关系\n- auto_install: 自动安装标志\n```\n\n#### 发现命令\n\n使用以下模式发现技能：\n\n```\nUser: \"有什么可用的技能？\"\nUser: \"列出所有 skills\"\nUser: \"show me all skills\"\n```\n\n**响应格式**：\n\n```markdown\n## 可用技能列表\n\n### 📊 Development (开发)\n- **api-design**: API设计能力，包括RESTful、GraphQL等\n- **backend-development**: 后端系统设计和开发指导\n- **fullstack-development**: 前后端全栈开发指导\n\n### 🧪 Testing (测试)\n- **api-testing**: 全面的API测试和验证工具\n- **test-automation**: 自动化测试框架和工具\n- **webapp-testing**: 使用Playwright进行Web应用测试\n\n### 🔒 Security (安全)\n- **security-analysis**: 代码安全漏洞检测和修复\n- **vulnerability-scanning**: 安全漏洞扫描和修复建议\n\n... [按分类显示所有技能]\n```\n\n### 2. 技能匹配 (Skill Matching)\n\n智能匹配最适合当前任务的技能。\n\n#### 匹配策略\n\n**优先级顺序**：\n\n1. **关键词匹配** - 检查用户请求中的关键词\n2. **语义匹配** - 理解任务意图\n3. **依赖检查** - 验证技能依赖是否满足\n4. **分类匹配** - 基于任务类型匹配分类\n5. **自动安装** - 优先匹配 `auto_install: true` 的技能\n\n#### 匹配示例\n\n| 用户请求 | 匹配技能 | 匹配理由 |\n|---------|---------|---------|\n| \"设计一个REST API\" | api-design | 关键词: API, REST, 设计 |\n| \"后端性能优化\" | backend-development + optimization-tools | 关键词: 后端, 性能, 优化 |\n| \"写测试用例\" | test-automation | 关键词: 测试, 用例 |\n| \"检查代码安全\" | security-analysis | 关键词: 安全, 检查 |\n\n#### 匹配命令模式\n\n```\nUser: \"我需要 [任务描述]\"\n→ Dispatcher: \"检测到该任务需要 [技能名]，正在调用...\"\n\nUser: \"帮我 [动词] [对象]\"\n→ Dispatcher: \"正在查找匹配的技能...\"\n```\n\n### 3. 技能调用 (Skill Invocation)\n\n加载和执行匹配的技能。\n\n#### 调用流程\n\n```\n1. 读取技能文件 (.cursor/features/skills/[skill-name].md)\n2. 解析技能内容和指令\n3. 验证依赖关系\n4. 应用技能到当前任务\n5. 执行技能定义的工作流\n```\n\n#### 调用语法\n\n```markdown\n## 调用技能: [skill-name]\n\n读取技能文件: `.cursor/features/skills/[skill-name].md`\n\n应用技能指导...\n\n[按照技能的指令执行任务]\n```\n\n#### 技能委托\n\n当任务需要多个技能时：\n\n```markdown\n## 技能组合调用\n\n主要技能: backend-development\n辅助技能: api-design, optimization-tools\n\n执行顺序:\n1. backend-development → 设计整体架构\n2. api-design → 设计API接口\n3. optimization-tools → 性能优化\n```\n\n## 使用指南\n\n### 主动模式\n\n当用户请求技能相关任务时，自动执行：\n\n```markdown\nUser: \"我需要设计一个用户认证系统\"\n\nDispatcher:\n✓ 检测到任务: 用户认证系统设计\n✓ 匹配技能: api-design, security-analysis, backend-development\n✓ 加载技能内容...\n✓ 应用综合指导...\n```\n\n### 被动模式\n\n当用户询问技能信息时：\n\n```markdown\nUser: \"你有什么技能可以帮助我？\"\n\nDispatcher:\n扫描 .cursor/features/skills/ 目录...\n\n发现 30+ 个可用技能，分为以下分类:\n- Development (开发)\n- Testing (测试)\n- Security (安全)\n- ...\n\n需要哪个类别的详细信息？\n```\n\n### 直接调用模式\n\n用户明确指定技能：\n\n```markdown\nUser: \"@skill-dispatcher 调用 backend-development\"\n\nDispatcher:\n正在加载 backend-development 技能...\n读取 .cursor/features/skills/backend-development.md\n✓ 技能已加载，现在可以提供后端开发指导\n```\n\n## 技能分类\n\n从 `registry.json` 读取的技能分类：\n\n### Development (开发)\n- api-design\n- backend-development\n- fullstack-development\n- web-artifacts-builder\n\n### Testing (测试)\n- api-testing\n- test-automation\n- webapp-testing\n\n### Security (安全)\n- security-analysis\n- vulnerability-scanning\n\n### Analysis (分析)\n- code-analysis\n- performance-analysis\n- system-analysis\n\n### Optimization (优化)\n- optimization-tools\n- refactoring-tools\n- ssr-optimization\n\n### Documentation (文档)\n- documentation-tools\n- docx, pdf, pptx, xlsx\n\n### Collaboration (协作)\n- git-management\n\n### Learning (学习)\n- code-examples\n- learning-assistant\n\n## 技能元数据查询\n\n查询特定技能的详细信息：\n\n```markdown\nUser: \"告诉我 api-design 技能的信息\"\n\nDispatcher:\n## 技能: api-design\n\n**名称**: API设计\n**描述**: 专业的API设计能力，包括RESTful、GraphQL等\n**分类**: development\n**自动安装**: 是\n**依赖**: javascript, nodejs\n**文件路径**: .cursor/features/skills/api-design.md\n**来源**: cursor-ai-rules\n\n技能功能:\n- RESTful API 设计\n- GraphQL API 开发\n- 微服务架构设计\n- API 文档生成\n\n需要加载此技能吗？\n```\n\n## 依赖检查\n\n在调用技能前验证依赖：\n\n```markdown\n调用前检查:\n✓ javascript - 已检测到\n✓ nodejs - 已检测到\n✓ 所有依赖满足\n\n正在加载 api-design 技能...\n```\n\n## 技能组合\n\n对于复杂任务，组合多个技能：\n\n```markdown\nUser: \"构建一个完整的Web应用\"\n\nDispatcher 分析:\n任务复杂度: 高\n需要技能组合:\n\n1. **fullstack-development** (主技能)\n   - 提供全栈开发框架\n\n2. **frontend-design** (辅助)\n   - 设计前端界面\n\n3. **backend-development** (辅助)\n   - 构建后端API\n\n4. **api-testing** (验证)\n   - 测试API接口\n\n5. **security-analysis** (安全)\n   - 确保应用安全\n\n正在依次加载和应用这些技能...\n```\n\n## 错误处理\n\n### 技能未找到\n\n```markdown\nDispatcher: ⚠️ 技能 \"nonexistent-skill\" 未找到\n\n可用技能: [列出所有可用技能]\n是否需要相似技能推荐?\n```\n\n### 依赖缺失\n\n```markdown\nDispatcher: ⚠️ 技能 \"api-design\" 需要以下依赖:\n\n缺少: nodejs\n\n建议:\n1. 安装 Node.js\n2. 或选择其他不依赖 nodejs 的技能\n```\n\n### 技能加载失败\n\n```markdown\nDispatcher: ❌ 加载技能失败\n\n文件: .cursor/features/skills/skill-name.md\n错误: [具体错误信息]\n\n建议操作:\n- 检查文件是否存在\n- 验证文件格式\n```\n\n## 最佳实践\n\n### 技能选择原则\n\n1. **优先自动安装** - 优先使用 `auto_install: true` 的技能\n2. **满足依赖** - 确保项目满足技能的依赖要求\n3. **分类匹配** - 根据任务类型选择合适的分类\n4. **组合使用** - 复杂任务可以组合多个技能\n\n### 调用时机\n\n- 用户明确请求某个技能类型\n- 任务描述包含技能关键词\n- 用户询问可用技能列表\n- 需要特定领域的专业知识\n\n### 调用顺序\n\n对于多技能任务：\n\n1. 先调用**主技能**（核心功能）\n2. 再调用**辅助技能**（支持功能）\n3. 最后调用**验证技能**（测试和质量）\n\n## 技能生命周期\n\n```mermaid\ngraph LR\n    A[用户请求] --> B[发现技能]\n    B --> C[匹配技能]\n    C --> D[检查依赖]\n    D --> E{依赖满足?}\n    E -->|是| F[加载技能]\n    E -->|否| G[提示依赖]\n    F --> H[应用技能]\n    H --> I[完成任务]\n    G --> J[安装依赖/选择其他]\n    J --> C\n```\n\n## 相关资源\n\n- **技能注册表**: `.cursor/features/skills/registry.json`\n- **技能目录**: `.cursor/features/skills/`\n- **技能参考**: `.cursor/features/skills/reference/`\n\n---\n\n**版本**: 1.0.0  \n**注册表版本**: 2.0.0  \n**支持的技能数量**: 30+  \n**最后更新**: 2026-02-07\n"},"lastSynced":"2026-03-08T02:08:43.854Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring automated skill discovery and efficient human-machine collaboration.","zh":"适用于像 Cursor、Windsurf 和 Claude Code 这样的 AI Agent，需要自动化技能发现和高效的人机协作。","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに適しています。自動化されたスキル検出と効率的な人間と機械のコラボレーションが必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 자동화된 스킬 발견과 효율적인 인간-기계 협력이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren un descubrimiento de habilidades automatizado y una colaboración eficiente entre humanos y máquinas.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant une découverte de compétences automatisée et une collaboration humain-machine efficace.","de":"Ideal für KI-Agenten wie Cursor, Windsurf und Claude Code, die ein automatisiertes Skill-Discovery und eine effiziente Mensch-Maschine-Kollaboration erfordern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que requerem descoberta de habilidades automatizada e colaboração humano-máquina eficiente.","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих автоматического обнаружения навыков и эффективного сотрудничества человека и машины.","ar":"مثالي للوكلاء الذكية مثل Cursor و Windsurf و Claude Code الذين يتطلبون اكتشاف مهارات أوتوماتيكي وتعاون إنساني-آلي فعال."},"recommendation":{"en":"Empowers agents to automate skill discovery and loading, utilizing registry.json and .md file formats for seamless integration with the .cursor/features/skills/ directory, and supports dependencies and auto-installation flags for streamlined skill management.","zh":"赋予代理人自动化技能发现和加载的能力，利用 registry.json 和 .md 文件格式与 .cursor/features/skills/ 目录实现无缝集成，并支持依赖项和自动安装标志以实现流线型的技能管理。","ja":"エージェントに自動化されたスキル検出とロードの機能を提供します。registry.json と .md ファイル形式を使用して、.cursor/features/skills/ ディレクトリとのシームレスな統合を実現し、依存関係と自動インストール フラグをサポートして、スキル管理をストリームライン化します。","ko":"에이전트에게 자동화된 스킬 발견과 로딩의 기능을 제공합니다. registry.json과 .md 파일 형식을 사용하여 .cursor/features/skills/ 디렉토리와의 무결점 통합을 구현하며, 의존성과 자동 설치 플래그를 지원하여 스킬 관리를 스트림라인화합니다.","es":"Permite a los agentes automatizar el descubrimiento de habilidades y la carga, utilizando los formatos de archivo registry.json y .md para una integración sin problemas con el directorio .cursor/features/skills/, y admite dependencias y flags de instalación automática para una gestión de habilidades optimizada.","fr":"Permet aux agents d''automatiser la découverte de compétences et de chargement, en utilisant les formats de fichier registry.json et .md pour une intégration transparente avec le répertoire .cursor/features/skills/, et prend en charge les dépendances et les flags d''installation automatique pour une gestion de compétences rationalisée.","de":"Ermöglicht es Agenten, das Skill-Discovery und die Ladefunktion zu automatisieren, indem es die Dateiformate registry.json und .md für eine nahtlose Integration mit dem Verzeichnis .cursor/features/skills/ nutzt und Abhängigkeiten und Auto-Installationsflags für eine optimierte Skill-Verwaltung unterstützt.","pt":"Habilita os agentes a automatizar a descoberta e o carregamento de habilidades, utilizando os formatos registry.json e .md para integração perfeita com o diretório .cursor/features/skills/ e suporta dependências e flags de instalação automática para gerenciamento de habilidades otimizado.","ru":"Предоставляет агентам возможность автоматизировать обнаружение и загрузку навыков, используя форматы registry.json и .md для бесшовной интеграции с директорием .cursor/features/skills/ и поддерживает зависимости и флаги автоустановки для оптимизированного управления навыками.","ar":"تمكّن الوكلاء من تلقين اكتشاف المهارات وتحميلها، باستخدام صيغ registry.json و .md من أجل التكامل السلس مع الدليل .cursor/features/skills/ ودعم للاتكاءات وflags للتثبيت التلقائي من أجل إدارة المهارات المتدفقة."},"useCases":{"en":["Automating skill discovery in large-scale AI projects","Streamlining human-machine collaboration through efficient skill matching","Loading and managing skills with dependencies and auto-installation flags"],"zh":["在大型 AI 项目中自动化技能发现","通过高效的技能匹配实现人机协作的流线化","加载和管理具有依赖项和自动安装标志的技能"],"ja":["大規模な AI プロジェクトでスキル検出を自動化する","効率的なスキルマッチングを通じて人間と機械のコラボレーションをストリームライン化する","依存関係と自動インストール フラグを備えたスキルをロードして管理する"],"ko":["대규모 AI 프로젝트에서 스킬 발견을 자동화하는 것","효율적인 스킬 매칭을 통해 인간-기계 협력을 스트림라인화하는 것","의존성과 자동 설치 플래그를 갖춘 스킬을 로딩하고 관리하는 것"],"es":["Automatizar el descubrimiento de habilidades en proyectos de IA a gran escala","Optimizar la colaboración entre humanos y máquinas a través de un emparejamiento de habilidades eficiente","Cargar y gestionar habilidades con dependencias y flags de instalación automática"],"fr":["Automatiser la découverte de compétences dans les projets d''IA à grande échelle","Rationaliser la collaboration humain-machine grâce à un appariement de compétences efficace","Charger et gérer des compétences avec des dépendances et des flags d''installation automatique"],"de":["Automatisieren des Skill-Discoverys in großen KI-Projekten","Optimieren der Mensch-Maschine-Kollaboration durch effizientes Skill-Matching","Laden und Verwalten von Skills mit Abhängigkeiten und Auto-Installationsflags"],"pt":["Automatizar a descoberta de habilidades em projetos de IA em larga escala","Otimizar a colaboração humano-máquina por meio de correspondência de habilidades eficiente","Carregar e gerenciar habilidades com dependências e flags de instalação automática"],"ru":["Автоматизировать обнаружение навыков в крупномасштабных проектах ИИ","Оптимизировать сотрудничество человека и машины за счет эффективного соответствия навыков","Загружать и управлять навыками с зависимостями и флагами автоустановки"],"ar":["تلقين اكتشاف المهارات في مشاريع الذكاء الاصطناعي على نطاق واسع","تحسين التعاون بين الإنسان والآلة من خلال مطابقة المهارات الفعالة","تحميل وإدارة المهارات مع الاعتماديات وflags للتثبيت التلقائي"]},"limitations":{"en":["Requires access to the .cursor/features/skills/ directory","Dependent on registry.json and .md file formats for skill discovery","Limited to skills registered in the registry.json file"],"zh":["需要访问 .cursor/features/skills/ 目录","依赖于 registry.json 和 .md 文件格式进行技能发现","仅限于在 registry.json 文件中注册的技能"],"ja":[".cursor/features/skills/ ディレクトリへのアクセスが必要","スキル検出には registry.json と .md ファイル形式に依存","registry.json ファイルに登録されたスキルに限定"],"ko":[".cursor/features/skills/ 디렉토리への 액세스가 필요합니다","스킬 발견에는 registry.json과 .md 파일 형식에 의존합니다","registry.json 파일에 등록된 스킬로 제한됩니다"],"es":["Requiere acceso al directorio .cursor/features/skills/","Depende de los formatos de archivo registry.json y .md para el descubrimiento de habilidades","Limitado a habilidades registradas en el archivo registry.json"],"fr":["Nécessite un accès au répertoire .cursor/features/skills/","Dépend des formats de fichier registry.json et .md pour la découverte de compétences","Limité aux compétences enregistrées dans le fichier registry.json"],"de":["Benötigt Zugriff auf das Verzeichnis .cursor/features/skills/","Hängt von den Dateiformaten registry.json und .md für das Skill-Discovery ab","Begrenzt auf Skills, die im registry.json-Datei registriert sind"],"pt":["Requer acesso ao diretório .cursor/features/skills/","Depende dos formatos registry.json e .md para descoberta de habilidades","Limitado às habilidades registradas no arquivo registry.json"],"ru":["Требует доступа к директорию .cursor/features/skills/","Зависит от форматов registry.json и .md для обнаружения навыков","Ограничен навыками, зарегистрированными в файле registry.json"],"ar":["يتطلب الوصول إلى الدليل .cursor/features/skills/","يعتمد على صيغ registry.json و .md من أجل اكتشاف المهارات","محدود بالمehارات المسجلة في ملف registry.json"]},"version":4},"contentHash":"8e7d24baee842952a7545f47aa9ebd8a2ede5895ea85623a33fe5d5e93a15d40","qualityScore":36}');
