INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wangqiqi/cursor-ai-rules/skill-dispatcher', 'skill-dispatcher', 'wangqiqi', 'cursor-ai-rules', 'community', 'skill-dispatcher wangqiqi cursor-ai-rules community The skill-dispatcher skill provides an intelligent framework for discovering and matching skills in AI agents, supporting efficient human-machine collaboration. It benefits developers by automating skill discovery and loading. Skill Dispatcher 是一个智能技能调度器，用于发现、匹配和调用技能，实现高效的 AI 协作体验 Skill Dispatcher は、スキルを自動で発見、匹配、呼び出し、AI エージェントとの協業を最適化する Skill Dispatcher 는 인공지능 툴의 스마트한 협업 파트너로, 기술을 자동으로 발견, 일치 및 호출하여 효율적인 협업 경험을 제공합니다 El skill-dispatcher es un sistema de colaboración de IA que permite la descubierta y llamada de habilidades en proyectos de desarrollo Le skill-dispatcher est un système de collaboration d''IA qui permet la découverte et l''appel de compétences dans les projets de développement Der skill-dispatcher ist ein KI-Kollaborationssystem, das die Entdeckung und den Aufruf von Fähigkeiten in Entwicklungsprojekten ermöglicht O Skill Dispatcher é uma ferramenta de inteligência artificial que automatiza a descoberta e o carregamento de habilidades no Cursor Editor Skill Dispatcher - это инструмент ИИ, который автоматизирует обнаружение и загрузку навыков в редакторе Cursor Skill Dispatcher هو أداة ذكاء اصطناعي التي تautomatiza اكتشاف وتحميل المهارات في محرر Cursor how to use skill-dispatcher what is skill-dispatcher skill-dispatcher alternative skill-dispatcher vs cursor skill-dispatcher install guide skill-dispatcher setup tutorial ai agent skill dispatcher intelligent skill matching automated skill discovery Skill Dispatcher AI 协作 智能技能调度器 自动发现 一键部署 个性化配置 人机协作 Cursor 编辑器 Automates skill discovery and loading from .cursor/features/skills/ directory Supports skill registration via registry.json and flat .md files Parses skill metadata, including name, description, category, and dependencies Enables one-click deployment and customizable configuration Scans skills directory using .cursor/features/skills/*.md files skill-dispatcher is a smart skill dispatcher that discovers, matches, and calls skills in the .cursor/features/skills/ directory, enabling adaptive collaboration in AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SETI/rms-cloud-tasks/run-all-checks', 'community', 'SETI', 'rms-cloud-tasks', 'SETI/rms-cloud-tasks', 'run-all-checks', 0, 0, 36, '2026-03-08T01:57:15.444Z', '2026-03-08T02:08:51.622Z', '196bfeaafbeac006e99806cf6418ea6f2b0de1ac2b029d9d39f8aaf2ae05c0d1', '{"id":"SETI/rms-cloud-tasks/run-all-checks","name":"run-all-checks","description":{"en":"The run-all-checks skill automates project validation by executing checks like ruff, mypy, pytest, and Sphinx docs, benefiting developers by streamlining error detection and fixing.","zh":"Run All Checks 脚本用于执行项目的所有检查，包括 ruff、mypy、pytest 和 Sphinx 文档，并自动修复错误","ja":"Run All Checks スクリプトは、プロジェクトのすべての检查を実行します。ruff、mypy、pytest、Sphinx ドキュメントを含み、自動でエラーを修復します","ko":"Run All Checks 스크립트는 프로젝트의 모든 검사를 실행합니다. ruff, mypy, pytest, Sphinx 문서를 포함하여 자동으로 오류를 수정합니다","es":"El script run-all-checks ejecuta todas las comprobaciones de proyecto, incluyendo ruff, mypy, pytest y Sphinx docs, y soluciona errores encontrados","fr":"Le script run-all-checks exécute toutes les vérifications de projet, y compris ruff, mypy, pytest et Sphinx docs, et résout les erreurs trouvées","de":"Das Skript run-all-checks führt alle Projektprüfungen aus, einschließlich ruff, mypy, pytest und Sphinx docs, und behebt gefundenen Fehler","pt":"O run-all-checks é uma ferramenta que executa todos os testes do projeto, incluindo ruff, mypy, pytest e Sphinx docs, e corrige erros","ru":"Run-all-checks - это инструмент, который запускает все проверки проекта, включая ruff, mypy, pytest и Sphinx docs, и исправляет ошибки","ar":"run-all-checks هو أداة تشغل جميع الفحوصات لمشروعك، بما في ذلك ruff و mypy و pytest و Sphinx docs، وتصلح الأخطاء"},"seo":{"title":{"en":"run-all-checks: Automated Project Validation Setup Guide ...","zh":"运行所有检查的设置指南 - Run All Checks","ja":"全てのチェックを実行するためのベストプラクティス - Run All Checks AIエージェント","ko":"모든 검사 실행 가이드 - Run All Checks AI 도구","es":"Guía de configuración de run-all-checks para desarrolladores","fr":"Guide d''installation de run-all-checks pour les développeurs","de":"Einrichtungsanleitung für run-all-checks für Entwickler","pt":"Guia de Configuração do run-all-checks: Executando Todos ...","ru":"ИИ Агенты: Руководство по Настройке run-all-checks для За...","ar":"دليل إعداد run-all-checks: تشغيل جميع الفحوصات مع أدوات ا..."},"description":{"en":"Discover how to automate project checks with run-all-checks. Learn to execute ruff, mypy, pytest, and Sphinx docs with ease. Get started now!","zh":"学习如何使用 Run All Checks 脚本执行项目检查，包括 ruff、mypy、pytest 和 Sphinx 文档，并修复错误","ja":"Run All Checks スクリプトを使用してプロジェクトの检查を実行する方法を学びます。ruff、mypy、pytest、Sphinx ドキュメントを含み、エラーを修復します","ko":"Run All Checks 스크립트를 사용하여 프로젝트 검사 실행 방법을 배우세요. ruff, mypy, pytest, Sphinx 문서 포함, 오류 수정","es":"Aprende a ejecutar todas las comprobaciones de proyecto con run-all-checks y a solucionar errores con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment exécuter toutes les vérifications de projet avec run-all-checks et résoudre les erreurs avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie alle Projektprüfungen mit run-all-checks ausführen und Fehler beheben können, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a executar todos os testes do seu projeto com o run-all-checks, incluindo ruff, mypy, pytest e Sphinx docs","ru":"Запустите все проверки вашего проекта с помощью run-all-checks, включая ruff, mypy, pytest и Sphinx docs, и исправьте ошибки","ar":"تعلم كيف تشغل جميع الفحوصات لمشروعك مع run-all-checks، بما في ذلك ruff و mypy و pytest و Sphinx docs"},"definition":{"en":"run-all-checks is a skill that automates the execution of various project checks, including ruff, mypy, pytest, and Sphinx docs, to identify and fix errors.","zh":"Run All Checks 是一个脚本，用于执行项目的所有检查，包括代码检查和文档检查","ja":"Run All Checks は、プロジェクトのすべての检查を実行するスクリプトです。コード检查とドキュメント检查を含みます","ko":"Run All Checks는 프로젝트의 모든 검사를 실행하는 스크립트입니다. 코드 검사와 문서 검사를 포함합니다","es":"Run-all-checks es un script que ejecuta todas las comprobaciones de proyecto y soluciona errores","fr":"Run-all-checks est un script qui exécute toutes les vérifications de projet et résout les erreurs","de":"Run-all-checks ist ein Skript, das alle Projektprüfungen ausführt und Fehler behebt","pt":"O run-all-checks é uma ferramenta de teste que executa todas as verificações de um projeto","ru":"Run-all-checks - это инструмент проверки, который запускает все проверки проекта","ar":"run-all-checks هو أداة فحص تشغل جميع الفحوصات لمشروعك"},"features":{"en":["Executes ruff for code quality checks","Runs mypy for static type checking","Integrates pytest for unit testing","Generates and checks Sphinx documentation","Supports parallel execution with the --parallel option","Provides a script-based approach for ease of use"],"zh":["执行 ruff、mypy、pytest 和 Sphinx 文档检查","自动修复错误","支持并行执行检查","使用脚本执行检查","支持从项目根目录执行检查"],"ja":["ruff、mypy、pytest、Sphinx ドキュメントの检查を実行","エラーを自動で修復","並行実行のサポート","スクリプトを使用して检查を実行","プロジェクトルートディレクトリから检查を実行するサポート"],"ko":["ruff, mypy, pytest, Sphinx 문서의 검사를 실행","오류를 자동으로 수정","병렬 실행 지원","스크립트를 사용하여 검사를 실행","프로젝트 루트 디렉토리에서 검사를 실행하는 지원"],"es":["Ejecuta comprobaciones de código con ruff y mypy","Ejecuta pruebas unitarias con pytest","Genera documentación con Sphinx docs","Soluciona errores encontrados","Permite la ejecución en paralelo con la opción --parallel"],"fr":["Exécute les vérifications de code avec ruff et mypy","Exécute les tests unitaires avec pytest","Génère la documentation avec Sphinx docs","Résout les erreurs trouvées","Permet l''exécution en parallèle avec l''option --parallel"],"de":["Führt Code-Prüfungen mit ruff und mypy aus","Führt Einheitstests mit pytest aus","Erstellt Dokumentation mit Sphinx docs","Behebt gefundenen Fehler","Ermöglicht die Ausführung in Parallel mit der Option --parallel"],"pt":["Executa todos os testes do projeto, incluindo ruff, mypy, pytest e Sphinx docs","Corrige erros e avisa sobre warnings","Permite executar testes em paralelo com a opção --parallel","Pode ser executado a partir do diretório raiz do projeto com venv ativado","Fornece saída detalhada para revisão e depuração"],"ru":["Запускает все проверки проекта, включая ruff, mypy, pytest и Sphinx docs","Исправляет ошибки и предупреждает о warnings","Позволяет запускать проверки в параллели с помощью опции --parallel","Может быть запущен из корневого каталога проекта с активированным venv","Предоставляет подробный вывод для рассмотрения и отладки"],"ar":["تشغل جميع الفحوصات لمشروعك، بما في ذلك ruff و mypy و pytest و Sphinx docs","تصلح الأخطاء وتحذر من تحذيرات","تسمح بتشغيل الفحوصات بالتوازي مع خيار --parallel","يمكن تشغيلها من دليل الجذر للمشروع مع تفعيل venv","توفر إخراج مفصل لمراجعة وتصحيح الأخطاء"]},"keywords":{"en":["how to use run-all-checks","run-all-checks setup guide","run-all-checks vs manual checking","install run-all-checks","run-all-checks for Python projects","automated project validation with run-all-checks","run-all-checks tutorial","run-all-checks best practices"],"zh":["Run All Checks","AI工具","代码检查","文档检查","ruff","mypy","pytest","Sphinx","自动修复错误"],"ja":["Run All Checks","AIエージェント","コード检查","ドキュメント检查","ruff","mypy","pytest","Sphinx","エラーを自動で修復"],"ko":["Run All Checks","AI 도구","코드 검사","문서 검사","ruff","mypy","pytest","Sphinx","오류를 자동으로 수정"],"es":["run-all-checks","herramientas de desarrollo","comprobaciones de proyecto","ruff","mypy","pytest","Sphinx docs","desarrollo de software","pruebas unitarias"],"fr":["run-all-checks","outils de développement","vérifications de projet","ruff","mypy","pytest","Sphinx docs","développement de logiciels","tests unitaires"],"de":["run-all-checks","Entwicklertools","Projektprüfungen","ruff","mypy","pytest","Sphinx docs","Software-Entwicklung","Einheitstests"],"pt":["run-all-checks","testes de projeto","ruff","mypy","pytest","Sphinx docs","executar testes em paralelo","corrigir erros","ferramentas de teste"],"ru":["run-all-checks","проверки проекта","ruff","mypy","pytest","Sphinx docs","запускать проверки в параллели","исправлять ошибки","инструменты проверки"],"ar":["run-all-checks","فحوصات مشروع","ruff","mypy","pytest","Sphinx docs","تشغيل الفحوصات بالتوازي","تصحيح الأخطاء","أدوات الفحص"]}},"owner":"SETI","repo":"rms-cloud-tasks","repoPath":"SETI/rms-cloud-tasks","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.444Z","topics":[],"category":"community","skillMd":{"name":"run-all-checks","description":"Run all linting, type checking, tests, and documentation builds for the rms-cloud-tasks project. Check for errors and warnings, then fix any problems found. Use when the user asks to run checks, verify the build, run CI locally, or fix lint/type/test errors.","bodyPreview":"# Run All Checks\n\nExecute all project checks (ruff, mypy, pytest, Sphinx docs) and fix any errors found.\n\n## Quick Start\n\nRun all checks and fix errors:\n\n1. Execute the run-all-checks script (or run checks manually).\n2. Review output for errors and warnings.\n3. Fix any issues found.\n4. Re-run checks to verify fixes.\n\n## Preferred Method: Script\n\nFrom project root with venv activated:\n\n```bash\n./scripts/run-all-checks.sh\n```\n\nOptions:\n\n- `-p, --parallel` — Run code checks and docs in parallel (de","body":"# Run All Checks\n\nExecute all project checks (ruff, mypy, pytest, Sphinx docs) and fix any errors found.\n\n## Quick Start\n\nRun all checks and fix errors:\n\n1. Execute the run-all-checks script (or run checks manually).\n2. Review output for errors and warnings.\n3. Fix any issues found.\n4. Re-run checks to verify fixes.\n\n## Preferred Method: Script\n\nFrom project root with venv activated:\n\n```bash\n./scripts/run-all-checks.sh\n```\n\nOptions:\n\n- `-p, --parallel` — Run code checks and docs in parallel (default).\n- `-s, --sequential` — Run all checks one after another (easier to debug).\n- `-c, --code` — Only ruff, mypy, pytest.\n- `-d, --docs` — Only Sphinx documentation build.\n- `-h, --help` — Show usage.\n\n## Check Commands (Manual)\n\nAll commands assume project root and `source venv/bin/activate` (or `venv\\Scripts\\activate` on Windows).\n\n### Code (from project root)\n\n```bash\n# Lint (ruff)\npython -m ruff check src tests examples\npython -m ruff format --check src tests examples\n\n# Type check (mypy)\npython -m mypy src tests examples\n\n# Tests (pytest)\npython -m pytest tests -q\n```\n\n### Documentation (from project root)\n\n```bash\ncd docs && make clean && make html SPHINXOPTS=\"-W\"\n```\n\nThe script and docs build use `SPHINXOPTS=\"-W\"` so Sphinx treats warnings as errors; the docs check fails if any warnings are produced.\n\n## Execution Workflow\n\nCopy this checklist and track progress:\n\n```text\nCheck Progress:\n- [ ] Ruff check (src, tests, examples)\n- [ ] Ruff format --check\n- [ ] Mypy (src, tests, examples)\n- [ ] Pytest (tests)\n- [ ] Docs build without warnings\n- [ ] All errors fixed\n- [ ] Re-verify all checks pass\n```\n\n### Step 1: Run All Checks\n\n**Option A – Script (recommended):**\n\n```bash\n./scripts/run-all-checks.sh\n```\n\n**Option B – Sequential manual:**\n\n```bash\nsource venv/bin/activate\npython -m ruff check src tests examples && \\\npython -m ruff format --check src tests examples && \\\npython -m mypy src tests examples && \\\npython -m pytest tests -q && \\\n(cd docs && make clean && make html SPHINXOPTS=\"-W\")\n```\n\n### Step 2: Analyze Results\n\nCheck output for:\n\n- **Errors**: Must be fixed (non-zero exit code).\n- **Warnings**: Must be fixed. The docs build is run with `SPHINXOPTS=\"-W\"`, so Sphinx warnings cause the documentation check to fail.\n\nCommon error types:\n\n| Check   | Error Pattern              | Typical Fix                          |\n|---------|----------------------------|--------------------------------------|\n| ruff    | `F401` unused import       | Remove import                        |\n| ruff    | `UP035` typing import      | Use `collections.abc` for ABCs       |\n| ruff    | `ARG001` unused argument   | Prefix with `_` or `# noqa: ARG001`  |\n| mypy    | `error: ... is not defined` | Add import or fix typo               |\n| mypy    | `assignment`, `attr-defined` | Add type annotations or `# type: ignore[...]` |\n| pytest  | `FAILED` or `ERROR`        | Fix test or code under test          |\n| sphinx  | `WARNING: duplicate object`| Add `:no-index:` or fix duplicate    |\n\n### Step 3: Fix Issues\n\nFor each error:\n\n1. Read the error message and file/line.\n2. Open the file and apply the appropriate fix.\n3. Re-run the failing check to confirm.\n\n### Step 4: Re-verify\n\nAfter fixing, run all checks again:\n\n```bash\n./scripts/run-all-checks.sh\n```\n\nAll checks should pass with exit code 0.\n\n## Common Fixes Reference\n\n### Ruff Unused Argument (ARG001)\n\nFor pytest fixtures that are dependencies but not directly used:\n\n```python\ndef my_fixture(other_fixture: None) -> None:  # noqa: ARG001\n    ...\n```\n\n### Ruff UP035 (typing → collections.abc)\n\nUse `collections.abc` for `AsyncGenerator`, `Iterable`, etc.:\n\n```python\nfrom collections.abc import AsyncGenerator, Iterable\n```\n\n### Sphinx Duplicate Object Warning\n\nAdd `:no-index:` to automodule directive:\n\n```rst\n.. automodule:: cloud_tasks.config\n   :members:\n   :no-index:\n```\n\n### Mypy in Tests\n\nTests use overrides in `pyproject.toml` (`module = \"tests.*\"`) for `method-assign` and `attr-defined` (mocks). For other mypy errors in tests, add targeted `# type: ignore[code]` or fix the type.\n\n### Type Annotation Errors\n\nFor union or forward-reference issues:\n\n```python\nfrom __future__ import annotations  # Add at top of file\n```\n\n## Success Criteria\n\nAll checks pass when:\n\n- `ruff check src tests examples` → \"All checks passed!\"\n- `ruff format --check src tests examples` → \"All files formatted\"\n- `mypy src tests examples` → \"Success: no issues found\"\n- `pytest tests -q` → All tests pass\n- `make html SPHINXOPTS=\"-W\"` (in docs/) → Build completes with exit 0 (no errors or warnings)\n"},"lastSynced":"2026-03-08T02:08:51.622Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing comprehensive project validation and automated error detection.","zh":"适用于需要全面项目验证和自动错误检测的代码审查代理。","ja":"コードレビュー代理が包括的なプロジェクト検証と自動エラーディテクションを必要とする場合に最適です。","ko":"전체 프로젝트 검증 및 자동 오류 감지 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan una validación de proyecto integral y una detección automática de errores.","fr":"Parfait pour les agents de révision de code nécessitant une validation de projet complète et une détection automatique d''erreurs.","de":"Perfekt für Code-Review-Agents, die eine umfassende Projekvalidierung und eine automatische Fehlererkennung benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de validação de projeto abrangente e detecção de erros automatizada.","ru":"Идеально подходит для агентов код-ревью, которым необходима комплексная проверка проекта и автоматическое обнаружение ошибок.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى التحقق الشامل من المشروع والكشف التلقائي عن الأخطاء."},"recommendation":{"en":"Empowers agents to streamline error detection and fixing by executing checks like ruff, mypy, pytest, and Sphinx docs, providing a robust project validation workflow using Python and shell scripts.","zh":"使代理能够通过执行ruff、mypy、pytest和Sphinx文档等检查来简化错误检测和修复，提供使用Python和shell脚本的强大的项目验证工作流。","ja":"ruff、mypy、pytest、Sphinxドキュメントなどのチェックを実行することで、エージェントがエラーディテクションと修復を最適化できるようにし、Pythonとシェルスクリプトを使用した堅牢なプロジェクト検証ワークフローを提供します。","ko":"ruff, mypy, pytest 및 Sphinx 문서 등의 검사를 실행하여 에이전트가 오류 감지 및 수정을 최적화할 수 있도록 하며, Python 및 셸 스크립트를 사용한 강력한 프로젝트 검증 워크플로를 제공합니다.","es":"Habilita a los agentes a simplificar la detección y corrección de errores mediante la ejecución de comprobaciones como ruff, mypy, pytest y Sphinx docs, proporcionando un flujo de trabajo robusto de validación de proyectos utilizando Python y scripts de shell.","fr":"Permet aux agents de rationaliser la détection et la correction des erreurs en exécutant des vérifications comme ruff, mypy, pytest et Sphinx docs, fournissant un flux de travail robuste de validation de projets en utilisant Python et des scripts shell.","de":"Ermächtigt die Agenten, die Fehlererkennung und -behebung durch die Ausführung von Prüfungen wie ruff, mypy, pytest und Sphinx-Docs zu rationalisieren, wodurch ein robuster Workflow für die Projekvalidierung unter Verwendung von Python und Shell-Skripten bereitgestellt wird.","pt":"Habilita os agentes a simplificar a detecção e correção de erros executando verificações como ruff, mypy, pytest e Sphinx docs, fornecendo um fluxo de trabalho de validação de projeto robusto usando Python e scripts de shell.","ru":"Позволяет агентам оптимизировать обнаружение и исправление ошибок, выполняя проверки, такие как ruff, mypy, pytest и Sphinx docs, обеспечивая надежный рабочий процесс проверки проекта с использованием Python и сценариев командной строки.","ar":"تمكين العميل من简ification الكشف عن الأخطاء وإصلاحها من خلال تنفيذ الفحوصات مثل ruff و mypy و pytest و Sphinx docs، وتوفير تدفق عمل التحقق من المشروع القوي باستخدام Python وسكريبتات Shell."},"useCases":{"en":["Automating project validation with ruff and mypy","Debugging code issues with pytest","Generating and validating Sphinx documentation"],"zh":["使用ruff和mypy进行项目自动验证","使用pytest进行代码问题调试","生成和验证Sphinx文档"],"ja":["ruffとmypyを使用したプロジェクト自動検証","pytestを使用したコード問題のデバッグ","Sphinxドキュメントの生成と検証"],"ko":["ruff 및 mypy를 사용한 프로젝트 자동 검증","pytest를 사용한 코드 문제 디버깅","Sphinx 문서 생성 및 검증"],"es":["Automatización de la validación de proyectos con ruff y mypy","Depuración de problemas de código con pytest","Generación y validación de la documentación de Sphinx"],"fr":["Automatisation de la validation de projets avec ruff et mypy","Débogage des problèmes de code avec pytest","Génération et validation de la documentation Sphinx"],"de":["Automatisierung der Projekvalidierung mit ruff und mypy","Fehlerbehebung von Codeproblemen mit pytest","Erzeugung und Validierung von Sphinx-Dokumentation"],"pt":["Automatizar a validação do projeto com ruff e mypy","Depurar problemas de código com pytest","Gerar e validar documentação Sphinx"],"ru":["Автоматизировать проверку проекта с помощью ruff и mypy","Отладить проблемы с кодом с помощью pytest","Генерировать и проверять документацию Sphinx"],"ar":["التنفيذ الآلي للتحقق من المشروع مع ruff و mypy","تصحيح مشاكل الشفرة باستخدام pytest","توليد وتحقق وثائق Sphinx"]},"limitations":{"en":["Requires Python environment with necessary libraries installed","Limited to projects using ruff, mypy, pytest, and Sphinx"],"zh":["需要安装必要库的Python环境","仅限使用ruff、mypy、pytest和Sphinx的项目"],"ja":["必要なライブラリがインストールされたPython環境が必要","ruff、mypy、pytest、Sphinxを使用するプロジェクトに限定される"],"ko":["필요한 라이브러리가 설치된 Python 환경이 필요","ruff, mypy, pytest 및 Sphinx를 사용하는 프로젝트로 제한됨"],"es":["Requiere un entorno de Python con bibliotecas necesarias instaladas","Limitado a proyectos que utilizan ruff, mypy, pytest y Sphinx"],"fr":["Nécessite un environnement Python avec des bibliothèques nécessaires installées","Limité aux projets utilisant ruff, mypy, pytest et Sphinx"],"de":["Benötigt eine Python-Umgebung mit notwendigen Bibliotheken installiert","Begrenzt auf Projekte, die ruff, mypy, pytest und Sphinx verwenden"],"pt":["Requer ambiente Python com bibliotecas necessárias instaladas","Limitado a projetos que usam ruff, mypy, pytest e Sphinx"],"ru":["Требуется среда Python с установленными необходимыми библиотеками","Ограничен для проектов, использующих ruff, mypy, pytest и Sphinx"],"ar":["يتطلب بيئة Python مع المكتبات الضرورية المثبتة","محدود لمشاريع التي تستخدم ruff و mypy و pytest و Sphinx"]},"version":4},"contentHash":"196bfeaafbeac006e99806cf6418ea6f2b0de1ac2b029d9d39f8aaf2ae05c0d1","qualityScore":36}');
