INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SETI/rms-cloud-tasks/run-all-checks', 'run-all-checks', 'SETI', 'rms-cloud-tasks', 'community', 'run-all-checks SETI rms-cloud-tasks community The run-all-checks skill automates project validation by executing checks like ruff, mypy, pytest, and Sphinx docs, benefiting developers by streamlining error detection and fixing. Run All Checks 脚本用于执行项目的所有检查，包括 ruff、mypy、pytest 和 Sphinx 文档，并自动修复错误 Run All Checks スクリプトは、プロジェクトのすべての检查を実行します。ruff、mypy、pytest、Sphinx ドキュメントを含み、自動でエラーを修復します Run All Checks 스크립트는 프로젝트의 모든 검사를 실행합니다. ruff, mypy, pytest, Sphinx 문서를 포함하여 자동으로 오류를 수정합니다 El script run-all-checks ejecuta todas las comprobaciones de proyecto, incluyendo ruff, mypy, pytest y Sphinx docs, y soluciona errores encontrados Le script run-all-checks exécute toutes les vérifications de projet, y compris ruff, mypy, pytest et Sphinx docs, et résout les erreurs trouvées Das Skript run-all-checks führt alle Projektprüfungen aus, einschließlich ruff, mypy, pytest und Sphinx docs, und behebt gefundenen Fehler O run-all-checks é uma ferramenta que executa todos os testes do projeto, incluindo ruff, mypy, pytest e Sphinx docs, e corrige erros Run-all-checks - это инструмент, который запускает все проверки проекта, включая ruff, mypy, pytest и Sphinx docs, и исправляет ошибки run-all-checks هو أداة تشغل جميع الفحوصات لمشروعك، بما في ذلك ruff و mypy و pytest و Sphinx docs، وتصلح الأخطاء how to use run-all-checks run-all-checks setup guide run-all-checks vs manual checking install run-all-checks run-all-checks for Python projects automated project validation with run-all-checks run-all-checks tutorial run-all-checks best practices Run All Checks AI工具 代码检查 文档检查 ruff mypy pytest Sphinx 自动修复错误 Executes ruff for code quality checks Runs mypy for static type checking Integrates pytest for unit testing Generates and checks Sphinx documentation Supports parallel execution with the --parallel option Provides a script-based approach for ease of use run-all-checks is a skill that automates the execution of various project checks, including ruff, mypy, pytest, and Sphinx docs, to identify and fix errors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdorfman/www/add-video', 'community', 'jdorfman', 'www', 'jdorfman/www', 'add-video', 0, 0, 36, '2026-03-08T01:57:15.445Z', '2026-03-08T02:08:53.543Z', 'da47f905a0d571ddff00c6361be4e1d7999b6c4e861cea7fddddce6f5591fc80', '{"id":"jdorfman/www/add-video","name":"add-video","description":{"en":"The add-video skill allows developers to add YouTube videos to their personal website by extracting video IDs and fetching video titles using the YouTube oEmbed API. This skill benefits web developers and AI agent users.","zh":"使用YouTube oEmbed API和视频ID添加视频到个人网站，实现动态内容更新","ja":"AIエージェントを使用して動画を追加し、個人サイトのコンテンツを強化する","ko":"YouTube oEmbed API와 비디오 ID를 사용하여 개인 웹사이트에 동적 비디오 내용을 추가합니다","es":"Add-video es una habilidad que te permite agregar videos a tu sitio web personal. Extrae IDs de video de YouTube y obtén títulos de video con la API oEmbed","fr":"Add-video est une fonctionnalité qui vous permet d''ajouter des vidéos à votre site web personnel. Extrayez les IDs de vidéo YouTube et obtenez les titres de vidéo avec l''API oEmbed","de":"Add-video ist eine Fähigkeit, die es Ihnen ermöglicht, Videos zu Ihrer persönlichen Website hinzuzufügen. Extrahieren Sie Video-IDs von YouTube und erhalten Sie Video-Titel mit der oEmbed-API","pt":"O Add-Video permite que você adicione vídeos ao seu portfólio de forma fácil, utilizando a API do YouTube para extrair o título do vídeo","ru":"Add-Video позволяет легко добавлять видео в портфолио, используя API YouTube для извлечения названия видео","ar":"يسمح Add-Video بإضافة الفيديوهات إلى موقعك الشخصي بسهولة، باستخدام واجهة برمجة تطبيقات YouTube لاستخراج عنوان الفيديو"},"seo":{"title":{"en":"add-video: YouTube Video Integration Setup Guide | AI Age...","zh":"添加视频到个人网站的设置指南","ja":"AIエージェントを使用した動画追加のベストプラクティス","ko":"개인 웹사이트에 비디오 추가하기 위한 개발자 가이드","es":"Guía de configuración de add-video para sitios web person...","fr":"Configurer add-video pour les sites web personnels - Guid...","de":"Add-video Einrichtungsleitfaden für persönliche Websites","pt":"Guia de Configuração do Add-Video para Desenvolvedores","ru":"Настройка ИИ Агентов: Руководство по Add-Video","ar":"إضافة الفيديو إلى الموقع الشخصي: دليل الإعداد"},"description":{"en":"Discover how to integrate YouTube videos into your personal website using the add-video AI agent skill - learn how to extract video IDs and fetch video title...","zh":"了解如何使用YouTube oEmbed API和视频ID添加视频到个人网站","ja":"AIエージェントを使用して動画を追加する方法を学ぶ","ko":"YouTube oEmbed API와 비디오 ID를 사용하여 개인 웹사이트에 비디오를 추가하는 방법","es":"Aprende a agregar videos a tu sitio web personal con add-video. Descubre cómo extraer IDs de video y obtener títulos de video con la API oEmbed de YouTube","fr":"Découvrez comment ajouter des vidéos à votre site web personnel avec add-video. Apprenez à extraire les IDs de vidéo et à obtenir les titres de vidéo avec l''...","de":"Erfahren Sie, wie Sie mit add-video Videos zu Ihrer persönlichen Website hinzufügen. Entdecken Sie, wie Sie Video-IDs extrahieren und Video-Titel mit der You...","pt":"Aprenda a adicionar vídeos ao seu portfólio com o Add-Video, utilizando a API do YouTube e seguindo os passos certos","ru":"Узнайте, как добавить видео в портфолио с помощью Add-Video, используя API YouTube и следуя инструкциям","ar":"تعرف على كيفية إضافة الفيديوهات إلى موقعك الشخصي باستخدام Add-Video وواجهة برمجة تطبيقات YouTube"},"definition":{"en":"add-video is a skill that enables the integration of YouTube videos into a personal website by extracting video IDs from URLs and fetching video titles via the YouTube oEmbed API","zh":"添加视频到个人网站的功能，使用YouTube oEmbed API和视频ID","ja":"AIエージェントを使用した動画追加機能","ko":"개인 웹사이트에 비디오 추가하기 위한 기능","es":"Add-video es una habilidad que permite agregar videos a sitios web personales mediante la extracción de IDs de video y la obtención de títulos de video con la API oEmbed de YouTube","fr":"Add-video est une fonctionnalité qui permet d''ajouter des vidéos à des sites web personnels en extrayant les IDs de vidéo et en obtenant les titres de vidéo avec l''API oEmbed de YouTube","de":"Add-video ist eine Fähigkeit, die das Hinzufügen von Videos zu persönlichen Websites ermöglicht, indem Video-IDs extrahiert und Video-Titel mit der YouTube oEmbed-API erhalten werden","pt":"O Add-Video é uma ferramenta que permite adicionar vídeos a um portfólio, utilizando a API do YouTube","ru":"Add-Video - это инструмент, который позволяет добавлять видео в портфолио, используя API YouTube","ar":"Add-Video هو أداة تسمح بإضافة الفيديوهات إلى موقعك الشخصي، باستخدام واجهة برمجة تطبيقات YouTube"},"features":{"en":["Extracts video IDs from YouTube URLs (youtube.com/watch?v=VIDEO_ID, youtu.be/VIDEO_ID, youtube.com/embed/VIDEO_ID)","Fetches video titles using the YouTube oEmbed API (https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={VIDEO_ID}&format=json)","Supports YouTube video integration into personal websites","Uses JSON format for video title retrieval","Requires no API key for video title fetching","Triggers with the `/add-video <URL>` command"],"zh":["使用YouTube oEmbed API获取视频标题","支持YouTube视频ID的提取","实现动态内容更新","兼容多种视频URL格式","无需API密钥即可使用","支持JSON格式的数据交换"],"ja":["YouTube oEmbed APIを使用して動画タイトルを取得","YouTube動画IDの抽出をサポート","動的コンテンツ更新を実現","複数の動画URLフォーマットをサポート","APIキーなしで使用可能","JSON形式のデータ交換をサポート"],"ko":["YouTube oEmbed API를 사용하여 비디오 제목을 가져옵니다","YouTube 비디오 ID 추출을 지원합니다","동적 콘텐츠 업데이트를 구현합니다","다양한 비디오 URL 형식을 지원합니다","API 키 없이 사용할 수 있습니다","JSON 형식의 데이터 교환을 지원합니다"],"es":["Extracción de IDs de video de YouTube","Uso de la API oEmbed de YouTube para obtener títulos de video","Compatibilidad con URLs de YouTube (youtube.com/watch, youtu.be, youtube.com/embed)","Funcionalidad para sitios web personales","Implementación mediante comando `/add-video <URL>`","Soporte para la obtención de títulos de video en formato JSON"],"fr":["Extraction des IDs de vidéo YouTube","Utilisation de l''API oEmbed de YouTube pour obtenir les titres de vidéo","Compatibilité avec les URLs YouTube (youtube.com/watch, youtu.be, youtube.com/embed)","Fonctionnalité pour les sites web personnels","Implémentation via la commande `/add-video <URL>`","Prise en charge de l''obtention des titres de vidéo au format JSON"],"de":["Extraktion von Video-IDs von YouTube","Verwendung der YouTube oEmbed-API zur Beschaffung von Video-Titeln","Kompatibilität mit YouTube-URLs (youtube.com/watch, youtu.be, youtube.com/embed)","Funktion für persönliche Websites","Implementierung über den Befehl `/add-video <URL>`","Unterstützung für die Beschaffung von Video-Titeln im JSON-Format"],"pt":["Extração do ID do vídeo do YouTube","Uso da API do YouTube para obter o título do vídeo","Suporte a URLs do YouTube, incluindo youtube.com/watch e youtu.be","Integração com a API do YouTube para obter informações do vídeo","Facilidade de uso com a sintaxe /add-video <URL>"],"ru":["Извлечение ID видео из YouTube","Использование API YouTube для получения названия видео","Поддержка URL-адресов YouTube, включая youtube.com/watch и youtu.be","Интеграция с API YouTube для получения информации о видео","Легкость использования с синтаксисом /add-video <URL>"],"ar":["استخراج معرف الفيديو من YouTube","استخدام واجهة برمجة تطبيقات YouTube لاستخراج عنوان الفيديو","دعم عناوين URL لليوتيوب، بما في ذلك youtube.com/watch و youtu.be","التكامل مع واجهة برمجة تطبيقات YouTube لاستخراج معلومات الفيديو","سهولة الاستخدام مع بناء الجملة /add-video <URL>"]},"keywords":{"en":["how to use add-video","add-video setup guide","YouTube oEmbed API tutorial","add-video alternative","add-video vs YouTube API","add-video install","what is add-video","add-video for personal websites","YouTube video integration","add-video AI agent skill"],"zh":["添加视频到个人网站","YouTube oEmbed API","视频ID","动态内容更新","AI工具","个人网站开发","视频添加功能","YouTube API","JSON数据交换"],"ja":["AIエージェント","動画追加","YouTube oEmbed API","動画ID","動的コンテンツ更新","個人サイト開発","動画追加機能","YouTube API","JSONデータ交換"],"ko":["개인 웹사이트에 비디오 추가","YouTube oEmbed API","비디오 ID","동적 콘텐츠 업데이트","AI 도구","개인 웹사이트 개발","비디오 추가 기능","YouTube API","JSON 데이터 교환"],"es":["add-video","sitios web personales","API oEmbed de YouTube","extracción de IDs de video","obtención de títulos de video","comando `/add-video <URL>`","YouTube","vídeos","desarrollo web","herramientas de desarrollo"],"fr":["add-video","sites web personnels","API oEmbed de YouTube","extraction des IDs de vidéo","obtention des titres de vidéo","commande `/add-video <URL>`","YouTube","vidéos","développement web","outils de développement"],"de":["add-video","persönliche Websites","YouTube oEmbed-API","Extraktion von Video-IDs","Beschaffung von Video-Titeln","Befehl `/add-video <URL>`","YouTube","Videos","Webentwicklung","Entwicklungstools"],"pt":["Add-Video","API do YouTube","adicionar vídeos ao portfólio","desenvolvedores","ferramentas de desenvolvimento","programação","vídeos","portfólio","Guia de configuração"],"ru":["Add-Video","API YouTube","добавление видео в портфолио","разработчики","инструменты разработки","программирование","видео","портфолио","Руководство по настройке"],"ar":["Add-Video","واجهة برمجة تطبيقات YouTube","إضافة الفيديوهات إلى الموقع الشخصي","مطورون","أدوات التطوير","البرمجة","الفيديوهات","الموقع الشخصي","دليل الإعداد"]}},"owner":"jdorfman","repo":"www","repoPath":"jdorfman/www","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.445Z","topics":[],"category":"community","skillMd":{"name":"add-video","description":"Add a new YouTube video to the portfolio. New video becomes Horizontal Video Card 1, all other videos shift down, oldest goes to More section. Use when user types /add-video followed by a YouTube URL.","bodyPreview":"# Add Video to Portfolio\n\nWhen user types `/add-video <URL>`, follow these steps exactly.\n\n## Step 1: Extract Video ID\n\nFrom the URL, extract the video ID:\n- `youtube.com/watch?v=VIDEO_ID` → use VIDEO_ID\n- `youtu.be/VIDEO_ID` → use VIDEO_ID\n- `youtube.com/embed/VIDEO_ID` → use VIDEO_ID\n\n## Step 2: Fetch Video Title\n\nUse the YouTube oEmbed API to get the video title (no API key needed):\n\n```\nhttps://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={VIDEO_ID}&format=json\n```\n\nFetch this","body":"# Add Video to Portfolio\n\nWhen user types `/add-video <URL>`, follow these steps exactly.\n\n## Step 1: Extract Video ID\n\nFrom the URL, extract the video ID:\n- `youtube.com/watch?v=VIDEO_ID` → use VIDEO_ID\n- `youtu.be/VIDEO_ID` → use VIDEO_ID\n- `youtube.com/embed/VIDEO_ID` → use VIDEO_ID\n\n## Step 2: Fetch Video Title\n\nUse the YouTube oEmbed API to get the video title (no API key needed):\n\n```\nhttps://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={VIDEO_ID}&format=json\n```\n\nFetch this URL and extract the `title` field from the JSON response. Use this title for:\n- The iframe `title` attribute\n- The `<h3 class=\"video-card-title\">` text\n\nIf the fetch fails, fall back to \"Video\" as the default title.\n\n## Step 3: Read index.html\n\nRead `index.html` and identify these 5 video cards by their HTML comments:\n- `<!-- Horizontal Video Card 1 -->` - first large video\n- `<!-- Horizontal Video Card 2 -->` - second large video\n- `<!-- Small Video Card 1 -->` - first small video\n- `<!-- Small Video Card 2 -->` - second small video\n- `<!-- Small Video Card 3 -->` - third small video\n\nAlso find `<!-- More Videos Section -->` where archived videos go.\n\n## Step 4: Cascade Videos Down\n\nPerform these moves in order:\n\n1. **Small Card 3 → More section**: Copy the entire `<article>` from Small Card 3 and insert it at the START of the More section''s `<div class=\"video-grid\">`, right after the `<!-- Archived videos appear here -->` comment (push existing archived videos down).\n\n2. **Small Card 2 → Small Card 3**: Replace Small Card 3''s `<article>` content with Small Card 2''s content. Keep the `<!-- Small Video Card 3 -->` comment.\n\n3. **Small Card 1 → Small Card 2**: Replace Small Card 2''s `<article>` content with Small Card 1''s content. Keep the `<!-- Small Video Card 2 -->` comment.\n\n4. **Horizontal Card 2 → Small Card 1**: Replace Small Card 1''s `<article>` with Horizontal Card 2''s content, but change the class from `video-card-horizontal` to `video-card-small`. Keep the `<!-- Small Video Card 1 -->` comment.\n\n5. **Horizontal Card 1 → Horizontal Card 2**: Replace Horizontal Card 2''s `<article>` content with Horizontal Card 1''s content. Keep the `<!-- Horizontal Video Card 2 -->` comment.\n\n6. **New video → Horizontal Card 1**: Update Horizontal Card 1 with the new video:\n   - Set iframe src to `https://www.youtube.com/embed/{VIDEO_ID}`\n   - Set iframe title to the fetched YouTube title (from Step 2)\n   - Set `<h3 class=\"video-card-title\">` to the fetched YouTube title\n   - Keep category as \"Deep Dives / Demos\" unless specified\n\n## Video Card Templates\n\n**Horizontal card (for positions 1-2):**\n```html\n          <!-- Horizontal Video Card 1 -->\n          <article class=\"video-card video-card-horizontal\">\n            <div class=\"video-thumbnail video-thumbnail-16-9\">\n              <iframe \n                src=\"https://www.youtube.com/embed/{VIDEO_ID}\" \n                title=\"{TITLE}\"\n                frameborder=\"0\" \n                allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" \n                allowfullscreen\n                style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%;\">\n              </iframe>\n            </div>\n            <div class=\"video-info\">\n              <span class=\"video-category\">{CATEGORY}</span>\n              <h3 class=\"video-card-title\">{TITLE}</h3>\n            </div>\n          </article>\n```\n\n**Small card (for positions 1-3 and More section):**\n```html\n          <!-- Small Video Card 1 -->\n          <article class=\"video-card video-card-small\">\n            <div class=\"video-thumbnail video-thumbnail-16-9\">\n              <iframe \n                src=\"https://www.youtube.com/embed/{VIDEO_ID}\" \n                title=\"{TITLE}\"\n                frameborder=\"0\" \n                allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" \n                allowfullscreen\n                style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%;\">\n              </iframe>\n            </div>\n            <div class=\"video-info\">\n              <span class=\"video-category\">{CATEGORY}</span>\n              <h3 class=\"video-card-title\">{TITLE}</h3>\n            </div>\n          </article>\n```\n\n## Example\n\nInput: `/add-video https://www.youtube.com/watch?v=abc123`\n\nBefore:\n- Horizontal 1: Video A\n- Horizontal 2: Video B\n- Small 1: Video C\n- Small 2: Video D\n- Small 3: Video E\n- More: [Video F, Video G...]\n\nAfter:\n- Horizontal 1: **NEW VIDEO** (abc123)\n- Horizontal 2: Video A\n- Small 1: Video B (changed from horizontal to small class)\n- Small 2: Video C\n- Small 3: Video D\n- More: [Video E, Video F, Video G...]\n\n## Optional Title/Category Override\n\nBy default, the video title is fetched automatically from YouTube.\n\nIf user wants to override the title: `/add-video URL \"My Custom Title\"`\nIf user wants to override title and category: `/add-video URL \"My Custom Title\" \"Category Name\"`\n\nUser-provided values take precedence over the fetched YouTube title. Default category is \"Deep Dives / Demos\".\n"},"lastSynced":"2026-03-08T02:08:53.543Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing seamless YouTube video integration.","zh":"非常适合需要无缝集成YouTube视频的Web开发代理。","ja":"YouTube動画を無邪気に統合する必要があるWeb開発エージェントに最適です。","ko":"YouTube 비디오를無断으로 통합해야 하는 웹 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo web que necesitan una integración de vídeo de YouTube sin problemas.","fr":"Parfait pour les agents de développement web nécessitant une intégration de vidéos YouTube sans interruption.","de":"Perfekt für Webentwicklungsagenten, die eine nahtlose YouTube-Video-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que precisam de integração de vídeo do YouTube sem interrupções.","ru":"Идеально подходит для агентов веб-разработки, требующих бесшовной интеграции видео YouTube.","ar":"مثالي للوكلاء الذين يحتاجون إلى تكامل فيديو يوتيوب بدون انقطاع لتقنيات الويب."},"recommendation":{"en":"Empowers agents to fetch video titles using the YouTube oEmbed API and embed videos into websites, leveraging JSON format for effortless data exchange and utilizing URL patterns like youtube.com/watch?v=VIDEO_ID for video ID extraction.","zh":"赋予代理获取视频标题使用YouTube oEmbed API并将视频嵌入网站的能力，利用JSON格式进行轻松的数据交换，并利用URL模式（如youtube.com/watch?v=VIDEO_ID）进行视频ID提取。","ja":"YouTube oEmbed APIを使用してビデオタイトルを取得し、JSON形式を使用してデータ交換を容易に行い、URLパターン（例：youtube.com/watch?v=VIDEO_ID）を使用してビデオIDを抽出して、ビデオをWebサイトに埋め込むことができる機能をエージェントに提供します。","ko":"에이전트가 YouTube oEmbed API를 사용하여 비디오 제목을 가져오고 JSON 형식을 사용하여 데이터 교환을 쉽게 수행하고 URL 패턴(youtube.com/watch?v=VIDEO_ID)을 사용하여 비디오 ID를 추출하여 비디오를 웹 사이트에 삽입 할 수있는 기능을 제공합니다.","es":"Habilita a los agentes a recuperar títulos de video utilizando la API oEmbed de YouTube y embeber vídeos en sitios web, aprovechando el formato JSON para un intercambio de datos sin esfuerzo y utilizando patrones de URL como youtube.com/watch?v=VIDEO_ID para la extracción de ID de video.","fr":"Permet aux agents de récupérer des titres de vidéos à l''aide de l''API oEmbed de YouTube et d''intégrer des vidéos dans des sites web, en exploitant le format JSON pour un échange de données sans effort et en utilisant des modèles d''URL comme youtube.com/watch?v=VIDEO_ID pour l''extraction d''ID de vidéo.","de":"Ermächtigt Agenten, Videotitel mithilfe der YouTube oEmbed API abzurufen und Videos in Websites einzubetten, wobei das JSON-Format für einen mühelosen Datenaustausch genutzt wird und URL-Muster wie youtube.com/watch?v=VIDEO_ID für die Videoidentifikationsextraktion verwendet werden.","pt":"Habilita os agentes a capturar títulos de vídeo usando a API oEmbed do YouTube e incorporar vídeos em sites, aproveitando o formato JSON para troca de dados sem esforço e utilizando padrões de URL como youtube.com/watch?v=VIDEO_ID para extração de ID de vídeo.","ru":"Наделяет агентов возможностью получать названия видео с помощью API oEmbed YouTube и встраивать видео на сайты, используя формат JSON для беспроблемного обмена данными и используя шаблоны URL, такие как youtube.com/watch?v=VIDEO_ID, для извлечения идентификатора видео.","ar":"تمكين الوكلاء من استخراج عناوين الفيديو باستخدام واجهة برمجة تطبيقات يوتيوب oEmbed ودمج الفيديوهات في المواقع ، باستخدام تنسيق JSON لتبادل البيانات بلا جهد واستخدام أنماط URL مثل youtube.com/watch?v=VIDEO_ID لاستخراج معرف الفيديو."},"useCases":{"en":["Embedding YouTube videos into personal portfolios","Automating video title fetching for website content","Generating video galleries with titles and IDs"],"zh":["将YouTube视频嵌入个人作品集","自动获取网站内容的视频标题","使用标题和ID生成视频库"],"ja":["個人ポートフォリオにYouTube動画を埋め込む","Webサイトのコンテンツのビデオタイトルを自動取得する","タイトルとIDを使用してビデオギャラリーを生成する"],"ko":["개인 포트폴리오에 YouTube 비디오를 삽입하는 것","웹 사이트 콘텐츠의 비디오 제목을 자동으로 가져오는 것","제목 및 ID를 사용하여 비디오 갤러리를 생성하는 것"],"es":["Integrar vídeos de YouTube en portfolios personales","Automatizar la recuperación de títulos de video para contenido de sitios web","Generar galerías de video con títulos e IDs"],"fr":["Intégrer des vidéos YouTube dans des portfolios personnels","Automatiser la récupération de titres de vidéos pour le contenu de sites web","Générer des galeries de vidéos avec des titres et des IDs"],"de":["YouTube-Videos in persönliche Portfolios einbetten","Automatisieren des Video-Titel-Abrufs für Website-Inhalte","Generieren von Video-Galerien mit Titeln und IDs"],"pt":["Incorporação de vídeos do YouTube em portfólios pessoais","Automatização da captura de títulos de vídeo para conteúdo de site","Geração de galerias de vídeo com títulos e IDs"],"ru":["Встраивание видео YouTube в личные портфолио","Автоматизация извлечения названий видео для контента сайта","Генерация галерей видео с названиями и идентификаторами"],"ar":["دمج فيديوهات يوتيوب في المحافظ الشخصية","تأتمتة استخراج عناوين الفيديو لمحتوى الموقع","توليد معارض الفيديو مع العناوين والمعرفات"]},"limitations":{"en":["Requires YouTube oEmbed API access","Limited to YouTube video platform","No API key needed but subject to YouTube API terms"],"zh":["需要YouTube oEmbed API访问","仅限YouTube视频平台","无需API密钥，但受YouTube API条款限制"],"ja":["YouTube oEmbed APIへのアクセスが必要","YouTube動画プラットフォームのみ","APIキーは不要ですが、YouTube APIの利用規約が適用されます"],"ko":["YouTube oEmbed API 액세스가 필요합니다.","YouTube 비디오 플랫폼만 해당됩니다.","API 키가 필요하지는 않지만 YouTube API 사용 약관의 적용을 받습니다."],"es":["Requiere acceso a la API oEmbed de YouTube","Limitado a la plataforma de video de YouTube","No se necesita una clave de API, pero está sujeto a los términos de la API de YouTube"],"fr":["Nécessite un accès à l''API oEmbed de YouTube","Limité à la plateforme de vidéos YouTube","Pas de clé API nécessaire, mais soumis aux conditions de l''API YouTube"],"de":["Benötigt Zugriff auf die YouTube oEmbed API","Begrenzt auf die YouTube-Video-Plattform","Kein API-Schlüssel erforderlich, aber unterliegt den Nutzungsbedingungen der YouTube API"],"pt":["Requer acesso à API oEmbed do YouTube","Limitado à plataforma de vídeo do YouTube","Nenhuma chave de API necessária, mas sujeito aos termos da API do YouTube"],"ru":["Требует доступа к API oEmbed YouTube","Ограниченная платформа видео YouTube","Не требуется ключ API, но подлежит условиям использования API YouTube"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات يوتيوب oEmbed","محدود بمATFORM الفيديو في يوتيوب","لا يحتاج إلى مفتاح واجهة برمجة التطبيقات ولكن خاضع لشروط استخدام واجهة برمجة تطبيقات يوتيوب"]},"version":4},"contentHash":"da47f905a0d571ddff00c6361be4e1d7999b6c4e861cea7fddddce6f5591fc80","qualityScore":36}');
