INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jdorfman/www/add-video', 'add-video', 'jdorfman', 'www', 'community', 'add-video jdorfman www community The add-video skill allows developers to add YouTube videos to their personal website by extracting video IDs and fetching video titles using the YouTube oEmbed API. This skill benefits web developers and AI agent users. 使用YouTube oEmbed API和视频ID添加视频到个人网站，实现动态内容更新 AIエージェントを使用して動画を追加し、個人サイトのコンテンツを強化する YouTube oEmbed API와 비디오 ID를 사용하여 개인 웹사이트에 동적 비디오 내용을 추가합니다 Add-video es una habilidad que te permite agregar videos a tu sitio web personal. Extrae IDs de video de YouTube y obtén títulos de video con la API oEmbed Add-video est une fonctionnalité qui vous permet d''ajouter des vidéos à votre site web personnel. Extrayez les IDs de vidéo YouTube et obtenez les titres de vidéo avec l''API oEmbed Add-video ist eine Fähigkeit, die es Ihnen ermöglicht, Videos zu Ihrer persönlichen Website hinzuzufügen. Extrahieren Sie Video-IDs von YouTube und erhalten Sie Video-Titel mit der oEmbed-API O Add-Video permite que você adicione vídeos ao seu portfólio de forma fácil, utilizando a API do YouTube para extrair o título do vídeo Add-Video позволяет легко добавлять видео в портфолио, используя API YouTube для извлечения названия видео يسمح Add-Video بإضافة الفيديوهات إلى موقعك الشخصي بسهولة، باستخدام واجهة برمجة تطبيقات YouTube لاستخراج عنوان الفيديو how to use add-video add-video setup guide YouTube oEmbed API tutorial add-video alternative add-video vs YouTube API add-video install what is add-video add-video for personal websites YouTube video integration add-video AI agent skill 添加视频到个人网站 YouTube oEmbed API 视频ID 动态内容更新 AI工具 个人网站开发 视频添加功能 YouTube API JSON数据交换 Extracts video IDs from YouTube URLs (youtube.com/watch?v=VIDEO_ID, youtu.be/VIDEO_ID, youtube.com/embed/VIDEO_ID) Fetches video titles using the YouTube oEmbed API (https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={VIDEO_ID}&format=json) Supports YouTube video integration into personal websites Uses JSON format for video title retrieval Requires no API key for video title fetching Triggers with the `/add-video <URL>` command add-video is a skill that enables the integration of YouTube videos into a personal website by extracting video IDs from URLs and fetching video titles via the YouTube oEmbed API');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GELLIFY/acme-app/better-auth-security-best-practices', 'community', 'GELLIFY', 'acme-app', 'GELLIFY/acme-app', 'better-auth-security-best-practices', 0, 0, 36, '2026-03-08T01:57:15.452Z', '2026-03-08T02:09:00.760Z', '5124e42ccce39e04996fc4aa273154fdc2ff3827d174901913d777a72b3bbcd7', '{"id":"GELLIFY/acme-app/better-auth-security-best-practices","name":"better-auth-security-best-practices","description":{"en":"better-auth-security-best-practices is a template for securing full-stack apps with best-in-class auth integrations, benefiting developers seeking robust security measures.","zh":"Better Auth 的秘密管理是安全的基础，通过环境变量和配置选项实现安全的身份验证","ja":"Better Auth のシークレット管理はセキュリティの基盤であり、環境変数とコンフィグオプションを使用して安全な認証を実現します","ko":"Better Auth의 비밀 관리는 보안의 기초이며 환경 변수와 구성 옵션을 사용하여 안전한 인증을 구현합니다","es":"Better Auth proporciona una forma segura de autenticar a los usuarios. Configura el secreto de autenticación para proteger tus aplicaciones.","fr":"Better Auth offre une façon sécurisée d''authentifier les utilisateurs. Configurez le secret d''authentification pour protéger vos applications.","de":"Better Auth bietet eine sichere Möglichkeit, Benutzer zu authentifizieren. Konfigurieren Sie das Authentifizierungsgeheimnis, um Ihre Anwendungen zu schützen.","pt":"O melhor-auth-security-best-practices é um template para aplicações full-stack configuradas para usar as melhores integrações para projetos padrão, com foco em segurança de autenticação","ru":"Лучшие практики безопасности аутентификации ИИ Агентов - это шаблон для полнофункциональных приложений, настроенных для использования лучших интеграций для стандартных проектов, с фокусом на безопасности аутентификации","ar":"أفضل ممارسات أمان المصادقة للوكلاء الذكيين هي قوالب لتطبيقات الويب الكاملة المصممة لاستخدام أفضل التكاملات لمشاريع معيارية، مع التركيز على أمان المصادقة"},"seo":{"title":{"en":"better-auth-security-best-practices: Secure Authenticatio...","zh":"Better Auth 安全最佳实践设置指南","ja":"Better Auth セキュリティベストプラクティス設定ガイド","ko":"Better Auth 보안 최적화 설정 가이드","es":"Mejores prácticas de seguridad de autenticación con Bette...","fr":"Guide de configuration de la sécurité d''authentification ...","de":"Better Auth Sicherheitsbest Practices für Entwickler","pt":"Melhor Guia de Configuração de Segurança de Autenticação","ru":"Лучшие практики безопасности аутентификации ИИ Агентов","ar":"دليل أفضل ممارسات أمان المصادقة للوكلاء الذكيين"},"description":{"en":"Unlock robust auth security with better-auth-security-best-practices. Learn how to configure secrets and env variables for secure session tokens and cookies.","zh":"了解 Better Auth 的秘密管理和安全最佳实践，通过环境变量和配置选项实现安全的身份验证","ja":"Better Auth のシークレット管理とセキュリティベストプラクティスについて学び、環境変数とコンフィグオプションを使用して安全な認証を実現します","ko":"Better Auth의 비밀 관리와 보안 최적화에 대해 알아보고 환경 변수와 구성 옵션을 사용하여 안전한 인증을 구현하세요","es":"Aprende a configurar la seguridad de autenticación con Better Auth y sigue las mejores prácticas para proteger tus aplicaciones","fr":"Découvrez comment configurer la sécurité d''authentification avec Better Auth et suivez les meilleures pratiques pour protéger vos applications","de":"Erfahren Sie, wie Sie die Authentifizierungssicherheit mit Better Auth konfigurieren und folgen Sie den besten Praktiken, um Ihre Anwendungen zu schützen","pt":"Aprenda a configurar a segurança de autenticação com o melhor-auth-security-best-practices. Descubra como proteger seus dados com sessões seguras e criptografia","ru":"Узнайте, как настроить безопасность аутентификации с помощью лучших практик ИИ Агентов. Откройте для себя, как защитить ваши данные с помощью безопасных сесс...","ar":"تعرف على كيفية تكوين أمان المصادقة مع أفضل ممارسات الوكلاء الذكيين. اكتشف كيف تحمي بياناتك باستخدام الجلسات الآمنة والتشفير"},"definition":{"en":"better-auth-security-best-practices is a security template for full-stack apps, focusing on secret management for secure authentication and session token generation.","zh":"Better Auth 安全最佳实践是指通过秘密管理和安全配置实现安全的身份验证","ja":"Better Auth セキュリティベストプラクティスとは、シークレット管理とセキュリティコンフィグを使用して安全な認証を実現すること","ko":"Better Auth 보안 최적화는 비밀 관리와 보안 구성으로 안전한 인증을 구현하는 것을 의미합니다","es":"Better Auth es un sistema de autenticación que utiliza un secreto para firmar tokens de sesión y generar cookies seguras","fr":"Better Auth est un système d''authentification qui utilise un secret pour signer les tokens de session et générer des cookies sécurisés","de":"Better Auth ist ein Authentifizierungssystem, das ein Geheimnis verwendet, um Sitzungstoken zu signieren und sichere Cookies zu generieren","pt":"O que é melhor-auth-security-best-practices? É um conjunto de práticas de segurança para autenticação em aplicações full-stack","ru":"Что такое лучшие практики безопасности аутентификации ИИ Агентов? Это набор практик безопасности для аутентификации в полнофункциональных приложениях","ar":"ما هي أفضل ممارسات أمان المصادقة للوكلاء الذكيين؟ هي مجموعة من ممارسات الأمان للمصادقة في تطبيقات الويب الكاملة"},"features":{"en":["Configures auth secrets via environment variables or options.secret","Supports secure cookie generation using the auth secret","Utilizes the Better Auth library for robust authentication","Prioritizes secret management for secure session token signing and encryption","Allows configuration via the BETTER_AUTH_SECRET environment variable"],"zh":["通过环境变量实现秘密管理","使用配置选项实现安全的身份验证","支持 Better Auth 的标准项目集成","实现安全的会话令牌签名和加密","生成安全的 Cookie","支持多种配置选项"],"ja":["環境変数を使用したシークレット管理","コンフィグオプションを使用した安全な認証","Better Auth の標準プロジェクト統合をサポート","安全なセッショントークンの署名と暗号化を実現","安全な Cookie を生成","複数のコンフィグオプションをサポート"],"ko":["환경 변수를 사용한 비밀 관리","구성 옵션을 사용한 안전한 인증","Better Auth의 표준 프로젝트 통합을 지원","안전한 세션 토큰 서명 및 암호화를 구현","안전한 쿠키를 생성","여러 구성 옵션을 지원"],"es":["Configuración del secreto de autenticación mediante opciones o variables de entorno","Uso de TypeScript para configurar Better Auth","Generación de cookies seguras mediante el secreto de autenticación","Firma de tokens de sesión con el secreto de autenticación","Protección de datos sensibles mediante el secreto de autenticación"],"fr":["Configuration du secret d''authentification via des options ou des variables d''environnement","Utilisation de TypeScript pour configurer Better Auth","Génération de cookies sécurisés via le secret d''authentification","Signature des tokens de session avec le secret d''authentification","Protection des données sensibles via le secret d''authentification"],"de":["Konfiguration des Authentifizierungsgeheimnisses über Optionen oder Umgebungsvariablen","Verwendung von TypeScript zur Konfiguration von Better Auth","Generierung sicherer Cookies mittels des Authentifizierungsgeheimnisses","Signierung von Sitzungstoken mit dem Authentifizierungsgeheimnis","Schutz sensibler Daten mittels des Authentifizierungsgeheimnisses"],"pt":["Configuração de segredo de autenticação com opções de segurança","Uso de variáveis de ambiente para armazenar segredos","Suporte a sessões seguras e criptografia","Integração com melhor-auth para autenticação segura","Configuração flexível para projetos padrão"],"ru":["Настройка секрета аутентификации с опциями безопасности","Использование переменных окружения для хранения секретов","Поддержка безопасных сессий и шифрования","Интеграция с лучшим-auth для безопасной аутентификации","Гибкая настройка для стандартных проектов"],"ar":["تكوين سر المصادقة مع خيارات أمان","استخدام متغيرات البيئة لتخزين الأسرار","دعم الجلسات الآمنة والتشفير","التكامل مع أفضل-مصادقة لأمان المصادقة","تكوين مرن لمشاريع معيارية"]},"keywords":{"en":["better-auth-security-best-practices setup guide","how to use better-auth-security-best-practices","what is better-auth-security-best-practices","better-auth-security-best-practices alternative","better-auth-security-best-practices vs auth0","install better-auth-security-best-practices"],"zh":["Better Auth","安全最佳实践","秘密管理","环境变量","配置选项","安全身份验证","会话令牌","Cookie","AI 工具","AI エージェント"],"ja":["Better Auth","セキュリティベストプラクティス","シークレット管理","環境変数","コンフィグオプション","安全な認証","セッショントークン","Cookie","AI エージェント","AI ツール"],"ko":["Better Auth","보안 최적화","비밀 관리","환경 변수","구성 옵션","안전한 인증","세션 토큰","쿠키","AI 에이전트","AI 도구"],"es":["seguridad de autenticación","mejores prácticas de seguridad","Better Auth","TypeScript","autenticación de usuarios","protección de datos","seguridad de aplicaciones","Herramientas de AI para desarrolladores","Agentes de AI para seguridad"],"fr":["sécurité d''authentification","meilleures pratiques de sécurité","Better Auth","TypeScript","authentification des utilisateurs","protection des données","sécurité des applications","Outils d''IA pour les développeurs","Agents d''IA pour la sécurité"],"de":["Authentifizierungssicherheit","Sicherheitsbest Practices","Better Auth","TypeScript","Benutzerauthentifizierung","Datenschutz","Anwendungssicherheit","AI-Tools für Entwickler","AI-Agents für Sicherheit"],"pt":["melhor-auth-security-best-practices","segurança de autenticação","autenticação segura","sessões seguras","criptografia","variáveis de ambiente","projetos full-stack"],"ru":["лучшие практики безопасности аутентификации ИИ Агентов","безопасность аутентификации","безопасная аутентификация","безопасные сессии","шифрование","переменные окружения","полнофункциональные приложения"],"ar":["أفضل ممارسات أمان المصادقة للوكلاء الذكيين","أمان المصادقة","مصادقة آمنة","جلسات آمنة","تشفير","متغيرات البيئة","تطبيقات الويب الكاملة"]}},"owner":"GELLIFY","repo":"acme-app","repoPath":"GELLIFY/acme-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.452Z","topics":[],"category":"community","skillMd":{"name":"better-auth-security-best-practices","description":"This skill provides guidance for implementing security features that span across Better Auth, including rate limiting, CSRF protection, session security, trusted origins, secret management, OAuth security, IP tracking, and security auditing. These topics are not covered in individual plugin skills.","bodyPreview":"## Secret Management\n\nThe auth secret is the foundation of Better Auth''s security. It''s used for signing session tokens, encrypting sensitive data, and generating secure cookies.\n\n### Configuring the Secret\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  secret: process.env.BETTER_AUTH_SECRET, // or via `BETTER_AUTH_SECRET` env\n});\n```\n\nBetter Auth looks for secrets in this order:\n1. `options.secret` in your config\n2. `BETTER_AUTH_SECRET` environment variable","body":"## Secret Management\n\nThe auth secret is the foundation of Better Auth''s security. It''s used for signing session tokens, encrypting sensitive data, and generating secure cookies.\n\n### Configuring the Secret\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  secret: process.env.BETTER_AUTH_SECRET, // or via `BETTER_AUTH_SECRET` env\n});\n```\n\nBetter Auth looks for secrets in this order:\n1. `options.secret` in your config\n2. `BETTER_AUTH_SECRET` environment variable\n3. `AUTH_SECRET` environment variable\n\n### Secret Requirements\n\nBetter Auth validates your secret and will:\n- **Reject** default/placeholder secrets in production\n- **Warn** if the secret is shorter than 32 characters\n- **Warn** if entropy is below 120 bits\n\nGenerate a secure secret:\n\n```bash\nopenssl rand -base64 32\n```\n\n**Important**: Never commit secrets to version control. Use environment variables or a secrets manager.\n\n## Rate Limiting\n\nRate limiting protects your authentication endpoints from brute-force attacks and abuse.\nBy default, rate limiting is enabled in production but disabled in development. To explicitly enable it, set `rateLimit.enabled` to `true` in your auth config.\nBetter Auth applies rate limiting to all endpoints by default.\n\nEach plugin can optionally have it''s own configuration to adjust rate-limit rules for a given endpoint.\n\n### Default Configuration\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  rateLimit: {\n    enabled: true, // Default: true in production\n    window: 10, // Time window in seconds (default: 10)\n    max: 100, // Max requests per window (default: 100)\n  },\n});\n```\n\n### Storage Options\n\nConfigure where rate limit counters are stored:\n\n```ts\nrateLimit: {\n  storage: \"database\", // Options: \"memory\", \"database\", \"secondary-storage\"\n}\n```\n\n- **`memory`**: Fast, but resets on server restart (default when no secondary storage)\n- **`database`**: Persistent, but adds database load\n- **`secondary-storage`**: Uses configured secondary storage like Redis (default when available)\n\n**Note**: It is not recommended to use `memory` especially on serverless platforms.\n\n### Custom Storage\n\nImplement your own rate limit storage:\n\n```ts\nrateLimit: {\n  customStorage: {\n    get: async (key) => {\n      // Return { count: number, expiresAt: number } or null\n    },\n    set: async (key, data) => {\n      // Store the rate limit data\n    },\n  },\n}\n```\n\n### Per-Endpoint Rules\n\nBetter Auth applies stricter limits to sensitive endpoints by default:\n- `/sign-in`, `/sign-up`, `/change-password`, `/change-email`: 3 requests per 10 seconds\n\nOverride or customize rules for specific paths:\n\n```ts\nrateLimit: {\n  customRules: {\n    \"/api/auth/sign-in/email\": {\n      window: 60, // 1 minute window\n      max: 5, // 5 attempts\n    },\n    \"/api/auth/some-safe-endpoint\": false, // Disable rate limiting\n  },\n}\n```\n\n## CSRF Protection\n\nBetter Auth implements multiple layers of CSRF protection to prevent cross-site request forgery attacks.\n\n### How CSRF Protection Works\n\n1. **Origin Header Validation**: When cookies are present, the `Origin` or `Referer` header must match a trusted origin\n2. **Fetch Metadata**: Uses `Sec-Fetch-Site`, `Sec-Fetch-Mode`, and `Sec-Fetch-Dest` headers to detect cross-site requests\n3. **First-Login Protection**: Even without cookies, validates origin when Fetch Metadata indicates a cross-site navigation\n\n### Configuration\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  advanced: {\n    disableCSRFCheck: false, // Default: false (keep enabled)\n  },\n});\n```\n\n**Warning**: Only disable CSRF protection for testing or if you have an alternative CSRF mechanism in place.\n\n### Fetch Metadata Blocking\n\nBetter Auth automatically blocks requests where:\n- `Sec-Fetch-Site: cross-site` AND\n- `Sec-Fetch-Mode: navigate` AND\n- `Sec-Fetch-Dest: document`\n\nThis prevents form-based CSRF attacks even on first login when no session cookie exists.\n\n## Trusted Origins\n\nTrusted origins control which domains can make authenticated requests to your Better Auth instance. This protects against open redirect attacks and cross-origin abuse.\n\n### Configuring Trusted Origins\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  baseURL: \"https://api.example.com\",\n  trustedOrigins: [\n    \"https://app.example.com\",\n    \"https://admin.example.com\",\n  ],\n});\n```\n\n**Note**: The `baseURL` origin is automatically trusted.\n\n### Environment Variable\n\nSet trusted origins via environment variable (comma-separated):\n\n```bash\nBETTER_AUTH_TRUSTED_ORIGINS=https://app.example.com,https://admin.example.com\n```\n\n### Wildcard Patterns\n\nSupport for subdomain wildcards:\n\n```ts\ntrustedOrigins: [\n  \"*.example.com\", // Matches any subdomain\n  \"https://*.example.com\", // Protocol-specific wildcard\n  \"exp://192.168.*.*:*/*\", // Custom schemes (e.g., Expo)\n]\n```\n\n### Dynamic Trusted Origins\n\nCompute trusted origins based on the request:\n\n```ts\ntrustedOrigins: async (request) => {\n  // Validate against database, header, etc.\n  const tenant = getTenantFromRequest(request);\n  return [`https://${tenant}.myapp.com`];\n}\n```\n\n### What Gets Validated\n\nBetter Auth validates these URL parameters against trusted origins:\n- `callbackURL` - Where to redirect after authentication\n- `redirectTo` - General redirect parameter\n- `errorCallbackURL` - Where to redirect on errors\n- `newUserCallbackURL` - Where to redirect new users\n- `origin` - Request origin header\n- and more... \n\nInvalid URLs receive a 403 Forbidden response.\n\n## Session Security\n\nSessions control how long users stay authenticated and how session data is secured.\n\n### Session Expiration\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  session: {\n    expiresIn: 60 * 60 * 24 * 7, // 7 days (default)\n    updateAge: 60 * 60 * 24, // Refresh session every 24 hours (default)\n  },\n});\n```\n\n### Fresh Sessions for Sensitive Actions\n\nThe `freshAge` setting defines how recently a user must have authenticated to perform sensitive operations:\n\n```ts\nsession: {\n  freshAge: 60 * 60 * 24, // 24 hours (default)\n}\n```\n\nUse this to require re-authentication for actions like changing passwords or viewing sensitive data.\n\n### Session Caching Strategies\n\nCache session data in cookies to reduce database queries:\n\n```ts\nsession: {\n  cookieCache: {\n    enabled: true,\n    maxAge: 60 * 5, // 5 minutes\n    strategy: \"compact\", // Options: \"compact\", \"jwt\", \"jwe\"\n  },\n}\n```\n\n- **`compact`**: Base64url + HMAC-SHA256 (smallest, signed)\n- **`jwt`**: HS256 JWT (standard, signed)\n- **`jwe`**: A256CBC-HS512 encrypted (largest, encrypted)\n\n**Note**: Use `jwe` strategy when session data contains sensitive information that shouldn''t be readable client-side.\n\n\n## Cookie Security\n\nBetter Auth uses secure cookie defaults but allows customization for specific deployment scenarios.\n\n### Default Cookie Settings\n\n- **`secure`**: `true` when baseURL uses HTTPS or in production\n- **`sameSite`**: `\"lax\"` (prevents CSRF while allowing normal navigation)\n- **`httpOnly`**: `true` (prevents JavaScript access)\n- **`path`**: `\"/\"` (available site-wide)\n- **Prefix**: `__Secure-` when secure is enabled\n\n### Custom Cookie Configuration\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  advanced: {\n    useSecureCookies: true, // Force secure cookies\n    cookiePrefix: \"myapp\", // Custom prefix (default: \"better-auth\")\n    defaultCookieAttributes: {\n      sameSite: \"strict\", // Stricter CSRF protection\n      path: \"/auth\", // Limit cookie scope\n    },\n  },\n});\n```\n\n### Per-Cookie Configuration\n\nCustomize specific cookies:\n\n```ts\nadvanced: {\n  cookies: {\n    session_token: {\n      name: \"auth-session\",\n      attributes: {\n        sameSite: \"strict\",\n      },\n    },\n  },\n}\n```\n\n### Cross-Subdomain Cookies\n\nShare authentication across subdomains:\n\n```ts\nadvanced: {\n  crossSubDomainCookies: {\n    enabled: true,\n    domain: \".example.com\", // Note the leading dot\n    additionalCookies: [\"session_token\", \"session_data\"],\n  },\n}\n```\n\n**Security Note**: Cross-subdomain cookies expand the attack surface. Only enable if you need authentication sharing and trust all subdomains.\n\n## OAuth / Social Provider Security\n\nWhen using social login providers, Better Auth implements industry-standard security measures.\n\n### PKCE (Proof Key for Code Exchange)\n\nBetter Auth automatically uses PKCE for all OAuth flows:\n\n1. Generates a 128-character random `code_verifier`\n2. Creates a `code_challenge` using S256 (SHA-256)\n3. Sends `code_challenge_method: \"S256\"` in the authorization URL\n4. Validates the code exchange with the original verifier\n\nThis prevents authorization code interception attacks.\n\n### State Parameter Security\n\nThe state parameter prevents CSRF attacks on OAuth callbacks:\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  account: {\n    storeStateStrategy: \"cookie\", // Options: \"cookie\" (default), \"database\"\n  },\n});\n```\n\nState tokens:\n- Are 32-character random strings\n- Expire after 10 minutes\n- Contain callback URLs and PKCE verifier (encrypted)\n\n### Encrypting OAuth Tokens\n\nEncrypt stored access and refresh tokens in the database:\n\n```ts\naccount: {\n  encryptOAuthTokens: true, // Uses AES-256-GCM\n}\n```\n\n**Recommendation**: Enable this if you store OAuth tokens for API access on behalf of users.\n\n### Skipping State Cookie Check\n\nFor mobile apps or specific OAuth flows where cookies aren''t available:\n\n```ts\naccount: {\n  skipStateCookieCheck: true, // Not recommended for web apps\n}\n```\n\n**Warning**: Only use this for mobile apps that cannot maintain cookies across redirects.\n\n## IP-Based Security\n\nBetter Auth tracks IP addresses for rate limiting and session security.\n\n### IP Address Configuration\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  advanced: {\n    ipAddress: {\n      ipAddressHeaders: [\"x-forwarded-for\", \"x-real-ip\"], // Headers to check\n      disableIpTracking: false, // Keep enabled for rate limiting\n    },\n  },\n});\n```\n\n### IPv6 Subnet Configuration\n\nFor rate limiting, IPv6 addresses can be grouped by subnet:\n\n```ts\nadvanced: {\n  ipAddress: {\n    ipv6Subnet: 64, // Options: 128, 64, 48, 32 (default: 64)\n  },\n}\n```\n\nSmaller values group more addresses together, which is useful when users share IPv6 prefixes.\n\n### Trusted Proxy Headers\n\nWhen behind a reverse proxy, enable trusted headers:\n\n```ts\nadvanced: {\n  trustedProxyHeaders: true, // Trust x-forwarded-host, x-forwarded-proto\n}\n```\n\n**Security Note**: Only enable this if you trust your proxy. Malicious clients could spoof these headers otherwise.\n\n## Database Hooks for Security Auditing\n\nUse database hooks to implement security auditing and monitoring.\n\n### Setting Up Audit Logging\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  databaseHooks: {\n    session: {\n      create: {\n        after: async ({ data, ctx }) => {\n          await auditLog(\"session.created\", {\n            userId: data.userId,\n            ip: ctx?.request?.headers.get(\"x-forwarded-for\"),\n            userAgent: ctx?.request?.headers.get(\"user-agent\"),\n          });\n        },\n      },\n      delete: {\n        before: async ({ data }) => {\n          await auditLog(\"session.revoked\", { sessionId: data.id });\n        },\n      },\n    },\n    user: {\n      update: {\n        after: async ({ data, oldData }) => {\n          if (oldData?.email !== data.email) {\n            await auditLog(\"user.email_changed\", {\n              userId: data.id,\n              oldEmail: oldData?.email,\n              newEmail: data.email,\n            });\n          }\n        },\n      },\n    },\n    account: {\n      create: {\n        after: async ({ data }) => {\n          await auditLog(\"account.linked\", {\n            userId: data.userId,\n            provider: data.providerId,\n          });\n        },\n      },\n    },\n  },\n});\n```\n\n### Blocking Operations\n\nReturn `false` from a `before` hook to prevent an operation:\n\n```ts\ndatabaseHooks: {\n  user: {\n    delete: {\n      before: async ({ data }) => {\n        // Prevent deletion of protected users\n        if (protectedUserIds.includes(data.id)) {\n          return false;\n        }\n      },\n    },\n  },\n}\n```\n\n## Background Tasks for Timing Attack Prevention\n\nSensitive operations should complete in constant time to prevent timing attacks.\n\n### Configuring Background Tasks\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  advanced: {\n    backgroundTasks: {\n      handler: (promise) => {\n        // Platform-specific handler\n        // Vercel: waitUntil(promise)\n        // Cloudflare: ctx.waitUntil(promise)\n        waitUntil(promise);\n      },\n    },\n  },\n});\n```\n\nThis ensures operations like sending emails don''t affect response timing, which could leak information about whether a user exists.\n\n## Account Enumeration Prevention\n\nBetter Auth implements several measures to prevent attackers from discovering valid accounts.\n\n### Built-in Protections\n\n1. **Consistent Response Messages**: Password reset always returns \"If this email exists in our system, check your email for the reset link\"\n2. **Dummy Operations**: When a user isn''t found, Better Auth still performs token generation and database lookups with dummy values\n3. **Background Email Sending**: Emails are sent asynchronously to prevent timing differences\n\n### Additional Recommendations\n\nFor sign-up and sign-in endpoints, consider:\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  emailAndPassword: {\n    enabled: true,\n    // Generic error messages (implement in your error handling)\n  },\n});\n```\n\nReturn generic error messages like \"Invalid credentials\" rather than \"User not found\" or \"Incorrect password\".\n\n## Complete Security Configuration Example\n\n```ts\nimport { betterAuth } from \"better-auth\";\n\nexport const auth = betterAuth({\n  secret: process.env.BETTER_AUTH_SECRET,\n  baseURL: \"https://api.example.com\",\n  trustedOrigins: [\n    \"https://app.example.com\",\n    \"https://*.preview.example.com\",\n  ],\n  \n  // Rate limiting\n  rateLimit: {\n    enabled: true,\n    storage: \"secondary-storage\",\n    customRules: {\n      \"/api/auth/sign-in/email\": { window: 60, max: 5 },\n      \"/api/auth/sign-up/email\": { window: 60, max: 3 },\n    },\n  },\n  \n  // Session security\n  session: {\n    expiresIn: 60 * 60 * 24 * 7, // 7 days\n    updateAge: 60 * 60 * 24, // 24 hours\n    freshAge: 60 * 60, // 1 hour for sensitive actions\n    cookieCache: {\n      enabled: true,\n      maxAge: 300,\n      strategy: \"jwe\", // Encrypted session data\n    },\n  },\n  \n  // OAuth security\n  account: {\n    encryptOAuthTokens: true,\n    storeStateStrategy: \"cookie\",\n  },\n  \n  \n  // Advanced settings\n  advanced: {\n    useSecureCookies: true,\n    cookiePrefix: \"myapp\",\n    defaultCookieAttributes: {\n      sameSite: \"lax\",\n    },\n    ipAddress: {\n      ipAddressHeaders: [\"x-forwarded-for\"],\n      ipv6Subnet: 64,\n    },\n    backgroundTasks: {\n      handler: (promise) => waitUntil(promise),\n    },\n  },\n  \n  // Security auditing\n  databaseHooks: {\n    session: {\n      create: {\n        after: async ({ data, ctx }) => {\n          console.log(`New session for user ${data.userId}`);\n        },\n      },\n    },\n    user: {\n      update: {\n        after: async ({ data, oldData }) => {\n          if (oldData?.email !== data.email) {\n            console.log(`Email changed for user ${data.id}`);\n          }\n        },\n      },\n    },\n  },\n});\n```\n\n## Security Checklist\n\nBefore deploying to production:\n\n- [ ] **Secret**: Use a strong, unique secret (32+ characters, high entropy)\n- [ ] **HTTPS**: Ensure `baseURL` uses HTTPS\n- [ ] **Trusted Origins**: Configure all valid origins (frontend, mobile apps)\n- [ ] **Rate Limiting**: Keep enabled with appropriate limits\n- [ ] **CSRF Protection**: Keep enabled (`disableCSRFCheck: false`)\n- [ ] **Secure Cookies**: Enabled automatically with HTTPS\n- [ ] **OAuth Tokens**: Consider `encryptOAuthTokens: true` if storing tokens\n- [ ] **Background Tasks**: Configure for serverless platforms\n- [ ] **Audit Logging**: Implement via `databaseHooks` or `hooks`\n- [ ] **IP Tracking**: Configure headers if behind a proxy\n"},"lastSynced":"2026-03-08T02:09:00.760Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing robust authentication and authorization with advanced secret management capabilities.","zh":"非常适合需要强大身份验证和授权功能以及高级密钥管理能力的全栈Agent。","ja":"堅牢な認証と認可機能を備えた高度なシークレット管理機能を必要とするフルスタックエージェントに最適です。","ko":"강력한 인증 및 권한 부여 기능과 고급 비밀 관리 기능이 필요한 풀스택 에이전트에 완벽합니다.","es":"Perfecto para Agentes Full-Stack que necesitan una autenticación y autorización robusta con capacidades avanzadas de gestión de secretos.","fr":"Parfait pour les Agents Full-Stack nécessitant une authentification et une autorisation robustes avec des capacités avancées de gestion des secrets.","de":"Perfekt für Full-Stack Agents, die eine robuste Authentifizierung und Autorisierung mit erweiterten Fähigkeiten zur Geheimnisverwaltung benötigen.","pt":"Perfeito para Agentes Full-Stack que necessitam de autenticação e autorização robustas com capacidades avançadas de gerenciamento de segredos.","ru":"Идеально подходит для агентов Full-Stack, которым требуются надежная аутентификация и авторизация с продвинутыми возможностями управления секретами.","ar":"مثالي للوكلاء المتكاملين الذين يحتاجون إلى مصادقة قوية وتصريح مع إمكانيات إدارة السر المتقدمة."},"recommendation":{"en":"Empowers agents to secure full-stack apps with best-in-class auth integrations, utilizing environment variables and secure cookie generation via the Better Auth library, while configuring secrets through options.secret or the BETTER_AUTH_SECRET environment variable.","zh":"通过Better Auth库利用环境变量和安全cookie生成，同时通过options.secret或BETTER_AUTH_SECRET环境变量配置密钥，使Agent能够使用一流的身份验证集成来保护全栈应用程序的安全。","ja":"Better Authライブラリを使用して環境変数と安全なCookie生成を活用し、options.secretまたはBETTER_AUTH_SECRET環境変数を介してシークレットを設定しながら、エージェントが一流の認証統合でフルスタックアプリケーションを保護できるようにします。","ko":"Better Auth 라이브러리를 통해 환경 변수와 보안 쿠키 생성을 활용하고, options.secret 또는 BETTER_AUTH_SECRET 환경 변수를 통해 시크릿을 구성하여 에이전트가 최고 수준의 인증 통합으로 풀스택 애플리케이션을 보호할 수 있도록 합니다.","es":"Permite a los agentes proteger aplicaciones full-stack con integraciones de autenticación de primer nivel, utilizando variables de entorno y generación segura de cookies a través de la biblioteca Better Auth, mientras configura los secretos mediante options.secret o la variable de entorno BETTER_AUTH_SECRET.","fr":"Permet aux agents de sécuriser les applications full-stack avec des intégrations d''authentification de premier ordre, en utilisant des variables d''environnement et la génération sécurisée de cookies via la bibliothèque Better Auth, tout en configurant les secrets via options.secret ou la variable d''environnement BETTER_AUTH_SECRET.","de":"Ermöglicht es Agents, Full-Stack-Apps mit erstklassigen Auth-Integrationen zu sichern, indem sie Umgebungsvariablen und die sichere Cookie-Generierung über die Better Auth-Bibliothek nutzen, während sie Geheimnisse über options.secret oder die Umgebungsvariable BETTER_AUTH_SECRET konfigurieren.","pt":"Habilita os agentes a proteger aplicativos full-stack com as melhores integrações de autenticação, utilizando variáveis de ambiente e geração de cookies seguros via a biblioteca Better Auth, ao mesmo tempo em que configura segredos por meio de options.secret ou da variável de ambiente BETTER_AUTH_SECRET.","ru":"Наделяет агентов возможностью защищать полнофункциональные приложения с помощью лучших интеграций аутентификации, используя переменные среды и безопасную генерацию файлов cookie через библиотеку Better Auth, а также настраивает секреты через options.secret или переменную среды BETTER_AUTH_SECRET.","ar":"يمنح الوكلاء إمكانية حماية التطبيقات المتكاملة بأفضل إدماجات المصادقة، باستخدام متغيرات البيئة وتوليد ملفات تعريف الارتباط الآمنة عبر مكتبة Better Auth، وفي الوقت نفسه يضبط السر من خلال options.secret أو متغير البيئة BETTER_AUTH_SECRET."},"useCases":{"en":["Configuring auth secrets for secure session token signing","Encrypting sensitive data with robust authentication measures","Generating secure cookies for full-stack applications"],"zh":["配置身份验证密钥以进行安全的会话令牌签名","通过强大的身份验证措施加密敏感数据","为全栈应用程序生成安全cookie"],"ja":["安全なセッショントークン署名のための認証シークレットの設定","堅牢な認証措置による機密データの暗号化","フルスタックアプリケーションのための安全なCookieの生成"],"ko":["보안 세션 토큰 서명을 위한 인증 시크릿 구성","강력한 인증 조치로 민감한 데이터 암호화","풀스택 애플리케이션을 위한 보안 쿠키 생성"],"es":["Configurar secretos de autenticación para la firma segura de tokens de sesión","Cifrar datos sensibles con medidas de autenticación robustas","Generar cookies seguras para aplicaciones full-stack"],"fr":["Configuration des secrets d''authentification pour la signature sécurisée des jetons de session","Chiffrement des données sensibles avec des mesures d''authentification robustes","Génération de cookies sécurisés pour les applications full-stack"],"de":["Konfigurieren von Auth-Geheimnissen für die sichere Signierung von Sitzungstokens","Verschlüsseln sensibler Daten mit robusten Authentifizierungsmaßnahmen","Generieren sicherer Cookies für Full-Stack-Anwendungen"],"pt":["Configurando segredos de autenticação para assinatura de token de sessão segura","Criptografando dados sensíveis com medidas de autenticação robustas","Gerando cookies seguros para aplicativos full-stack"],"ru":["Настройка секретов аутентификации для безопасного подписания сессионных токенов","Шифрование чувствительных данных с помощью надежных мер аутентификации","Генерация безопасных файлов cookie для полнофункциональных приложений"],"ar":["تكوين أسرار المصادقة لتوقيع رموز الجلسة الآمنة","تشفير البيانات الحساسة بإجراءات مصادقة قوية","توليد ملفات تعريف الارتباط الآمنة للتطبيقات المتكاملة"]},"limitations":{"en":["Requires Better Auth library installation","Dependent on environment variable or options.secret configuration"],"zh":["需要安装Better Auth库","依赖于环境变量或options.secret配置"],"ja":["Better Authライブラリのインストールが必要","環境変数またはoptions.secret設定に依存"],"ko":["Better Auth 라이브러리 설치 필요","환경 변수 또는 options.secret 구성에 의존"],"es":["Requiere la instalación de la biblioteca Better Auth","Depende de la variable de entorno o de la configuración options.secret"],"fr":["Nécessite l''installation de la bibliothèque Better Auth","Dépend de la variable d''environnement ou de la configuration options.secret"],"de":["Erfordert die Installation der Better Auth-Bibliothek","Abhängig von der Umgebungsvariable oder der options.secret-Konfiguration"],"pt":["Exige a instalação da biblioteca Better Auth","Dependente da configuração da variável de ambiente ou options.secret"],"ru":["Требует установки библиотеки Better Auth","Зависит от настройки переменной среды или options.secret"],"ar":["يتطلب تثبيت مكتبة Better Auth","يعتمد على تكوين متغير البيئة أو options.secret"]},"version":4},"contentHash":"5124e42ccce39e04996fc4aa273154fdc2ff3827d174901913d777a72b3bbcd7","qualityScore":36}');
