INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Velocity-Alpha/ai-recap-newsletter/design', 'design', 'Velocity-Alpha', 'ai-recap-newsletter', 'community', 'design Velocity-Alpha ai-recap-newsletter community The design skill provides a technical framework for creating a daily briefing UI with a unique watercolor style and typography-driven structure, benefiting AI agent developers AI 设计系统采用水彩风格和编辑设计理念，旨在打造独特的用户界面 AI エージェントのデザインシステムは、水彩スタイルと編集デザイン哲学を使用してユニークなユーザーインターフェースを構築します AI 디자인 시스템은 수채화 스타일과 편집 디자인 철학을 사용하여 고유한 사용자 인터페이스를 구축합니다 El sistema de diseño de AI Recap se basa en ilustraciones de acuarela y tipografía minimalista para crear experiencias de usuario únicas Le système de conception de l''AI Recap repose sur des illustrations à l''aquarelle et une typographie minimaliste pour créer des expériences utilisateur uniques Das Design-System von AI Recap basiert auf Aquarell-Illustrationen und minimalistischer Typografie, um benutzerdefinierte Erlebnisse zu schaffen O design para ferramentas de IA deve ser editorial, não corporativo, com ilustrações em watercolor e tipografia elegante. Дизайн для ИИ Агентов должен быть редакционным, а не корпоративным, с иллюстрациями в стиле водяных красок и элегантной типографией. يجب أن يكون تصميم أدوات الذكاء الاصطناعي تحريرياً، وليس شركياً، مع رسومات مائية وطباعة أنيقة. how to use design in ai agents what is design system in ai design alternative for ai agents design vs material ui for ai design install guide for ai agents design setup tutorial for developers ai agent design best practices design philosophy for ai interfaces watercolor design in ai agents AI 设计系统 水彩风格 编辑设计理念 用户界面设计 空白空间设计 排版设计 颜色设计 UI 设计 Utilizes loose watercolor washes in muted blues, rusts, and sages for illustrations Employs typography and whitespace to create a quiet confidence UI Supports a non-corporate sterility design philosophy Incorporates soft edges and organic warmth in UI components Leverages color to support structure and action in the design system Design is a technical system for creating authoritative and handcrafted UI components with soft edges, organic warmth, and muted color palettes');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('StarKnightt/MineCraft/web-games', 'community', 'StarKnightt', 'MineCraft', 'StarKnightt/MineCraft', 'web-games', 0, 0, 36, '2026-03-08T01:57:15.463Z', '2026-03-08T02:09:19.339Z', '1213dbf108ac6a56c7c2cb67e81705b10cf0b9d136fa775ad161273bfe452a90', '{"id":"StarKnightt/MineCraft/web-games","name":"web-games","description":{"en":"The web-games skill enables developers to craft engaging browser games with vibe, utilizing frameworks like Phaser, PixiJS, Babylon.js, and Three.js. It benefits web developers and game designers.","zh":"Web游戏开发框架选择指南，帮助您为项目选择合适的技术栈","ja":"Webゲーム開発のためのフレームワーク選定ガイド。プロジェクトに最適な技術スタックを選択するためのヒント","ko":"웹 게임 개발을 위한 프레임워크 선택 가이드: 프로젝트에 적합한 기술 스택을 선택하는 방법","es":"El desarrollo de juegos web implica la selección de frameworks adecuados como Phaser, PixiJS, Babylon.js y Three.js. Aprende a elegir el framework correcto para tu juego.","fr":"Le développement de jeux web implique la sélection de frameworks appropriés tels que Phaser, PixiJS, Babylon.js et Three.js. Apprenez à choisir le framework correct pour votre jeu.","de":"Die Entwicklung von Web-Spielen beinhaltet die Auswahl geeigneter Frameworks wie Phaser, PixiJS, Babylon.js und Three.js. Erfahren Sie, wie Sie das richtige Framework für Ihr Spiel auswählen.","pt":"Desenvolva jogos para navegador com frameworks como Phaser e PixiJS. Aprenda a escolher o framework certo para o seu jogo","ru":"Разрабатывайте браузерные игры с помощью фреймворков như Babylon.js и Three.js. Выберите правильный фреймворк для вашей игры с ИИ Агентами","ar":"قم بإنشاء ألعاب للويب باستخدام إطارات مثل Phaser و PixiJS. اختر الإطار الصحيح للعبة الخاصة بك مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"web-games: Browser Game Development Setup Guide | AI Agen...","zh":"Web游戏开发框架选择指南","ja":"Webゲーム開発フレームワーク選定ガイド - AIエージェント","ko":"웹 게임 개발을 위한 최적의 프레임워크 선택하기","es":"Desar