INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StarKnightt/MineCraft/web-games', 'web-games', 'StarKnightt', 'MineCraft', 'community', 'web-games StarKnightt MineCraft community The web-games skill enables developers to craft engaging browser games with vibe, utilizing frameworks like Phaser, PixiJS, Babylon.js, and Three.js. It benefits web developers and game designers. Web游戏开发框架选择指南，帮助您为项目选择合适的技术栈 Webゲーム開発のためのフレームワーク選定ガイド。プロジェクトに最適な技術スタックを選択するためのヒント 웹 게임 개발을 위한 프레임워크 선택 가이드: 프로젝트에 적합한 기술 스택을 선택하는 방법 El desarrollo de juegos web implica la selección de frameworks adecuados como Phaser, PixiJS, Babylon.js y Three.js. Aprende a elegir el framework correcto para tu juego. Le développement de jeux web implique la sélection de frameworks appropriés tels que Phaser, PixiJS, Babylon.js et Three.js. Apprenez à choisir le framework correct pour votre jeu. Die Entwicklung von Web-Spielen beinhaltet die Auswahl geeigneter Frameworks wie Phaser, PixiJS, Babylon.js und Three.js. Erfahren Sie, wie Sie das richtige Framework für Ihr Spiel auswählen. Desenvolva jogos para navegador com frameworks como Phaser e PixiJS. Aprenda a escolher o framework certo para o seu jogo Разрабатывайте браузерные игры с помощью фреймворков như Babylon.js и Three.js. Выберите правильный фреймворк для вашей игры с ИИ Агентами قم بإنشاء ألعاب للويب باستخدام إطارات مثل Phaser و PixiJS. اختر الإطار الصحيح للعبة الخاصة بك مع أدوات الذكاء الاصطناعي how to use web-games web-games framework selection web-games vs Phaser web-games setup guide web-games install what is web-games web-games alternative web-games browser game development web-games 2D game development web-games 3D game development Web游戏开发 游戏开发框架 Phaser PixiJS Babylon.js Three.js Web游戏开发工具 游戏开发技术 Web游戏开发指南 Utilizes Phaser for 2D game development with full game engine features Leverages PixiJS for raw rendering power in 2D games Employs Babylon.js for 3D game development with physics and XR support Supports Three.js for rendering-focused 3D game development Allows for custom game development using Raw Canvas and WebGL web-games is a skill for developing web-based games, focusing on framework selection and browser-specific principles for 2D and 3D game development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Mona-kecil/kecildotdev/slack-gif-creator', 'community', 'Mona-kecil', 'kecildotdev', 'Mona-kecil/kecildotdev', 'slack-gif-creator', 0, 0, 36, '2026-03-08T01:57:15.464Z', '2026-03-08T02:09:20.980Z', '2efca615ce55a3edd8fc05c779068a8085816617991987e446606403cd3abb22', '{"id":"Mona-kecil/kecildotdev/slack-gif-creator","name":"slack-gif-creator","description":{"en":"The slack-gif-creator skill provides utilities for creating animated GIFs optimized for Slack, benefiting developers and designers. It offers a core workflow for building GIFs with specific dimensions and parameters.","zh":"Slack GIF Creator是一款工具包，提供创建优化的动态GIF的技术和知识","ja":"Slack GIF作成ツールは、最適化された動画GIFを作成するためのユーティリティと知識を提供するツールキットです","ko":"슬랙 GIF 생성기는 최적화된 애니메이션 GIF를 생성하기 위한 유틸리티와 지식을 제공하는 툴킷입니다","es":"Slack GIF Creator es un toolkit técnico que proporciona utilidades en Python para generar GIFs animados optimizados específicamente para la plataforma Slack, cumpliendo con sus requisitos de dimensiones y rendimiento.","fr":"Slack GIF Creator est une boîte à outils technique fournissant des utilitaires en Python pour générer des GIFs animés optimisés spécifiquement pour la plateforme Slack, respectant ses exigences de dimensions et de performances.","de":"Slack GIF Creator ist ein Toolkit, das Python-Utilities zur Generierung von animierten GIFs bietet, die speziell für die Slack-Plattform optimiert sind und deren Anforderungen an Abmessungen und Leistung erfüllen.","pt":"O Slack GIF Creator é uma ferramenta que fornece utilitários e conhecimentos para criar GIFs animados otimizados para o Slack.","ru":"Slack GIF Creator - это набор инструментов, предоставляющий утилиты и знания для создания анимированных GIF-файлов, оптимизированных для Slack.","ar":"معدّ GIF في سلاك هو أداة توفر أدوات و معارف لإنشاء صور GIF متحركة محسّنة لسلاك"},"seo":{"title":{"en":"slack-gif-creator: Animated GIF Setup Guide for AI Agents...","zh":"Slack GIF Creator 工具包设置指南","ja":"Slack GIF作成ツールのベストプラクティス","ko":"슬랙 GIF 생성기 설정 가이드","es":"Slack GIF Creator: Guía de Configuración y Mejores Prácticas","fr":"Slack GIF Creator : Guide d''Installation et Bonnes Pratiques","de":"Slack GIF Creator: Setup-Anleitung und Best Practices","pt":"Guia de Configuração do Criador de GIFs do Slack","ru":"Настройка ИИ Агента Slack GIF Creator","ar":"دليل إعداد معدّ GIF في سلاك"},"description":{"en":"Discover how to create optimized animated GIFs for Slack with the slack-gif-creator toolkit. Learn how to get started and optimize your GIFs today!","zh":"了解Slack GIF Creator的技术要求和核心工作流程，创建优化的动态GIF","ja":"Slack GIF作成ツールの仕様とワークフローをマスターして、最適化されたGIFを作成する","ko":"슬랙 GIF 생성기의 기술 요구사항과 핵심 워크플로우를 학습하고 최적화된 GIF를 생성하세요","es":"Herramienta de AI Agents para crear GIFs optimizados para Slack con Python. Especifica dimensiones (128x128, 480x480), FPS (10-30) y paleta de colores para r...","fr":"Outil d''Agents IA pour créer des GIFs optimisés pour Slack avec Python. Définit les dimensions (128x128, 480x480), FPS (10-30) et la palette de couleurs pour...","de":"AI Agents Tool zur Erstellung von für Slack optimierten GIFs mit Python. Legt Abmessungen (128x128, 480x480), FPS (10-30) und Farbpalette fest, um die Dateig...","pt":"Aprenda a criar GIFs animados otimizados para o Slack com nosso guia de configuração","ru":"Изучите, как создавать анимированные GIF-файлы, оптимизированные для Slack, с помощью нашего ИИ Агента","ar":"تعلم كيفية إنشاء صور GIF متحركة محسّنة لبرنامج سلاك باستخدام دليلنا"},"definition":{"en":"slack-gif-creator is a toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack, with specific requirements for dimensions, FPS, colors, and duration.","zh":"Slack GIF Creator是一款创建优化的动态GIF的工具包","ja":"Slack GIF作成ツールは、動画GIFを作成するためのツールキットです","ko":"슬랙 GIF 생성기는 애니메이션 GIF를 생성하기 위한 툴킷입니다","es":"Slack GIF Creator es un skill de AI Agents que ofrece un conjunto de herramientas y conocimientos para la creación de GIFs animados. Se especializa en ajustar parámetros técnicos como dimensiones, FPS y paleta de colores para cumplir con las especificaciones de Slack y optimizar el tamaño del archivo.","fr":"Slack GIF Creator est une compétence d''Agents IA offrant un ensemble d''outils et de connaissances pour la création de GIFs animés. Il spécialise dans le réglage de paramètres techniques comme les dimensions, FPS et la palette de couleurs pour respecter les spécifications de Slack et optimiser la taille des fichiers.","de":"Slack GIF Creator ist ein AI Agents Skill, der einen Werkzeugsatz und Know-how für die Erstellung animierter GIFs bereitstellt. Er spezialisiert sich auf die Anpassung technischer Parameter wie Abmessungen, FPS und Farbpalette, um den Slack-Spezifikationen zu entsprechen und die Dateigröße zu optimieren.","pt":"O que é o Slack GIF Creator? É uma ferramenta para criar GIFs animados otimizados para o Slack.","ru":"Что такое Slack GIF Creator? Это инструмент для создания анимированных GIF-файлов, оптимизированных для Slack.","ar":"ما هو معدّ GIF في سلاك؟ هو أداة لإنشاء صور GIF متحركة محسّنة لسلاك"},"features":{"en":["Creates animated GIFs with recommended dimensions of 128x128 for emoji GIFs and 480x480 for message GIFs","Supports FPS range of 10-30 for customizable file size","Allows for color customization with 48-128 colors for optimized file size","Enables creation of GIFs with duration under 3 seconds for emoji GIFs","Utilizes Python and PIL libraries for GIF building and image manipulation"],"zh":["支持创建128x128和480x480像素的GIF","可调整FPS、颜色和持续时间以优化GIF","使用Python和PIL库创建GIF","提供核心工作流程以简化GIF创建","支持创建emoji和message GIF"],"ja":["128x128と480x480ピクセルのGIFを作成することが可能","FPS、色、期間を調整してGIFを最適化する","PythonとPILライブラリを使用してGIFを作成する","コアワークフローを提供してGIFの作成を簡素化する","絵文字とメッセージGIFの作成をサポートする"],"ko":["128x128과 480x480 픽셀의 GIF 생성 지원","FPS, 색상, 지속 시간을 조정하여 GIF 최적화","Python과 PIL 라이브러리를 사용하여 GIF 생성","핵심 워크플로우를 제공하여 GIF 생성을 간소화","이모티콘과 메시지 GIF 생성 지원"],"es":["Generación de GIFs para emojis (128x128) y mensajes (480x480)","Control de FPS entre 10-30 para gestionar el tamaño del archivo","Optimización de la paleta de colores (48-128 colores)","Limitación de duración (menos de 3 segundos para emojis)","Integración con bibliotecas Python como PIL (Pillow)","Uso de la clase `GIFBuilder` para la construcción programática"],"fr":["Génération de GIFs pour emojis (128x128) et messages (480x480)","Contrôle du FPS entre 10-30 pour gérer la taille des fichiers","Optimisation de la palette de couleurs (48-128 couleurs)","Limitation de la durée (moins de 3 secondes pour les emojis)","Intégration avec des bibliothèques Python comme PIL (Pillow)","Utilisation de la classe `GIFBuilder` pour une construction programmatique"],"de":["Generierung von GIFs für Emojis (128x128) und Nachrichten (480x480)","FPS-Kontrolle zwischen 10-30 zur Verwaltung der Dateigröße","Optimierung der Farbpalette (48-128 Farben)","Begrenzung der Dauer (unter 3 Sekunden für Emojis)","Integration mit Python-Bibliotheken wie PIL (Pillow)","Verwendung der `GIFBuilder`-Klasse für die programmatische Erstellung"],"pt":["Suporte a dimensões de 128x128 para emojis GIF","Suporte a dimensões de 480x480 para mensagens GIF","Controle de FPS entre 10-30","Controle de cores entre 48-128","Duração máxima de 3 segundos para emojis GIF"],"ru":["Поддержка размеров 128x128 для эмодзи GIF","Поддержка размеров 480x480 для сообщений GIF","Контроль FPS между 10-30","Контроль цветов между 48-128","Максимальная продолжительность 3 секунд для эмодзи GIF"],"ar":["دعم لأبعاد 128x128 لصور GIF الإيموجي","دعم لأبعاد 480x480 لرسائل GIF","تحكم في معدل الإطار بين 10-30","تحكم في الألوان بين 48-128","مدة أقصى 3 ثوانٍ لصور GIF الإيموجي"]},"keywords":{"en":["how to use slack-gif-creator","slack-gif-creator alternative","slack-gif-creator setup guide","what is slack-gif-creator","slack-gif-creator vs giflib","slack-gif-creator install","creating animated gifs for slack","optimized gif dimensions for slack","slack gif creator python library"],"zh":["Slack GIF Creator","动态GIF创建","Python GIF库","PIL库","GIF优化","Slack工具包","AIエージェント工具"],"ja":["Slack GIF作成ツール","動画GIF作成","Python GIFライブラリ","PILライブラリ","GIF最適化","Slackツールキット","AIエージェントツール"],"ko":["슬랙 GIF 생성기","애니메이션 GIF 생성","Python GIF 라이브러리","PIL 라이브러리","GIF 최적화","슬랙 툴킷","AI 에이전트 툴"],"es":["slack gif creator python","crear gifs para slack emoji","optimizar gif para slack","slack gif dimensions 128x128","python pil crear gif animado","ai agents herramientas desarrollo","slack gif builder library","reducir tamaño gif slack"],"fr":["slack gif creator python","créer gif pour slack emoji","optimiser gif pour slack","slack gif dimensions 128x128","python pil créer gif animé","agents ia outils développement","slack gif builder library","réduire taille fichier gif slack"],"de":["slack gif creator python","gif für slack emoji erstellen","gif für slack optimieren","slack gif abmessungen 128x128","python pil animiertes gif erstellen","ai agents entwicklungswerkzeuge","slack gif builder bibliothek","gif dateigröße reduzieren slack"],"pt":["slack gif creator","criar gif para slack","otimizar gif para slack","dimensões de gif para slack","fps de gif para slack","cores de gif para slack"],"ru":["slack gif creator","создать gif для slack","оптимизировать gif для slack","размеры gif для slack","fps gif для slack","цвета gif для slack"],"ar":["معدّ GIF في سلاك","إنشاء صور GIF لمدينة سلاك","تحسين صور GIF لسلاك","أبعاد صور GIF لسلاك","معدل الإطار لصور GIF لسلاك","ألوان صور GIF لسلاك"]}},"owner":"Mona-kecil","repo":"kecildotdev","repoPath":"Mona-kecil/kecildotdev","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.464Z","topics":[],"category":"community","skillMd":{"name":"slack-gif-creator","description":"Knowledge and utilities for creating animated GIFs optimized for Slack. Provides constraints, validation tools, and animation concepts. Use when users request animated GIFs for Slack like make me a GIF of X doing Y for Slack.","bodyPreview":"# Slack GIF Creator\n\nA toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack.\n\n## Slack Requirements\n\n**Dimensions:**\n- Emoji GIFs: 128x128 (recommended)\n- Message GIFs: 480x480\n\n**Parameters:**\n- FPS: 10-30 (lower is smaller file size)\n- Colors: 48-128 (fewer = smaller file size)\n- Duration: Keep under 3 seconds for emoji GIFs\n\n## Core Workflow\n\n```python\nfrom core.gif_builder import GIFBuilder\nfrom PIL import Image, ImageDraw\n\n# 1. Create builder\nbuilder = GI","body":"# Slack GIF Creator\n\nA toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack.\n\n## Slack Requirements\n\n**Dimensions:**\n- Emoji GIFs: 128x128 (recommended)\n- Message GIFs: 480x480\n\n**Parameters:**\n- FPS: 10-30 (lower is smaller file size)\n- Colors: 48-128 (fewer = smaller file size)\n- Duration: Keep under 3 seconds for emoji GIFs\n\n## Core Workflow\n\n```python\nfrom core.gif_builder import GIFBuilder\nfrom PIL import Image, ImageDraw\n\n# 1. Create builder\nbuilder = GIFBuilder(width=128, height=128, fps=10)\n\n# 2. Generate frames\nfor i in range(12):\n    frame = Image.new(''RGB'', (128, 128), (240, 248, 255))\n    draw = ImageDraw.Draw(frame)\n\n    # Draw your animation using PIL primitives\n    # (circles, polygons, lines, etc.)\n\n    builder.add_frame(frame)\n\n# 3. Save with optimization\nbuilder.save(''output.gif'', num_colors=48, optimize_for_emoji=True)\n```\n\n## Drawing Graphics\n\n### Working with User-Uploaded Images\nIf a user uploads an image, consider whether they want to:\n- **Use it directly** (e.g., \"animate this\", \"split this into frames\")\n- **Use it as inspiration** (e.g., \"make something like this\")\n\nLoad and work with images using PIL:\n```python\nfrom PIL import Image\n\nuploaded = Image.open(''file.png'')\n# Use directly, or just as reference for colors/style\n```\n\n### Drawing from Scratch\nWhen drawing graphics from scratch, use PIL ImageDraw primitives:\n\n```python\nfrom PIL import ImageDraw\n\ndraw = ImageDraw.Draw(frame)\n\n# Circles/ovals\ndraw.ellipse([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Stars, triangles, any polygon\npoints = [(x1, y1), (x2, y2), (x3, y3), ...]\ndraw.polygon(points, fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Lines\ndraw.line([(x1, y1), (x2, y2)], fill=(r, g, b), width=5)\n\n# Rectangles\ndraw.rectangle([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n```\n\n**Don''t use:** Emoji fonts (unreliable across platforms) or assume pre-packaged graphics exist in this skill.\n\n### Making Graphics Look Good\n\nGraphics should look polished and creative, not basic. Here''s how:\n\n**Use thicker lines** - Always set `width=2` or higher for outlines and lines. Thin lines (width=1) look choppy and amateurish.\n\n**Add visual depth**:\n- Use gradients for backgrounds (`create_gradient_background`)\n- Layer multiple shapes for complexity (e.g., a star with a smaller star inside)\n\n**Make shapes more interesting**:\n- Don''t just draw a plain circle - add highlights, rings, or patterns\n- Stars can have glows (draw larger, semi-transparent versions behind)\n- Combine multiple shapes (stars + sparkles, circles + rings)\n\n**Pay attention to colors**:\n- Use vibrant, complementary colors\n- Add contrast (dark outlines on light shapes, light outlines on dark shapes)\n- Consider the overall composition\n\n**For complex shapes** (hearts, snowflakes, etc.):\n- Use combinations of polygons and ellipses\n- Calculate points carefully for symmetry\n- Add details (a heart can have a highlight curve, snowflakes have intricate branches)\n\nBe creative and detailed! A good Slack GIF should look polished, not like placeholder graphics.\n\n## Available Utilities\n\n### GIFBuilder (`core.gif_builder`)\nAssembles frames and optimizes for Slack:\n```python\nbuilder = GIFBuilder(width=128, height=128, fps=10)\nbuilder.add_frame(frame)  # Add PIL Image\nbuilder.add_frames(frames)  # Add list of frames\nbuilder.save(''out.gif'', num_colors=48, optimize_for_emoji=True, remove_duplicates=True)\n```\n\n### Validators (`core.validators`)\nCheck if GIF meets Slack requirements:\n```python\nfrom core.validators import validate_gif, is_slack_ready\n\n# Detailed validation\npasses, info = validate_gif(''my.gif'', is_emoji=True, verbose=True)\n\n# Quick check\nif is_slack_ready(''my.gif''):\n    print(\"Ready!\")\n```\n\n### Easing Functions (`core.easing`)\nSmooth motion instead of linear:\n```python\nfrom core.easing import interpolate\n\n# Progress from 0.0 to 1.0\nt = i / (num_frames - 1)\n\n# Apply easing\ny = interpolate(start=0, end=400, t=t, easing=''ease_out'')\n\n# Available: linear, ease_in, ease_out, ease_in_out,\n#           bounce_out, elastic_out, back_out\n```\n\n### Frame Helpers (`core.frame_composer`)\nConvenience functions for common needs:\n```python\nfrom core.frame_composer import (\n    create_blank_frame,         # Solid color background\n    create_gradient_background,  # Vertical gradient\n    draw_circle,                # Helper for circles\n    draw_text,                  # Simple text rendering\n    draw_star                   # 5-pointed star\n)\n```\n\n## Animation Concepts\n\n### Shake/Vibrate\nOffset object position with oscillation:\n- Use `math.sin()` or `math.cos()` with frame index\n- Add small random variations for natural feel\n- Apply to x and/or y position\n\n### Pulse/Heartbeat\nScale object size rhythmically:\n- Use `math.sin(t * frequency * 2 * math.pi)` for smooth pulse\n- For heartbeat: two quick pulses then pause (adjust sine wave)\n- Scale between 0.8 and 1.2 of base size\n\n### Bounce\nObject falls and bounces:\n- Use `interpolate()` with `easing=''bounce_out''` for landing\n- Use `easing=''ease_in''` for falling (accelerating)\n- Apply gravity by increasing y velocity each frame\n\n### Spin/Rotate\nRotate object around center:\n- PIL: `image.rotate(angle, resample=Image.BICUBIC)`\n- For wobble: use sine wave for angle instead of linear\n\n### Fade In/Out\nGradually appear or disappear:\n- Create RGBA image, adjust alpha channel\n- Or use `Image.blend(image1, image2, alpha)`\n- Fade in: alpha from 0 to 1\n- Fade out: alpha from 1 to 0\n\n### Slide\nMove object from off-screen to position:\n- Start position: outside frame bounds\n- End position: target location\n- Use `interpolate()` with `easing=''ease_out''` for smooth stop\n- For overshoot: use `easing=''back_out''`\n\n### Zoom\nScale and position for zoom effect:\n- Zoom in: scale from 0.1 to 2.0, crop center\n- Zoom out: scale from 2.0 to 1.0\n- Can add motion blur for drama (PIL filter)\n\n### Explode/Particle Burst\nCreate particles radiating outward:\n- Generate particles with random angles and velocities\n- Update each particle: `x += vx`, `y += vy`\n- Add gravity: `vy += gravity_constant`\n- Fade out particles over time (reduce alpha)\n\n## Optimization Strategies\n\nOnly when asked to make the file size smaller, implement a few of the following methods:\n\n1. **Fewer frames** - Lower FPS (10 instead of 20) or shorter duration\n2. **Fewer colors** - `num_colors=48` instead of 128\n3. **Smaller dimensions** - 128x128 instead of 480x480\n4. **Remove duplicates** - `remove_duplicates=True` in save()\n5. **Emoji mode** - `optimize_for_emoji=True` auto-optimizes\n\n```python\n# Maximum optimization for emoji\nbuilder.save(\n    ''emoji.gif'',\n    num_colors=48,\n    optimize_for_emoji=True,\n    remove_duplicates=True\n)\n```\n\n## Philosophy\n\nThis skill provides:\n- **Knowledge**: Slack''s requirements and animation concepts\n- **Utilities**: GIFBuilder, validators, easing functions\n- **Flexibility**: Create the animation logic using PIL primitives\n\nIt does NOT provide:\n- Rigid animation templates or pre-made functions\n- Emoji font rendering (unreliable across platforms)\n- A library of pre-packaged graphics built into the skill\n\n**Note on user uploads**: This skill doesn''t include pre-built graphics, but if a user uploads an image, use PIL to load and work with it - interpret based on their request whether they want it used directly or just as inspiration.\n\nBe creative! Combine concepts (bouncing + rotating, pulsing + sliding, etc.) and use PIL''s full capabilities.\n\n## Dependencies\n\n```bash\npip install pillow imageio numpy\n```\n"},"lastSynced":"2026-03-08T02:09:20.980Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual Content Agents needing advanced animated GIF creation capabilities for Slack.","zh":"非常适合需要高级动画GIF创建功能的Visual Content Agents使用Slack。","ja":"Slackで高度なアニメーションGIF作成機能を必要とするVisual Content Agentsに最適です。","ko":"Slack에서 고급 애니메이션 GIF 생성 기능을 필요한 비주얼 콘텐츠 에이전트에 적합합니다.","es":"Perfecto para agentes de contenido visual que necesitan capacidades avanzadas de creación de GIF animados para Slack.","fr":"Parfait pour les agents de contenu visuel ayant besoin de capacités avancées de création de GIF animés pour Slack.","de":"Perfekt für visuelle Inhaltsagenten, die erweiterte Funktionen zur Erstellung von animierten GIFs für Slack benötigen.","pt":"Perfeito para Agentes de Conteúdo Visual que precisam de capacidades avançadas de criação de GIFs animados para Slack.","ru":"Идеально подходит для Визуальных Контент Агентов, которым необходимы расширенные возможности создания анимированных GIF для Slack.","ar":"مثالي للوكلاء المحتوى المرئي الذين يحتاجون إلى مواصفات متقدمة لإنشاء ملفات GIF المتحركة لبرنامج Slack."},"recommendation":{"en":"Empowers agents to generate optimized animated GIFs using Python and the PIL library, with specific dimensions and parameters such as 128x128 for emoji GIFs and 480x480 for message GIFs, while controlling FPS, colors, and duration.","zh":"使代理能够使用Python和PIL库生成优化的动画GIF，具有特定的尺寸和参数，例如128x128用于表情GIF，480x480用于消息GIF，同时控制FPS、颜色和持续时间。","ja":"PythonとPILライブラリを使用して、特定のサイズとパラメータ（例：128x128のemoji GIF、480x480のメッセージGIF）で最適化されたアニメーションGIFを生成できるようにエージェントをEmpowerし、FPS、色、期間を制御します。","ko":"Python과 PIL 라이브러리를 사용하여 특정 크기와 매개변수(예: 이모티콘 GIF의 128x128, 메시지 GIF의 480x480)를 갖는 최적화된 애니메이션 GIF를 생성할 수 있도록 에이전트를 능력화하며, FPS, 색상 및 기간을 제어합니다.","es":"Habilita a los agentes a generar GIFs animados optimizados utilizando Python y la biblioteca PIL, con dimensiones y parámetros específicos como 128x128 para GIFs de emojis y 480x480 para GIFs de mensajes, mientras controla los FPS, colores y duración.","fr":"Permet aux agents de générer des GIFs animés optimisés en utilisant Python et la bibliothèque PIL, avec des dimensions et des paramètres spécifiques tels que 128x128 pour les GIFs d''émoticônes et 480x480 pour les GIFs de messages, tout en contrôlant les FPS, les couleurs et la durée.","de":"Ermöglicht es Agenten, optimierte animierte GIFs mithilfe von Python und der PIL-Bibliothek zu generieren, mit spezifischen Abmessungen und Parametern wie 128x128 für Emoticon-GIFs und 480x480 für Nachrichten-GIFs, während sie die Bildwiederholfrequenz, Farben und Dauer steuern.","pt":"Habilita os agentes a gerar GIFs animados otimizados usando Python e a biblioteca PIL, com dimensões e parâmetros específicos, como 128x128 para GIFs de emoji e 480x480 para GIFs de mensagem, controlando FPS, cores e duração.","ru":"Наделяет агентов возможностью генерировать оптимизированные анимированные GIF, используя Python и библиотеку PIL, с определенными размерами и параметрами, такими как 128x128 для GIF-эмоций и 480x480 для GIF-сообщений, контролируя FPS, цвета и продолжительность.","ar":"يمنح الوكلاء khảية إنشاء ملفات GIF المتحركة المُحسّنة باستخدام Python ومكتبة PIL، مع أبعاد ومؤشرات محددة، مثل 128x128 لملفات GIF الإيموجي و 480x480 لملفات GIF الرسائل، مع التحكم في معدل الإطار وال ألوان والمدة."},"useCases":{"en":["Generating animated GIFs for Slack messaging","Creating optimized emoji GIFs with specific dimensions","Building custom GIFs with controlled FPS and colors"],"zh":["为Slack消息生成动画GIF","创建具有特定尺寸的优化emoji GIF","使用控制的FPS和颜色构建自定义GIF"],"ja":["Slackメッセージ用のアニメーションGIFを生成する","特定のサイズの最適化されたemoji GIFを作成する","制御されたFPSと色でカスタムGIFを構築する"],"ko":["슬랙 메시지용 애니메이션 GIF 생성","특정 크기의 최적화된 이모티콘 GIF 생성","제어된 FPS와 색상으로 사용자 정의 GIF 빌드"],"es":["Generación de GIFs animados para mensajería de Slack","Creación de GIFs de emojis optimizados con dimensiones específicas","Creación de GIFs personalizados con FPS y colores controlados"],"fr":["Génération de GIFs animés pour la messagerie Slack","Création de GIFs d''émoticônes optimisés avec des dimensions spécifiques","Conception de GIFs personnalisés avec des FPS et des couleurs contrôlés"],"de":["Generierung von animierten GIFs für Slack-Nachrichten","Erstellung von optimierten Emoticon-GIFs mit spezifischen Abmessungen","Erstellung von benutzerdefinierten GIFs mit gesteuerter Bildwiederholfrequenz und Farben"],"pt":["Gerar GIFs animados para mensagens do Slack","Criar GIFs de emoji otimizados com dimensões específicas","Construir GIFs personalizados com FPS e cores controlados"],"ru":["Генерировать анимированные GIF для сообщений Slack","Создавать оптимизированные GIF-эмоции с определенными размерами","Строить пользовательские GIF с контролируемым FPS и цветами"],"ar":["إنشاء ملفات GIF المتحركة لمessaging Slack","إنشاء GIFs الإيموجي المُحسّنة بأبعاد محددة","بناء GIFs مخصصة مع FPS وألوان خاضعة للرقابة"]},"limitations":{"en":["Requires Python and PIL library","GIF duration limited to under 3 seconds for emoji GIFs","Specific dimensions required for Slack compatibility"],"zh":["需要Python和PIL库","GIF持续时间限制在3秒以下用于emoji GIF","需要特定尺寸以确保Slack兼容性"],"ja":["PythonとPILライブラリが必要","emoji GIFのGIF期間は3秒未満に制限される","Slackとの互換性を確保するために特定のサイズが必要"],"ko":["Python과 PIL 라이브러리가 필요","이모티콘 GIF의 GIF 기간은 3초 미만으로 제한","슬랙 호환성을 보장하기 위해 특정 크기가 필요"],"es":["Requiere Python y la biblioteca PIL","La duración del GIF está limitada a menos de 3 segundos para GIFs de emojis","Se requieren dimensiones específicas para la compatibilidad con Slack"],"fr":["Nécessite Python et la bibliothèque PIL","La durée du GIF est limitée à moins de 3 secondes pour les GIFs d''émoticônes","Des dimensions spécifiques sont requises pour la compatibilité avec Slack"],"de":["Benötigt Python und die PIL-Bibliothek","Die GIF-Dauer ist für Emoticon-GIFs auf unter 3 Sekunden begrenzt","Spezifische Abmessungen sind für die Slack-Kompatibilität erforderlich"],"pt":["Requer Python e biblioteca PIL","Duração do GIF limitada a menos de 3 segundos para GIFs de emoji","Dimensões específicas necessárias para compatibilidade com o Slack"],"ru":["Требует Python и библиотеку PIL","Продолжительность GIF ограничена менее 3 секунд для GIF-эмоций","Определенные размеры необходимы для совместимости со Slack"],"ar":["يتطلب Python ومكتبة PIL","مدة ملف GIF محدودة بأقل من 3 ثوانٍ لملفات GIF الإيموجي","أبعاد محددة مطلوبة لتوافق Slack"]},"version":4},"contentHash":"2efca615ce55a3edd8fc05c779068a8085816617991987e446606403cd3abb22","qualityScore":36}');
