INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mona-kecil/kecildotdev/slack-gif-creator', 'slack-gif-creator', 'Mona-kecil', 'kecildotdev', 'community', 'slack-gif-creator Mona-kecil kecildotdev community The slack-gif-creator skill provides utilities for creating animated GIFs optimized for Slack, benefiting developers and designers. It offers a core workflow for building GIFs with specific dimensions and parameters. Slack GIF Creator是一款工具包，提供创建优化的动态GIF的技术和知识 Slack GIF作成ツールは、最適化された動画GIFを作成するためのユーティリティと知識を提供するツールキットです 슬랙 GIF 생성기는 최적화된 애니메이션 GIF를 생성하기 위한 유틸리티와 지식을 제공하는 툴킷입니다 Slack GIF Creator es un toolkit técnico que proporciona utilidades en Python para generar GIFs animados optimizados específicamente para la plataforma Slack, cumpliendo con sus requisitos de dimensiones y rendimiento. Slack GIF Creator est une boîte à outils technique fournissant des utilitaires en Python pour générer des GIFs animés optimisés spécifiquement pour la plateforme Slack, respectant ses exigences de dimensions et de performances. Slack GIF Creator ist ein Toolkit, das Python-Utilities zur Generierung von animierten GIFs bietet, die speziell für die Slack-Plattform optimiert sind und deren Anforderungen an Abmessungen und Leistung erfüllen. O Slack GIF Creator é uma ferramenta que fornece utilitários e conhecimentos para criar GIFs animados otimizados para o Slack. Slack GIF Creator - это набор инструментов, предоставляющий утилиты и знания для создания анимированных GIF-файлов, оптимизированных для Slack. معدّ GIF في سلاك هو أداة توفر أدوات و معارف لإنشاء صور GIF متحركة محسّنة لسلاك how to use slack-gif-creator slack-gif-creator alternative slack-gif-creator setup guide what is slack-gif-creator slack-gif-creator vs giflib slack-gif-creator install creating animated gifs for slack optimized gif dimensions for slack slack gif creator python library Slack GIF Creator 动态GIF创建 Python GIF库 PIL库 GIF优化 Slack工具包 AIエージェント工具 Creates animated GIFs with recommended dimensions of 128x128 for emoji GIFs and 480x480 for message GIFs Supports FPS range of 10-30 for customizable file size Allows for color customization with 48-128 colors for optimized file size Enables creation of GIFs with duration under 3 seconds for emoji GIFs Utilizes Python and PIL libraries for GIF building and image manipulation slack-gif-creator is a toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack, with specific requirements for dimensions, FPS, colors, and duration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('skrischer/structcms/write-readme', 'community', 'skrischer', 'structcms', 'skrischer/structcms', 'write-readme', 0, 0, 36, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:25.567Z', '10bec20d80dd02950711a707e2dbb94a8bf15c2086f229fd4e6d39d169505bfd', '{"id":"skrischer/structcms/write-readme","name":"write-readme","description":{"en":"The write-readme skill generates high-quality README files, helping developers describe architecture, purpose, and usage of packages or apps. Ideal for developers seeking to improve their project documentation.","zh":"write-readme是一种优化README配置的技术，通过遵循特定的原则和规则，提高代码质量和可读性","ja":"write-readmeは、READMEの設定を最適化する技術です。特定の原則とルールに従って、コードの品質と可読性を向上させます","ko":"write-readme는 README 설정을 최적화하는 기술입니다. 특정한 원칙과 규칙을 따름으로써 코드의 품질과 가독성을 향상시킵니다","es":"El skill write-readme proporciona una guía para escribir READMEs claros y concisos, enfocándose en la arquitectura, propósito y uso de paquetes y aplicaciones","fr":"Le skill write-readme fournit un guide pour écrire des README clairs et concis, en se concentrant sur l''architecture, le but et l''utilisation des paquets et applications","de":"Der Skill write-readme bietet eine Anleitung zum Schreiben von klaren und knappen README-Dateien, die sich auf Architektur, Zweck und Verwendung von Paketen und Anwendungen konzentriert","pt":"O agente write-readme ajuda a criar READMEs que descrevem a arquitetura, propósito e uso de pacotes e apps, sem duplicar código.","ru":"Агент write-readme помогает создавать README, которые описывают архитектуру, назначение и использование пакетов и приложений, без дублирования кода.","ar":"يساعد وكيل write-readme في إنشاء ملفات README التي تصف الهندسة المعمارية والغرض واستخدام الحزم والتطبيقات، دون تكرار الكود."},"seo":{"title":{"en":"write-readme: README Setup Guide for AI Agents","zh":"write-readme Setup Guide: 优化README配置","