INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('skrischer/structcms/write-readme', 'write-readme', 'skrischer', 'structcms', 'community', 'write-readme skrischer structcms community The write-readme skill generates high-quality README files, helping developers describe architecture, purpose, and usage of packages or apps. Ideal for developers seeking to improve their project documentation. write-readme是一种优化README配置的技术，通过遵循特定的原则和规则，提高代码质量和可读性 write-readmeは、READMEの設定を最適化する技術です。特定の原則とルールに従って、コードの品質と可読性を向上させます write-readme는 README 설정을 최적화하는 기술입니다. 특정한 원칙과 규칙을 따름으로써 코드의 품질과 가독성을 향상시킵니다 El skill write-readme proporciona una guía para escribir READMEs claros y concisos, enfocándose en la arquitectura, propósito y uso de paquetes y aplicaciones Le skill write-readme fournit un guide pour écrire des README clairs et concis, en se concentrant sur l''architecture, le but et l''utilisation des paquets et applications Der Skill write-readme bietet eine Anleitung zum Schreiben von klaren und knappen README-Dateien, die sich auf Architektur, Zweck und Verwendung von Paketen und Anwendungen konzentriert O agente write-readme ajuda a criar READMEs que descrevem a arquitetura, propósito e uso de pacotes e apps, sem duplicar código. Агент write-readme помогает создавать README, которые описывают архитектуру, назначение и использование пакетов и приложений, без дублирования кода. يساعد وكيل write-readme في إنشاء ملفات README التي تصف الهندسة المعمارية والغرض واستخدام الحزم والتطبيقات، دون تكرار الكود. how to use write-readme write-readme setup guide what is write-readme write-readme alternative write-readme vs markdown write-readme install write-readme for developers README best practices effective README files write-readme style guide write-readme README配置 代码质量 AIエージェント README风格指南 代码复制 CLI命令 References source files instead of duplicating code Supports inclusion of short setup snippets, such as .env examples and CLI commands Follows a principle of describing architecture, purpose, and usage of packages or apps Avoids duplicating full file contents in README files Allows for exceptions, such as referencing lib/adapters.ts for adapter configuration Enforces a rule of not updating READMEs unless the architecture itself changes write-readme is a skill that assists in creating README files, following a style guide that emphasizes referencing source files and avoiding code duplication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jianxcao/qbittorrent-web/i18n-checker', 'community', 'jianxcao', 'qbittorrent-web', 'jianxcao/qbittorrent-web', 'i18n-checker', 0, 0, 36, '2026-03-08T01:57:15.442Z', '2026-03-08T02:09:33.373Z', 'c55142218372884d7c6818e60d221f83d1f2819287a20d3c4e73c2435cc1ebff', '{"id":"jianxcao/qbittorrent-web/i18n-checker","name":"i18n-checker","description":{"en":"i18n-checker is a tool for optimizing Vue i18n translation files, ensuring translation quality through code scanning, language file loading, checking, and report generation.","zh":"i18n-checker 是一个用于优化 Vue i18n 翻译文件的工具，通过扫描代码、加载语言文件、执行检查和生成报告来确保翻译的质量。","ja":"i18n-checker は、Vue i18n 翻訳ファイルを最適化するためのツールで、コードのスキャン、言語ファイルの読み込み、チェックの実行、レポートの生成により翻訳の品質を保証します。","ko":"i18n-checker는 Vue i18n 번역 파일을 최적화하는 도구로, 코드 스캔, 언어 파일 로드, 체크 실행, 보고서 생성을 통해 번역의 품질을 보장합니다.","es":"i18n-checker es una herramienta para verificar y limpiar traducciones en proyectos Vue, garantizando la integridad y consistencia de las traducciones","fr":"i18n-checker est un outil pour vérifier et nettoyer les traductions dans les projets Vue, assurant l''intégrité et la cohérence des traductions","de":"i18n-checker ist ein Tool zur Überprüfung und Bereinigung von Übersetzungen in Vue-Projekten, um die Integrität und Konsistenz der Übersetzungen zu gewährleisten","pt":"O i18n-checker é uma ferramenta para verificar e limpar arquivos de tradução em projetos Vue, garantindo a consistência e a otimização.","ru":"И18n-checker — это инструмент для проверки и очистки файлов перевода в проектах Vue, обеспечивающий целостность и оптимизацию.","ar":"أداة i18n-checker هي أداة للتحقق من ملفات الترجمة وإزالتها في مشاريع Vue، مما يضمن الاتساق والتحسين."},"seo":{"title":{"en":"i18n-checker Setup Guide: Optimizing Vue i18n Translation...","zh":"i18n-checker 设置指南：Vue i18n 翻译文件检查工具","ja":"i18n-checker のベストプラクティス: AIエージェントによるVue i18n翻訳ファイルの最適化","ko":"i18n-checker 설정 가이드: Vue i18n 번역 파일 최적화 도구","es":"i18n-checker: Guía de configuración para Vue i18n","fr":"i18n-checker: Guide de démarrage pour la gestion des trad...","de":"i18n-checker: Einrichtungsanleitung für Vue i18n-Tools","pt":"Guia de Configuração do i18n-checker para Ferramentas de AI","ru":"ИИ Агенты: Руководство по Настройке i18n-checker","ar":"إعداد أداة i18n-checker لعمليات الترجمة الفورية"},"description":{"en":"i18n-checker is a tool for checking and cleaning Vue i18n translation files, ensuring translation completeness, consistency, and optimization.","zh":"i18n-checker 是一个用于检查和清理 Vue i18n 翻译文件的工具，确保翻译的完整性、一致性和最优化。","ja":"i18n-checker は、Vue i18n 翻訳ファイルをチェックおよびクリーンアップするためのツールで、翻訳の完全性、一貫性、最適化を保証します。","ko":"i18n-checker는 Vue i18n 번역 파일을 체크하고 정리하는 도구로, 번역의 완전성, 일관성, 최적화를 보장합니다.","es":"Optimice sus archivos de traducción con i18n-checker, una herramienta para verificar y limpiar traducciones en proyectos Vue","fr":"Améliorez vos fichiers de traduction avec i18n-checker, un outil pour vérifier et nettoyer les traductions dans les projets Vue","de":"Optimieren Sie Ihre Übersetzungsdateien mit i18n-checker, einem Tool zur Überprüfung und Bereinigung von Übersetzungen in Vue-Projekten","pt":"Aprenda a configurar o i18n-checker para garantir a integridade das traduções em seus projetos Vue","ru":"Узнайте, как настроить i18n-checker для проверки и очистки файлов перевода в ваших проектах Vue","ar":"اكتشف كيفية ضبط أداة i18n-checker لضمان دقة الترجمات في مشاريع Vue الخاصة بك"},"definition":{"en":"i18n-checker is a tool for checking and cleaning Vue i18n translation files, ensuring translation completeness, consistency, and optimization.","zh":"i18n-checker 是一个 Vue i18n 翻译文件检查和清理工具，用于确保翻译的完整性、一致性和最优化。","ja":"i18n-checker は、Vue i18n 翻訳ファイルをチェックおよびクリーンアップするためのツールで、翻訳の完全性、一貫性、最適化を保証します。","ko":"i18n-checker는 Vue i18n 번역 파일을 체크하고 정리하는 도구로, 번역의 완전성, 일관성, 최적화를 보장합니다.","es":"i18n-checker es una herramienta de código abierto para la gestión de traducciones en proyectos Vue","fr":"i18n-checker est un outil open source pour la gestion des traductions dans les projets Vue","de":"i18n-checker ist ein Open-Source-Tool für die Verwaltung von Übersetzungen in Vue-Projekten","pt":"O i18n-checker é uma ferramenta de linha de comando para verificar e limpar arquivos de tradução em projetos Vue.","ru":"И18n-checker — это консольный инструмент для проверки и очистки файлов перевода в проектах Vue.","ar":"أداة i18n-checker هي أداة سطر أوامر للتحقق من ملفات الترجمة وإزالتها في مشاريع Vue."},"features":{"en":["Scan code for translation usage","Load all language files","Execute various checks","Generate report and clean up","Support Vue I18n Composition API","Use $t() and t() functions to call translations"],"zh":["扫描代码中的翻译使用","加载所有语言文件","执行各项检查","生成报告并执行清理","支持 Vue I18n Composition API","使用 $t() 和 t() 函数调用翻译"],"ja":["コード内の翻訳の使用をスキャン","すべての言語ファイルを読み込み","各種のチェックを実行","レポートを生成してクリーンアップを実行","Vue I18n Composition API をサポート","$t() と t() 関数を使用して翻訳を呼び出す"],"ko":["코드 내 번역 사용 스캔","모든 언어 파일 로드","각종 체크 실행","보고서 생성 및 정리","Vue I18n Composition API 지원","$t() 및 t() 함수 사용 번역 호출"],"es":["Verificación de traducciones en código","Carga de archivos de traducción","Ejecución de comprobaciones de traducción","Generación de informes y limpieza de traducciones","Compatibilidad con Vue I18n Composition API","Soporte para múltiples idiomas"],"fr":["Vérification des traductions dans le code","Chargement des fichiers de traduction","Exécution des vérifications de traduction","Génération de rapports et nettoyage des traductions","Compatibilité avec Vue I18n Composition API","Prise en charge de plusieurs langues"],"de":["Überprüfung von Übersetzungen im Code","Laden von Übersetzungsdateien","Ausführung von Übersetzungsprüfungen","Erstellung von Berichten und Bereinigung von Übersetzungen","Kompatibilität mit Vue I18n Composition API","Unterstützung für mehrere Sprachen"],"pt":["Verificação de traduções em arquivos de código","Carga de arquivos de idioma","Execução de verificações de tradução","Geração de relatórios e limpeza de traduções","Suporte à API de Composição do Vue I18n"],"ru":["Проверка переводов в файлах кода","Загрузка файлов языков","Выполнение проверок перевода","Генерация отчетов и очистка переводов","Поддержка Composition API от Vue I18n"],"ar":["التحقق من الترجمات في ملفات الكود","تحميل ملفات اللغة","تنفيذ التحقق من الترجمة","توليد تقارير وتنظيف الترجمات","دعم واجهة برمجة التطبيقات Composition API من Vue I18n"]},"keywords":{"en":["i18n-checker","Vue i18n","translation file checking","translation file cleaning","AI agents","Vue I18n Composition API","translation tools"],"zh":["i18n-checker","Vue i18n","翻译文件检查","翻译文件清理","AIエージェント","Vue I18n Composition API","翻译工具"],"ja":["i18n-checker","Vue i18n","翻訳ファイルのチェック","翻訳ファイルのクリーンアップ","AIエージェント","Vue I18n Composition API","翻訳ツール"],"ko":["i18n-checker","Vue i18n","번역 파일 체크","번역 파일 정리","AI 에이전트","Vue I18n Composition API","번역 도구"],"es":["i18n-checker","herramientas de traducción","Vue i18n","gestión de traducciones","verificación de traducciones","limpieza de traducciones","Vue I18n Composition API","traducción de código"],"fr":["i18n-checker","outils de traduction","Vue i18n","gestion des traductions","vérification des traductions","nettoyage des traductions","Vue I18n Composition API","traduction de code"],"de":["i18n-checker","Übersetzungs-Tools","Vue i18n","Verwaltung von Übersetzungen","Überprüfung von Übersetzungen","Bereinigung von Übersetzungen","Vue I18n Composition API","Code-Übersetzung"],"pt":["i18n-checker","ferramentas de AI","tradução de projetos Vue","verificação de traduções","limpeza de traduções","API de Composição do Vue I18n"],"ru":["ИИ Агенты","и18н-checker","проверка переводов","очистка переводов","Composition API от Vue I18n","инструменты для перевода проектов Vue"],"ar":["أدوات الذكاء الاصطناعي","i18n-checker","تحقق من الترجمة","تنظيف الترجمة","واجهة برمجة التطبيقات Composition API من Vue I18n","أدوات ترجمة مشاريع Vue"]}},"owner":"jianxcao","repo":"qbittorrent-web","repoPath":"jianxcao/qbittorrent-web","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.442Z","topics":[],"category":"community","skillMd":{"name":"i18n-checker","description":"检查和清理 Vue i18n 翻译文件，查找未使用的翻译 key、缺失的翻译、语言间不一致、空值翻译，以及提取重复的翻译值为公共 key。使用场景：检查 i18n 翻译、清理翻译文件、优化翻译结构，或当用户提及 i18n、翻译检查、重复翻译、未使用的翻译 key 等关键词时。","bodyPreview":"# i18n 翻译检查和清理\n\n这个技能帮助你检查和清理 qb-web 项目中的 Vue i18n 翻译文件，确保翻译的完整性、一致性和最优化。\n\n## 快速开始\n\n当需要检查翻译时，按以下顺序执行：\n\n1. **扫描代码中的翻译使用**\n2. **加载所有语言文件**\n3. **执行各项检查**\n4. **生成报告并执行清理**\n\n## 项目 i18n 配置\n\n- **翻译文件位置**: `src/i18n/locales/`\n- **支持的语言**: `zh-CN.json`, `en-US.json`\n- **使用模式**: Vue I18n Composition API\n- **调用方式**:\n  - 模板中: `$t(''key.path'')`\n  - 脚本中: `t(''key.path'')` 或 `i18n.global.t(''key.path'')`\n\n## 检查工作流程\n\n### 第 1 步：扫描代码中使用的翻译 key\n\n搜索所有代码文件中的翻译 key 使用：\n\n```bash\n# 扫描模板中的 $t() 调用\nrg ''\\$t\\([\"\\'']([^\"\\'']+)[\"\\'']","body":"# i18n 翻译检查和清理\n\n这个技能帮助你检查和清理 qb-web 项目中的 Vue i18n 翻译文件，确保翻译的完整性、一致性和最优化。\n\n## 快速开始\n\n当需要检查翻译时，按以下顺序执行：\n\n1. **扫描代码中的翻译使用**\n2. **加载所有语言文件**\n3. **执行各项检查**\n4. **生成报告并执行清理**\n\n## 项目 i18n 配置\n\n- **翻译文件位置**: `src/i18n/locales/`\n- **支持的语言**: `zh-CN.json`, `en-US.json`\n- **使用模式**: Vue I18n Composition API\n- **调用方式**:\n  - 模板中: `$t(''key.path'')`\n  - 脚本中: `t(''key.path'')` 或 `i18n.global.t(''key.path'')`\n\n## 检查工作流程\n\n### 第 1 步：扫描代码中使用的翻译 key\n\n搜索所有代码文件中的翻译 key 使用：\n\n```bash\n# 扫描模板中的 $t() 调用\nrg ''\\$t\\([\"\\'']([^\"\\'']+)[\"\\'']\\)'' --type vue --type ts -o\n\n# 扫描脚本中的 t() 调用\nrg ''(?:^|[^$])t\\([\"\\'']([^\"\\'']+)[\"\\'']\\)'' --type vue --type ts -o\n\n# 扫描 i18n.global.t() 调用\nrg ''i18n\\.global\\.t\\([\"\\'']([^\"\\'']+)[\"\\'']\\)'' --type vue --type ts -o\n```\n\n**提取所有使用的 key**，存储到一个集合中。\n\n### 第 2 步：加载翻译文件\n\n读取所有语言的翻译文件：\n\n- `src/i18n/locales/zh-CN.json`\n- `src/i18n/locales/en-US.json`\n\n解析 JSON 并提取所有的翻译 key（包括嵌套路径，如 `common.yes`, `login.title`）。\n\n### 第 3 步：执行检查\n\n按优先级执行以下检查：\n\n#### 3.1 检查缺失的翻译（高优先级）\n\n对比代码中使用的 key 和翻译文件中的 key：\n\n- **缺失的 key**: 代码中使用但翻译文件中不存在\n- **影响**: 会导致页面显示 key 本身而非翻译文本\n\n**输出格式**:\n\n```\n❌ 缺失的翻译 key:\n  - settings.newFeature.title (在 ConnectionSettings.vue:123 使用)\n  - common.newButton (在 3 个文件中使用)\n```\n\n#### 3.2 检查语言间不一致（高优先级）\n\n检查不同语言文件的 key 结构是否一致：\n\n- zh-CN 有但 en-US 没有的 key\n- en-US 有但 zh-CN 没有的 key\n\n**输出格式**:\n\n```\n⚠️  语言间 key 不一致:\n  zh-CN 独有:\n    - settings.advanced.newOption\n  en-US 独有:\n    - settings.advanced.oldOption\n```\n\n#### 3.3 检查空值翻译（中优先级）\n\n查找值为空字符串的翻译 key：\n\n```\n⚠️  空值翻译:\n  - common.placeholder: \"\"\n  - login.hint: \"\"\n```\n\n#### 3.4 检查未使用的 key（中优先级）\n\n找出翻译文件中存在但代码中从未使用的 key：\n\n```\n🗑️  未使用的翻译 key (将被删除):\n  - oldDialog.title\n  - deprecated.message\n  - test.debugInfo\n```\n\n#### 3.5 检查重复的翻译值（优化建议）\n\n识别不同 key 但翻译内容相同的情况，建议提取为公共 key：\n\n**检查逻辑**:\n\n1. 遍历所有翻译值\n2. 找出在**至少 2 个不同 key** 中出现的相同值\n3. 排除极短的值（≤2 字符）和通用词（如 \"是\"、\"否\"、\"确定\"、\"取消\"）\n4. 对于每个重复值，建议提取位置和新的公共 key 名称\n\n**输出格式**:\n\n```\n💡 重复的翻译值（建议提取为公共 key）:\n\n  值: \"操作成功\" (出现 5 次)\n  当前使用位置:\n    - settings.saveSuccess\n    - category.addSuccess\n    - tag.deleteSuccess\n    - tracker.updateSuccess\n    - profile.updateSuccess\n\n  建议: 提取为 common.operationSuccess\n\n  ---\n\n  值: \"请输入名称\" (出现 3 次)\n  当前使用位置:\n    - dialog.namePlaceholder\n    - category.namePlaceholder\n    - tag.namePlaceholder\n\n  建议: 提取为 common.enterNamePlaceholder\n```\n\n### 第 4 步：生成完整报告\n\n汇总所有检查结果，按优先级排序：\n\n```markdown\n# i18n 翻译检查报告\n\n## 📊 统计摘要\n\n- 代码中使用的 key: 156 个\n- zh-CN 翻译 key: 158 个\n- en-US 翻译 key: 157 个\n- 缺失的翻译: 2 个\n- 未使用的 key: 5 个\n- 语言不一致: 3 个\n- 空值翻译: 1 个\n- 重复翻译值: 8 组\n\n## ❌ 缺失的翻译 (必须修复)\n\n[详细列表...]\n\n## ⚠️ 语言间不一致 (必须修复)\n\n[详细列表...]\n\n## ⚠️ 空值翻译 (建议修复)\n\n[详细列表...]\n\n## 🗑️ 未使用的翻译 key (将自动删除)\n\n[详细列表...]\n\n## 💡 重复翻译优化建议\n\n[详细列表...]\n```\n\n### 第 5 步：执行自动清理\n\n**仅对未使用的 key 执行自动删除**：\n\n1. 读取两个语言文件的完整 JSON\n2. 从 JSON 对象中删除未使用的 key（保持嵌套结构）\n3. 使用格式化的 JSON 写回文件（2 空格缩进）\n4. 报告删除结果\n\n**注意**:\n\n- ✅ 自动删除：未使用的 key\n- ⚠️ 手动处理：缺失的翻译、语言不一致、空值\n- 💡 手动决策：重复翻译提取（需要评估是否真的应该公用）\n\n```\n✅ 清理完成:\n  - 已从 zh-CN.json 删除 5 个未使用的 key\n  - 已从 en-US.json 删除 5 个未使用的 key\n```\n\n## 重复翻译提取指南\n\n当发现重复翻译时，评估是否应该提取为公共 key：\n\n### 应该提取的情况\n\n- ✅ 通用的操作反馈消息（如 \"操作成功\"、\"操作失败\"）\n- ✅ 常见的表单占位符（如 \"请输入\"、\"请选择\"）\n- ✅ 通用的按钮文本（如 \"保存并继续\"）\n- ✅ 标准的确认提示（如 \"确认要删除吗？\"）\n\n### 不应该提取的情况\n\n- ❌ 虽然文字相同但语义不同的翻译\n- ❌ 可能在未来需要独立修改的翻译\n- ❌ 仅出现 2 次且不太可能扩展的翻译\n\n### 提取步骤\n\n如果决定提取重复翻译：\n\n1. 在 `common` 命名空间下创建新的公共 key\n2. 使用语义化的命名（如 `operationSuccess` 而非 `success1`）\n3. 更新所有使用旧 key 的代码位置\n4. 删除旧的重复 key\n5. 在两种语言文件中同步操作\n\n## 正则表达式模式\n\n用于搜索翻译使用的准确模式：\n\n```javascript\n// 模板中的 $t() 调用\n/\\$t\\([''\"]([^''\"]+)[''\"]\\)/g\n\n// 脚本中的 t() 调用（不包括 $t）\n/(?:^|[^$\\w])t\\([''\"]([^''\"]+)[''\"]\\)/g\n\n// i18n.global.t() 调用\n/i18n\\.global\\.t\\([''\"]([^''\"]+)[''\"]\\)/g\n```\n\n## 扁平化嵌套 key\n\n翻译文件是嵌套 JSON，但使用时是点号路径。需要扁平化处理：\n\n```javascript\n// 嵌套结构\n{\n  \"common\": {\n    \"yes\": \"Yes\",\n    \"no\": \"No\"\n  }\n}\n\n// 扁平化为\n{\n  \"common.yes\": \"Yes\",\n  \"common.no\": \"No\"\n}\n```\n\n## 排除模式\n\n某些情况不应该报告为问题：\n\n- 动态构造的 key（如 `t(\\`status.\\${state}\\`)`）：提示用户手动检查\n- 测试文件中的 key\n- 注释中的 key 引用\n\n## 最佳实践建议\n\n检查完成后，向用户提供以下建议：\n\n1. **优先修复缺失的翻译**：避免页面显示错误\n2. **保持语言文件同步**：每次添加新 key 时同步更新所有语言\n3. **定期运行检查**：建议在提交前运行此检查\n4. **使用 common 命名空间**：通用翻译统一放在 `common` 下\n5. **语义化命名**：key 名称应该描述内容含义而非位置\n\n## 输出示例\n\n完整的检查输出示例：\n\n```\n🔍 正在检查 i18n 翻译...\n\n📁 扫描代码文件...\n  找到 156 个使用的翻译 key\n\n📄 加载翻译文件...\n  zh-CN.json: 158 个 key\n  en-US.json: 157 个 key\n\n🔎 执行检查...\n\n❌ 发现 2 个缺失的翻译:\n  1. settings.newFeature.title\n     使用位置: src/components/Settings/ConnectionSettings.vue:123\n\n  2. common.newAction\n     使用位置:\n       - src/components/AppHeader.vue:45\n       - src/views/DashboardView.vue:89\n\n⚠️  发现 3 处语言不一致:\n  zh-CN 独有:\n    - settings.advanced.option1\n\n  en-US 独有:\n    - settings.advanced.option2\n    - sidebar.newMenu\n\n⚠️  发现 1 个空值翻译:\n  - login.emptyHint: \"\"\n\n🗑️  发现 5 个未使用的 key:\n  - oldFeature.title\n  - deprecated.message\n  - test.debug\n  - unused.key1\n  - unused.key2\n\n💡 发现 3 组重复翻译:\n\n  \"操作成功\" (出现 5 次)\n  → 建议提取为 common.operationSuccess\n    当前位置: settings.saveSuccess, tag.addSuccess, ...\n\n  \"请输入名称\" (出现 3 次)\n  → 建议提取为 common.enterNamePlaceholder\n    当前位置: dialog.namePlaceholder, tag.namePlaceholder, ...\n\n🔧 正在清理未使用的 key...\n\n✅ 清理完成！\n  - 从 zh-CN.json 删除了 5 个 key\n  - 从 en-US.json 删除了 5 个 key\n\n---\n\n📋 总结:\n  ✅ 已自动清理: 5 个未使用的 key\n  ⚠️  需要手动修复: 2 个缺失翻译, 3 处语言不一致, 1 个空值\n  💡 优化建议: 3 组重复翻译可提取为公共 key\n\n建议下一步:\n  1. 添加缺失的翻译 key\n  2. 统一不同语言文件的 key 结构\n  3. 填充空值翻译\n  4. 考虑提取重复的翻译值（参考上述建议）\n```\n\n## 注意事项\n\n- 删除 key 前会备份原始文件（添加 `.backup` 后缀）\n- 仅删除确认未使用的 key，不会删除任何被引用的 key\n- 对于动态 key 使用（如 `t(\\`prefix.\\${variable}\\`)`），会提示需要手动检查\n- 重复翻译提取是建议性的，需要人工判断是否合理\n- 保持 JSON 文件格式化（2 空格缩进）\n"},"lastSynced":"2026-03-08T02:09:33.373Z","agentAnalysis":{"suitability":{"en":"Ideal for Vue.js Development Agents requiring advanced i18n translation file optimization and validation.","zh":"适用于需要高级 i18n 翻译文件优化和验证的 Vue.js 开发代理。","ja":"Vue.js 開発エージェントが高度な i18n 翻訳ファイルの最適化と検証を必要とする場合に最適です。","ko":"고급 i18n 번역 파일 최적화 및 검증이 필요한 Vue.js 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo de Vue.js que requieren una optimización y validación avanzadas de archivos de traducción i18n.","fr":"Idéal pour les Agents de Développement Vue.js nécessitant une optimisation et une validation avancées de fichiers de traduction i18n.","de":"Ideal für Vue.js-Entwicklungsagenten, die eine erweiterte Optimierung und Validierung von i18n-Übersetzungsdateien erfordern.","pt":"Ideal para Agentes de Desenvolvimento Vue.js que exigem otimização e validação avançadas de arquivos de tradução i18n.","ru":"Идеально для агентов разработки Vue.js, требующих продвинутой оптимизации и проверки файлов перевода i18n.","ar":"مثالي للوكلاء الذين يطورون تطبيقات Vue.js الذين يحتاجون إلى تحسين وتأكيد متقدمين لملفات الترجمة i18n."},"recommendation":{"en":"Empowers agents to ensure translation quality through code scanning, language file loading, and report generation, utilizing Vue I18n Composition API and supporting multiple languages like zh-CN.json and en-US.json.","zh":"通过代码扫描、语言文件加载和报告生成，利用 Vue I18n Composition API 来确保翻译质量，并支持多种语言，如 zh-CN.json 和 en-US.json。","ja":"コードスキャン、言語ファイルの読み込み、レポートの生成を使用して翻訳の品質を確保し、Vue I18n Composition API を利用して複数の言語（例：zh-CN.json、en-US.json）をサポートします。","ko":"코드 스캔, 언어 파일 로딩, 보고서 생성을 통해 번역 품질을 보장하며, Vue I18n Composition API를 사용하여 여러 언어(zh-CN.json, en-US.json 등)를 지원합니다.","es":"Permite a los agentes garantizar la calidad de la traducción a través de la exploración de código, la carga de archivos de idioma y la generación de informes, utilizando la API de Composición de Vue I18n y admitiendo varios idiomas como zh-CN.json y en-US.json.","fr":"Permet aux agents de garantir la qualité de la traduction via l''analyse de code, le chargement de fichiers de langue et la génération de rapports, en utilisant l''API de Composition de Vue I18n et en prenant en charge plusieurs langues comme zh-CN.json et en-US.json.","de":"Ermöglicht es Agenten, die Übersetzungsqualität durch Code-Scanning, Sprachdatei-Laden und Berichterstellung sicherzustellen, indem sie die Vue I18n Composition API nutzen und mehrere Sprachen wie zh-CN.json und en-US.json unterstützen.","pt":"Habilita os agentes a garantir a qualidade da tradução por meio da varredura de código, carregamento de arquivos de idioma e geração de relatórios, utilizando a Vue I18n Composition API e suportando vários idiomas como zh-CN.json e en-US.json.","ru":"Наделяет агентов возможностью обеспечить качество перевода посредством сканирования кода, загрузки языковых файлов и генерации отчетов, используя Vue I18n Composition API и поддерживая несколько языков, таких как zh-CN.json и en-US.json.","ar":"يمنح الوكلاء القدرة على ضمان جودة الترجمة من خلال مسح الشفرة وتحميل ملفات اللغة وتوليد التقارير، باستخدام Vue I18n Composition API ودعم لغات متعددة مثل zh-CN.json و en-US.json."},"useCases":{"en":["Scanning code for translation key usage","Loading and checking language files for consistency","Generating reports to identify and clean up incomplete translations"],"zh":["扫描代码以检查翻译键的使用情况","加载和检查语言文件的一致性","生成报告以识别和清理不完整的翻译"],"ja":["コードの翻訳キーの使用状況をスキャンする","言語ファイルを読み込み一致性をチェックする","不完全な翻訳を識別してクリーンアップするためのレポートを生成する"],"ko":["코드를 스캔하여 번역 키의 사용情况을 확인한다","언어 파일을 로딩하고 일관성을 확인한다","불완전한 번역을 식별하고 정리하기 위한 보고서를 생성한다"],"es":["Explorar el código para el uso de claves de traducción","Cargar y comprobar archivos de idioma para la coherencia","Generar informes para identificar y limpiar traducciones incompletas"],"fr":["Analyser le code pour l''utilisation de clés de traduction","Charger et vérifier les fichiers de langue pour la cohérence","Générer des rapports pour identifier et nettoyer les traductions incomplètes"],"de":["Code scannen für die Verwendung von Überschlüssel","Sprachdateien laden und auf Konsistenz prüfen","Berichte generieren, um unvollständige Übersetzungen zu identifizieren und zu bereinigen"],"pt":["Varredura de código para uso de chaves de tradução","Carregamento e verificação de arquivos de idioma para consistência","Geração de relatórios para identificar e limpar traduções incompletas"],"ru":["Сканирование кода для использования ключей перевода","Загрузка и проверка языковых файлов на согласованность","Генерация отчетов для выявления и очистки неполных переводов"],"ar":["فحص الشفرة لاستخدام مفاتيح الترجمة","تحميل ملفات اللغة و فحصها للتسلسل","توليد تقارير لتحديد و تنظيف الترجمات غير كاملة"]},"limitations":{"en":["Requires access to Vue i18n translation files","Limited to Vue.js projects using the Composition API"],"zh":["需要访问 Vue i18n 翻译文件","仅限于使用 Composition API 的 Vue.js 项目"],"ja":["Vue i18n 翻訳ファイルへのアクセスが必要","Composition API を使用する Vue.js プロジェクトのみに限定される"],"ko":["Vue i18n 번역 파일에 접근해야 함","Composition API를 사용하는 Vue.js 프로젝트에만 제한됨"],"es":["Requiere acceso a archivos de traducción de Vue i18n","Limitado a proyectos Vue.js que utilizan la API de Composición"],"fr":["Nécessite l''accès aux fichiers de traduction de Vue i18n","Limité aux projets Vue.js utilisant l''API de Composition"],"de":["Erfordert Zugriff auf Vue i18n-Übersetzungsdateien","Begrenzt auf Vue.js-Projekte, die die Composition-API verwenden"],"pt":["Exige acesso a arquivos de tradução Vue i18n","Limitado a projetos Vue.js que usam a Composition API"],"ru":["Требует доступа к файлам перевода Vue i18n","Ограничен проектами Vue.js, использующими Composition API"],"ar":["يتطلب الوصول إلى ملفات الترجمة Vue i18n","محدود بمشاريع Vue.js التي تستخدم Composition API"]},"version":4},"contentHash":"c55142218372884d7c6818e60d221f83d1f2819287a20d3c4e73c2435cc1ebff","qualityScore":36}');
