INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jianxcao/qbittorrent-web/i18n-checker', 'i18n-checker', 'jianxcao', 'qbittorrent-web', 'community', 'i18n-checker jianxcao qbittorrent-web community i18n-checker is a tool for optimizing Vue i18n translation files, ensuring translation quality through code scanning, language file loading, checking, and report generation. i18n-checker 是一个用于优化 Vue i18n 翻译文件的工具，通过扫描代码、加载语言文件、执行检查和生成报告来确保翻译的质量。 i18n-checker は、Vue i18n 翻訳ファイルを最適化するためのツールで、コードのスキャン、言語ファイルの読み込み、チェックの実行、レポートの生成により翻訳の品質を保証します。 i18n-checker는 Vue i18n 번역 파일을 최적화하는 도구로, 코드 스캔, 언어 파일 로드, 체크 실행, 보고서 생성을 통해 번역의 품질을 보장합니다. i18n-checker es una herramienta para verificar y limpiar traducciones en proyectos Vue, garantizando la integridad y consistencia de las traducciones i18n-checker est un outil pour vérifier et nettoyer les traductions dans les projets Vue, assurant l''intégrité et la cohérence des traductions i18n-checker ist ein Tool zur Überprüfung und Bereinigung von Übersetzungen in Vue-Projekten, um die Integrität und Konsistenz der Übersetzungen zu gewährleisten O i18n-checker é uma ferramenta para verificar e limpar arquivos de tradução em projetos Vue, garantindo a consistência e a otimização. И18n-checker — это инструмент для проверки и очистки файлов перевода в проектах Vue, обеспечивающий целостность и оптимизацию. أداة i18n-checker هي أداة للتحقق من ملفات الترجمة وإزالتها في مشاريع Vue، مما يضمن الاتساق والتحسين. i18n-checker Vue i18n translation file checking translation file cleaning AI agents Vue I18n Composition API translation tools i18n-checker Vue i18n 翻译文件检查 翻译文件清理 AIエージェント Vue I18n Composition API 翻译工具 Scan code for translation usage Load all language files Execute various checks Generate report and clean up Support Vue I18n Composition API Use $t() and t() functions to call translations i18n-checker is a tool for checking and cleaning Vue i18n translation files, ensuring translation completeness, consistency, and optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jorggerojas/next-skeleton-page/pages-router', 'community', 'jorggerojas', 'next-skeleton-page', 'jorggerojas/next-skeleton-page', 'pages-router', 0, 0, 36, '2026-03-08T01:57:15.483Z', '2026-03-08T02:09:57.656Z', '8968d7114928f52abe6441b237508065f550076bbad60916593af2a5fb2ab217', '{"id":"jorggerojas/next-skeleton-page/pages-router","name":"pages-router","description":{"en":"The pages-router skill provides a Next.js Pages router repo template for faster development with a simple, clean architecture. It benefits developers working with Next.js and Pages Router.","zh":"Next.js Pages Router 是一个简单的清洁架构和 MCP 技能的实现方案，帮助开发者快速入门","ja":"Next.js Pages Router は、クリーンアーキテクチャと MCP スキルを実現するためのシンプルなソリューションです","ko":"Next.js Pages Router 는 간단한 클린 아키텍처와 MCP 기술을 구현하기 위한 솔루션입니다","es":"Pages Router es un repositorio de plantillas para Next.js que permite crear rutas de página de manera sencilla y limpia. Ofrece una estructura clara para crear páginas y rutas.","fr":"Pages Router est un modèle de référentiel pour Next.js qui permet de créer des routes de page de manière simple et propre. Il offre une structure claire pour créer des pages et des routes.","de":"Pages Router ist ein Repository-Vorlagen für Next.js, das das Erstellen von Seitenspezifischen Routen auf einfache und saubere Weise ermöglicht. Es bietet eine klare Struktur zum Erstellen von Seiten und Routen.","pt":"O Pages Router é um recurso do Next.js que permite uma estrutura de projeto limpa e simples. Aprenda a usá-lo para melhorar a produtividade","ru":"Pages Router - это функция Next.js, которая позволяет создавать чистую и простую структуру проекта. Узнайте, как использовать ее для повышения производительности с помощью ИИ Агентов","ar":"Pages Router هو ميزة في Next.js تتيح هيكلا نظيفا وبسيطا للمشروع. تعلم كيفية استخدامه لتحسين الإنتاجية مع أدوات الإیجیینٹس الذكية"},"seo":{"title":{"en":"pages-router: Next.js Pages Router Setup Guide | AI Agent...","zh":"Next.js Pages Router 快速入门指南","ja":"Next.js Pages Router のベストプラクティス","ko":"Next.js Pages Router 설정 가이드","es":"Guía de configuración de Pages Router para Next.js","fr":"Guide de mise en place de Pages Router pour Next.js","de":"Einrichtungsleitfaden für Pages Router in Next.js","pt":"Guia de Configuração do Pages Router para Desenvolvedores","ru":"Настройка Pages Router: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد Pages Router لمنشئي الإیجیینٹس الذكية"},"description":{"en":"Unlock faster development with pages-router! Learn how to leverage Next.js Pages Router for clean architecture and efficient routing. Get started now!","zh":"了解如何使用 Next.js Pages Router 实现简单的清洁架构和 MCP 技能，提高开发效率","ja":"Next.js Pages Router を使用してクリーンアーキテクチャと MCP スキルを実現する方法を学びましょう","ko":"Next.js Pages Router 를 사용하여 간단한 클린 아키텍처와 MCP 기술을 구현하고 개발 속도를 높여보세요","es":"Aprende a utilizar Pages Router en Next.js para crear rutas de página simples y limpias. Descubre cómo crear páginas básicas y rutas dinámicas.","fr":"Découvrez comment utiliser Pages Router dans Next.js pour créer des routes de page simples et propres. Apprenez à créer des pages de base et des routes dynam...","de":"Erfahren Sie, wie Sie Pages Router in Next.js verwenden, um einfache und saubere Seitenspezifische Routen zu erstellen. Entdecken Sie, wie Sie grundlegende S...","pt":"Aprenda a configurar o Pages Router para melhorar a estrutura do seu projeto Next.js e aumentar a produtividade","ru":"Узнайте, как настроить Pages Router, чтобы ускорить разработку и улучшить архитектуру вашего проекта Next.js с помощью ИИ Агентов","ar":"اكتشف كيفية إعداد Pages Router لتحسين هيكل مشروعك في Next.js وزيادة الإنتاجية مع أدوات الإیجیینٹس الذكية"},"definition":{"en":"pages-router is a Next.js Pages router repository template that enables fast development with a clean architecture, using Pages Router exclusively.","zh":"Next.js Pages Router 是一个用于实现简单的清洁架构和 MCP 技能的模板","ja":"Next.js Pages Router は、シンプルなクリーンアーキテクチャと MCP スキルを実現するためのテンプレートです","ko":"Next.js Pages Router 는 간단한 클린 아키텍처와 MCP 기술을 구현하기 위한 템플릿입니다","es":"Pages Router es un modelo de enrutamiento para Next.js que utiliza una estructura de carpetas para crear rutas de página","fr":"Pages Router est un modèle de routage pour Next.js qui utilise une structure de dossiers pour créer des routes de page","de":"Pages Router ist ein Routing-Modell für Next.js, das eine Verzeichnisstruktur verwendet, um Seitenspezifische Routen zu erstellen","pt":"O Pages Router é um recurso do Next.js que gerencia as rotas das páginas de um projeto","ru":"Pages Router - это функция Next.js, которая управляет маршрутами страниц проекта","ar":"Pages Router هو ميزة في Next.js تدير مسارات صفحات المشروع"},"features":{"en":["Uses Pages Router exclusively for all pages in src/pages/","Supports regular pages via src/pages/[filename].tsx","Enables dynamic routes via src/pages/[id]/page.tsx","Allows API routes via src/pages/api/[route].ts","Includes special files _app.tsx and _document.tsx in src/pages/"],"zh":["使用 Pages Router 实现简单的路由","支持正则路由和动态路由","提供 API 路由和特殊文件支持","简化 Next.js 项目的结构和开发","提高开发效率和代码可维护性"],"ja":["Pages Router を使用してシンプルなルーティングを実現","正規ルーティングと動的ルーティングをサポート","API ルーティングと特殊ファイルをサポート","Next.js プロジェクトの構造と開発を簡素化","開発効率とコードの維持性を向上"],"ko":["Pages Router 를 사용하여 간단한 라우팅을 구현","정규 라우팅과 동적 라우팅을 지원","API 라우팅과 특수 파일을 지원","Next.js 프로젝트의 구조와 개발을 단순화","개발 효율과 코드의 유지 보수를 향상"],"es":["Estructura de carpetas para crear rutas de página","Soporte para rutas dinámicas","Soporte para rutas de API","Archivos especiales como _app.tsx y _document.tsx","Creación de páginas básicas con src/pages/[filename].tsx","Creación de rutas dinámicas con src/pages/[id]/page.tsx"],"fr":["Structure de dossiers pour créer des routes de page","Prise en charge des routes dynamiques","Prise en charge des routes d''API","Fichiers spéciaux tels que _app.tsx et _document.tsx","Création de pages de base avec src/pages/[filename].tsx","Création de routes dynamiques avec src/pages/[id]/page.tsx"],"de":["Verzeichnisstruktur zum Erstellen von Seitenspezifischen Routen","Unterstützung für dynamische Routen","Unterstützung für API-Routen","Spezielle Dateien wie _app.tsx und _document.tsx","Erstellung von grundlegenden Seiten mit src/pages/[filename].tsx","Erstellung von dynamischen Routen mit src/pages/[id]/page.tsx"],"pt":["Suporte a rotas regulares","Suporte a rotas dinâmicas","Suporte a rotas de API","Estrutura de projeto limpa e simples","Melhoria da produtividade"],"ru":["Поддержка обычных маршрутов","Поддержка динамических маршрутов","Поддержка маршрутов API","Чистая и простая структура проекта","Повышение производительности"],"ar":["دعم المسارات العادية","دعم المسارات الديناميكية","دعم مسارات واجهة برمجة التطبيقات","هيكل مشروع نظيف وبسيط","تحسين الإنتاجية"]},"keywords":{"en":["how to use pages-router","what is pages-router","pages-router alternative","pages-router vs react-router","pages-router install","pages-router setup guide","next.js pages router","clean architecture with pages-router","efficient routing with pages-router"],"zh":["Next.js Pages Router","AIエージェント","清洁架构","MCP 技能","快速入门指南","开发效率","代码可维护性"],"ja":["Next.js Pages Router","AIエージェント","クリーンアーキテクチャ","MCP スキル","ベストプラクティス","開発効率","コードの維持性"],"ko":["Next.js Pages Router","AI 에이전트","클린 아키텍처","MCP 기술","설정 가이드","개발 효율","코드의 유지 보수"],"es":["Pages Router","Next.js","enrutamiento de páginas","rutas dinámicas","rutas de API","estructura de carpetas","creación de páginas","desarrollo web","react","typescript"],"fr":["Pages Router","Next.js","routage de pages","routes dynamiques","routes d''API","structure de dossiers","création de pages","développement web","react","typescript"],"de":["Pages Router","Next.js","Seitenspezifisches Routing","dynamische Routen","API-Routen","Verzeichnisstruktur","Seitenerstellung","Webentwicklung","react","typescript"],"pt":["Pages Router","Next.js","rotas de páginas","estrutura de projeto","produtividade","desenvolvimento web","react","typescript"],"ru":["Pages Router","Next.js","маршруты страниц","структура проекта","производительность","веб-разработка","react","typescript","ИИ Агенты"],"ar":["Pages Router","Next.js","مسارات الصفحات","هيكل المشروع","الإنتاجية","تطوير الويب","react","typescript","أدوات الإیجیینٹس الذكية"]}},"owner":"jorggerojas","repo":"next-skeleton-page","repoPath":"jorggerojas/next-skeleton-page","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.483Z","topics":[],"category":"community","skillMd":{"name":"pages-router","description":"Work with Next.js Pages Router pages in src/pages/. Use when creating or modifying pages, working with _app.tsx, _document.tsx, or any page components in the Pages Router structure.","bodyPreview":"# Next.js Pages Router\n\n## Structure\n\nThis project uses **Pages Router** exclusively. All pages go in `src/pages/`.\n\n- Regular pages: `src/pages/[filename].tsx` → `/filename` route\n- Dynamic routes: `src/pages/[id]/page.tsx` → `/[id]` route\n- API routes: `src/pages/api/[route].ts` → `/api/[route]` endpoint\n- Special files: `_app.tsx`, `_document.tsx` in `src/pages/`\n\n## Creating Pages\n\n### Basic Page\n\n```tsx\n// src/pages/about.tsx\nexport default function About() {\n  return <div>About page</div>;","body":"# Next.js Pages Router\n\n## Structure\n\nThis project uses **Pages Router** exclusively. All pages go in `src/pages/`.\n\n- Regular pages: `src/pages/[filename].tsx` → `/filename` route\n- Dynamic routes: `src/pages/[id]/page.tsx` → `/[id]` route\n- API routes: `src/pages/api/[route].ts` → `/api/[route]` endpoint\n- Special files: `_app.tsx`, `_document.tsx` in `src/pages/`\n\n## Creating Pages\n\n### Basic Page\n\n```tsx\n// src/pages/about.tsx\nexport default function About() {\n  return <div>About page</div>;\n}\n```\n\n### Dynamic Route\n\n```tsx\n// src/pages/users/[id].tsx\nimport { useRouter } from ''next/router'';\n\nexport default function User() {\n  const router = useRouter();\n  const { id } = router.query;\n  \n  return <div>User {id}</div>;\n}\n```\n\n### Nested Dynamic Route\n\n```tsx\n// src/pages/posts/[id]/[slug].tsx\nimport { useRouter } from ''next/router'';\n\nexport default function Post() {\n  const router = useRouter();\n  const { id, slug } = router.query;\n  \n  return <div>Post {id} - {slug}</div>;\n}\n```\n\n## Special Files\n\n### _app.tsx\n\nWraps all pages. Use for:\n\n- Global providers\n- Global styles\n- Layout components\n- Page-level state\n\n```tsx\n// src/pages/_app.tsx\nimport \"@/styles/globals.css\";\nimport type { AppProps } from \"next/app\";\n\nexport default function App({ Component, pageProps }: AppProps) {\n  return <Component {...pageProps} />;\n}\n```\n\n### _document.tsx\n\nCustomizes HTML document. Use for:\n\n- `<html>` and `<body>` attributes\n- Custom fonts\n- Analytics scripts\n- Meta tags\n\n```tsx\n// src/pages/_document.tsx\nimport { Html, Head, Main, NextScript } from \"next/document\";\n\nexport default function Document() {\n  return (\n    <Html lang=\"en\">\n      <Head />\n      <body className=\"antialiased\">\n        <Main />\n        <NextScript />\n      </body>\n    </Html>\n  );\n}\n```\n\n## Data Fetching\n\n**CRITICAL**: Only pages handle server-side data fetching. Components, hooks, or other files should NOT make server calls directly. All data fetching happens in the page file using `getServerSideProps`, `getStaticProps`, or `getStaticPaths`.\n\nFor **client-side** data (lists, forms, mutations), use custom hooks that call the internal API via **actions** (`src/lib/api/*/actions.ts`) and **query keys** (`src/lib/api/*/keys.ts`). See the **hooks** skill. If your project integrates external APIs, see `src/lib/TRANSFORMATIONS.md` for the full flow.\n\n### getServerSideProps\n\nThe page component goes first, then the data fetching function. **The page component''s Props type MUST be inferred from `getServerSideProps` using `InferGetServerSidePropsType`.**\n\n```tsx\n// src/pages/posts/[id].tsx\nimport type { GetServerSideProps, InferGetServerSidePropsType } from \"next\";\nimport { PageLayout } from \"@/components\";\n\nexport const getServerSideProps: GetServerSideProps = async (context) => {\n  const { id } = context.params!;\n  const res = await fetch(`https://api.example.com/posts/${id}`);\n  const post = await res.json();\n  \n  return {\n    props: { post },\n  };\n};\n\n// Type MUST be inferred from getServerSideProps\nexport default function Post({ post }: InferGetServerSidePropsType<typeof getServerSideProps>) {\n  return (\n    <PageLayout\n      title={post.title}\n      description={post.content}\n      canonical={`/posts/${post.id}`}\n    >\n      <div>\n        <h1>{post.title}</h1>\n        <p>{post.content}</p>\n      </div>\n    </PageLayout>\n  );\n}\n```\n\n### getStaticProps\n\n**The page component''s Props type MUST be inferred from `getStaticProps` using `InferGetStaticPropsType`.**\n\n```tsx\n// src/pages/posts/[id].tsx\nimport type { GetStaticProps, GetStaticPaths, InferGetStaticPropsType } from \"next\";\nimport { PageLayout } from \"@/components\";\n\nexport const getStaticProps: GetStaticProps = async (context) => {\n  const { id } = context.params!;\n  const res = await fetch(`https://api.example.com/posts/${id}`);\n  const post = await res.json();\n  \n  return {\n    props: { post },\n    revalidate: 60, // ISR: revalidate every 60 seconds\n  };\n};\n\nexport const getStaticPaths: GetStaticPaths = async () => {\n  return {\n    paths: [{ params: { id: ''1'' } }, { params: { id: ''2'' } }],\n    fallback: ''blocking'', // or true, false\n  };\n};\n\n// Type MUST be inferred from getStaticProps\nexport default function Post({ post }: InferGetStaticPropsType<typeof getStaticProps>) {\n  return (\n    <PageLayout\n      title={post.title}\n      description={post.content}\n      canonical={`/posts/${post.id}`}\n    >\n      <div>\n        <h1>{post.title}</h1>\n        <p>{post.content}</p>\n      </div>\n    </PageLayout>\n  );\n}\n```\n\n### Type Inference\n\n**IMPORTANT**: The page component''s `Props` type **MUST** be inferred from `getServerSideProps` or `getStaticProps` using `InferGetServerSidePropsType` or `InferGetStaticPropsType`. Do not manually define the Props type.\n\n```tsx\nimport type { GetServerSideProps, InferGetServerSidePropsType } from \"next\";\n\nexport const getServerSideProps: GetServerSideProps = async () => {\n  return {\n    props: { post: { id: \"1\", title: \"Hello\" } },\n  };\n};\n\n// Type MUST be inferred from getServerSideProps\nexport default function Post({ post }: InferGetServerSidePropsType<typeof getServerSideProps>) {\n  return <div>{post.title}</div>;\n}\n```\n\n### Using Hooks in Pages\n\nPages can use custom hooks for client-side data fetching, mutations, or other client-side logic. Examples:\n\n```tsx\n// src/pages/users.tsx\nimport type { GetServerSideProps, InferGetServerSidePropsType } from \"next\";\nimport { useUsers } from \"@/hooks/users\";\n\nexport const getServerSideProps: GetServerSideProps = async () => {\n  return { props: { initialUsers: [] } };\n};\n\nexport default function UsersPage({ initialUsers }: InferGetServerSidePropsType<typeof getServerSideProps>) {\n  const { data: users, isLoading } = useUsers();\n  \n  return (\n    <div>\n      {isLoading ? <p>Loading...</p> : <UserList users={users} />}\n    </div>\n  );\n}\n```\n\n```tsx\n// src/pages/users/[id].tsx\nimport type { GetServerSideProps, InferGetServerSidePropsType } from \"next\";\nimport { useUser, useCreateUser } from \"@/hooks/users\";\n\nexport default function UserPage({ userId }: InferGetServerSidePropsType<typeof getServerSideProps>) {\n  const { data: user } = useUser(userId);\n  const createMutation = useCreateUser();\n  \n  const handleCreate = () => {\n    createMutation.mutate({ name: \"New User\" });\n  };\n  \n  return (\n    <div>\n      <h1>{user?.name}</h1>\n      <button onClick={handleCreate}>Create User</button>\n    </div>\n  );\n}\n\nexport const getServerSideProps: GetServerSideProps = async (context) => {\n  const { id } = context.params!;\n  return { props: { userId: id } };\n};\n```\n\n**Note**: Server-side data fetching (API calls) should only happen in `getServerSideProps` or `getStaticProps`. Hooks like `useUsers()`, `useUser()`, `useCreateUser()`, etc., are for client-side data fetching, mutations, or other client-side logic.\n\n## Client-Side Navigation\n\n```tsx\nimport Link from ''next/link'';\nimport { useRouter } from ''next/router'';\n\nexport default function Navigation() {\n  const router = useRouter();\n  \n  return (\n    <div>\n      <Link href=\"/about\">About</Link>\n      <button onClick={() => router.push(''/contact'')}>\n        Go to Contact\n      </button>\n    </div>\n  );\n}\n```\n\n## SEO with PageLayout\n\nUse the `PageLayout` component for SEO metadata (static or dynamic):\n\n```tsx\n// Static SEO\nimport { PageLayout } from \"@/components\";\n\nexport default function AboutPage() {\n  return (\n    <PageLayout\n      title=\"About Us\"\n      description=\"Learn more about our company\"\n      keywords=\"about, company, team\"\n      canonical=\"/about\"\n    >\n      <div>About content</div>\n    </PageLayout>\n  );\n}\n```\n\n```tsx\n// Dynamic SEO from props\nimport type { GetServerSideProps, InferGetServerSidePropsType } from \"next\";\nimport { PageLayout } from \"@/components\";\n\nexport const getServerSideProps: GetServerSideProps = async () => {\n  return {\n    props: {\n      seo: {\n        title: \"Dynamic Page\",\n        description: \"Dynamic description\",\n      },\n    },\n  };\n};\n\nexport default function DynamicPage({ seo }: InferGetServerSidePropsType<typeof getServerSideProps>) {\n  return (\n    <PageLayout {...seo}>\n      <div>Content</div>\n    </PageLayout>\n  );\n}\n```\n\n## Important Notes\n\n- **Always use Pages Router** - never App Router patterns\n- **Only pages handle server-side data fetching** - components, hooks, or other files should NOT make server calls\n- **Page Props type MUST be inferred** - use `InferGetServerSidePropsType<typeof getServerSideProps>` or `InferGetStaticPropsType<typeof getStaticProps>`\n- Pages are React components that export a default function\n- Data fetching functions (`getServerSideProps`, `getStaticProps`, `getStaticPaths`) go **after** the page component\n- Pages can use hooks like `useUsers()`, `useUser()`, `useCreateUser()`, etc. for client-side data fetching and mutations\n- Use `PageLayout` component for SEO metadata (static or dynamic)\n- Use `useRouter` from `next/router` (not `next/navigation`)\n- Global styles go in `src/styles/globals.css` and imported in `_app.tsx`\n- TypeScript: Use `AppProps` from `next/app` for `_app.tsx`\n- The app includes `ErrorBoundary` and `QueryProvider` in `_app.tsx` - they wrap all pages automatically\n"},"lastSynced":"2026-03-08T02:09:57.656Z","agentAnalysis":{"suitability":{"en":"Perfect for Next.js Agents needing streamlined page routing and architecture.","zh":"非常适合需要简化页面路由和架构的 Next.js 代理。","ja":"Next.js エージェントがストリームライン化されたページルーティングとアーキテクチャを必要とする場合に最適です。","ko":"스트림 라인화된 페이지 라우팅과 아키텍처가 필요한 Next.js 에이전트에 적합합니다.","es":"Perfecto para Agentes de Next.js que necesitan enrutamiento de páginas y arquitectura optimizados.","fr":"Parfait pour les agents Next.js nécessitant un routage de page et une architecture rationalisés.","de":"Perfekt für Next.js-Agents, die ein optimiertes Seitenaufbau- und Architektur-Management benötigen.","pt":"Perfeito para Agentes Next.js que necessitam de roteamento de página e arquitetura otimizados.","ru":"Идеально подходит для агентов Next.js, которым необходима оптимизированная маршрутизация страниц и архитектура.","ar":"مثالي لعميل Next.js الذي يحتاج إلى توجيه صفحة ومعمارية متسلسلة."},"recommendation":{"en":"Empowers agents to create scalable Next.js applications with simple, clean architecture using Pages Router, enabling easy management of regular pages, dynamic routes, and API routes via `src/pages/` structure and files like `_app.tsx` and `_document.tsx`.","zh":"赋予代理创建可扩展的 Next.js 应用程序的能力，使用 Pages Router，具有简单、干净的架构，能够通过 `src/pages/` 结构和文件（如 `_app.tsx` 和 `_document.tsx`）轻松管理常规页面、动态路由和 API 路由。","ja":"エージェントがシンプルでクリーンなアーキテクチャを使用してスケーラブルな Next.js アプリケーションを作成できるようにします。Pages Router を使用して、`src/pages/` 構造とファイル（たとえば `_app.tsx` と `_document.tsx`）を介して通常のページ、動的ルート、および API ルートを簡単に管理できます。","ko":"에이전트가 페이지 라우터를 사용하여 간단하고 깨끗한 아키텍처로 확장 가능한 Next.js 애플리케이션을 만들 수 있도록 합니다. `src/pages/` 구조 및 파일(예: `_app.tsx` 및 `_document.tsx`)을 통해 정상 페이지, 동적 라우트 및 API 라우트를 쉽게 관리할 수 있습니다.","es":"Habilita a los agentes a crear aplicaciones Next.js escalables con una arquitectura simple y limpia utilizando Pages Router, lo que permite una fácil gestión de páginas regulares, rutas dinámicas y rutas de API a través de la estructura y archivos como `src/pages/`, `_app.tsx` y `_document.tsx`.","fr":"Permet aux agents de créer des applications Next.js évolutives avec une architecture simple et propre en utilisant Pages Router, permettant ainsi une gestion facile des pages régulières, des routes dynamiques et des routes API via la structure et les fichiers tels que `src/pages/`, `_app.tsx` et `_document.tsx`.","de":"Ermöglicht es den Agents, skalierbare Next.js-Anwendungen mit einfacher, sauberer Architektur unter Verwendung von Pages Router zu erstellen, wodurch ein einfaches Management von regulären Seiten, dynamischen Routen und API-Routen über die Struktur und Dateien wie `src/pages/`, `_app.tsx` und `_document.tsx` ermöglicht wird.","pt":"Habilita os agentes a criar aplicações Next.js escaláveis com arquitetura simples e limpa usando o Pages Router, permitindo uma gestão fácil de páginas regulares, rotas dinâmicas e rotas de API via estrutura e arquivos como `_app.tsx` e `_document.tsx`.","ru":"Позволяет агентам создавать масштабируемые приложения Next.js с простой и чистой архитектурой, используя Pages Router, что обеспечивает легкое управление обычными страницами, динамическими маршрутами и маршрутами API через структуру и файлы типа `_app.tsx` и `_document.tsx`.","ar":"يمنح الوكلاء إنشاء تطبيقات Next.js القابلة للتحجيم مع هندسة بسيطة ونظيفة باستخدام Pages Router، مما يتيح إدارة سهلة للصفحات العادية وطرق ديناميكية وطرق API من خلال هيكل وملفات مثل `_app.tsx` و `_document.tsx`."},"useCases":{"en":["Generating dynamic routes with `[id]` parameters","Creating API endpoints with `src/pages/api/[route].ts`","Organizing page components in `src/pages/` for efficient routing"],"zh":["使用 `[id]` 参数生成动态路由","使用 `src/pages/api/[route].ts` 创建 API 端点","在 `src/pages/` 中组织页面组件以实现高效路由"],"ja":[" `[id]` パラメータを使用して動的ルートを生成する"," `src/pages/api/[route].ts` を使用して API エンドポイントを作成する"," `src/pages/` 内でページコンポーネントを整理して効率的なルーティングを実現する"],"ko":[" `[id]` 매개 변수를 사용하여 동적 라우트를 생성하는 것"," `src/pages/api/[route].ts`를 사용하여 API 엔드포인트를 생성하는 것"," `src/pages/`에서 페이지 컴포넌트를 조직하여 효율적인 라우팅을 구현하는 것"],"es":["Generar rutas dinámicas con parámetros `[id]`","Crear puntos de conexión de API con `src/pages/api/[route].ts`","Organizar componentes de página en `src/pages/` para un enrutamiento eficiente"],"fr":["Générer des routes dynamiques avec des paramètres `[id]`","Créer des points de terminaison API avec `src/pages/api/[route].ts`","Organiser les composants de page dans `src/pages/` pour un routage efficace"],"de":["Generieren von dynamischen Routen mit `[id]`-Parametern","Erstellen von API-Endpunkten mit `src/pages/api/[route].ts`","Organisieren von Seitenelementen in `src/pages/` für ein effizientes Routing"],"pt":["Geração de rotas dinâmicas com parâmetros `[id]`","Criação de pontos finais de API com `src/pages/api/[route].ts`","Organização de componentes de página em `src/pages/` para roteamento eficiente"],"ru":["Генерация динамических маршрутов с параметрами `[id]`","Создание конечных точек API с `src/pages/api/[route].ts`","Организация компонентов страницы в `src/pages/` для эффективной маршрутизации"],"ar":["توليد مسارات ديناميكية مع معاملات `[id]`","إنشاء نقاط نهاية API مع `src/pages/api/[route].ts`","تنظيم مكونات الصفحة في `src/pages/` من أجل توجيه فعال"]},"limitations":{"en":["Requires Next.js environment","Exclusive use of Pages Router"],"zh":["需要 Next.js 环境","仅限使用 Pages Router"],"ja":["Next.js 環境が必要","Pages Router のみを使用"],"ko":["Next.js 환경이 필요","페이지 라우터만 사용"],"es":["Requiere un entorno Next.js","Uso exclusivo de Pages Router"],"fr":["Nécessite un environnement Next.js","Utilisation exclusive de Pages Router"],"de":["Benötigt eine Next.js-Umgebung","Exklusiver Einsatz von Pages Router"],"pt":["Exige ambiente Next.js","Uso exclusivo do Pages Router"],"ru":["Требуется окружение Next.js","Использование только Pages Router"],"ar":["يتطلب بيئة Next.js","استخدام حصرية لبروتوكول Pages Router"]},"version":4},"contentHash":"8968d7114928f52abe6441b237508065f550076bbad60916593af2a5fb2ab217","qualityScore":36}');
