INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MycosoftLabs/mycosoft-mas/create-api-endpoint', 'create-api-endpoint', 'MycosoftLabs', 'mycosoft-mas', 'community', 'create-api-endpoint MycosoftLabs mycosoft-mas community The create-api-endpoint skill helps developers create new FastAPI API endpoints. It provides a structured approach to registering routers and updating the API catalog. 本指南介绍如何使用FastAPI创建新的API端点，包括路由器文件创建和注册 このガイドでは、AIエージェントを使用してFastAPIで新しいAPIエンドポイントを作成する方法を説明します 이 가이드에서는 FastAPI를 사용하여 새로운 API 엔드포인트를 생성하는 방법을 설명합니다 El punto de acceso API se crea utilizando FastAPI''s APIRouter con prefijo y etiquetas, y se registra en myca_main.py. Los pasos incluyen la creación de un archivo de enrutador y la actualización del catálogo de API. Le point de terminaison API est créé à l''aide de l''APIRouter de FastAPI avec préfixe et balises, et est enregistré dans myca_main.py. Les étapes incluent la création d''un fichier de routage et la mise à jour du catalogue d''API. Der API-Endpunkt wird mithilfe von FastAPI''s APIRouter mit Präfix und Tags erstellt und in myca_main.py registriert. Die Schritte umfassen die Erstellung einer Router-Datei und die Aktualisierung des API-Katalogs. Criar um ponto de extremidade de API com FastAPI envolve criar arquivos de roteador e registrar em myca_main.py. Aprenda os passos necessários. Создание конечной точки API с FastAPI включает в себя создание файлов маршрутизатора и регистрацию в myca_main.py. Узнайте необходимые шаги для ИИ Агентов إنشاء نقطة نهاية واجهة برمجة التطبيقات مع FastAPI يتضمن إنشاء ملفات الموجه و التسجيل في myca_main.py. تعلم الخطوات الضرورية للآلات الذكية how to use create-api-endpoint create-api-endpoint setup guide FastAPI API endpoint creation create-api-endpoint alternative create-api-endpoint vs Flask create-api-endpoint install FastAPI创建API端点 API路由器设置 Python API开发 AI工具创建API FastAPI路由器注册 API端点测试 Creates router files using FastAPI''s APIRouter Registers routers in myca_main.py Updates the API catalog with new endpoints Follows a step-by-step creation progress Utilizes Python for endpoint implementation create-api-endpoint is a skill that enables developers to generate new API endpoints using FastAPI''s APIRouter with prefix and tags.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jameingh/dida-clone/tauri2-react-rust', 'community', 'jameingh', 'dida-clone', 'jameingh/dida-clone', 'tauri2-react-rust', 0, 0, 36, '2026-03-08T01:57:15.487Z', '2026-03-08T02:10:06.662Z', '513340ea6d93f16eeac9e9e51d70d7c0f76abfc73d88426259029febe8ac3571', '{"id":"jameingh/dida-clone/tauri2-react-rust","name":"tauri2-react-rust","description":{"en":"The tauri2-react-rust skill enables developers to build cross-platform desktop applications using Tauri 2, TypeScript, React, and Rust. It provides guidance on architecture, IPC, and best practices for a robust development experience.","zh":"Tauri 2 + React + Rust 跨平台开发指引，整合架构、IPC、后端与前端最佳实践","ja":"Tauri 2 + React + Rust クロスプラットフォーム開発ガイド、Architecture、IPC、バックエンドとフロントエンドのベストプラクティスを統合","ko":"Tauri 2 + React + Rust 크로스 플랫폼 개발 가이드, 아키텍처, IPC, 백엔드 및 프론트엔드의 베스트 프랙티스를 통합","es":"Tauri 2 con React y Rust es una combinación poderosa para el desarrollo de aplicaciones de escritorio cruzadas. Aprende a diseñar y implementar arquitecturas efectivas.","fr":"Tauri 2 avec React et Rust est un combo puissant pour le développement d''applications de bureau cross-platform. Apprenez à concevoir et à mettre en œuvre des architectures efficaces.","de":"Tauri 2 mit React und Rust ist eine leistungsfähige Kombination für die Entwicklung von Cross-Desktop-Anwendungen. Lernen Sie, effektive Architekturen zu entwerfen und umzusetzen.","pt":"O Tauri2-React-Rust é uma combinação poderosa para desenvolvimento de aplicações cruz-plataforma. Aprenda a criar aplicações escaláveis e seguras com essa tecnologia.","ru":"Tauri2-React-Rust - это мощная комбинация для разработки кроссплатформенных приложений. Узнайте, как создавать масштабируемые и безопасные приложения с помощью этой технологии и ИИ Агентов.","ar":"Tauri2-React-Rust هو مزيج قوي لإنشاء تطبيقات متعددة المنصات. تعلم كيفية إنشاء تطبيقات 